function createWorkspacePerfDiagnostics() {
  const MAX_COMPLETED_SPANS = 512;
  const MAX_ACTIVE_TASKS = 128;
  const MAX_ACTIVE_SPANS = 128;
  const MAX_COUNTERS = 64;
  const clockNow = () => globalThis.performance?.now?.() ?? Date.now();
  let scenario = null;
  let nextId = 1;
  const completed = [];
  const activeSpans = new Map();
  const activeTasks = new Map();
  const counters = new Map();
  const invalidReasons = [];
  let droppedCompletedSpans = 0;

  const markInvalid = (reason) => {
    if (!invalidReasons.includes(reason)) invalidReasons.push(reason);
  };

  const startSpan = (name, meta = {}) => {
    if (activeSpans.size >= MAX_ACTIVE_SPANS) {
      markInvalid("active-span-overflow");
      return { id: null, end() {} };
    }
    const id = nextId++;
    const requestedParentId = meta.parentId || null;
    const parentId = requestedParentId && activeSpans.has(requestedParentId) ? requestedParentId : null;
    if (requestedParentId && !parentId) markInvalid("orphan-span-parent");
    const record = { id, parentId, name, meta: Object.assign({}, meta), startedAt: clockNow(), childMs: 0 };
    activeSpans.set(id, record);
    return {
      id,
      end(extra = {}) {
        const current = activeSpans.get(id);
        if (!current) return null;
        activeSpans.delete(id);
        const inclusiveMs = Math.max(0, clockNow() - current.startedAt);
        const result = Object.assign({}, current, extra, {
          inclusiveMs,
          exclusiveMs: Math.max(0, inclusiveMs - current.childMs),
        });
        if (parentId && activeSpans.has(parentId)) {
          activeSpans.get(parentId).childMs += inclusiveMs;
        } else if (parentId) {
          markInvalid("span-parent-ended-before-child");
        }
        if (completed.length >= MAX_COMPLETED_SPANS) {
          completed.shift();
          droppedCompletedSpans += 1;
        }
        completed.push(result);
        return result;
      },
    };
  };

  const beginTask = (name, meta = {}) => {
    if (activeTasks.size >= MAX_ACTIVE_TASKS) {
      markInvalid("active-task-overflow");
      return { id: null, end() {} };
    }
    const id = nextId++;
    activeTasks.set(id, { id, name, meta: Object.assign({}, meta), startedAt: clockNow() });
    return { id, end() { activeTasks.delete(id); } };
  };

  const increment = (name, value = 1) => {
    if (!counters.has(name) && counters.size >= MAX_COUNTERS) {
      markInvalid("counter-overflow");
      return;
    }
    counters.set(name, Number(counters.get(name) || 0) + Number(value || 0));
  };

  const reset = (scenarioId = "") => {
    scenario = scenarioId;
    completed.length = 0;
    activeSpans.clear();
    activeTasks.clear();
    counters.clear();
    invalidReasons.length = 0;
    droppedCompletedSpans = 0;
  };

  const snapshot = () => ({
    scenario,
    valid: invalidReasons.length === 0 && activeTasks.size === 0 && activeSpans.size === 0,
    invalidReasons: invalidReasons.slice(),
    pendingTasks: Array.from(activeTasks.values()).map((entry) => Object.assign({}, entry)),
    activeSpanCount: activeSpans.size,
    completedSpans: completed.map((entry) => Object.assign({}, entry, { meta: Object.assign({}, entry.meta) })),
    counters: Object.fromEntries(counters),
    droppedCompletedSpans,
    limits: {
      completedSpans: MAX_COMPLETED_SPANS,
      activeSpans: MAX_ACTIVE_SPANS,
      activeTasks: MAX_ACTIVE_TASKS,
      counters: MAX_COUNTERS,
    },
  });

  return { startSpan, beginTask, increment, reset, snapshot, markInvalid };
}

let workspacePerfDiagnostics = null;
function getWorkspacePerfDiagnostics() {
  if (typeof globalThis === "undefined" || globalThis.__WSM_PERF_DIAG !== true) return null;
  if (!workspacePerfDiagnostics) {
    workspacePerfDiagnostics = createWorkspacePerfDiagnostics();
    globalThis.__workspaceMountPerfDiagApi = workspacePerfDiagnostics;
  }
  return workspacePerfDiagnostics;
}

function resetWorkspacePerfDiagnosticsOnUnload() {
  if (
    workspacePerfDiagnostics
    && typeof globalThis !== "undefined"
    && globalThis.__workspaceMountPerfDiagApi === workspacePerfDiagnostics
  ) {
    delete globalThis.__workspaceMountPerfDiagApi;
  }
  workspacePerfDiagnostics = null;
}

function startWorkspacePerfSpan(name, meta = {}) {
  return getWorkspacePerfDiagnostics()?.startSpan(name, meta) || null;
}

function beginWorkspacePerfTask(name, meta = {}) {
  return getWorkspacePerfDiagnostics()?.beginTask(name, meta) || null;
}

function incrementWorkspacePerfCounter(name, value = 1) {
  getWorkspacePerfDiagnostics()?.increment(name, value);
}

function trackWorkspacePerfDetached(name, meta, operation) {
  const task = beginWorkspacePerfTask(name, meta);
  if (!task) {
    void operation();
    return;
  }
  incrementWorkspacePerfCounter("detachedTasksStarted");
  let result;
  try {
    result = operation();
  } catch (error) {
    task.end();
    incrementWorkspacePerfCounter("detachedTasksCompleted");
    throw error;
  }
  void Promise.resolve(result).finally(() => {
    task.end();
    incrementWorkspacePerfCounter("detachedTasksCompleted");
  });
}

function workspacePerfByteLength(value) {
  const text = String(value || "");
  if (typeof TextEncoder !== "undefined") return new TextEncoder().encode(text).length;
  return text.length;
}

async function measureWorkspacePerfAsync(name, meta, operation) {
  const span = startWorkspacePerfSpan(name, meta);
  try {
    return await operation();
  } finally {
    span?.end();
  }
}

function nowString() {
  return new Date().toISOString();
}

function cleanupRetiredWorkspacePinButtons() {
  if (typeof document === "undefined") return;
  document.body?.querySelectorAll?.(".workspace-pin-btn")?.forEach?.((button) => button.remove?.());
}

function auditSnippet(value, fallback = "", maxLength = 400) {
  const normalized = sanitizeText(typeof value === "string" ? value.replace(/\s+/g, " ").trim() : value, fallback);
  if (!normalized) return fallback;
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, Math.max(0, maxLength - 3))}...`;
}

function sanitizeText(value, fallback = "") {
  const text = String(value == null ? "" : value).trim();
  return text || fallback;
}

function isContextCarrierDiagEnabled() {
  try {
    return typeof window !== "undefined"
      && (window.__WM_CONTEXT_CARRIER_DIAG === true || window.__CONTEXT_CARRIER_DIAG === true);
  } catch (_) {
    return false;
  }
}

function previewContextCarrierText(value, maxLength = 40) {
  const normalized = sanitizeText(value, "").replace(/\s+/g, " ");
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, Math.max(0, maxLength - 3))}...`;
}

function logWorkspaceJump(traceId, stage, payload = {}) {
  const prefix = traceId ? `[Workspace Mount][${traceId}]` : "[Workspace Mount]";
  let serialized = "";
  try {
    serialized = JSON.stringify(payload);
  } catch (error) {
    serialized = String(payload);
  }
  console.log(`${prefix}[${stage}] ${serialized}`);
}

function encodeJumpSegment(value) {
  return encodeURIComponent(sanitizeText(value, ""));
}

function decodeJumpSegment(value) {
  try {
    return decodeURIComponent(String(value || ""));
  } catch (error) {
    return sanitizeText(value, "");
  }
}

function buildJumpNodeKey({ viewType = "", notePath = "", scopeType = "", scopeId = "", itemId = "" } = {}) {
  const segments = [viewType, notePath, scopeType, scopeId, itemId].map((value) => sanitizeText(value, ""));
  if (segments.some((segment) => !segment)) return "";
  return `${JUMP_NODE_PREFIX}${segments.map((segment) => encodeJumpSegment(segment)).join("|")}`;
}

function parseJumpNodeKey(nodeKey) {
  const normalized = sanitizeText(nodeKey, "");
  if (!normalized.startsWith(JUMP_NODE_PREFIX)) return null;
  const encodedSegments = normalized.slice(JUMP_NODE_PREFIX.length).split("|");
  if (encodedSegments.length !== JUMP_NODE_SEGMENT_COUNT) return null;
  const [viewType, notePath, scopeType, scopeId, itemId] = encodedSegments.map((segment) => decodeJumpSegment(segment));
  if (!viewType || !notePath || !scopeType || !scopeId || !itemId) return null;
  return {
    nodeKey: buildJumpNodeKey({ viewType, notePath, scopeType, scopeId, itemId }),
    viewType,
    notePath,
    scopeType,
    scopeId,
    itemId,
  };
}

function buildWorkspaceJumpNodeKey(notePath, tabId, itemId) {
  return buildJumpNodeKey({
    viewType: VIEW_TYPE_WORKSPACE_MOUNT,
    notePath,
    scopeType: "tab",
    scopeId: tabId,
    itemId,
  });
}

function buildLegacyWorkspaceNodeKey(itemId) {
  const normalizedItemId = sanitizeText(itemId, "");
  if (!normalizedItemId) return "";
  return `${LEGACY_WORKSPACE_NODE_PREFIX}${normalizedItemId}`;
}

function parseLegacyWorkspaceNodeKey(nodeKey) {
  const normalized = sanitizeText(nodeKey, "");
  if (!normalized.startsWith(LEGACY_WORKSPACE_NODE_PREFIX)) return "";
  return normalized.slice(LEGACY_WORKSPACE_NODE_PREFIX.length).trim();
}

function parseWorkspaceJumpNodeKey(nodeKey) {
  const parsed = parseJumpNodeKey(nodeKey);
  if (!parsed || parsed.viewType !== VIEW_TYPE_WORKSPACE_MOUNT || parsed.scopeType !== "tab") return null;
  return parsed;
}

function mergeRelationSnapshots(primary = {}, legacy = {}) {
  const mergeList = (left, right) => {
    const seen = new Set();
    return []
      .concat(Array.isArray(left) ? left : [], Array.isArray(right) ? right : [])
      .filter((relation) => {
        const relationId = sanitizeText(relation?.id, "");
        if (!relationId || seen.has(relationId)) return false;
        seen.add(relationId);
        return true;
      });
  };
  return {
    outgoing: mergeList(primary?.outgoing, legacy?.outgoing),
    incoming: mergeList(primary?.incoming, legacy?.incoming),
  };
}

function ensureJumpOpenerRegistry() {
  const existing = window[JUMP_OPENER_REGISTRY_GLOBAL];
  if (
    existing
    && typeof existing.register === "function"
    && typeof existing.unregister === "function"
    && typeof existing.get === "function"
  ) {
    return existing;
  }
  const openersByViewType = new Map();
  const registry = {
    version: 1,
    register(descriptor = {}) {
      const openerId = sanitizeText(descriptor.openerId, "");
      const viewType = sanitizeText(descriptor.viewType, "");
      if (!openerId || !viewType || typeof descriptor.openNode !== "function") return null;
      openersByViewType.set(viewType, {
        openerId,
        viewType,
        openNode: descriptor.openNode,
      });
      return true;
    },
    unregister(openerId) {
      const targetId = sanitizeText(openerId, "");
      if (!targetId) return false;
      let removed = false;
      Array.from(openersByViewType.entries()).forEach(([viewType, descriptor]) => {
        if (descriptor?.openerId !== targetId) return;
        openersByViewType.delete(viewType);
        removed = true;
      });
      return removed;
    },
    get(viewType) {
      return openersByViewType.get(sanitizeText(viewType, "")) || null;
    },
  };
  window[JUMP_OPENER_REGISTRY_GLOBAL] = registry;
  return registry;
}

function isObjectLike(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function deepClone(value, fallback = null) {
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (error) {
    return fallback;
  }
}

function parentKey(parentId) {
  const value = sanitizeText(parentId, "");
  return value || ROOT_KEY;
}

function tabParentKey(tabId, parentId) {
  const ownerId = sanitizeText(tabId, DEFAULT_TAB_ID) || DEFAULT_TAB_ID;
  return `${ownerId}::${parentKey(parentId)}`;
}

function paradigmParentKey(paradigmId, parentId) {
  return `${sanitizeText(paradigmId, "")}::${parentKey(parentId)}`;
}

function paradigmTreeKey(parentParadigmId) {
  return parentKey(parentParadigmId);
}

function paradigmCategoryTreeKey(parentCategoryId) {
  return parentKey(parentCategoryId);
}

function paradigmCopyTreeKey(hostParadigmId) {
  return parentKey(hostParadigmId);
}

function makeParadigmMountMapKey(tabId, mountScopeId, paradigmItemId) {
  let bindingId = "";
  if (arguments.length >= 4) bindingId = sanitizeText(arguments[3], "");
  const tabKey = sanitizeText(tabId, "");
  const scopeKey = sanitizeText(mountScopeId, "");
  const itemKey = sanitizeText(paradigmItemId, "");
  return bindingId
    ? `${tabKey}::${bindingId}@@${scopeKey}@@${itemKey}`
    : `${tabKey}::${scopeKey}@@${itemKey}`;
}

function parseParadigmMountMapKey(rawKey) {
  const raw = sanitizeText(rawKey, "");
  const parsed = splitScopedKey(raw);
  const suffix = sanitizeText(parsed.parent, "");
  const parts = suffix.split("@@");
  if (parts.length >= 3) {
    return {
      tabId: parsed.ownerId,
      bindingId: sanitizeText(parts[0], ""),
      mountScopeId: sanitizeText(parts[1], ""),
      paradigmItemId: sanitizeText(parts.slice(2).join("@@"), ""),
    };
  }
  const sep = suffix.indexOf("@@");
  if (sep < 0) {
    return { tabId: parsed.ownerId, bindingId: "", mountScopeId: "", paradigmItemId: suffix };
  }
  return {
    tabId: parsed.ownerId,
    bindingId: "",
    mountScopeId: sanitizeText(suffix.slice(0, sep), ""),
    paradigmItemId: sanitizeText(suffix.slice(sep + 2), ""),
  };
}

function makeSyntheticRootParadigmBindingId(tabId, paradigmId) {
  return `root::${sanitizeText(tabId, "")}::${sanitizeText(paradigmId, "")}`;
}

function createParadigmMountBindingId() {
  return `bind_${createId("pgMount")}`;
}

function ensureUniqueIds(listLike) {
  const out = [];
  const seen = new Set();
  for (const raw of Array.isArray(listLike) ? listLike : []) {
    const id = sanitizeText(raw, "");
    if (!id || seen.has(id)) continue;
    out.push(id);
    seen.add(id);
  }
  return out;
}

function removeIdFromSimpleChildrenMap(childrenMap, id) {
  Object.keys(childrenMap || {}).forEach((key) => {
    const list = Array.isArray(childrenMap[key]) ? childrenMap[key] : [];
    childrenMap[key] = list.filter((x) => x !== id);
  });
}

function buildTransferMarkerLine(meta) {
  const sourceTabId = sanitizeText(meta?.sourceTabId, "");
  const sourceItemId = sanitizeText(meta?.sourceItemId, "");
  const sourceParadigmId = sanitizeText(meta?.sourceParadigmId, "");
  return `[workspace-transfer] sourceTabId=${sourceTabId};sourceItemId=${sourceItemId};sourceParadigmId=${sourceParadigmId};`;
}

function parseTransferMarkerLine(text) {
  const raw = String(text || "");
  const match = raw.match(/\[workspace-transfer\]\s*sourceTabId=([^;\n]+);sourceItemId=([^;\n]+);sourceParadigmId=([^;\n]+);/);
  if (!match) return null;
  return {
    sourceTabId: sanitizeText(match[1], ""),
    sourceItemId: sanitizeText(match[2], ""),
    sourceParadigmId: sanitizeText(match[3], ""),
  };
}

function normalizeTransferredCommentLayout(text) {
  const raw = String(text || "").trim();
  if (!raw || !parseTransferMarkerLine(raw)) return raw;
  const lines = raw.split(/\r?\n/);
  const markerIndex = lines.findIndex((line) => /\[workspace-transfer\]/.test(line));
  if (markerIndex < 0) return raw;
  const transferStart = Math.max(0, markerIndex - 3);
  const transferBlock = lines.slice(transferStart, markerIndex + 1).join("\n").trim();
  const remaining = lines.slice(0, transferStart).concat(lines.slice(markerIndex + 1)).join("\n").trim();
  return remaining ? `${remaining}\n\n${transferBlock}` : transferBlock;
}

function composeTransferredItemComment(meta, originalComment = "") {
  const sourceTabName = sanitizeText(meta?.sourceTabName, sanitizeText(meta?.sourceTabId, ""));
  const sourceParadigmName = sanitizeText(meta?.sourceParadigmName, sanitizeText(meta?.sourceParadigmId, ""));
  const sourceItemTitle = sanitizeText(meta?.sourceItemTitle, sanitizeText(meta?.sourceItemId, ""));
  const sourceItemId = sanitizeText(meta?.sourceItemId, "");
  const transferBlock = [
    `转自 Tab：${sourceTabName}${meta?.sourceTabId ? ` (${meta.sourceTabId})` : ""}`,
    `来源范式：${sourceParadigmName}`,
    `来源条目：${sourceItemTitle}${sourceItemId ? ` (${sourceItemId})` : ""}`,
    buildTransferMarkerLine(meta),
  ].join("\n");
  const cleanOriginal = normalizeTransferredCommentLayout(originalComment);
  return cleanOriginal ? `${cleanOriginal}\n\n${transferBlock}` : transferBlock;
}

function createId(prefix = "id") {
  return `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
}

function canonicalizeJson(value) {
  if (Array.isArray(value)) return value.map((entry) => canonicalizeJson(entry));
  if (!isObjectLike(value)) return value;
  const out = {};
  Object.keys(value).sort().forEach((key) => {
    out[key] = canonicalizeJson(value[key]);
  });
  return out;
}

function canonicalJsonString(value) {
  return JSON.stringify(canonicalizeJson(value));
}

function hashCanonicalJson(value) {
  const text = canonicalJsonString(value);
  let hashA = 2166136261;
  let hashB = 5381;
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    hashA ^= code;
    hashA = Math.imul(hashA, 16777619);
    hashB = Math.imul(hashB, 33) ^ code;
  }
  return `wsm1-${(hashA >>> 0).toString(16).padStart(8, "0")}-${(hashB >>> 0).toString(16).padStart(8, "0")}-${text.length}`;
}

function hashParadigmOntology(ontology) {
  return hashCanonicalJson(ontology == null ? null : ontology);
}

function getParadigmOntologyImageExtension(pathLike) {
  const value = String(pathLike || "").trim();
  const match = value.match(/\.([a-zA-Z0-9]+)$/);
  return match ? match[1].toLowerCase() : "";
}

function getParadigmOntologyImageKindByExtension(extension) {
  const ext = String(extension || "").toLowerCase();
  return Object.entries(PARADIGM_ONTOLOGY_IMAGE_TYPES)
    .find(([, policy]) => policy.extensions.includes(ext))?.[0] || "";
}

function getParadigmOntologyImageKindByMime(mimeType) {
  const mime = String(mimeType || "").trim().toLowerCase();
  if (!mime) return "";
  return Object.entries(PARADIGM_ONTOLOGY_IMAGE_TYPES)
    .find(([, policy]) => policy.mimeTypes.includes(mime))?.[0] || "";
}

function detectParadigmOntologyImageSignature(bufferLike) {
  const bytes = bufferLike instanceof Uint8Array
    ? bufferLike
    : new Uint8Array(bufferLike instanceof ArrayBuffer ? bufferLike : []);
  if (bytes.length >= 8
    && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47
    && bytes[4] === 0x0d && bytes[5] === 0x0a && bytes[6] === 0x1a && bytes[7] === 0x0a) return "png";
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return "jpeg";
  if (bytes.length >= 6) {
    const header = String.fromCharCode(...bytes.slice(0, 6));
    if (header === "GIF87a" || header === "GIF89a") return "gif";
  }
  if (bytes.length >= 12) {
    const riff = String.fromCharCode(...bytes.slice(0, 4));
    const webp = String.fromCharCode(...bytes.slice(8, 12));
    if (riff === "RIFF" && webp === "WEBP") return "webp";
  }
  if (bytes.length >= 2 && bytes[0] === 0x42 && bytes[1] === 0x4d) return "bmp";
  return "";
}

function validateParadigmOntologyImageFile(fileLike, bufferLike, limits = PARADIGM_ONTOLOGY_IMAGE_LIMITS) {
  const name = String(fileLike?.name || "").trim();
  const declaredSize = Number(fileLike?.size ?? 0);
  const actualSize = Number(bufferLike?.byteLength ?? 0);
  const size = Math.max(Number.isFinite(declaredSize) ? declaredSize : 0, Number.isFinite(actualSize) ? actualSize : 0);
  if (!name) return { ok: false, error: "图片文件缺少名称。" };
  if (!Number.isFinite(size) || size < 0 || size > limits.maxFileBytes) {
    return { ok: false, error: `图片 ${name} 超过单文件大小限制。` };
  }
  const extensionKind = getParadigmOntologyImageKindByExtension(getParadigmOntologyImageExtension(name));
  const mime = String(fileLike?.type || "").trim().toLowerCase();
  const mimeKind = getParadigmOntologyImageKindByMime(mime);
  const signatureKind = detectParadigmOntologyImageSignature(bufferLike);
  if (!extensionKind) return { ok: false, error: `图片 ${name} 的扩展名不受支持。` };
  if (mime && !mimeKind) return { ok: false, error: `图片 ${name} 的 MIME 类型不受支持。` };
  if (!signatureKind) return { ok: false, error: `图片 ${name} 的文件签名无法识别。` };
  if ((mimeKind && mimeKind !== extensionKind) || signatureKind !== extensionKind) {
    return { ok: false, error: `图片 ${name} 的扩展名、MIME 或文件签名不一致。` };
  }
  return { ok: true, kind: extensionKind, mimeType: mime || PARADIGM_ONTOLOGY_IMAGE_TYPES[extensionKind].mimeTypes[0] };
}

function decodeParadigmOntologyImageTarget(value) {
  let target = String(value || "").trim();
  if (target.startsWith("<") && target.endsWith(">")) target = target.slice(1, -1).trim();
  const delimiterIndex = target.search(/[?#]/);
  if (delimiterIndex >= 0) target = target.slice(0, delimiterIndex);
  try {
    target = decodeURIComponent(target);
  } catch (_) {}
  return target.replace(/\\/g, "/").trim();
}

function parseParadigmOntologyImageEmbeds(value) {
  const text = String(value || "");
  const records = [];
  const pushRecord = (kind, match, rawTarget, metadata = {}) => {
    const token = String(match[0] || "");
    const start = Number(match.index) || 0;
    const end = start + token.length;
    const target = decodeParadigmOntologyImageTarget(rawTarget);
    if (!target
      || !getParadigmOntologyImageKindByExtension(getParadigmOntologyImageExtension(target))
      || records.some((record) => start < record.end && end > record.start)) return;
    records.push({ kind, token, start, end, target, ...metadata });
  };
  const wikiPattern = /!\[\[([^\]]+)\]\]/g;
  let match;
  while ((match = wikiPattern.exec(text)) != null) {
    const parts = String(match[1] || "").split("|");
    const target = String(parts.shift() || "").trim();
    pushRecord("wiki", match, target, { aliasOrSize: parts.join("|").trim() });
  }
  const markdownPattern = /!\[([^\]]*)\]\(\s*(<[^>]+>|[^)\s]+)(?:\s+["']([^"']*)["'])?\s*\)/g;
  while ((match = markdownPattern.exec(text)) != null) {
    pushRecord("markdown", match, match[2], { alt: String(match[1] || ""), title: String(match[3] || "") });
  }
  return records.sort((left, right) => left.start - right.start);
}

function getParadigmOntologyLineBreak(value, fallback = "\n") {
  const match = String(value || "").match(/\r\n|\n|\r/);
  return match?.[0] || fallback;
}

function removeParadigmOntologyImageEmbedFromProjection(value, record) {
  const text = String(value || "");
  const token = String(record?.token || "");
  const start = Number(record?.start);
  const end = Number(record?.end);
  if (!token || !Number.isInteger(start) || !Number.isInteger(end)
    || start < 0 || end < start || text.slice(start, end) !== token) return text;
  let before = text.slice(0, start);
  let after = text.slice(end);
  const previousBreak = before.match(/(?:\r\n|\n|\r)$/)?.[0] || "";
  const nextBreak = after.match(/^(?:\r\n|\n|\r)/)?.[0] || "";
  if (previousBreak && nextBreak) after = after.slice(nextBreak.length);
  else if (!before && nextBreak) after = after.slice(nextBreak.length);
  else if (!after && previousBreak) before = before.slice(0, -previousBreak.length);
  return `${before}${after}`;
}

function stripParadigmOntologyImageEmbeds(value) {
  let result = String(value || "");
  parseParadigmOntologyImageEmbeds(result).slice().reverse().forEach((record) => {
    result = removeParadigmOntologyImageEmbedFromProjection(result, record);
  });
  return result;
}

function escapeParadigmOntologyMermaidLabel(value, maxLength = PARADIGM_ONTOLOGY_TREE_LIMITS.maxLabelChars) {
  const normalized = String(value == null ? "" : value)
    .replace(/\r\n|\n|\r/g, " · ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[\\"'`\[\]{}()<>;&]/g, (character) => ({
      "\\": "＼",
      "\"": "＂",
      "'": "＇",
      "`": "｀",
      "[": "［",
      "]": "］",
      "{": "｛",
      "}": "｝",
      "(": "（",
      ")": "）",
      "<": "＜",
      ">": "＞",
      ";": "；",
      "&": "＆",
    })[character] || character);
  const limit = Math.max(16, Math.floor(Number(maxLength) || PARADIGM_ONTOLOGY_TREE_LIMITS.maxLabelChars));
  return normalized.length > limit ? `${normalized.slice(0, Math.max(1, limit - 1))}…` : normalized;
}

function getParadigmOntologyTreeCellLabel(column, cell, limits = PARADIGM_ONTOLOGY_TREE_LIMITS) {
  const rawValue = String(cell?.value || "");
  const images = parseParadigmOntologyImageEmbeds(rawValue);
  const body = stripParadigmOntologyImageEmbeds(rawValue).replace(/\s+/g, " ").trim();
  const parts = [];
  const columnLabel = sanitizeText(column?.label, "未命名列");
  parts.push(`${columnLabel}：${body || "空白"}`);
  if (images.length > 0) parts.push(`图片 ×${images.length}`);
  return escapeParadigmOntologyMermaidLabel(parts.join(" · "), limits.maxLabelChars);
}

function buildParadigmOntologyTreeProjection(ontology, options = {}) {
  const limits = Object.assign({}, PARADIGM_ONTOLOGY_TREE_LIMITS, isObjectLike(options.limits) ? options.limits : {});
  limits.maxNodes = Math.max(2, Math.floor(Number(limits.maxNodes) || PARADIGM_ONTOLOGY_TREE_LIMITS.maxNodes));
  limits.maxEdges = Math.max(1, Math.floor(Number(limits.maxEdges) || PARADIGM_ONTOLOGY_TREE_LIMITS.maxEdges));
  limits.maxSourceBytes = Math.max(512, Math.floor(Number(limits.maxSourceBytes) || PARADIGM_ONTOLOGY_TREE_LIMITS.maxSourceBytes));
  limits.maxLabelChars = Math.max(16, Math.floor(Number(limits.maxLabelChars) || PARADIGM_ONTOLOGY_TREE_LIMITS.maxLabelChars));
  const rootTableId = sanitizeText(ontology?.rootTableId, "");
  const tablesById = isObjectLike(ontology?.tablesById) ? ontology.tablesById : {};
  const schemasById = isObjectLike(ontology?.schemasById) ? ontology.schemasById : {};
  if (!rootTableId || !tablesById[rootTableId]) {
    return {
      ok: false,
      error: "Ontology 根表不存在。",
      mermaid: "",
      nodeCount: 0,
      edgeCount: 0,
      tableCount: 0,
      omittedNodeCount: 0,
      omittedEdgeCount: 0,
      truncated: false,
      truncationReasons: [],
    };
  }

  const nodes = [];
  const edges = [];
  const visitedTables = new Set();
  const truncationReasons = new Set();
  let omittedNodeCount = 0;
  let omittedEdgeCount = 0;
  let tableCount = 0;
  const addNode = (label, kind) => {
    if (nodes.length >= limits.maxNodes) {
      omittedNodeCount += 1;
      truncationReasons.add("node-limit");
      return "";
    }
    const id = `ontTree${nodes.length}`;
    nodes.push({ id, label: escapeParadigmOntologyMermaidLabel(label, limits.maxLabelChars), kind });
    return id;
  };
  const addEdge = (from, to) => {
    if (!from || !to) return false;
    if (edges.length >= limits.maxEdges) {
      omittedEdgeCount += 1;
      truncationReasons.add("edge-limit");
      return false;
    }
    edges.push({ from, to });
    return true;
  };
  const visitTable = (tableId, parentNodeId = "") => {
    const id = sanitizeText(tableId, "");
    if (!id || visitedTables.has(id)) {
      if (id) truncationReasons.add("cycle-or-repeated-table");
      return "";
    }
    const table = tablesById[id];
    const schema = schemasById[table?.schemaId];
    if (!table || !schema) {
      truncationReasons.add("missing-table-or-schema");
      omittedNodeCount += 1;
      return "";
    }
    visitedTables.add(id);
    tableCount += 1;
    const tableNodeId = addNode(`${id === rootTableId ? "根表" : "子表"} · ${sanitizeText(schema.name, "表格")}`, "ontologyTable");
    addEdge(parentNodeId, tableNodeId);
    if (!tableNodeId) return "";
    const activeColumnIds = Array.isArray(schema.columnOrder) ? schema.columnOrder : [];
    const rowOrder = Array.isArray(table.rowOrder) ? table.rowOrder : [];
    rowOrder.forEach((rowId, rowIndex) => {
      const row = table.rowsById?.[rowId];
      if (!row) {
        omittedNodeCount += 1;
        truncationReasons.add("missing-row");
        return;
      }
      const rowNodeId = addNode(`第 ${rowIndex + 1} 行`, "ontologyRow");
      addEdge(tableNodeId, rowNodeId);
      let previousNodeId = rowNodeId;
      activeColumnIds.forEach((columnId) => {
        const column = schema.columnsById?.[columnId];
        const cell = row.cellsByColumnId?.[columnId];
        if (!column || !cell) {
          omittedNodeCount += 1;
          truncationReasons.add("missing-active-cell");
          return;
        }
        const cellNodeId = addNode(getParadigmOntologyTreeCellLabel(column, cell, limits), "ontologyCell");
        addEdge(previousNodeId, cellNodeId);
        if (cellNodeId) previousNodeId = cellNodeId;
        const childTableId = sanitizeText(cell.nestedTableId, "");
        if (childTableId && cellNodeId) visitTable(childTableId, cellNodeId);
      });
    });
    return tableNodeId;
  };
  const rootNodeId = visitTable(rootTableId);
  if (!rootNodeId) {
    return {
      ok: false,
      error: "Ontology 全景树无法建立根节点。",
      mermaid: "",
      nodeCount: nodes.length,
      edgeCount: edges.length,
      tableCount,
      omittedNodeCount,
      omittedEdgeCount,
      truncated: true,
      truncationReasons: Array.from(truncationReasons),
    };
  }

  const buildSource = (sourceNodes, sourceEdges, includeStyles = true) => [
    "flowchart LR",
    ...sourceNodes.map((node) => `  ${node.id}[\"${node.label}\"]:::${node.kind}`),
    ...sourceEdges.map((edge) => `  ${edge.from} --> ${edge.to}`),
    ...(includeStyles ? [
      "  classDef ontologyTable fill:#dfe9f5,stroke:#4c6b8a,stroke-width:2px,color:#17202a;",
      "  classDef ontologyRow fill:#f3f4f6,stroke:#8b949e,color:#24292f;",
      "  classDef ontologyCell fill:#ffffff,stroke:#a8b0ba,color:#24292f;",
      "  classDef ontologyTruncated fill:#fff3cd,stroke:#b7791f,stroke-width:2px,color:#5f3b00;",
    ] : []),
  ].join("\n");

  let visibleNodes = nodes.slice();
  let visibleEdges = edges.slice();
  let source = buildSource(visibleNodes, visibleEdges);
  if (workspacePerfByteLength(source) > limits.maxSourceBytes) {
    truncationReasons.add("source-byte-limit");
    while (workspacePerfByteLength(source) > limits.maxSourceBytes && visibleNodes.length > 1) {
      const removed = visibleNodes.pop();
      visibleEdges = visibleEdges.filter((edge) => edge.from !== removed.id && edge.to !== removed.id);
      omittedNodeCount += 1;
      source = buildSource(visibleNodes, visibleEdges);
    }
  }
  if (truncationReasons.size > 0) {
    if (visibleNodes.length >= limits.maxNodes && visibleNodes.length > 1) {
      const removed = visibleNodes.pop();
      visibleEdges = visibleEdges.filter((edge) => edge.from !== removed.id && edge.to !== removed.id);
      omittedNodeCount += 1;
    }
    const markerId = `ontTreeTruncated`;
    visibleNodes.push({
      id: markerId,
      label: escapeParadigmOntologyMermaidLabel(`全景已截断 · 省略节点 ${omittedNodeCount} · 省略连线 ${omittedEdgeCount}`, limits.maxLabelChars),
      kind: "ontologyTruncated",
    });
    if (visibleEdges.length < limits.maxEdges) visibleEdges.push({ from: rootNodeId, to: markerId });
    source = buildSource(visibleNodes, visibleEdges);
  }
  if (workspacePerfByteLength(source) > limits.maxSourceBytes) {
    source = buildSource(visibleNodes, visibleEdges, false);
    while (workspacePerfByteLength(source) > limits.maxSourceBytes && visibleNodes.length > 1) {
      const markerPresent = visibleNodes[visibleNodes.length - 1]?.id === "ontTreeTruncated";
      const removeIndex = markerPresent ? visibleNodes.length - 2 : visibleNodes.length - 1;
      if (removeIndex <= 0) break;
      const removed = visibleNodes.splice(removeIndex, 1)[0];
      if (!removed) break;
      visibleEdges = visibleEdges.filter((edge) => edge.from !== removed.id && edge.to !== removed.id);
      omittedNodeCount += 1;
      source = buildSource(visibleNodes, visibleEdges, false);
    }
  }
  return {
    ok: true,
    error: "",
    mermaid: source,
    nodeCount: visibleNodes.length,
    edgeCount: visibleEdges.length,
    tableCount,
    omittedNodeCount,
    omittedEdgeCount,
    truncated: truncationReasons.size > 0,
    truncationReasons: Array.from(truncationReasons).sort(),
  };
}

function composeParadigmOntologyCellValue(body, tokens = [], lineBreak = "") {
  const text = String(body || "");
  const imageTokens = (Array.isArray(tokens) ? tokens : [])
    .map((token) => String(token || ""))
    .filter(Boolean);
  if (imageTokens.length === 0) return text;
  const separator = String(lineBreak || "") || getParadigmOntologyLineBreak(text);
  const prefix = text ? separator : "";
  return `${text}${prefix}${imageTokens.join(separator)}`;
}

function appendParadigmOntologyImageEmbeds(value, embeds) {
  const text = String(value || "");
  const additions = Array.from(new Set((Array.isArray(embeds) ? embeds : [])
    .map((entry) => String(entry || "").trim())
    .filter(Boolean)));
  if (additions.length === 0) return text;
  const separator = text.length === 0 || text.endsWith("\n") ? "" : "\n";
  return `${text}${separator}${additions.join("\n")}`;
}

function replaceParadigmOntologyImageEmbed(value, oldToken, newToken) {
  const text = String(value || "");
  const from = String(oldToken || "");
  const to = String(newToken || "").trim();
  if (!from || !to) return text;
  const index = text.indexOf(from);
  if (index < 0) return text;
  return `${text.slice(0, index)}${to}${text.slice(index + from.length)}`;
}

function removeParadigmOntologyImageEmbed(value, record) {
  const text = String(value || "");
  const token = String(record?.token || "");
  let start = Number(record?.start);
  let end = Number(record?.end);
  if (!token) return text;
  if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end < start || text.slice(start, end) !== token) {
    return text;
  }
  let before = text.slice(0, start);
  let after = text.slice(end);
  if (before.endsWith("\n") && after.startsWith("\n")) after = after.slice(1);
  else if (!before && after.startsWith("\n")) after = after.slice(1);
  else if (!after && before.endsWith("\n")) before = before.slice(0, -1);
  return `${before}${after}`;
}

function deepFreezeParadigmOntologyRangeValue(value, seen = new WeakSet()) {
  if (!value || typeof value !== "object" || seen.has(value)) return value;
  seen.add(value);
  Object.values(value).forEach((entry) => deepFreezeParadigmOntologyRangeValue(entry, seen));
  return Object.freeze(value);
}

function getParadigmOntologyRangeImageLikeStarts(value) {
  const text = String(value || "");
  const starts = [];
  for (let index = 0; index < text.length - 1; index += 1) {
    if (text.startsWith("![[", index)) {
      starts.push({ index, kind: "wiki" });
      index += 2;
    } else if (text.startsWith("![", index)) {
      starts.push({ index, kind: "markdown" });
      index += 1;
    }
  }
  return starts;
}

function isParadigmOntologyRangeImageStartEscaped(text, index) {
  let slashCount = 0;
  for (let cursor = index - 1; cursor >= 0 && text[cursor] === "\\"; cursor -= 1) slashCount += 1;
  return slashCount % 2 === 1;
}

function getParadigmOntologyRangeCodeRanges(value) {
  const text = String(value || "");
  const ranges = [];
  const fencedRanges = [];
  let activeFence = null;
  let offset = 0;
  const lines = text.match(/.*(?:\r\n|\n|\r|$)/g)?.filter((line, index, all) => line.length > 0 || index < all.length - 1) || [];
  lines.forEach((line) => {
    const lineEnd = offset + line.length;
    const content = line.replace(/(?:\r\n|\n|\r)$/, "");
    const opener = content.match(/^ {0,3}(`{3,}|~{3,})/);
    if (!activeFence && opener) {
      activeFence = { char: opener[1][0], length: opener[1].length, start: offset };
    } else if (activeFence) {
      const closer = content.match(/^ {0,3}(`+|~+)\s*$/);
      if (closer && closer[1][0] === activeFence.char && closer[1].length >= activeFence.length) {
        fencedRanges.push({ start: activeFence.start, end: lineEnd });
        activeFence = null;
      }
    }
    offset = lineEnd;
  });
  if (activeFence) fencedRanges.push({ start: activeFence.start, end: text.length });
  ranges.push(...fencedRanges);

  offset = 0;
  lines.forEach((line) => {
    const lineEnd = offset + line.length;
    if (fencedRanges.some((range) => offset >= range.start && offset < range.end)) {
      offset = lineEnd;
      return;
    }
    const content = line.replace(/(?:\r\n|\n|\r)$/, "");
    let cursor = 0;
    while (cursor < content.length) {
      if (content[cursor] !== "`" || isParadigmOntologyRangeImageStartEscaped(content, cursor)) {
        cursor += 1;
        continue;
      }
      let runEnd = cursor + 1;
      while (runEnd < content.length && content[runEnd] === "`") runEnd += 1;
      const runLength = runEnd - cursor;
      let closeStart = -1;
      for (let candidate = runEnd; candidate < content.length;) {
        if (content[candidate] !== "`") {
          candidate += 1;
          continue;
        }
        let candidateEnd = candidate + 1;
        while (candidateEnd < content.length && content[candidateEnd] === "`") candidateEnd += 1;
        if (candidateEnd - candidate === runLength) {
          closeStart = candidate;
          break;
        }
        candidate = candidateEnd;
      }
      const end = closeStart >= 0 ? closeStart + runLength : content.length;
      ranges.push({ start: offset + cursor, end: offset + end });
      cursor = end;
    }
    offset = lineEnd;
  });
  return ranges;
}

function isParadigmOntologyRangeImageStartInCode(codeRanges, index) {
  return codeRanges.some((range) => index >= range.start && index < range.end);
}

function inspectParadigmOntologyRangeImageSyntax(value) {
  const text = String(value || "");
  const records = parseParadigmOntologyImageEmbeds(text);
  const starts = getParadigmOntologyRangeImageLikeStarts(text);
  const codeRanges = getParadigmOntologyRangeCodeRanges(text);
  const errors = [];
  const consumed = new Set();
  starts.forEach((start) => {
    if (isParadigmOntologyRangeImageStartEscaped(text, start.index)) {
      errors.push({ code: "ESCAPED_IMAGE_LIKE_TOKEN", index: start.index, kind: start.kind });
      return;
    }
    if (isParadigmOntologyRangeImageStartInCode(codeRanges, start.index)) {
      errors.push({ code: "CODE_IMAGE_LIKE_TOKEN", index: start.index, kind: start.kind });
      return;
    }
    const matches = records.filter((record) => record.start === start.index);
    if (matches.length !== 1) {
      errors.push({ code: "UNSUPPORTED_OR_MALFORMED_IMAGE_TOKEN", index: start.index, kind: start.kind });
      return;
    }
    const recordIndex = records.indexOf(matches[0]);
    if (consumed.has(recordIndex)) {
      errors.push({ code: "OVERLAPPING_IMAGE_TOKEN", index: start.index, kind: start.kind });
      return;
    }
    consumed.add(recordIndex);
  });
  records.forEach((record, index) => {
    if (!consumed.has(index)) errors.push({ code: "UNACCOUNTED_IMAGE_TOKEN", index: record.start, kind: record.kind });
  });
  return { ok: errors.length === 0, records, errors };
}

function getParadigmOntologyRangePayloadHashInput(payload) {
  const input = deepClone(payload, {}) || {};
  delete input.payloadHash;
  return input;
}

function stabilizeParadigmOntologyRangePayloadByteCount(payloadWithoutHash) {
  const input = deepClone(payloadWithoutHash, {}) || {};
  delete input.payloadHash;
  let byteCount = Math.max(0, Number(input.byteCount) || 0);
  for (let index = 0; index < 12; index += 1) {
    input.byteCount = byteCount;
    const next = workspacePerfByteLength(canonicalJsonString(input));
    if (next === byteCount) return { input, byteCount };
    byteCount = next;
  }
  input.byteCount = byteCount;
  return { input, byteCount: workspacePerfByteLength(canonicalJsonString(input)) };
}

function finalizeParadigmOntologyRangeClipboardPayload(payloadValue, limits = PARADIGM_ONTOLOGY_RANGE_CLIPBOARD_LIMITS) {
  const input = deepClone(payloadValue, {}) || {};
  const payload = {
    version: PARADIGM_ONTOLOGY_RANGE_CLIPBOARD_VERSION,
    vaultScope: sanitizeText(input.vaultScope, ""),
    providerGeneration: sanitizeText(input.providerGeneration, ""),
    rowCount: Math.max(0, Math.floor(Number(input.rowCount) || 0)),
    columnCount: Math.max(0, Math.floor(Number(input.columnCount) || 0)),
    createdAt: Math.max(1, Number(input.createdAt) || Date.now()),
    imageCount: Math.max(0, Math.floor(Number(input.imageCount) || 0)),
    ignoredNestedTableCount: Math.max(0, Math.floor(Number(input.ignoredNestedTableCount) || 0)),
    ignoredReferenceCount: Math.max(0, Math.floor(Number(input.ignoredReferenceCount) || 0)),
    cells: Array.isArray(input.cells) ? input.cells.map((cell) => ({
      rowOffset: Math.max(0, Math.floor(Number(cell?.rowOffset) || 0)),
      columnOffset: Math.max(0, Math.floor(Number(cell?.columnOffset) || 0)),
      body: String(cell?.body || ""),
      lineBreak: String(cell?.lineBreak || "\n"),
      images: Array.isArray(cell?.images) ? cell.images.map((image) => ({
        path: sanitizeText(image?.path, ""),
        size: Number(image?.size),
        mtime: Number(image?.mtime),
      })) : [],
    })) : [],
  };
  payload.cellCount = payload.rowCount * payload.columnCount;
  payload.expiresAt = payload.createdAt + Math.max(1, Number(limits.ttlMs) || 1);
  if (!payload.vaultScope || !payload.providerGeneration) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_SCOPE_INVALID", "Ontology 区域剪贴板缺少 vault 或 editor generation。");
  }
  if (payload.rowCount < 1 || payload.columnCount < 1 || payload.cells.length !== payload.cellCount) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_SHAPE_INVALID", "Ontology 区域剪贴板尺寸无效。");
  }
  if (payload.cellCount > limits.maxCellCount) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_CELL_LIMIT", "Ontology 区域超过 4096 个格子，未复制。");
  }
  payload.cells.forEach((cell, index) => {
    if (cell.rowOffset >= payload.rowCount || cell.columnOffset >= payload.columnCount
      || cell.images.some((image) => !image.path || !Number.isFinite(image.size) || !Number.isFinite(image.mtime))) {
      throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_CELL_INVALID", `Ontology 区域第 ${index + 1} 个格子无效。`);
    }
  });
  const stable = stabilizeParadigmOntologyRangePayloadByteCount(getParadigmOntologyRangePayloadHashInput(payload));
  payload.byteCount = stable.byteCount;
  if (payload.byteCount > limits.maxByteCount) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_BYTE_LIMIT", "Ontology 区域剪贴板超过 1 MiB，未复制。");
  }
  const hashInput = getParadigmOntologyRangePayloadHashInput(payload);
  const restabilized = stabilizeParadigmOntologyRangePayloadByteCount(hashInput);
  payload.byteCount = restabilized.byteCount;
  hashInput.byteCount = payload.byteCount;
  payload.payloadHash = hashCanonicalJson(hashInput);
  return deepFreezeParadigmOntologyRangeValue(payload);
}

function validateParadigmOntologyRangeClipboardPayload(payloadValue, expected = {}, limits = PARADIGM_ONTOLOGY_RANGE_CLIPBOARD_LIMITS) {
  const errors = [];
  let payload;
  try {
    payload = deepClone(payloadValue, null);
    if (!isObjectLike(payload)) throw new Error("剪贴板为空。");
    if (payload.version !== PARADIGM_ONTOLOGY_RANGE_CLIPBOARD_VERSION) errors.push("CLIPBOARD_VERSION_MISMATCH");
    const allowedPayloadKeys = new Set(["version", "vaultScope", "providerGeneration", "rowCount", "columnCount", "cellCount", "createdAt", "expiresAt", "imageCount", "ignoredNestedTableCount", "ignoredReferenceCount", "cells", "byteCount", "payloadHash"]);
    if (Object.keys(payload).some((key) => !allowedPayloadKeys.has(key))) errors.push("CLIPBOARD_FIELDS_INVALID");
    const hashInput = getParadigmOntologyRangePayloadHashInput(payload);
    const stable = stabilizeParadigmOntologyRangePayloadByteCount(hashInput);
    if (Number(payload.byteCount) !== stable.byteCount) errors.push("CLIPBOARD_BYTE_COUNT_MISMATCH");
    hashInput.byteCount = stable.byteCount;
    if (sanitizeText(payload.payloadHash, "") !== hashCanonicalJson(hashInput)) errors.push("CLIPBOARD_HASH_MISMATCH");
    if (Math.max(0, Number(payload.cellCount) || 0) !== Math.max(0, Number(payload.rowCount) || 0) * Math.max(0, Number(payload.columnCount) || 0)
      || !Array.isArray(payload.cells) || payload.cells.length !== Number(payload.cellCount)) errors.push("CLIPBOARD_SHAPE_INVALID");
    if (Number(payload.cellCount) > limits.maxCellCount || Number(payload.byteCount) > limits.maxByteCount) errors.push("CLIPBOARD_LIMIT_EXCEEDED");
    if (Number(expected.now || Date.now()) >= Number(payload.expiresAt || 0)) errors.push("CLIPBOARD_EXPIRED");
    const expectedVaultScope = sanitizeText(expected.vaultScope, "");
    const expectedProviderGeneration = sanitizeText(expected.providerGeneration, "");
    if (!expectedVaultScope || !expectedProviderGeneration) errors.push("CLIPBOARD_SCOPE_UNAVAILABLE");
    if (expectedVaultScope && sanitizeText(payload.vaultScope, "") !== expectedVaultScope) errors.push("CLIPBOARD_VAULT_MISMATCH");
    if (expectedProviderGeneration
      && sanitizeText(payload.providerGeneration, "") !== expectedProviderGeneration) errors.push("CLIPBOARD_GENERATION_MISMATCH");
    payload.cells?.forEach?.((cell) => {
      const allowedCellKeys = new Set(["rowOffset", "columnOffset", "body", "lineBreak", "images"]);
      if (!isObjectLike(cell) || Object.keys(cell).some((key) => !allowedCellKeys.has(key))) errors.push("CLIPBOARD_CELL_FIELDS_INVALID");
      if (!Array.isArray(cell?.images) || cell.images.some((image) => !sanitizeText(image?.path, "")
        || Object.keys(image || {}).some((key) => !["path", "size", "mtime"].includes(key))
        || !Number.isFinite(Number(image?.size)) || !Number.isFinite(Number(image?.mtime)))) errors.push("CLIPBOARD_IMAGE_IDENTITY_INVALID");
    });
    const derivedImageCount = payload.cells?.reduce?.((count, cell) => count + (Array.isArray(cell?.images) ? cell.images.length : 0), 0) || 0;
    if (Number(payload.imageCount) !== derivedImageCount) errors.push("CLIPBOARD_IMAGE_COUNT_MISMATCH");
  } catch (error) {
    errors.push(sanitizeText(error?.message, "CLIPBOARD_INVALID"));
  }
  return {
    ok: errors.length === 0,
    errors: [...new Set(errors)],
    payload: errors.length === 0 ? deepFreezeParadigmOntologyRangeValue(deepClone(payload, null)) : null,
  };
}

function getParadigmOntologyRangeCellOccupancy(cell) {
  const reasons = [];
  if (!isObjectLike(cell)) return { occupied: true, reasons: ["CELL_MISSING_OR_INVALID"] };
  if (typeof cell.value !== "string" || cell.value.length > 0) reasons.push("CELL_VALUE_PRESENT");
  if (cell.nestedTableId !== null && typeof cell.nestedTableId !== "undefined" && cell.nestedTableId !== "") reasons.push("CELL_NESTED_TABLE_PRESENT");
  if (Object.prototype.hasOwnProperty.call(cell, "reference")) reasons.push("CELL_REFERENCE_PRESENT");
  return { occupied: reasons.length > 0, reasons };
}

function buildParadigmOntologyRangeRefs(tableId, rowIds, columnIds, anchorRef, extentRef) {
  const rows = Array.isArray(rowIds) ? rowIds.map((id) => sanitizeText(id, "")) : [];
  const columns = Array.isArray(columnIds) ? columnIds.map((id) => sanitizeText(id, "")) : [];
  const anchorRow = rows.indexOf(sanitizeText(anchorRef?.rowId, ""));
  const anchorColumn = columns.indexOf(sanitizeText(anchorRef?.columnId, ""));
  const extentRow = rows.indexOf(sanitizeText(extentRef?.rowId, ""));
  const extentColumn = columns.indexOf(sanitizeText(extentRef?.columnId, ""));
  if ([anchorRow, anchorColumn, extentRow, extentColumn].some((index) => index < 0)) return { ok: false, code: "ONTOLOGY_RANGE_SELECTION_INVALID", refs: [] };
  const minRow = Math.min(anchorRow, extentRow);
  const maxRow = Math.max(anchorRow, extentRow);
  const minColumn = Math.min(anchorColumn, extentColumn);
  const maxColumn = Math.max(anchorColumn, extentColumn);
  const refs = [];
  for (let rowIndex = minRow; rowIndex <= maxRow; rowIndex += 1) {
    for (let columnIndex = minColumn; columnIndex <= maxColumn; columnIndex += 1) {
      refs.push({
        tableId: sanitizeText(tableId, ""),
        rowId: rows[rowIndex],
        columnId: columns[columnIndex],
        rowOffset: rowIndex - minRow,
        columnOffset: columnIndex - minColumn,
      });
    }
  }
  return {
    ok: true,
    rowCount: maxRow - minRow + 1,
    columnCount: maxColumn - minColumn + 1,
    refs,
  };
}

function inspectParadigmOntologyRangePasteTarget(ontology, options = {}) {
  const tableId = sanitizeText(options.tableId, "");
  const table = ontology?.tablesById?.[tableId];
  const rowIds = Array.isArray(options.rowIds) ? options.rowIds.map((id) => sanitizeText(id, "")) : [];
  const columnIds = Array.isArray(options.columnIds) ? options.columnIds.map((id) => sanitizeText(id, "")) : [];
  const payload = options.payload;
  if (!table || canonicalJsonString(table.rowOrder || []) !== canonicalJsonString(rowIds)) {
    return { ok: false, code: "ONTOLOGY_RANGE_TARGET_ROWS_CHANGED", conflicts: [], targetRefs: [] };
  }
  const startRow = rowIds.indexOf(sanitizeText(options.targetRowId, ""));
  const startColumn = columnIds.indexOf(sanitizeText(options.targetColumnId, ""));
  const rowCount = Math.max(0, Number(payload?.rowCount) || 0);
  const columnCount = Math.max(0, Number(payload?.columnCount) || 0);
  if (startRow < 0 || startColumn < 0 || rowCount < 1 || columnCount < 1
    || startRow + rowCount > rowIds.length || startColumn + columnCount > columnIds.length) {
    return { ok: false, code: "ONTOLOGY_RANGE_TARGET_OUT_OF_BOUNDS", conflicts: [], targetRefs: [] };
  }
  const targetRefs = [];
  const conflicts = [];
  for (let rowOffset = 0; rowOffset < rowCount; rowOffset += 1) {
    for (let columnOffset = 0; columnOffset < columnCount; columnOffset += 1) {
      const ref = {
        tableId,
        rowId: rowIds[startRow + rowOffset],
        columnId: columnIds[startColumn + columnOffset],
        rowOffset,
        columnOffset,
      };
      targetRefs.push(ref);
      const cell = table.rowsById?.[ref.rowId]?.cellsByColumnId?.[ref.columnId];
      const occupancy = getParadigmOntologyRangeCellOccupancy(cell);
      if (occupancy.occupied) conflicts.push({ ref, reasons: occupancy.reasons });
    }
  }
  const signature = hashCanonicalJson({
    tableId,
    rowIds,
    columnIds,
    targetRefs,
    conflicts,
    payloadHash: sanitizeText(payload?.payloadHash, ""),
  });
  return {
    ok: conflicts.length === 0,
    code: conflicts.length > 0 ? "ONTOLOGY_RANGE_TARGET_OCCUPIED" : "ONTOLOGY_RANGE_TARGET_READY",
    conflicts,
    targetRefs,
    signature,
  };
}

function createParadigmOntologyRangePasteCandidate(ontology, targetRefs, materializedCells) {
  const candidate = deepClone(ontology, null);
  if (!candidate || !Array.isArray(targetRefs) || !Array.isArray(materializedCells) || targetRefs.length !== materializedCells.length) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_PASTE_INVALID", "Ontology 区域粘贴数据不完整。");
  }
  const timestamp = nowString();
  const touchedRows = new Set();
  const touchedTables = new Set();
  targetRefs.forEach((ref, index) => {
    const table = candidate.tablesById?.[sanitizeText(ref?.tableId, "")];
    const row = table?.rowsById?.[sanitizeText(ref?.rowId, "")];
    const cell = row?.cellsByColumnId?.[sanitizeText(ref?.columnId, "")];
    const occupancy = getParadigmOntologyRangeCellOccupancy(cell);
    if (occupancy.occupied) {
      throw createParadigmOntologyContractError("ONTOLOGY_RANGE_TARGET_OCCUPIED", "目标区域已经包含内容或结构，未粘贴。", { ref, reasons: occupancy.reasons });
    }
    cell.value = String(materializedCells[index]?.value || "");
    row.updatedAt = timestamp;
    table.updatedAt = timestamp;
    touchedRows.add(`${table.id}\u0000${row.id}`);
    touchedTables.add(table.id);
  });
  candidate.updatedAt = timestamp;
  const validation = validateParadigmOntology(candidate);
  if (!validation.ok) {
    throw createParadigmOntologyContractError("ONTOLOGY_RANGE_PASTE_VALIDATION_FAILED", validation.errors[0] || "Ontology 区域粘贴后结构校验失败。", { errors: validation.errors });
  }
  return {
    candidate,
    byteCount: validation.stats?.bytes || workspacePerfByteLength(canonicalJsonString(candidate)),
    touchedRowCount: touchedRows.size,
    touchedTableCount: touchedTables.size,
  };
}

function hasParadigmOntologyContent(ontology) {
  if (Object.values(ontology?.schemasById || {}).some((schema) => paradigmOntologySchemaHasRetainedLineage(schema))) return true;
  if (!isObjectLike(ontology?.tablesById)) return false;
  try {
    for (const table of Object.values(ontology.tablesById)) {
      if (!isObjectLike(table?.rowsById)) continue;
      for (const row of Object.values(table.rowsById)) {
        if (!isObjectLike(row?.cellsByColumnId)) continue;
        for (const cell of Object.values(row.cellsByColumnId)) {
          try {
            if (paradigmOntologyCellHasRetainedData(cell)) return true;
          } catch (_) {}
        }
      }
    }
  } catch (_) {
    return false;
  }
  return false;
}

function paradigmItemOwnsOntology(item) {
  return isObjectLike(item)
    && Object.prototype.hasOwnProperty.call(item, "ontology")
    && item.ontology !== null
    && typeof item.ontology !== "undefined";
}

function getMountedParadigmItemIdentity(item) {
  if (!isObjectLike(item)
    || sanitizeText(item.id, "") === ""
    || item.sourceType !== "paradigm"
    || sanitizeText(item.sourceParadigmId, "") === ""
    || sanitizeText(item.sourceParadigmItemId, "") === "") {
    return null;
  }
  return {
    mountedItemId: sanitizeText(item.id, ""),
    tabId: sanitizeText(item.tabId, ""),
    sourceType: "paradigm",
    sourceParadigmId: sanitizeText(item.sourceParadigmId, ""),
    sourceParadigmItemId: sanitizeText(item.sourceParadigmItemId, ""),
    sourceParadigmMountScopeId: sanitizeText(item.sourceParadigmMountScopeId, ""),
    sourceParadigmBindingRootId: sanitizeText(item.sourceParadigmBindingRootId, ""),
  };
}

function getMountedParadigmItemIdentitySignature(identity) {
  if (!isObjectLike(identity)) return "";
  return JSON.stringify([
    sanitizeText(identity.mountedItemId, ""),
    sanitizeText(identity.tabId, ""),
    sanitizeText(identity.sourceType, ""),
    sanitizeText(identity.sourceParadigmId, ""),
    sanitizeText(identity.sourceParadigmItemId, ""),
    sanitizeText(identity.sourceParadigmMountScopeId, ""),
    sanitizeText(identity.sourceParadigmBindingRootId, ""),
  ]);
}

function collectParadigmSubtreeItemIdsFromData(data, paradigmId, startParadigmItemId) {
  const normalizedParadigmId = sanitizeText(paradigmId, "");
  const startId = sanitizeText(startParadigmItemId, "");
  if (!normalizedParadigmId || !startId) return [];
  const out = [];
  const seen = new Set();
  const stack = [startId];
  while (stack.length > 0) {
    const current = sanitizeText(stack.pop(), "");
    if (!current || seen.has(current)) continue;
    const item = data?.paradigmItemsById?.[current];
    if (!item || sanitizeText(item.paradigmId, "") !== normalizedParadigmId) continue;
    seen.add(current);
    out.push(current);
    const childIds = ensureUniqueIds(data?.paradigmChildrenByParent?.[paradigmParentKey(normalizedParadigmId, current)] || []);
    for (let index = childIds.length - 1; index >= 0; index -= 1) stack.push(childIds[index]);
  }
  return out;
}

function getParadigmOntologyDeletionProtection(data, itemIds = []) {
  const ids = ensureUniqueIds(itemIds).filter((id) => !!data?.paradigmItemsById?.[id]);
  const protectedIds = ids.filter((id) => paradigmItemOwnsOntology(data?.paradigmItemsById?.[id]));
  return {
    itemIds: ids,
    signature: ids.slice().sort().join("\u001f"),
    protectedIds,
    protected: protectedIds.length > 0,
  };
}

function createParadigmDeletionRefusal(code, message, detail = {}) {
  const error = new Error(message);
  error.code = code;
  error.detail = detail;
  return error;
}

function createParadigmOntologyCell(value = "") {
  return {
    value: String(value || ""),
    nestedTableId: null,
  };
}

function createParadigmOntologyContractError(code, message, detail = {}) {
  const error = new Error(message);
  error.code = code;
  error.detail = detail;
  return error;
}

function normalizeParadigmOntologyStableRef(value) {
  if (value == null || typeof value === "function" || typeof value === "symbol") {
    throw createParadigmOntologyContractError("ONTOLOGY_ADDRESS_INVALID", "Ontology ownerStableRef 无效。");
  }
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    const normalized = sanitizeText(value, "");
    if (!normalized) throw createParadigmOntologyContractError("ONTOLOGY_ADDRESS_INVALID", "Ontology ownerStableRef 不能为空。");
    return normalized;
  }
  let cloned;
  try {
    cloned = JSON.parse(JSON.stringify(value));
  } catch (_) {
    throw createParadigmOntologyContractError("ONTOLOGY_ADDRESS_INVALID", "Ontology ownerStableRef 必须可序列化。");
  }
  if (!isObjectLike(cloned) || Object.keys(cloned).length === 0) {
    throw createParadigmOntologyContractError("ONTOLOGY_ADDRESS_INVALID", "Ontology ownerStableRef 必须是非空稳定引用。");
  }
  return canonicalizeJson(cloned);
}

function normalizeParadigmOntologyAddress(rawAddress, expectedVersion, terminalKey) {
  if (!isObjectLike(rawAddress)) {
    throw createParadigmOntologyContractError("ONTOLOGY_ADDRESS_INVALID", "Ontology 地址缺失。");
  }
  const addressVersion = sanitizeText(rawAddress.addressVersion, "");
  if (addressVersion !== expectedVersion) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_ADDRESS_VERSION_UNSUPPORTED",
      `不支持的 Ontology 地址版本：${addressVersion || "missing"}`,
    );
  }
  const normalized = {
    addressVersion,
    providerId: sanitizeText(rawAddress.providerId, ""),
    scopeId: sanitizeText(rawAddress.scopeId, ""),
    familyId: sanitizeText(rawAddress.familyId, ""),
    ownerStableRefVersion: sanitizeText(rawAddress.ownerStableRefVersion, ""),
    ownerStableRef: normalizeParadigmOntologyStableRef(rawAddress.ownerStableRef),
    documentId: sanitizeText(rawAddress.documentId, ""),
    [terminalKey]: sanitizeText(rawAddress[terminalKey], ""),
  };
  if (expectedVersion === PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION) {
    normalized.rowId = sanitizeText(rawAddress.rowId, "");
    normalized.columnId = sanitizeText(rawAddress.columnId, "");
  }
  const required = ["providerId", "scopeId", "familyId", "ownerStableRefVersion", "documentId", terminalKey]
    .concat(expectedVersion === PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION ? ["rowId", "columnId"] : []);
  const missing = required.filter((key) => !sanitizeText(normalized[key], ""));
  if (missing.length > 0) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_ADDRESS_INVALID",
      `Ontology 地址缺少字段：${missing.join(", ")}`,
      { missing },
    );
  }
  return canonicalizeJson(normalized);
}

function normalizeParadigmOntologyCellAddress(rawAddress) {
  return normalizeParadigmOntologyAddress(rawAddress, PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION, "tableId");
}

function normalizeParadigmOntologySchemaAddress(rawAddress) {
  const version = sanitizeText(rawAddress?.addressVersion, "");
  if (version === PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_VERSION) {
    return normalizeParadigmOntologyAddress(rawAddress, PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_VERSION, "schemaId");
  }
  if (version !== PARADIGM_ONTOLOGY_SCHEMA_AUTHORITY_ADDRESS_VERSION || !isObjectLike(rawAddress)) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_ADDRESS_VERSION_UNSUPPORTED",
      `不支持的 Ontology 地址版本：${version || "missing"}`,
    );
  }
  const normalized = {
    addressVersion: version,
    providerId: sanitizeText(rawAddress.providerId, ""),
    scopeId: sanitizeText(rawAddress.scopeId, ""),
    familyId: sanitizeText(rawAddress.familyId, ""),
    authorityStableRefVersion: sanitizeText(rawAddress.authorityStableRefVersion, ""),
    authorityStableRef: normalizeParadigmOntologyStableRef(rawAddress.authorityStableRef),
    schemaId: sanitizeText(rawAddress.schemaId, ""),
  };
  if (isObjectLike(rawAddress.navigationContext)) {
    normalized.navigationContext = canonicalizeJson(deepClone(rawAddress.navigationContext, null));
  }
  const missing = ["providerId", "scopeId", "familyId", "authorityStableRefVersion", "schemaId"]
    .filter((key) => !sanitizeText(normalized[key], ""));
  if (missing.length > 0) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_ADDRESS_INVALID",
      `Ontology schema authority 地址缺少字段：${missing.join(", ")}`,
      { missing },
    );
  }
  return canonicalizeJson(normalized);
}

function getParadigmOntologySchemaAddressDocumentId(address) {
  const normalized = normalizeParadigmOntologySchemaAddress(address);
  return normalized.addressVersion === PARADIGM_ONTOLOGY_SCHEMA_AUTHORITY_ADDRESS_VERSION
    ? sanitizeText(normalized.authorityStableRef?.documentId, "")
    : sanitizeText(normalized.documentId, "");
}

function serializeParadigmOntologyAddress(rawAddress) {
  const version = sanitizeText(rawAddress?.addressVersion, "");
  const normalized = version === PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION
    ? normalizeParadigmOntologyCellAddress(rawAddress)
    : normalizeParadigmOntologySchemaAddress(rawAddress);
  return canonicalJsonString(normalized);
}

function createParadigmOntologyCellReference(sourceAddress, evidence = {}) {
  return {
    referenceVersion: PARADIGM_ONTOLOGY_CELL_REFERENCE_VERSION,
    sourceAddress: normalizeParadigmOntologyCellAddress(sourceAddress),
    sourceRevision: sanitizeText(evidence.sourceRevision, ""),
    sourceHash: sanitizeText(evidence.sourceHash, ""),
    capturedAt: sanitizeText(evidence.capturedAt, nowString()),
    sourceLabel: sanitizeText(evidence.sourceLabel, ""),
    sourceBreadcrumb: sanitizeText(evidence.sourceBreadcrumb, ""),
  };
}

function validateParadigmOntologyCellReference(reference) {
  const errors = [];
  if (!isObjectLike(reference)) return { ok: false, errors: ["Cell reference is missing."], reference: null };
  if (Number(reference.referenceVersion) !== PARADIGM_ONTOLOGY_CELL_REFERENCE_VERSION) {
    errors.push(`Unsupported cell referenceVersion: ${String(reference.referenceVersion ?? "missing")}`);
  }
  let sourceAddress = null;
  try {
    sourceAddress = normalizeParadigmOntologyCellAddress(reference.sourceAddress);
  } catch (error) {
    errors.push(error.message);
  }
  if (!sanitizeText(reference.capturedAt, "")) errors.push("Cell reference capturedAt is missing.");
  return {
    ok: errors.length === 0,
    errors,
    reference: errors.length === 0 ? createParadigmOntologyCellReference(sourceAddress, reference) : null,
  };
}

function paradigmOntologyCellHasRetainedData(cell) {
  return sanitizeText(cell?.value, "") !== "" || isObjectLike(cell?.reference);
}

function paradigmOntologySchemaHasRetainedLineage(schema) {
  return isObjectLike(schema?.sourceLineage);
}

function hasParadigmOntologyReferenceState(ontology) {
  return collectParadigmOntologyOutboundReferences(ontology).length > 0
    || Object.values(ontology?.schemasById || {}).some(paradigmOntologySchemaHasRetainedLineage);
}

function resolveParadigmOntologyCellByAddress(ontology, address) {
  let normalized;
  try { normalized = normalizeParadigmOntologyCellAddress(address); } catch (_) { return null; }
  if (sanitizeText(ontology?.documentId, "") !== normalized.documentId) return null;
  const table = ontology?.tablesById?.[normalized.tableId];
  const row = table?.rowsById?.[normalized.rowId];
  const cell = row?.cellsByColumnId?.[normalized.columnId];
  return table && row && cell ? { address: normalized, table, row, cell } : null;
}

function getParadigmOntologyCellProjection(ontology, address) {
  const resolved = resolveParadigmOntologyCellByAddress(ontology, address);
  if (!resolved) return null;
  const schema = ontology?.schemasById?.[sanitizeText(resolved.table?.schemaId, "")];
  const column = schema?.columnsById?.[resolved.address.columnId];
  if (!schema || !column) return null;
  const schemasById = {};
  const tablesById = {};
  const schemaQueue = [sanitizeText(column.childSchemaId, "")].filter(Boolean);
  const seenSchemas = new Set();
  while (schemaQueue.length > 0) {
    const schemaId = schemaQueue.shift();
    if (!schemaId || seenSchemas.has(schemaId)) continue;
    if (seenSchemas.size >= PARADIGM_ONTOLOGY_LIMITS.maxTables) {
      throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_PROJECTION_LIMIT", "引用来源的递归 schema 超过安全上限。");
    }
    const childSchema = ontology?.schemasById?.[schemaId];
    if (!childSchema) throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_SOURCE_INVALID", "引用来源的递归 schema 不完整。");
    seenSchemas.add(schemaId);
    schemasById[schemaId] = deepClone(childSchema, null);
    getParadigmOntologySchemaColumnIds(childSchema, true).forEach((columnId) => {
      const nestedSchemaId = sanitizeText(childSchema.columnsById?.[columnId]?.childSchemaId, "");
      if (nestedSchemaId && !seenSchemas.has(nestedSchemaId)) schemaQueue.push(nestedSchemaId);
    });
  }
  const tableQueue = [sanitizeText(resolved.cell?.nestedTableId, "")].filter(Boolean);
  const seenTables = new Set();
  while (tableQueue.length > 0) {
    const tableId = tableQueue.shift();
    if (!tableId || seenTables.has(tableId)) continue;
    if (seenTables.size >= PARADIGM_ONTOLOGY_LIMITS.maxTables) {
      throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_PROJECTION_LIMIT", "引用来源的递归表实例超过安全上限。");
    }
    const table = ontology?.tablesById?.[tableId];
    if (!table) throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_SOURCE_INVALID", "引用来源的递归表实例不完整。");
    seenTables.add(tableId);
    tablesById[tableId] = deepClone(table, null);
    getParadigmOntologyTableChildren(ontology, table).forEach((childId) => {
      if (!seenTables.has(childId)) tableQueue.push(childId);
    });
  }
  const projection = {
    value: String(resolved.cell?.value || ""),
    cell: deepClone(resolved.cell, null),
    column: deepClone(column, null),
    table: { id: resolved.table.id, schemaId: resolved.table.schemaId },
    row: { id: resolved.row.id },
    childSchemaId: sanitizeText(column.childSchemaId, ""),
    nestedTableId: sanitizeText(resolved.cell?.nestedTableId, ""),
    schemasById,
    tablesById,
  };
  if (workspacePerfByteLength(canonicalJsonString(projection)) > PARADIGM_ONTOLOGY_LIMITS.maxBytes) {
    throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_PROJECTION_LIMIT", "引用来源投影超过安全字节上限。");
  }
  return projection;
}

function getParadigmOntologyColumnPath(ontology, tableIdValue, columnIdValue) {
  const labels = [];
  const visited = new Set();
  let tableId = sanitizeText(tableIdValue, "");
  let columnId = sanitizeText(columnIdValue, "");
  while (tableId && columnId && !visited.has(tableId) && labels.length < PARADIGM_ONTOLOGY_LIMITS.maxDepth) {
    visited.add(tableId);
    const table = ontology?.tablesById?.[tableId];
    const schema = ontology?.schemasById?.[sanitizeText(table?.schemaId, "")];
    const column = schema?.columnsById?.[columnId];
    if (!table || !schema || !column) break;
    labels.unshift(sanitizeText(column.label, columnId).slice(0, 120));
    if (tableId === sanitizeText(ontology?.rootTableId, "")) break;
    const parentRef = table.parentCellRef;
    tableId = sanitizeText(parentRef?.parentTableId, "");
    columnId = sanitizeText(parentRef?.parentColumnId, "");
  }
  return labels.filter(Boolean);
}

function createWorkspaceOntologyReferenceDescriptor(entry, ontology, tableId, columnId) {
  const columnPath = getParadigmOntologyColumnPath(ontology, tableId, columnId);
  const sourceLabel = sanitizeText(entry?.sourceGroupLabel, "范式");
  const ownerLabel = sanitizeText(entry?.title, entry?.ownerKey);
  return {
    providerLabel: "Workspace Mount",
    familyLabel: "范式",
    sourceLabel,
    ownerLabel,
    columnPath,
    pathLabel: ["范式", sourceLabel, ownerLabel, ...columnPath].filter(Boolean).join(" / "),
  };
}

function collectParadigmOntologyOutboundReferences(ontology) {
  const edges = [];
  Object.values(ontology?.tablesById || {}).forEach((table) => {
    Object.values(table?.rowsById || {}).forEach((row) => {
      Object.entries(row?.cellsByColumnId || {}).forEach(([columnId, cell]) => {
        if (!isObjectLike(cell?.reference)) return;
        const validation = validateParadigmOntologyCellReference(cell.reference);
        if (!validation.ok) return;
        edges.push({
          tableId: sanitizeText(table.id, ""),
          rowId: sanitizeText(row.id, ""),
          columnId: sanitizeText(columnId, ""),
          sourceAddress: validation.reference.sourceAddress,
          sourceKey: serializeParadigmOntologyAddress(validation.reference.sourceAddress),
        });
      });
    });
  });
  return edges.sort((left, right) => canonicalJsonString(left).localeCompare(canonicalJsonString(right)));
}

function diffParadigmOntologyOutboundReferences(baseOntology, draftOntology) {
  const toMap = (ontology) => new Map(collectParadigmOntologyOutboundReferences(ontology).map((edge) => [
    `${edge.tableId}\u0000${edge.rowId}\u0000${edge.columnId}`,
    edge,
  ]));
  const before = toMap(baseOntology);
  const after = toMap(draftOntology);
  const added = [];
  const removed = [];
  const redirected = [];
  after.forEach((edge, targetKey) => {
    const prior = before.get(targetKey);
    if (!prior) added.push(edge);
    else if (prior.sourceKey !== edge.sourceKey) redirected.push({ before: prior, after: edge });
  });
  before.forEach((edge, targetKey) => {
    if (!after.has(targetKey)) removed.push(edge);
  });
  return { added, removed, redirected };
}

function wouldCreateParadigmOntologyReferenceCycle(edgesLike, sourceKey, targetKey) {
  const source = sanitizeText(sourceKey, "");
  const target = sanitizeText(targetKey, "");
  if (!source || !target || source === target) return true;
  const adjacency = new Map();
  (Array.isArray(edgesLike) ? edgesLike : []).forEach((edge) => {
    const from = sanitizeText(edge?.targetKey, "");
    const to = sanitizeText(edge?.sourceKey, "");
    if (!from || !to) return;
    if (!adjacency.has(from)) adjacency.set(from, new Set());
    adjacency.get(from).add(to);
  });
  if (!adjacency.has(target)) adjacency.set(target, new Set());
  adjacency.get(target).add(source);
  const pending = [source];
  const visited = new Set();
  while (pending.length > 0) {
    const current = pending.pop();
    if (current === target) return true;
    if (visited.has(current)) continue;
    visited.add(current);
    (adjacency.get(current) || []).forEach((next) => pending.push(next));
  }
  return false;
}

function getParadigmOntologySchemaColumnIds(schema, includeArchived = true) {
  const active = Array.isArray(schema?.columnOrder) ? schema.columnOrder : [];
  const archived = includeArchived && Array.isArray(schema?.archivedColumnOrder) ? schema.archivedColumnOrder : [];
  return [...new Set([...active, ...archived].map((id) => sanitizeText(id, "")).filter(Boolean))];
}

function reserveParadigmOntologyColumnIds(ontology, columnIds = []) {
  if (!isObjectLike(ontology)) return;
  const reserved = new Set(Array.isArray(ontology.reservedColumnIds) ? ontology.reservedColumnIds : []);
  columnIds.forEach((id) => {
    const normalized = sanitizeText(id, "");
    if (normalized) reserved.add(normalized);
  });
  ontology.reservedColumnIds = Array.from(reserved);
}

function createReservedParadigmOntologyColumnId(ontology) {
  const reserved = new Set(Array.isArray(ontology?.reservedColumnIds) ? ontology.reservedColumnIds : []);
  let columnId = "";
  do columnId = createId("pgOntCol"); while (reserved.has(columnId));
  reserveParadigmOntologyColumnIds(ontology, [columnId]);
  return columnId;
}

function upgradeParadigmOntologyToV2(rawOntology) {
  if (!isObjectLike(rawOntology)) return rawOntology;
  const draft = deepClone(rawOntology, rawOntology);
  if (Number(draft.schemaVersion) >= 2) return draft;
  if (Number(draft.schemaVersion) !== 1) return draft;
  const timestamp = nowString();
  const reserved = [];
  Object.values(draft.schemasById || {}).forEach((schema) => {
    schema.archivedColumnOrder = [];
    (Array.isArray(schema.columnOrder) ? schema.columnOrder : []).forEach((columnId) => {
      const column = schema.columnsById?.[columnId];
      if (!column) return;
      column.lifecycleState = "active";
      column.archivedAt = null;
      reserved.push(columnId);
    });
  });
  draft.schemaVersion = 2;
  draft.reservedColumnIds = [...new Set(reserved)];
  draft.migratedFromSchemaVersion = 1;
  draft.migratedAt = timestamp;
  draft.updatedAt = timestamp;
  return draft;
}

function upgradeParadigmOntologyToV3(rawOntology) {
  if (!isObjectLike(rawOntology)) return rawOntology;
  let draft = upgradeParadigmOntologyToV2(rawOntology);
  if (!isObjectLike(draft)) return draft;
  if (Number(draft.schemaVersion) === PARADIGM_ONTOLOGY_SCHEMA_VERSION) return draft;
  if (Number(draft.schemaVersion) !== 2) return draft;
  const timestamp = nowString();
  draft.schemaVersion = PARADIGM_ONTOLOGY_SCHEMA_VERSION;
  draft.migratedFromSchemaVersion = Number(rawOntology.schemaVersion) || 2;
  draft.migratedAt = timestamp;
  draft.updatedAt = timestamp;
  return draft;
}

function createParadigmOntologyRow(schema, valueByColumnId = {}) {
  const rowId = createId("pgOntRow");
  const cellsByColumnId = {};
  for (const columnId of getParadigmOntologySchemaColumnIds(schema, true)) {
    cellsByColumnId[columnId] = createParadigmOntologyCell(valueByColumnId?.[columnId]);
  }
  const timestamp = nowString();
  return {
    id: rowId,
    cellsByColumnId,
    createdAt: timestamp,
    updatedAt: timestamp,
  };
}

function createParadigmOntologySchema(name = "表格", columns = [], ontology = null) {
  const schemaId = createId("pgOntSchema");
  const timestamp = nowString();
  const schema = {
    id: schemaId,
    name: sanitizeText(name, "表格"),
    columnOrder: [],
    archivedColumnOrder: [],
    columnsById: {},
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  (Array.isArray(columns) ? columns : []).forEach((rawColumn) => {
    const columnId = ontology ? createReservedParadigmOntologyColumnId(ontology) : createId("pgOntCol");
    const description = typeof rawColumn?.description === "string" ? rawColumn.description : "";
    schema.columnOrder.push(columnId);
    schema.columnsById[columnId] = {
      id: columnId,
      label: sanitizeText(rawColumn?.label, "未命名列"),
      cellType: sanitizeText(rawColumn?.cellType, "long-text"),
      childSchemaId: sanitizeText(rawColumn?.childSchemaId, "") || null,
      ...(description ? { description } : {}),
      lifecycleState: "active",
      archivedAt: null,
      createdAt: timestamp,
      updatedAt: timestamp,
    };
  });
  return schema;
}

function buildParadigmOntologySchemaAddressFromTemplate(template, schemaId) {
  return normalizeParadigmOntologySchemaAddress(Object.assign({}, template, {
    addressVersion: sanitizeText(template?.addressVersion, PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_VERSION),
    schemaId: sanitizeText(schemaId, ""),
  }));
}

function restoreParadigmOntologySchemaLineageFromProvenance(
  targetOntology,
  localRootSchemaId,
  sourceOntology,
  sourceSchemaId,
  sourceSchemaAddress,
) {
  const rootLocalId = sanitizeText(localRootSchemaId, "");
  const rootSourceId = sanitizeText(sourceSchemaId, "");
  const normalizedRootAddress = normalizeParadigmOntologySchemaAddress(sourceSchemaAddress);
  const reject = (message) => {
    throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_LINEAGE_CONFLICT", message);
  };
  const candidates = (Array.isArray(targetOntology?.schemaProvenanceHistory)
    ? targetOntology.schemaProvenanceHistory
    : [])
    .filter((record) => sanitizeText(record?.rootLocalSchemaId, "") === rootLocalId)
    .map((record) => {
      const timestamp = Date.parse(sanitizeText(record?.detachedAt, ""));
      const eventId = sanitizeText(record?.eventId, "");
      if (!Number.isFinite(timestamp) || !eventId) reject("共享结构来源历史缺少可确定的时间或事件 ID。");
      return { record, timestamp, eventId };
    });
  if (candidates.length === 0) return false;
  const eventKeys = new Set();
  candidates.forEach((entry) => {
    const key = `${entry.timestamp}\u0000${entry.eventId}`;
    if (eventKeys.has(key)) reject("共享结构来源历史包含重复事件，不能自动恢复。");
    eventKeys.add(key);
  });
  candidates.sort((left, right) => left.timestamp - right.timestamp || left.eventId.localeCompare(right.eventId));
  const latest = candidates[candidates.length - 1].record;
  if (sanitizeText(latest?.type, "") !== "shared-schema-detached"
    || sanitizeText(latest?.outcome, "") !== "forked-local") {
    reject("目标列已有本地子表结构，且最新来源历史不是可恢复的共享结构分叉。");
  }
  const lineageSnapshots = Array.isArray(latest.lineages) ? latest.lineages : [];
  if (lineageSnapshots.length === 0) reject("共享结构来源历史缺少递归 lineage 快照。");

  const localGraphIds = collectParadigmOntologySchemaGraphIds(targetOntology, rootLocalId);
  const sourceGraphIds = collectParadigmOntologySchemaGraphIds(sourceOntology, rootSourceId);
  if (localGraphIds.length === 0 || sourceGraphIds.length === 0
    || lineageSnapshots.length !== localGraphIds.length
    || lineageSnapshots.length !== sourceGraphIds.length) {
    reject("共享结构来源历史与当前递归 Schema 数量不一致。");
  }
  const localGraphSet = new Set(localGraphIds);
  const sourceGraphSet = new Set(sourceGraphIds);
  const snapshotByLocalId = new Map();
  const localIdBySourceId = new Map();
  lineageSnapshots.forEach((snapshot) => {
    const localId = sanitizeText(snapshot?.localSchemaId, "");
    const lineage = snapshot?.sourceLineage;
    if (!localId || snapshotByLocalId.has(localId) || !localGraphSet.has(localId) || !isObjectLike(lineage)) {
      reject("共享结构来源历史包含重复、额外或无效的本地 Schema 映射。");
    }
    let sourceAddress;
    try { sourceAddress = normalizeParadigmOntologySchemaAddress(lineage.sourceSchemaAddress); }
    catch (_) { reject("共享结构来源历史包含无效的来源 Schema 地址。"); }
    const sourceId = sanitizeText(sourceAddress?.schemaId, "");
    const expectedAddress = buildParadigmOntologySchemaAddressFromTemplate(normalizedRootAddress, sourceId);
    if (!sourceGraphSet.has(sourceId)
      || localIdBySourceId.has(sourceId)
      || serializeParadigmOntologyAddress(sourceAddress) !== serializeParadigmOntologyAddress(expectedAddress)) {
      reject("共享结构来源历史与本次正式来源地址不一致。");
    }
    snapshotByLocalId.set(localId, snapshot);
    localIdBySourceId.set(sourceId, localId);
  });
  if (snapshotByLocalId.size !== localGraphSet.size || localIdBySourceId.size !== sourceGraphSet.size
    || localGraphIds.some((id) => !snapshotByLocalId.has(id))
    || sourceGraphIds.some((id) => !localIdBySourceId.has(id))) {
    reject("共享结构来源历史存在未消费或缺失的递归 Schema 映射。");
  }
  if (localIdBySourceId.get(rootSourceId) !== rootLocalId) {
    reject("共享结构来源历史的根 Schema 映射不一致。");
  }

  lineageSnapshots.forEach((snapshot) => {
    const localId = sanitizeText(snapshot.localSchemaId, "");
    const lineage = snapshot.sourceLineage;
    const sourceId = normalizeParadigmOntologySchemaAddress(lineage.sourceSchemaAddress).schemaId;
    const localSchema = targetOntology.schemasById?.[localId];
    const sourceSchema = sourceOntology.schemasById?.[sourceId];
    if (!localSchema || !sourceSchema || sanitizeText(localSchema.name, "") !== sanitizeText(sourceSchema.name, "")) {
      reject("共享结构的 Schema 名称与正式来源不一致。");
    }
    const sourceColumnIds = getParadigmOntologySchemaColumnIds(sourceSchema, true);
    const localColumnIds = getParadigmOntologySchemaColumnIds(localSchema, true);
    const mappingOrder = Array.isArray(lineage.mappingOrder) ? lineage.mappingOrder.map((id) => sanitizeText(id, "")) : [];
    const mappings = isObjectLike(lineage.mappingsBySourceColumnId) ? lineage.mappingsBySourceColumnId : {};
    const mappingKeys = Object.keys(mappings);
    if (new Set(mappingOrder).size !== mappingOrder.length
      || canonicalJsonString(mappingOrder) !== canonicalJsonString(sourceColumnIds)
      || new Set(mappingKeys).size !== mappingKeys.length
      || mappingKeys.length !== sourceColumnIds.length
      || sourceColumnIds.some((id) => !Object.prototype.hasOwnProperty.call(mappings, id))) {
      reject("共享结构的列映射不完整或存在重复。");
    }
    const mappedLocalIds = mappingOrder.map((sourceColumnId) => sanitizeText(mappings[sourceColumnId]?.localColumnId, ""));
    if (mappedLocalIds.some((id) => !id)
      || new Set(mappedLocalIds).size !== mappedLocalIds.length
      || mappedLocalIds.length !== localColumnIds.length
      || localColumnIds.some((id) => !mappedLocalIds.includes(id))) {
      reject("共享结构的本地列映射不完整或存在重复。");
    }
    const expectedActiveOrder = (sourceSchema.columnOrder || []).map((id) => sanitizeText(mappings[id]?.localColumnId, ""));
    const expectedArchivedOrder = (sourceSchema.archivedColumnOrder || []).map((id) => sanitizeText(mappings[id]?.localColumnId, ""));
    if (canonicalJsonString(localSchema.columnOrder || []) !== canonicalJsonString(expectedActiveOrder)
      || canonicalJsonString(localSchema.archivedColumnOrder || []) !== canonicalJsonString(expectedArchivedOrder)) {
      reject("共享结构的活动列或历史列顺序与正式来源不一致。");
    }
    sourceColumnIds.forEach((sourceColumnId) => {
      const mapping = mappings[sourceColumnId];
      const localColumn = localSchema.columnsById?.[sanitizeText(mapping?.localColumnId, "")];
      const sourceColumn = sourceSchema.columnsById?.[sourceColumnId];
      const sourceArchived = (sourceSchema.archivedColumnOrder || []).includes(sourceColumnId);
      const expectedLifecycle = sourceArchived ? "archived" : "active";
      const expectedLocalChildId = sanitizeText(sourceColumn?.childSchemaId, "")
        ? sanitizeText(localIdBySourceId.get(sanitizeText(sourceColumn.childSchemaId, "")), "")
        : "";
      if (!localColumn || !sourceColumn
        || sanitizeText(mapping?.sourceColumnId, sourceColumnId) !== sourceColumnId
        || sanitizeText(mapping?.sourceLabel, "") !== sanitizeText(sourceColumn.label, "")
        || (Object.prototype.hasOwnProperty.call(mapping || {}, "sourceDescription")
          && String(mapping.sourceDescription || "") !== String(sourceColumn.description || ""))
        || sanitizeText(mapping?.lifecycleState, "active") !== expectedLifecycle
        || sanitizeText(localColumn.label, "") !== sanitizeText(sourceColumn.label, "")
        || String(localColumn.description || "") !== String(sourceColumn.description || "")
        || sanitizeText(localColumn.cellType, "long-text") !== sanitizeText(sourceColumn.cellType, "long-text")
        || sanitizeText(localColumn.lifecycleState, "active") !== expectedLifecycle
        || sanitizeText(localColumn.childSchemaId, "") !== expectedLocalChildId) {
        reject("共享结构的列定义、生命周期或递归拓扑与正式来源不一致。");
      }
    });
  });

  lineageSnapshots.forEach((snapshot) => {
    targetOntology.schemasById[snapshot.localSchemaId].sourceLineage = deepClone(snapshot.sourceLineage, null);
  });
  const validation = validateParadigmOntology(targetOntology);
  if (!validation.ok) reject(validation.errors[0] || "恢复共享结构身份后 Ontology 无效。");
  return true;
}

function attachParadigmOntologySchemaLineageMirror(
  targetOntology,
  targetSchemaId,
  targetColumnId,
  sourceOntology,
  sourceSchemaId,
  sourceSchemaAddress,
  evidence = {},
) {
  const snapshot = deepClone(targetOntology, null);
  const targetSchema = targetOntology?.schemasById?.[sanitizeText(targetSchemaId, "")];
  const targetColumn = targetSchema?.columnsById?.[sanitizeText(targetColumnId, "")];
  const sourceRootSchema = sourceOntology?.schemasById?.[sanitizeText(sourceSchemaId, "")];
  if (!targetSchema || !targetColumn || !sourceRootSchema) {
    throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_MIRROR_INVALID", "无法定位 Ontology schema mirror 的源或目标。");
  }
  const normalizedRootAddress = normalizeParadigmOntologySchemaAddress(sourceSchemaAddress);
  const addressedDocumentId = getParadigmOntologySchemaAddressDocumentId(normalizedRootAddress);
  if ((addressedDocumentId && addressedDocumentId !== sanitizeText(sourceOntology?.documentId, ""))
    || normalizedRootAddress.schemaId !== sanitizeText(sourceRootSchema.id, "")) {
    throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_ADDRESS_MISMATCH", "来源 schema 地址与来源 Ontology 不一致。");
  }
  const existingChildSchemaId = sanitizeText(targetColumn.childSchemaId, "");
  if (existingChildSchemaId) {
    let existingLineage = targetOntology?.schemasById?.[existingChildSchemaId]?.sourceLineage;
    const existingKey = existingLineage?.sourceSchemaAddress
      ? serializeParadigmOntologyAddress(existingLineage.sourceSchemaAddress)
      : "";
    if (existingKey === serializeParadigmOntologyAddress(normalizedRootAddress)) {
      return { rootSchema: targetOntology.schemasById[existingChildSchemaId], createdSchemaIds: [], reused: true };
    }
    if (!existingLineage && restoreParadigmOntologySchemaLineageFromProvenance(
      targetOntology,
      existingChildSchemaId,
      sourceOntology,
      sourceRootSchema.id,
      normalizedRootAddress,
    )) {
      existingLineage = targetOntology.schemasById[existingChildSchemaId].sourceLineage;
      if (serializeParadigmOntologyAddress(existingLineage.sourceSchemaAddress)
        === serializeParadigmOntologyAddress(normalizedRootAddress)) {
        return {
          rootSchema: targetOntology.schemasById[existingChildSchemaId],
          createdSchemaIds: [],
          reused: true,
          lineageRecovered: true,
        };
      }
    }
    throw createParadigmOntologyContractError(
      "ONTOLOGY_SCHEMA_LINEAGE_CONFLICT",
      "目标列已经拥有其他子表结构，不能静默改成来源 schema。",
    );
  }
  const sourceToLocalSchemaIds = new Map();
  const createdSchemaIds = [];
  const visiting = new Set();
  const timestamp = nowString();
  const cloneSchema = (currentSourceSchemaId) => {
    const sourceId = sanitizeText(currentSourceSchemaId, "");
    if (visiting.has(sourceId)) {
      throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_LINEAGE_CYCLE", "来源 schema 结构存在循环，未建立 mirror。");
    }
    if (sourceToLocalSchemaIds.has(sourceId)) return targetOntology.schemasById[sourceToLocalSchemaIds.get(sourceId)];
    const sourceSchema = sourceOntology?.schemasById?.[sourceId];
    if (!sourceSchema) throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_MIRROR_INVALID", `来源 schema 不存在：${sourceId}`);
    visiting.add(sourceId);
    const localSchema = createParadigmOntologySchema(sanitizeText(sourceSchema.name, "来源结构"), [], targetOntology);
    localSchema.sourceLineage = {
      lineageVersion: PARADIGM_ONTOLOGY_SCHEMA_LINEAGE_VERSION,
      sourceSchemaAddress: buildParadigmOntologySchemaAddressFromTemplate(normalizedRootAddress, sourceId),
      sourceRevision: sanitizeText(evidence.sourceRevision, ""),
      sourceHash: sanitizeText(evidence.sourceHash, ""),
      state: "active",
      mappingOrder: [],
      mappingsBySourceColumnId: {},
      createdAt: timestamp,
      lastSyncedAt: timestamp,
      history: [{
        eventId: createId("pgOntLineageEvent"),
        type: "mirror-created",
        at: timestamp,
        sourceRevision: sanitizeText(evidence.sourceRevision, ""),
        sourceHash: sanitizeText(evidence.sourceHash, ""),
      }],
    };
    targetOntology.schemasById[localSchema.id] = localSchema;
    sourceToLocalSchemaIds.set(sourceId, localSchema.id);
    createdSchemaIds.push(localSchema.id);
    const sourceColumnIds = getParadigmOntologySchemaColumnIds(sourceSchema, true);
    sourceColumnIds.forEach((sourceColumnId) => {
      const sourceColumn = sourceSchema.columnsById?.[sourceColumnId];
      const localColumnId = createReservedParadigmOntologyColumnId(targetOntology);
      const sourceChildSchemaId = sanitizeText(sourceColumn?.childSchemaId, "");
      const localChildSchema = sourceChildSchemaId ? cloneSchema(sourceChildSchemaId) : null;
      const sourceArchived = Array.isArray(sourceSchema.archivedColumnOrder)
        && sourceSchema.archivedColumnOrder.includes(sourceColumnId);
      localSchema.columnsById[localColumnId] = {
        id: localColumnId,
        label: sanitizeText(sourceColumn?.label, "未命名列"),
        cellType: sanitizeText(sourceColumn?.cellType, "long-text"),
        childSchemaId: localChildSchema?.id || null,
        ...(typeof sourceColumn?.description === "string" && sourceColumn.description
          ? { description: sourceColumn.description }
          : {}),
        lifecycleState: sourceArchived ? "archived" : "active",
        archivedAt: sourceArchived ? timestamp : null,
        createdAt: timestamp,
        updatedAt: timestamp,
      };
      (sourceArchived ? localSchema.archivedColumnOrder : localSchema.columnOrder).push(localColumnId);
      localSchema.sourceLineage.mappingOrder.push(sourceColumnId);
      localSchema.sourceLineage.mappingsBySourceColumnId[sourceColumnId] = {
        sourceColumnId,
        localColumnId,
        sourceLabel: sanitizeText(sourceColumn?.label, "未命名列"),
        sourceDescription: typeof sourceColumn?.description === "string" ? sourceColumn.description : "",
        lifecycleState: sourceArchived ? "archived" : "active",
        mappedAt: timestamp,
        updatedAt: timestamp,
      };
    });
    visiting.delete(sourceId);
    return localSchema;
  };
  try {
    const rootSchema = cloneSchema(sourceRootSchema.id);
    targetColumn.childSchemaId = rootSchema.id;
    targetColumn.updatedAt = timestamp;
    targetSchema.updatedAt = timestamp;
    targetOntology.updatedAt = timestamp;
    const validation = validateParadigmOntology(targetOntology);
    if (!validation.ok) throw new Error(validation.errors[0] || "Schema mirror 建立后 Ontology 无效。");
    return { rootSchema, createdSchemaIds, reused: false };
  } catch (error) {
    restoreParadigmOntologySnapshot(targetOntology, snapshot);
    throw error;
  }
}

function reconcileParadigmOntologySchemaLineageMirror(
  ontology,
  localRootSchemaId,
  sourceProjection,
  sourceSchemaAddress,
  evidence = {},
) {
  const snapshot = deepClone(ontology, null);
  const sourceSchemas = sourceProjection?.schemasById || {};
  const sourceRootSchemaId = sanitizeText(sourceProjection?.rootSchemaId || sourceSchemaAddress?.schemaId, "");
  const sourceRoot = sourceSchemas[sourceRootSchemaId];
  const localRoot = ontology?.schemasById?.[sanitizeText(localRootSchemaId, "")];
  if (!sourceRoot || !localRoot || !isObjectLike(localRoot.sourceLineage)) {
    throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_INVALID", "共享结构同步缺少来源或本地映射。");
  }
  const timestamp = nowString();
  const visited = new Set();
  const reconcile = (localSchema, sourceSchema) => {
    const visitKey = `${localSchema.id}\u0000${sourceSchema.id}`;
    if (visited.has(visitKey)) return;
    visited.add(visitKey);
    const lineage = localSchema.sourceLineage;
    if (!isObjectLike(lineage)) throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_DIVERGED", "本地 Schema 已脱离共享结构，不能自动覆盖。");
    localSchema.name = sanitizeText(sourceSchema.name, localSchema.name || "共享结构");
    lineage.mappingOrder = Array.isArray(lineage.mappingOrder) ? lineage.mappingOrder : [];
    lineage.sourceSchemaAddress = buildParadigmOntologySchemaAddressFromTemplate(sourceSchemaAddress, sourceSchema.id);
    lineage.mappingsBySourceColumnId = isObjectLike(lineage.mappingsBySourceColumnId) ? lineage.mappingsBySourceColumnId : {};
    const sourceIds = getParadigmOntologySchemaColumnIds(sourceSchema, true);
    sourceIds.forEach((sourceColumnId) => {
      const sourceColumn = sourceSchema.columnsById?.[sourceColumnId];
      let mapping = lineage.mappingsBySourceColumnId[sourceColumnId];
      let localColumn = mapping ? localSchema.columnsById?.[sanitizeText(mapping.localColumnId, "")] : null;
      if (!localColumn) {
        const localColumnId = createReservedParadigmOntologyColumnId(ontology);
        localColumn = {
          id: localColumnId,
          label: sanitizeText(sourceColumn?.label, "未命名列"),
          cellType: sanitizeText(sourceColumn?.cellType, "long-text"),
          childSchemaId: null,
          ...(typeof sourceColumn?.description === "string" && sourceColumn.description
            ? { description: sourceColumn.description }
            : {}),
          lifecycleState: "active",
          archivedAt: null,
          createdAt: timestamp,
          updatedAt: timestamp,
        };
        localSchema.columnsById[localColumnId] = localColumn;
        mapping = { sourceColumnId, localColumnId, mappedAt: timestamp };
        lineage.mappingsBySourceColumnId[sourceColumnId] = mapping;
        if (!lineage.mappingOrder.includes(sourceColumnId)) lineage.mappingOrder.push(sourceColumnId);
        getParadigmOntologySchemaTables(ontology, localSchema.id).forEach((table) => {
          table.rowOrder.forEach((rowId) => { table.rowsById[rowId].cellsByColumnId[localColumnId] = createParadigmOntologyCell(); });
        });
      }
      const sourceArchived = (sourceSchema.archivedColumnOrder || []).includes(sourceColumnId);
      localColumn.label = sanitizeText(sourceColumn?.label, "未命名列");
      localColumn.cellType = sanitizeText(sourceColumn?.cellType, "long-text");
      if (typeof sourceColumn?.description === "string" && sourceColumn.description) {
        localColumn.description = sourceColumn.description;
      } else {
        delete localColumn.description;
      }
      localColumn.lifecycleState = sourceArchived ? "archived" : "active";
      localColumn.archivedAt = sourceArchived ? (localColumn.archivedAt || timestamp) : null;
      localColumn.updatedAt = timestamp;
      localSchema.columnOrder = (localSchema.columnOrder || []).filter((id) => id !== localColumn.id);
      localSchema.archivedColumnOrder = (localSchema.archivedColumnOrder || []).filter((id) => id !== localColumn.id);
      (sourceArchived ? localSchema.archivedColumnOrder : localSchema.columnOrder).push(localColumn.id);
      mapping.sourceLabel = localColumn.label;
      mapping.sourceDescription = typeof sourceColumn?.description === "string" ? sourceColumn.description : "";
      mapping.lifecycleState = localColumn.lifecycleState;
      mapping.updatedAt = timestamp;
      const sourceChildId = sanitizeText(sourceColumn?.childSchemaId, "");
      if (sourceChildId) {
        const sourceChild = sourceSchemas[sourceChildId];
        if (!sourceChild) throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_INVALID", `来源递归 Schema 缺失：${sourceChildId}`);
        let localChild = ontology.schemasById?.[sanitizeText(localColumn.childSchemaId, "")];
        if (!localChild) {
          localChild = createParadigmOntologySchema(sanitizeText(sourceChild.name, "共享结构"), [], ontology);
          localChild.sourceLineage = {
            lineageVersion: PARADIGM_ONTOLOGY_SCHEMA_LINEAGE_VERSION,
            sourceSchemaAddress: buildParadigmOntologySchemaAddressFromTemplate(sourceSchemaAddress, sourceChildId),
            sourceRevision: sanitizeText(evidence.sourceRevision, ""),
            sourceHash: sanitizeText(evidence.sourceHash, ""),
            state: "active",
            mappingOrder: [],
            mappingsBySourceColumnId: {},
            createdAt: timestamp,
            lastSyncedAt: timestamp,
            history: [],
          };
          ontology.schemasById[localChild.id] = localChild;
          localColumn.childSchemaId = localChild.id;
        }
        reconcile(localChild, sourceChild);
      } else if (sanitizeText(localColumn.childSchemaId, "")) {
        const localChildId = sanitizeText(localColumn.childSchemaId, "");
        const localChild = ontology.schemasById?.[localChildId];
        const childTables = getParadigmOntologySchemaTables(ontology, localChildId);
        const parentColumns = findParadigmOntologySchemaParentColumns(ontology, localChildId);
        if (!localChild || childTables.length > 0 || parentColumns.length !== 1) {
          throw createParadigmOntologyContractError(
            "ONTOLOGY_SCHEMA_RECONCILE_DIVERGED",
            "来源已移除子 Schema，但本地仍有实例或其他结构依赖；为防止数据丢失，已阻止自动同步。",
          );
        }
        const detachedGraphIds = collectParadigmOntologySchemaGraphIds(ontology, localChildId);
        stripParadigmOntologyActiveLineageGraph(ontology, localChildId, {
          outcome: "source-branch-pruned",
          reason: "source-child-schema-removed",
        });
        localColumn.childSchemaId = null;
        localColumn.updatedAt = timestamp;
        pruneUnreachableParadigmOntologySchemas(ontology, detachedGraphIds);
      }
    });
    lineage.mappingOrder.forEach((sourceColumnId) => {
      if (sourceIds.includes(sourceColumnId)) return;
      const localColumn = localSchema.columnsById?.[sanitizeText(lineage.mappingsBySourceColumnId?.[sourceColumnId]?.localColumnId, "")];
      if (!localColumn) return;
      localSchema.columnOrder = (localSchema.columnOrder || []).filter((id) => id !== localColumn.id);
      if (!localSchema.archivedColumnOrder.includes(localColumn.id)) localSchema.archivedColumnOrder.push(localColumn.id);
      localColumn.lifecycleState = "archived";
      localColumn.archivedAt = localColumn.archivedAt || timestamp;
      localColumn.updatedAt = timestamp;
    });
    lineage.sourceRevision = sanitizeText(evidence.sourceRevision, lineage.sourceRevision);
    lineage.sourceHash = sanitizeText(evidence.sourceHash, lineage.sourceHash);
    lineage.lastSyncedAt = timestamp;
    lineage.history = Array.isArray(lineage.history) ? lineage.history : [];
    if (lineage.history.length >= 512) throw createParadigmOntologyContractError("ONTOLOGY_PROVENANCE_CAPACITY", "共享结构同步历史已满，未覆盖旧历史。");
    lineage.history.push({ eventId: createId("pgOntLineageEvent"), type: "source-reconciled", at: timestamp, sourceRevision: lineage.sourceRevision, sourceHash: lineage.sourceHash });
    localSchema.updatedAt = timestamp;
  };
  try {
    reconcile(localRoot, sourceRoot);
    ontology.updatedAt = timestamp;
    const validation = validateParadigmOntology(ontology);
    if (!validation.ok) throw new Error(validation.errors[0] || "共享结构同步后 Ontology 无效。");
    return { ontology, localRootSchemaId: localRoot.id, sourceRootSchemaId, reconciledAt: timestamp };
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function setParadigmOntologyCellReference(ontology, targetCellAddress, reference) {
  const resolved = resolveParadigmOntologyCellByAddress(ontology, targetCellAddress);
  if (!resolved) throw createParadigmOntologyContractError("ONTOLOGY_TARGET_CELL_MISSING", "无法定位引用目标单元格。");
  const validation = validateParadigmOntologyCellReference(reference);
  if (!validation.ok) throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_INVALID", validation.errors[0], { errors: validation.errors });
  const targetKey = serializeParadigmOntologyAddress(resolved.address);
  const sourceKey = serializeParadigmOntologyAddress(validation.reference.sourceAddress);
  if (targetKey === sourceKey) throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_SELF", "不能引用当前单元格自身。");
  if (sanitizeText(resolved.cell.nestedTableId, "")) {
    throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_TARGET_HAS_NESTED_TABLE", "目标单元格已经拥有本地子表，不能同时建立内容引用。");
  }
  if (isObjectLike(resolved.cell.reference)) {
    const existing = validateParadigmOntologyCellReference(resolved.cell.reference);
    if (existing.ok && serializeParadigmOntologyAddress(existing.reference.sourceAddress) === sourceKey) {
      throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_DUPLICATE", "当前单元格已经引用该来源。");
    }
    throw createParadigmOntologyContractError("ONTOLOGY_REFERENCE_TARGET_OCCUPIED", "目标单元格已经拥有其他内容引用，请先解除原引用。");
  }
  resolved.cell.reference = validation.reference;
  const timestamp = nowString();
  resolved.row.updatedAt = timestamp;
  resolved.table.updatedAt = timestamp;
  ontology.updatedAt = timestamp;
  return deepClone(resolved.cell.reference, null);
}

function unlinkParadigmOntologyCellReference(ontology, targetCellAddress) {
  const resolved = resolveParadigmOntologyCellByAddress(ontology, targetCellAddress);
  if (!resolved || !isObjectLike(resolved.cell.reference)) return false;
  delete resolved.cell.reference;
  const timestamp = nowString();
  resolved.row.updatedAt = timestamp;
  resolved.table.updatedAt = timestamp;
  ontology.updatedAt = timestamp;
  return true;
}

function collectParadigmOntologySchemaGraphIds(ontology, rootSchemaId) {
  const ids = [];
  const seen = new Set();
  const visit = (schemaId) => {
    const id = sanitizeText(schemaId, "");
    if (!id || seen.has(id)) return;
    const schema = ontology?.schemasById?.[id];
    if (!schema) return;
    seen.add(id);
    ids.push(id);
    getParadigmOntologySchemaColumnIds(schema, true).forEach((columnId) => {
      visit(schema.columnsById?.[columnId]?.childSchemaId);
    });
  };
  visit(rootSchemaId);
  return ids;
}

function findParadigmOntologySchemaParentColumns(ontology, childSchemaId) {
  const targetId = sanitizeText(childSchemaId, "");
  const parents = [];
  Object.values(ontology?.schemasById || {}).forEach((schema) => {
    getParadigmOntologySchemaColumnIds(schema, true).forEach((columnId) => {
      if (sanitizeText(schema.columnsById?.[columnId]?.childSchemaId, "") === targetId) {
        parents.push({ schemaId: schema.id, columnId });
      }
    });
  });
  return parents;
}

function paradigmOntologyColumnHasNestedTableInstance(ontology, schemaId, columnId) {
  return getParadigmOntologySchemaTables(ontology, schemaId).some((table) => (
    (Array.isArray(table.rowOrder) ? table.rowOrder : []).some((rowId) => (
      Boolean(sanitizeText(table.rowsById?.[rowId]?.cellsByColumnId?.[columnId]?.nestedTableId, ""))
    ))
  ));
}

function paradigmOntologyColumnHasReference(ontology, schemaId, columnId) {
  return getParadigmOntologySchemaTables(ontology, schemaId).some((table) => (
    (Array.isArray(table.rowOrder) ? table.rowOrder : []).some((rowId) => (
      isObjectLike(table.rowsById?.[rowId]?.cellsByColumnId?.[columnId]?.reference)
    ))
  ));
}

function partitionParadigmOntologySharedSchemaGraphs(ontology) {
  const lineagedSchemas = Object.values(ontology?.schemasById || {})
    .filter((schema) => isObjectLike(schema?.sourceLineage));
  const lineagedIds = new Set(lineagedSchemas.map((schema) => sanitizeText(schema?.id, "")).filter(Boolean));
  const nestedLineagedIds = new Set();
  lineagedSchemas.forEach((schema) => {
    getParadigmOntologySchemaColumnIds(schema, true).forEach((columnId) => {
      const childSchemaId = sanitizeText(schema.columnsById?.[columnId]?.childSchemaId, "");
      if (lineagedIds.has(childSchemaId)) nestedLineagedIds.add(childSchemaId);
    });
  });
  const candidateRoots = lineagedSchemas.filter((schema) => !nestedLineagedIds.has(schema.id));
  const roots = candidateRoots.length > 0 ? candidateRoots : lineagedSchemas;
  const consumed = new Set();
  const result = { activeRoots: [], pendingDetachRoots: [], invalidOrphanRoots: [], allRoots: [] };

  roots.forEach((rootSchema) => {
    const rootSchemaId = sanitizeText(rootSchema?.id, "");
    if (!rootSchemaId || consumed.has(rootSchemaId)) return;
    const graphSchemaIds = collectParadigmOntologySchemaGraphIds(ontology, rootSchemaId)
      .filter((schemaId) => lineagedIds.has(schemaId));
    graphSchemaIds.forEach((schemaId) => consumed.add(schemaId));
    const parentColumns = findParadigmOntologySchemaParentColumns(ontology, rootSchemaId);
    const reasons = [];
    let validReferenceCount = 0;
    let malformedReferenceCount = 0;
    const parentEvidence = parentColumns.map((parent) => {
      const tables = getParadigmOntologySchemaTables(ontology, parent.schemaId);
      let rowCount = 0;
      let referenceCount = 0;
      let invalidCount = 0;
      tables.forEach((table) => {
        (Array.isArray(table.rowOrder) ? table.rowOrder : []).forEach((rowId) => {
          rowCount += 1;
          const cell = table.rowsById?.[rowId]?.cellsByColumnId?.[parent.columnId];
          if (!isObjectLike(cell) || !Object.prototype.hasOwnProperty.call(cell, "reference")) return;
          const reference = cell.reference;
          if (!isObjectLike(reference)) {
            invalidCount += 1;
            malformedReferenceCount += 1;
            reasons.push({
              code: "ONTOLOGY_SHARED_SCHEMA_REFERENCE_INVALID",
              message: "共享结构父列存在非对象 reference 属性。",
              parentSchemaId: parent.schemaId,
              parentColumnId: parent.columnId,
            });
            return;
          }
          const validation = validateParadigmOntologyCellReference(reference);
          if (validation.ok) {
            referenceCount += 1;
            validReferenceCount += 1;
          } else {
            invalidCount += 1;
            malformedReferenceCount += 1;
            reasons.push({
              code: "ONTOLOGY_SHARED_SCHEMA_REFERENCE_INVALID",
              message: validation.errors.join(" | ") || "共享结构父列存在无效引用。",
              parentSchemaId: parent.schemaId,
              parentColumnId: parent.columnId,
            });
          }
        });
      });
      return Object.assign({}, parent, { tableCount: tables.length, rowCount, referenceCount, invalidCount });
    });
    if (parentColumns.length === 0) {
      reasons.push({ code: "ONTOLOGY_SHARED_SCHEMA_ORPHAN_LINEAGE", message: "共享结构 lineage 没有可解析的父列。" });
    }
    if (!isObjectLike(rootSchema?.sourceLineage?.sourceSchemaAddress)) {
      reasons.push({ code: "ONTOLOGY_SHARED_SCHEMA_SOURCE_ADDRESS_MISSING", message: "共享结构缺少正式来源地址。" });
    } else {
      try { normalizeParadigmOntologySchemaAddress(rootSchema.sourceLineage.sourceSchemaAddress); }
      catch (error) {
        reasons.push({ code: error?.code || "ONTOLOGY_SHARED_SCHEMA_SOURCE_ADDRESS_INVALID", message: error?.message || "共享结构来源地址无效。" });
      }
    }
    if (parentColumns.length > 1 && validReferenceCount === 0) {
      reasons.push({ code: "ONTOLOGY_SHARED_SCHEMA_PARENT_AMBIGUOUS", message: "无有效引用的共享结构同时挂在多个父列，不能安全判断解除目标。" });
    }
    const entry = {
      rootSchemaId,
      schema: rootSchema,
      graphSchemaIds,
      parentColumns: parentEvidence,
      validReferenceCount,
      malformedReferenceCount,
      reasons,
      pendingDetach: false,
      state: "active",
    };
    if (reasons.length > 0) {
      entry.state = "invalid-orphan";
      result.invalidOrphanRoots.push(entry);
    } else if (validReferenceCount > 0) {
      result.activeRoots.push(entry);
    } else {
      entry.state = "pending-detach";
      entry.pendingDetach = true;
      result.pendingDetachRoots.push(entry);
    }
    result.allRoots.push(entry);
  });

  lineagedSchemas.forEach((schema) => {
    if (consumed.has(schema.id)) return;
    const entry = {
      rootSchemaId: schema.id,
      schema,
      graphSchemaIds: [schema.id],
      parentColumns: [],
      validReferenceCount: 0,
      malformedReferenceCount: 0,
      pendingDetach: false,
      state: "invalid-orphan",
      reasons: [{ code: "ONTOLOGY_SHARED_SCHEMA_GRAPH_UNRESOLVED", message: "共享结构无法归入唯一递归图。" }],
    };
    result.invalidOrphanRoots.push(entry);
    result.allRoots.push(entry);
  });
  return result;
}

const PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_FAILURE_CODES = new Set([
  "INVALID_ADDRESS",
  "INVALID_SCHEMA_ADDRESS",
  "ONTOLOGY_ADDRESS_INVALID",
  "ONTOLOGY_SCHEMA_RECONCILE_FAILED",
  "ONTOLOGY_SCHEMA_RECONCILE_AGGREGATE",
  "ONTOLOGY_SHARED_SCHEMA_GRAPH_INVALID",
  "ONTOLOGY_SHARED_SCHEMA_SOURCE_ADDRESS_INVALID",
]);

function collectParadigmOntologyFailureCodes(value, codes = new Set(), seen = new Set()) {
  if (value == null) return codes;
  if (typeof value === "string") {
    if (/^[A-Z][A-Z0-9_]+$/.test(value)) codes.add(value);
    return codes;
  }
  if (typeof value !== "object" || seen.has(value)) return codes;
  seen.add(value);
  if (Array.isArray(value)) {
    value.forEach((entry) => collectParadigmOntologyFailureCodes(entry, codes, seen));
    return codes;
  }
  if (typeof value.code === "string") codes.add(value.code);
  ["cause", "detail", "aggregateReasons", "reasons", "error"].forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      collectParadigmOntologyFailureCodes(value[key], codes, seen);
    }
  });
  return codes;
}

function isCorruptedParadigmOntologyAuthorityAddress(address) {
  return isObjectLike(address)
    && sanitizeText(address.addressVersion, "") === PARADIGM_ONTOLOGY_SCHEMA_AUTHORITY_ADDRESS_VERSION
    && !isObjectLike(address.authorityStableRef);
}

function getParadigmOntologyCorruptedSharedSchemaRecoveryCandidates(ontology, options = {}) {
  if (options.didRestoreRecovery !== true || !options.failure) return [];
  const failureCodes = collectParadigmOntologyFailureCodes(options.failure);
  if (![...failureCodes].some((code) => PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_FAILURE_CODES.has(code))) return [];
  const partition = partitionParadigmOntologySharedSchemaGraphs(ontology);
  return partition.allRoots.filter((entry) => {
    if (entry.validReferenceCount !== 0 || entry.malformedReferenceCount !== 0) return false;
    if (!Array.isArray(entry.parentColumns) || entry.parentColumns.length === 0) return false;
    return entry.graphSchemaIds.some((schemaId) => (
      isCorruptedParadigmOntologyAuthorityAddress(
        ontology?.schemasById?.[schemaId]?.sourceLineage?.sourceSchemaAddress,
      )
    ));
  });
}

function paradigmOntologyLineageGraphHasLegacyDivergence(ontology, rootSchemaId) {
  const graphIds = collectParadigmOntologySchemaGraphIds(ontology, rootSchemaId);
  if (graphIds.length === 0) return true;
  return graphIds.some((schemaId) => {
    const schema = ontology.schemasById[schemaId];
    const lineage = schema?.sourceLineage;
    if (!isObjectLike(lineage)) return true;
    const mappings = isObjectLike(lineage.mappingsBySourceColumnId) ? lineage.mappingsBySourceColumnId : {};
    const mappingOrder = Array.isArray(lineage.mappingOrder) ? lineage.mappingOrder : [];
    const mappedLocalIds = new Set(mappingOrder.map((sourceColumnId) => sanitizeText(mappings[sourceColumnId]?.localColumnId, "")).filter(Boolean));
    const localIds = getParadigmOntologySchemaColumnIds(schema, true);
    if (mappedLocalIds.size !== localIds.length || localIds.some((id) => !mappedLocalIds.has(id))) return true;
    return mappingOrder.some((sourceColumnId) => {
      const mapping = mappings[sourceColumnId];
      const column = schema.columnsById?.[sanitizeText(mapping?.localColumnId, "")];
      if (!column) return true;
      const expectedState = sanitizeText(mapping?.lifecycleState, "active");
      return sanitizeText(column.label, "") !== sanitizeText(mapping?.sourceLabel, "")
        || (Object.prototype.hasOwnProperty.call(mapping || {}, "sourceDescription")
          && String(column.description || "") !== String(mapping.sourceDescription || ""))
        || sanitizeText(column.lifecycleState, "active") !== expectedState;
    });
  });
}

function appendParadigmOntologySchemaProvenance(ontology, record) {
  const history = Array.isArray(ontology.schemaProvenanceHistory) ? ontology.schemaProvenanceHistory : [];
  if (history.length >= PARADIGM_ONTOLOGY_PROVENANCE_LIMIT) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_PROVENANCE_CAPACITY",
      "Ontology 结构来源历史已达到安全容量，解除操作未执行；请先使用未来的无损归档工具。",
    );
  }
  history.push(canonicalizeJson(deepClone(record, null)));
  ontology.schemaProvenanceHistory = history;
}

function stripParadigmOntologyActiveLineageGraph(ontology, rootSchemaId, options = {}) {
  const timestamp = sanitizeText(options.detachedAt, nowString());
  const graphIds = collectParadigmOntologySchemaGraphIds(ontology, rootSchemaId);
  const lineageSnapshots = graphIds.map((schemaId) => ({
    localSchemaId: schemaId,
    sourceLineage: deepClone(ontology.schemasById?.[schemaId]?.sourceLineage, null),
  })).filter((entry) => isObjectLike(entry.sourceLineage));
  appendParadigmOntologySchemaProvenance(ontology, {
    provenanceVersion: 1,
    eventId: createId("pgOntProvenance"),
    type: "shared-schema-detached",
    operationId: sanitizeText(options.operationId, ""),
    outcome: sanitizeText(options.outcome, "forked-local"),
    rootLocalSchemaId: sanitizeText(rootSchemaId, ""),
    detachedAt: timestamp,
    reason: sanitizeText(options.reason, "reference-unlinked"),
    lineages: lineageSnapshots,
  });
  graphIds.forEach((schemaId) => {
    const schema = ontology.schemasById?.[schemaId];
    if (!schema) return;
    delete schema.sourceLineage;
    schema.updatedAt = timestamp;
  });
  return { graphIds, lineageSnapshots };
}

function pruneUnreachableParadigmOntologySchemas(ontology, candidateSchemaIds = []) {
  const reachable = new Set();
  const visit = (schemaId) => {
    const id = sanitizeText(schemaId, "");
    if (!id || reachable.has(id) || !ontology?.schemasById?.[id]) return;
    reachable.add(id);
    const schema = ontology.schemasById[id];
    getParadigmOntologySchemaColumnIds(schema, true).forEach((columnId) => visit(schema.columnsById?.[columnId]?.childSchemaId));
  };
  visit(ontology?.rootSchemaId);
  Object.values(ontology?.tablesById || {}).forEach((table) => visit(table?.schemaId));
  const removed = [];
  candidateSchemaIds.forEach((schemaId) => {
    const id = sanitizeText(schemaId, "");
    if (id && !reachable.has(id) && ontology?.schemasById?.[id]) {
      delete ontology.schemasById[id];
      removed.push(id);
    }
  });
  return removed;
}

function finalizeParadigmOntologyDetachedBindings(ontology, options = {}) {
  const snapshot = deepClone(ontology, null);
  const downstreamSchemaAddressKeys = new Set(Array.isArray(options.downstreamSchemaAddressKeys) ? options.downstreamSchemaAddressKeys : []);
  const buildSchemaAddress = typeof options.buildSchemaAddress === "function" ? options.buildSchemaAddress : null;
  const retainedPendingRootSchemaIds = new Set(Array.isArray(options.retainedPendingRootSchemaIds)
    ? options.retainedPendingRootSchemaIds.map((id) => sanitizeText(id, "")).filter(Boolean)
    : []);
  const outcomes = [];
  try {
    const partition = partitionParadigmOntologySharedSchemaGraphs(ontology);
    if (partition.invalidOrphanRoots.length > 0) {
      throw createParadigmOntologyContractError(
        "ONTOLOGY_SHARED_SCHEMA_GRAPH_INVALID",
        partition.invalidOrphanRoots[0].reasons[0]?.message || "共享结构关系不完整，不能完成正式保存。",
        {
          invalidRoots: partition.invalidOrphanRoots.map((entry) => ({
            schemaId: entry.rootSchemaId,
            graphSchemaIds: entry.graphSchemaIds,
            parentColumns: entry.parentColumns,
            reasons: entry.reasons,
          })),
        },
      );
    }
    partition.activeRoots.forEach((entry) => {
      outcomes.push({ schemaId: entry.rootSchemaId, outcome: "binding-retained" });
    });
    partition.pendingDetachRoots.forEach((entry) => {
        const rootSchemaId = entry.rootSchemaId;
        const graphIds = entry.graphSchemaIds;
        if (retainedPendingRootSchemaIds.has(rootSchemaId)) {
          outcomes.push({ schemaId: rootSchemaId, outcome: "binding-retained", reason: "owner-policy" });
          return;
        }
        const hasLocalInstance = entry.parentColumns.some((parent) => (
          paradigmOntologyColumnHasNestedTableInstance(ontology, parent.schemaId, parent.columnId)
        ));
        const legacyDivergence = paradigmOntologyLineageGraphHasLegacyDivergence(ontology, rootSchemaId);
        const hasDownstream = buildSchemaAddress && graphIds.some((schemaId) => {
          try { return downstreamSchemaAddressKeys.has(serializeParadigmOntologyAddress(buildSchemaAddress(schemaId))); }
          catch (_) { return true; }
        });
        const proofComplete = options.proofComplete === true;
        const shouldFork = hasLocalInstance || legacyDivergence || hasDownstream || !proofComplete;
        stripParadigmOntologyActiveLineageGraph(ontology, rootSchemaId, {
          operationId: options.operationId,
          outcome: shouldFork ? "forked-local" : "blank-pruned",
          reason: shouldFork
            ? (hasLocalInstance ? "local-instance" : (legacyDivergence ? "legacy-divergence" : (hasDownstream ? "downstream-reference" : "proof-incomplete")))
            : "unused-complete-proof",
        });
        if (!shouldFork) {
          entry.parentColumns.forEach((parent) => {
            const column = ontology?.schemasById?.[parent.schemaId]?.columnsById?.[parent.columnId];
            if (!column || sanitizeText(column.childSchemaId, "") !== rootSchemaId) return;
            column.childSchemaId = null;
            column.updatedAt = nowString();
          });
          pruneUnreachableParadigmOntologySchemas(ontology, graphIds);
        }
        outcomes.push({ schemaId: rootSchemaId, outcome: shouldFork ? "forked-local" : "blank-pruned" });
    });
    ontology.updatedAt = nowString();
    const validation = validateParadigmOntology(ontology);
    if (!validation.ok) throw new Error(validation.errors[0] || "解除共享结构后 Ontology 无效。");
    return outcomes;
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function createParadigmOntologyTable(schema, parentCellRef = null, options = {}) {
  const tableId = createId("pgOntTable");
  const timestamp = nowString();
  const table = {
    id: tableId,
    schemaId: schema.id,
    parentCellRef: parentCellRef ? {
      parentTableId: sanitizeText(parentCellRef.parentTableId, ""),
      parentRowId: sanitizeText(parentCellRef.parentRowId, ""),
      parentColumnId: sanitizeText(parentCellRef.parentColumnId, ""),
    } : null,
    rowOrder: [],
    rowsById: {},
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  if (options.withInitialRow !== false) {
    const row = createParadigmOntologyRow(schema);
    table.rowOrder.push(row.id);
    table.rowsById[row.id] = row;
  }
  return table;
}

function createDefaultParadigmOntology() {
  const timestamp = nowString();
  const rootSchema = createParadigmOntologySchema("流程步骤", PARADIGM_ONTOLOGY_DEFAULT_COLUMNS);
  const rootTable = createParadigmOntologyTable(rootSchema, null, { withInitialRow: true });
  const ontology = {
    schemaVersion: PARADIGM_ONTOLOGY_SCHEMA_VERSION,
    documentId: createId("pgOntDoc"),
    rootSchemaId: rootSchema.id,
    rootTableId: rootTable.id,
    schemasById: { [rootSchema.id]: rootSchema },
    tablesById: { [rootTable.id]: rootTable },
    reservedColumnIds: getParadigmOntologySchemaColumnIds(rootSchema, true),
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  return ontology;
}

function createSingleCellParadigmOntology() {
  const timestamp = nowString();
  const rootSchema = createParadigmOntologySchema("表格", [{ label: "未命名列", cellType: "long-text" }]);
  const rootTable = createParadigmOntologyTable(rootSchema, null, { withInitialRow: true });
  const ontology = {
    schemaVersion: PARADIGM_ONTOLOGY_SCHEMA_VERSION,
    documentId: createId("pgOntDoc"),
    rootSchemaId: rootSchema.id,
    rootTableId: rootTable.id,
    schemasById: { [rootSchema.id]: rootSchema },
    tablesById: { [rootTable.id]: rootTable },
    reservedColumnIds: getParadigmOntologySchemaColumnIds(rootSchema, true),
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  return ontology;
}

function getParadigmOntologyRoot(ontology) {
  const schema = ontology?.schemasById?.[ontology?.rootSchemaId] || null;
  const table = ontology?.tablesById?.[ontology?.rootTableId] || null;
  return { schema, table };
}

function getParadigmOntologyTableChildren(ontology, table) {
  const schema = ontology?.schemasById?.[table?.schemaId];
  if (!schema) return [];
  const out = [];
  for (const rowId of Array.isArray(table?.rowOrder) ? table.rowOrder : []) {
    const row = table?.rowsById?.[rowId];
    if (!row) continue;
    for (const columnId of getParadigmOntologySchemaColumnIds(schema, true)) {
      const nestedTableId = sanitizeText(row?.cellsByColumnId?.[columnId]?.nestedTableId, "");
      if (nestedTableId) out.push(nestedTableId);
    }
  }
  return out;
}

function validateParadigmOntology(ontology, limits = PARADIGM_ONTOLOGY_LIMITS) {
  const errors = [];
  if (!isObjectLike(ontology)) return { ok: false, errors: ["Ontology document is missing."], stats: {} };
  const documentSchemaVersion = Number(ontology.schemaVersion);
  if (documentSchemaVersion < PARADIGM_ONTOLOGY_SCHEMA_VERSION_MIN
    || documentSchemaVersion > PARADIGM_ONTOLOGY_SCHEMA_VERSION) {
    errors.push(`Unsupported Ontology schemaVersion: ${String(ontology.schemaVersion ?? "missing")}`);
  }
  const schemasById = isObjectLike(ontology.schemasById) ? ontology.schemasById : {};
  const tablesById = isObjectLike(ontology.tablesById) ? ontology.tablesById : {};
  const rootSchemaId = sanitizeText(ontology.rootSchemaId, "");
  const rootTableId = sanitizeText(ontology.rootTableId, "");
  const documentId = sanitizeText(ontology.documentId, "");
  if (documentSchemaVersion >= 3 && !documentId) errors.push("v3 documentId is required.");
  const rootSchema = schemasById[rootSchemaId];
  const rootTable = tablesById[rootTableId];
  if (!rootSchemaId || !rootSchema) errors.push("rootSchemaId does not resolve.");
  if (!rootTableId || !rootTable) errors.push("rootTableId does not resolve.");
  if (rootTable && sanitizeText(rootTable.schemaId, "") !== rootSchemaId) errors.push("Root table/schema mismatch.");
  if (rootTable && rootTable.parentCellRef != null) errors.push("Root table must not have a parentCellRef.");

  let totalCells = 0;
  let referenceCount = 0;
  let lineageCount = 0;
  const keySetMatchesOrder = (orderLike, mapLike, label) => {
    const order = Array.isArray(orderLike) ? orderLike.map((entry) => sanitizeText(entry, "")).filter(Boolean) : [];
    const keys = Object.keys(isObjectLike(mapLike) ? mapLike : {});
    if (new Set(order).size !== order.length) errors.push(`${label} contains duplicate IDs.`);
    const orderSet = new Set(order);
    if (order.length !== keys.length || keys.some((key) => !orderSet.has(key))) {
      errors.push(`${label} does not exactly cover its map.`);
    }
    return order;
  };

  const reservedColumnIds = Array.isArray(ontology.reservedColumnIds)
    ? ontology.reservedColumnIds.map((id) => sanitizeText(id, "")).filter(Boolean)
    : [];
  const reservedColumnIdSet = new Set(reservedColumnIds);
  if (documentSchemaVersion >= 2 && reservedColumnIdSet.size !== reservedColumnIds.length) {
    errors.push("reservedColumnIds contains duplicate IDs.");
  }
  Object.entries(schemasById).forEach(([schemaId, schema]) => {
    if (!isObjectLike(schema) || sanitizeText(schema.id, "") !== schemaId) errors.push(`Schema identity mismatch: ${schemaId}`);
    const columnOrder = Array.isArray(schema?.columnOrder)
      ? schema.columnOrder.map((entry) => sanitizeText(entry, "")).filter(Boolean)
      : [];
    const archivedColumnOrder = documentSchemaVersion >= 2 && Array.isArray(schema?.archivedColumnOrder)
      ? schema.archivedColumnOrder.map((entry) => sanitizeText(entry, "")).filter(Boolean)
      : [];
    const allColumnOrder = [...columnOrder, ...archivedColumnOrder];
    const columnKeys = Object.keys(isObjectLike(schema?.columnsById) ? schema.columnsById : {});
    if (new Set(columnOrder).size !== columnOrder.length) errors.push(`schema ${schemaId} columnOrder contains duplicate IDs.`);
    if (new Set(archivedColumnOrder).size !== archivedColumnOrder.length) errors.push(`schema ${schemaId} archivedColumnOrder contains duplicate IDs.`);
    if (new Set(allColumnOrder).size !== allColumnOrder.length) errors.push(`Schema ${schemaId} active and archived columns overlap.`);
    const allColumnSet = new Set(allColumnOrder);
    if (allColumnOrder.length !== columnKeys.length || columnKeys.some((key) => !allColumnSet.has(key))) {
      errors.push(`schema ${schemaId} column orders do not exactly cover columnsById.`);
    }
    const maxActiveColumns = Number(limits.maxActiveColumnsPerSchema || limits.maxColumnsPerSchema || 32);
    const maxTotalColumns = Number(limits.maxTotalColumnsPerSchema || maxActiveColumns);
    if (columnOrder.length > maxActiveColumns) errors.push(`Schema ${schemaId} exceeds max active columns.`);
    if (allColumnOrder.length > maxTotalColumns) errors.push(`Schema ${schemaId} exceeds max total columns.`);
    allColumnOrder.forEach((columnId) => {
      const column = schema?.columnsById?.[columnId];
      if (!isObjectLike(column) || sanitizeText(column.id, "") !== columnId) errors.push(`Column identity mismatch: ${columnId}`);
      if (documentSchemaVersion >= 2) {
        const expectedState = archivedColumnOrder.includes(columnId) ? "archived" : "active";
        if (sanitizeText(column?.lifecycleState, "") !== expectedState) errors.push(`Column ${columnId} lifecycle state mismatch.`);
        if (!reservedColumnIdSet.has(columnId)) errors.push(`Column ${columnId} is missing from reservedColumnIds.`);
      }
      const childSchemaId = sanitizeText(column?.childSchemaId, "");
      if (Object.prototype.hasOwnProperty.call(column || {}, "description") && typeof column.description !== "string") {
        errors.push(`Column ${columnId} description must be a string.`);
      }
      if (childSchemaId && !schemasById[childSchemaId]) errors.push(`Column ${columnId} has a missing childSchemaId.`);
    });
    if (isObjectLike(schema?.sourceLineage)) {
      lineageCount += 1;
      if (documentSchemaVersion < 3) errors.push(`Schema ${schemaId} uses sourceLineage before v3.`);
      const lineage = schema.sourceLineage;
      if (Number(lineage.lineageVersion) !== PARADIGM_ONTOLOGY_SCHEMA_LINEAGE_VERSION) {
        errors.push(`Schema ${schemaId} has an unsupported lineageVersion.`);
      }
      let sourceSchemaAddress = null;
      try { sourceSchemaAddress = normalizeParadigmOntologySchemaAddress(lineage.sourceSchemaAddress); }
      catch (error) { errors.push(`Schema ${schemaId} lineage: ${error.message}`); }
      if (getParadigmOntologySchemaAddressDocumentId(sourceSchemaAddress) === documentId && sourceSchemaAddress?.schemaId === schemaId) {
        errors.push(`Schema ${schemaId} cannot derive from itself.`);
      }
      const mappingOrder = Array.isArray(lineage.mappingOrder)
        ? lineage.mappingOrder.map((id) => sanitizeText(id, "")).filter(Boolean)
        : [];
      const mappings = isObjectLike(lineage.mappingsBySourceColumnId) ? lineage.mappingsBySourceColumnId : {};
      if (new Set(mappingOrder).size !== mappingOrder.length
        || mappingOrder.length !== Object.keys(mappings).length
        || Object.keys(mappings).some((id) => !mappingOrder.includes(id))) {
        errors.push(`Schema ${schemaId} lineage mappingOrder does not exactly cover mappings.`);
      }
      const mappedLocalIds = new Set();
      mappingOrder.forEach((sourceColumnId) => {
        const mapping = mappings[sourceColumnId];
        const localColumnId = sanitizeText(mapping?.localColumnId, "");
        if (!isObjectLike(mapping) || sanitizeText(mapping.sourceColumnId, "") !== sourceColumnId) {
          errors.push(`Schema ${schemaId} has an invalid source-column mapping: ${sourceColumnId}`);
        }
        if (!localColumnId || !schema?.columnsById?.[localColumnId]) {
          errors.push(`Schema ${schemaId} lineage points to a missing local column.`);
        }
        if (mappedLocalIds.has(localColumnId)) errors.push(`Schema ${schemaId} lineage maps multiple source columns to ${localColumnId}.`);
        mappedLocalIds.add(localColumnId);
      });
      const history = Array.isArray(lineage.history) ? lineage.history : [];
      if (!Array.isArray(lineage.history) || history.length > 512) errors.push(`Schema ${schemaId} lineage history is invalid or unbounded.`);
      const forbiddenSnapshotKeys = new Set(["rowsById", "tablesById", "cellsByColumnId", "nestedTableId", "images"]);
      const scanLineage = (value, key = "", seen = new Set()) => {
        if (forbiddenSnapshotKeys.has(key) || key === "value") return true;
        if (!value || typeof value !== "object" || seen.has(value)) return false;
        seen.add(value);
        return Object.entries(value).some(([childKey, child]) => scanLineage(child, childKey, seen));
      };
      if (scanLineage(lineage)) errors.push(`Schema ${schemaId} lineage contains forbidden content snapshots.`);
    }
  });

  const schemaProvenanceHistory = Array.isArray(ontology.schemaProvenanceHistory) ? ontology.schemaProvenanceHistory : [];
  if (Object.prototype.hasOwnProperty.call(ontology, "schemaProvenanceHistory") && !Array.isArray(ontology.schemaProvenanceHistory)) {
    errors.push("schemaProvenanceHistory must be an array.");
  }
  if (schemaProvenanceHistory.length > PARADIGM_ONTOLOGY_PROVENANCE_LIMIT) {
    errors.push("schemaProvenanceHistory exceeds its safety capacity.");
  }
  const forbiddenProvenanceKeys = new Set(["rowsById", "tablesById", "cellsByColumnId", "nestedTableId", "images", "value"]);
  const provenanceContainsContent = (value, key = "", seen = new Set()) => {
    if (forbiddenProvenanceKeys.has(key)) return true;
    if (!value || typeof value !== "object" || seen.has(value)) return false;
    seen.add(value);
    return Object.entries(value).some(([childKey, child]) => provenanceContainsContent(child, childKey, seen));
  };
  if (schemaProvenanceHistory.some((record) => provenanceContainsContent(record))) {
    errors.push("schemaProvenanceHistory contains forbidden content snapshots.");
  }

  const localLineageEdges = new Map();
  Object.entries(schemasById).forEach(([schemaId, schema]) => {
    try {
      const sourceAddress = isObjectLike(schema?.sourceLineage)
        ? normalizeParadigmOntologySchemaAddress(schema.sourceLineage.sourceSchemaAddress)
        : null;
      if (getParadigmOntologySchemaAddressDocumentId(sourceAddress) === documentId && schemasById[sourceAddress.schemaId]) {
        localLineageEdges.set(schemaId, sourceAddress.schemaId);
      }
    } catch (_) {}
  });
  localLineageEdges.forEach((_sourceId, startId) => {
    const chain = new Set();
    let current = startId;
    while (current && localLineageEdges.has(current)) {
      if (chain.has(current)) {
        errors.push(`Schema lineage cycle detected at ${current}.`);
        break;
      }
      chain.add(current);
      current = localLineageEdges.get(current);
    }
  });

  const ownerByChildTableId = new Map();
  Object.entries(tablesById).forEach(([tableId, table]) => {
    if (!isObjectLike(table) || sanitizeText(table.id, "") !== tableId) errors.push(`Table identity mismatch: ${tableId}`);
    const schema = schemasById?.[sanitizeText(table?.schemaId, "")];
    if (!schema) {
      errors.push(`Table ${tableId} has a missing schema.`);
      return;
    }
    const rowOrder = keySetMatchesOrder(table?.rowOrder, table?.rowsById, `table ${tableId} rowOrder`);
    if (rowOrder.length > limits.maxRowsPerTable) errors.push(`Table ${tableId} exceeds max rows.`);
    const schemaColumnIds = documentSchemaVersion >= 2
      ? getParadigmOntologySchemaColumnIds(schema, true)
      : (Array.isArray(schema.columnOrder) ? schema.columnOrder : []);
    rowOrder.forEach((rowId) => {
      const row = table?.rowsById?.[rowId];
      if (!isObjectLike(row) || sanitizeText(row.id, "") !== rowId) errors.push(`Row identity mismatch: ${rowId}`);
      const cellKeys = Object.keys(isObjectLike(row?.cellsByColumnId) ? row.cellsByColumnId : {});
      const cellSet = new Set(cellKeys);
      if (cellKeys.length !== schemaColumnIds.length || schemaColumnIds.some((columnId) => !cellSet.has(columnId))) {
        errors.push(`Row ${rowId} cells do not exactly match schema ${schema.id}.`);
      }
      totalCells += cellKeys.length;
      schemaColumnIds.forEach((columnId) => {
        const cell = row?.cellsByColumnId?.[columnId];
        if (!isObjectLike(cell)) {
          errors.push(`Row ${rowId} has an invalid cell for column ${columnId}.`);
          return;
        }
        const nestedTableId = sanitizeText(cell.nestedTableId, "");
        const hasReferenceProperty = Object.prototype.hasOwnProperty.call(cell, "reference");
        if (hasReferenceProperty && !isObjectLike(cell.reference)) {
          errors.push(`Cell ${tableId}/${rowId}/${columnId} has a malformed reference property.`);
        } else if (isObjectLike(cell.reference)) {
          referenceCount += 1;
          if (documentSchemaVersion < 3) errors.push(`Cell ${tableId}/${rowId}/${columnId} uses reference before v3.`);
          const referenceValidation = validateParadigmOntologyCellReference(cell.reference);
          referenceValidation.errors.forEach((message) => errors.push(`Cell ${tableId}/${rowId}/${columnId}: ${message}`));
          if (nestedTableId) errors.push(`Referenced cell ${tableId}/${rowId}/${columnId} cannot own a local nested table.`);
          const source = referenceValidation.reference?.sourceAddress;
          if (source && source.documentId === documentId && source.tableId === tableId
            && source.rowId === rowId && source.columnId === columnId) {
            errors.push(`Cell ${tableId}/${rowId}/${columnId} cannot reference itself.`);
          }
        }
        if (!nestedTableId) return;
        const childTable = tablesById[nestedTableId];
        if (!childTable) {
          errors.push(`Cell ${tableId}/${rowId}/${columnId} points to a missing table.`);
          return;
        }
        const expectedSchemaId = sanitizeText(schema?.columnsById?.[columnId]?.childSchemaId, "");
        if (!expectedSchemaId || sanitizeText(childTable.schemaId, "") !== expectedSchemaId) {
          errors.push(`Nested table ${nestedTableId} is incompatible with column ${columnId}.`);
        }
        const owner = { parentTableId: tableId, parentRowId: rowId, parentColumnId: columnId };
        if (ownerByChildTableId.has(nestedTableId)) errors.push(`Nested table ${nestedTableId} has multiple owners.`);
        else ownerByChildTableId.set(nestedTableId, owner);
        if (canonicalJsonString(childTable.parentCellRef || null) !== canonicalJsonString(owner)) {
          errors.push(`Nested table ${nestedTableId} parentCellRef mismatch.`);
        }
      });
    });
  });

  Object.keys(tablesById).forEach((tableId) => {
    if (tableId === rootTableId) {
      if (ownerByChildTableId.has(tableId)) errors.push("Root table must not be owned by a cell.");
      return;
    }
    if (!ownerByChildTableId.has(tableId)) errors.push(`Table ${tableId} is unreachable or orphaned.`);
  });

  const visiting = new Set();
  const visited = new Set();
  let maxDepth = 0;
  const visit = (tableId, depth) => {
    if (visiting.has(tableId)) {
      errors.push(`Table graph cycle detected at ${tableId}.`);
      return;
    }
    if (visited.has(tableId)) return;
    if (depth > limits.maxDepth) errors.push(`Table graph exceeds max depth at ${tableId}.`);
    maxDepth = Math.max(maxDepth, depth);
    visiting.add(tableId);
    const table = tablesById[tableId];
    if (table) getParadigmOntologyTableChildren(ontology, table).forEach((childId) => visit(childId, depth + 1));
    visiting.delete(tableId);
    visited.add(tableId);
  };
  if (rootTableId && rootTable) visit(rootTableId, 1);
  if (visited.size !== Object.keys(tablesById).length) errors.push("Table graph contains unreachable instances.");
  if (Object.keys(tablesById).length > limits.maxTables) errors.push("Ontology exceeds max table count.");
  if (totalCells > limits.maxCells) errors.push("Ontology exceeds max cell count.");
  const bytes = workspacePerfByteLength(canonicalJsonString(ontology));
  if (bytes > limits.maxBytes) errors.push("Ontology exceeds max byte size.");
  return {
    ok: errors.length === 0,
    errors,
    stats: {
      schemaCount: Object.keys(schemasById).length,
      tableCount: Object.keys(tablesById).length,
      cellCount: totalCells,
      maxDepth,
      bytes,
      referenceCount,
      lineageCount,
    },
  };
}

function getParadigmOntologySchemaTables(ontology, schemaId) {
  return Object.values(ontology?.tablesById || {}).filter((table) => sanitizeText(table?.schemaId, "") === schemaId);
}

function pruneUnreferencedParadigmOntologySchemas(ontology) {
  const reachable = new Set();
  const queue = [sanitizeText(ontology?.rootSchemaId, "")]
    .concat(Object.values(ontology?.tablesById || {}).map((table) => sanitizeText(table?.schemaId, "")))
    .filter(Boolean);
  while (queue.length > 0) {
    const schemaId = queue.shift();
    if (!schemaId || reachable.has(schemaId)) continue;
    const schema = ontology?.schemasById?.[schemaId];
    if (!schema) continue;
    reachable.add(schemaId);
    for (const columnId of getParadigmOntologySchemaColumnIds(schema, true)) {
      const childSchemaId = sanitizeText(schema.columnsById?.[columnId]?.childSchemaId, "");
      if (childSchemaId && !reachable.has(childSchemaId)) queue.push(childSchemaId);
    }
  }
  let removed = 0;
  Object.keys(ontology?.schemasById || {}).forEach((schemaId) => {
    if (reachable.has(schemaId)) return;
    delete ontology.schemasById[schemaId];
    removed += 1;
  });
  return removed;
}

function selectParadigmOntologyRecovery(rawOntology, recovery) {
  const formalOntology = rawOntology == null ? null : deepClone(rawOntology, null);
  const formalHash = hashParadigmOntology(formalOntology);
  const fallbackDraft = formalOntology ? upgradeParadigmOntologyToV3(formalOntology) : createDefaultParadigmOntology();
  if (!isObjectLike(recovery?.draft) || sanitizeText(recovery?.status, "editing") === "committed") {
    return {
      draft: fallbackDraft,
      baseOntologyHash: formalHash,
      didRestoreRecovery: false,
      recoveryConflict: false,
      formalOntology,
      formalHash,
    };
  }
  const recoveryValidation = validateParadigmOntology(recovery.draft);
  if (!recoveryValidation.ok) {
    return {
      draft: fallbackDraft,
      baseOntologyHash: formalHash,
      didRestoreRecovery: false,
      recoveryConflict: false,
      formalOntology,
      formalHash,
    };
  }
  const recoveryBaseHash = sanitizeText(recovery.baseOntologyHash, "");
  const recoveryConflict = recoveryBaseHash !== formalHash;
  return {
    draft: upgradeParadigmOntologyToV3(recovery.draft) || deepClone(fallbackDraft, fallbackDraft),
    baseOntologyHash: recoveryConflict ? recoveryBaseHash : formalHash,
    didRestoreRecovery: true,
    recoveryConflict,
    formalOntology,
    formalHash,
  };
}

function restoreParadigmOntologySnapshot(ontology, snapshot) {
  Object.keys(ontology || {}).forEach((key) => delete ontology[key]);
  Object.entries(deepClone(snapshot, {}) || {}).forEach(([key, value]) => {
    ontology[key] = value;
  });
}

function getParadigmOntologySubtreeImpact(ontology, tableId) {
  const impact = { tableCount: 0, rowCount: 0, cellCount: 0, referenceCellCount: 0, schemaLineageCount: 0, maxDepth: 0 };
  const visited = new Set();
  const visit = (currentTableId, depth) => {
    if (visited.has(currentTableId)) return;
    const table = ontology?.tablesById?.[currentTableId];
    const schema = ontology?.schemasById?.[table?.schemaId];
    if (!table || !schema) return;
    visited.add(currentTableId);
    impact.tableCount += 1;
    if (paradigmOntologySchemaHasRetainedLineage(schema)) impact.schemaLineageCount += 1;
    impact.maxDepth = Math.max(impact.maxDepth, depth);
    const rowIds = Array.isArray(table.rowOrder) ? table.rowOrder : [];
    impact.rowCount += rowIds.length;
    impact.cellCount += rowIds.length * getParadigmOntologySchemaColumnIds(schema, true).length;
    rowIds.forEach((rowId) => {
      Object.values(table.rowsById?.[rowId]?.cellsByColumnId || {}).forEach((cell) => {
        if (isObjectLike(cell?.reference)) impact.referenceCellCount += 1;
      });
    });
    getParadigmOntologyTableChildren(ontology, table).forEach((childTableId) => visit(childTableId, depth + 1));
  };
  visit(sanitizeText(tableId, ""), 1);
  return impact;
}

function getParadigmOntologyNavigationPath(ontology, targetTableId) {
  const rootTableId = sanitizeText(ontology?.rootTableId, "");
  let currentTableId = sanitizeText(targetTableId, "");
  const reversed = [];
  const visited = new Set();
  while (currentTableId) {
    if (visited.has(currentTableId)) return { ok: false, path: [], error: "导航路径存在循环。" };
    if (reversed.length >= PARADIGM_ONTOLOGY_LIMITS.maxDepth) {
      return { ok: false, path: [], error: "导航路径超过最大层级。" };
    }
    visited.add(currentTableId);
    const table = ontology?.tablesById?.[currentTableId];
    const schema = ontology?.schemasById?.[table?.schemaId];
    if (!table || !schema) return { ok: false, path: [], error: "导航目标表格不存在。" };
    if (currentTableId === rootTableId) {
      if (table.parentCellRef != null) return { ok: false, path: [], error: "根表父引用异常。" };
      reversed.push({ tableId: currentTableId, schemaId: schema.id, label: "根表" });
      break;
    }
    const ref = table.parentCellRef;
    const parentTable = ontology?.tablesById?.[ref?.parentTableId];
    const parentSchema = ontology?.schemasById?.[parentTable?.schemaId];
    const parentRow = parentTable?.rowsById?.[ref?.parentRowId];
    const parentColumn = parentSchema?.columnsById?.[ref?.parentColumnId];
    const parentCell = parentRow?.cellsByColumnId?.[ref?.parentColumnId];
    if (!parentTable || !parentSchema || !parentRow || !parentColumn || !parentCell
      || sanitizeText(parentCell.nestedTableId, "") !== currentTableId) {
      return { ok: false, path: [], error: "导航父子引用不一致。" };
    }
    const parentRowOrder = Array.isArray(parentTable.rowOrder) ? parentTable.rowOrder : null;
    const parentColumnOrder = Array.isArray(parentSchema.columnOrder) ? parentSchema.columnOrder : null;
    const rowIndex = parentRowOrder?.indexOf(parentRow.id) ?? -1;
    const rowNameColumnId = sanitizeText(parentColumnOrder?.[0], "");
    const rowNameColumn = parentSchema?.columnsById?.[rowNameColumnId];
    const rowNameCell = parentRow?.cellsByColumnId?.[rowNameColumnId];
    if (!parentRowOrder || !parentColumnOrder || rowIndex < 0 || !rowNameColumnId || !rowNameColumn || !rowNameCell) {
      return { ok: false, path: [], error: "导航父行结构不完整。" };
    }
    const rowLabel = sanitizeText(rowNameCell.value, "").split(/\r?\n/)[0].slice(0, 32);
    reversed.push({
      tableId: currentTableId,
      schemaId: schema.id,
      label: rowLabel || `第 ${rowIndex + 1} 行`,
    });
    currentTableId = parentTable.id;
  }
  if (!reversed.length || reversed[reversed.length - 1].tableId !== rootTableId) {
    return { ok: false, path: [], error: "导航路径未到达根表。" };
  }
  return { ok: true, path: reversed.reverse(), error: "" };
}

function resolveParadigmOntologyViewStateTableId(ontology, record) {
  const rootTableId = sanitizeText(ontology?.rootTableId, "");
  if (!rootTableId || !ontology?.tablesById?.[rootTableId]) return "";
  const candidates = [];
  const targetTableId = sanitizeText(record?.tableId, "");
  if (targetTableId) candidates.push(targetTableId);
  const tablePath = Array.isArray(record?.tablePath) ? record.tablePath : [];
  for (let index = tablePath.length - 1; index >= 0; index -= 1) {
    const tableId = sanitizeText(tablePath[index]?.tableId || tablePath[index], "");
    if (tableId && !candidates.includes(tableId)) candidates.push(tableId);
  }
  for (const tableId of candidates) {
    if (getParadigmOntologyNavigationPath(ontology, tableId).ok) return tableId;
  }
  return rootTableId;
}

function buildParadigmOntologyViewStateRecord(ontology, tableId, identity = {}) {
  const navigation = getParadigmOntologyNavigationPath(ontology, tableId);
  if (!navigation.ok) return null;
  return {
    canonicalDataPath: sanitizeText(identity.dataPath, ""),
    paradigmItemId: sanitizeText(identity.paradigmItemId, ""),
    tableId: sanitizeText(tableId, ""),
    tablePath: navigation.path.map((entry) => sanitizeText(entry.tableId, "")).filter(Boolean),
    generation: Number(identity.generation) || 0,
    sessionId: sanitizeText(identity.sessionId, ""),
    updatedAt: Date.now(),
  };
}

function addParadigmOntologyRow(ontology, tableId, limits = PARADIGM_ONTOLOGY_LIMITS) {
  const table = ontology?.tablesById?.[tableId];
  const schema = ontology?.schemasById?.[table?.schemaId];
  if (!table || !schema) return null;
  if (table.rowOrder.length >= limits.maxRowsPerTable) throw new Error("已达到单表最大行数。");
  const snapshot = deepClone(ontology, null);
  try {
    const row = createParadigmOntologyRow(schema);
    table.rowsById[row.id] = row;
    table.rowOrder.push(row.id);
    table.updatedAt = nowString();
    ontology.updatedAt = table.updatedAt;
    const validation = validateParadigmOntology(ontology, limits);
    if (!validation.ok) throw new Error(validation.errors[0] || "新增行后 Ontology 结构无效。");
    return row;
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function addParadigmOntologyColumn(ontology, schemaId, label = "新列", limits = PARADIGM_ONTOLOGY_LIMITS) {
  const schema = ontology?.schemasById?.[schemaId];
  if (!schema) return null;
  const maxActiveColumns = Number(limits.maxActiveColumnsPerSchema || limits.maxColumnsPerSchema || 32);
  const maxTotalColumns = Number(limits.maxTotalColumnsPerSchema || maxActiveColumns);
  if (schema.columnOrder.length >= maxActiveColumns) throw new Error("已达到单表最大显示列数。");
  if (getParadigmOntologySchemaColumnIds(schema, true).length >= maxTotalColumns) throw new Error("已达到单表历史列总量上限。");
  const snapshot = deepClone(ontology, null);
  try {
  const timestamp = nowString();
  const columnId = createReservedParadigmOntologyColumnId(ontology);
  schema.columnsById[columnId] = {
    id: columnId,
    label: sanitizeText(label, "新列"),
    cellType: "long-text",
    childSchemaId: null,
    lifecycleState: "active",
    archivedAt: null,
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  schema.columnOrder.push(columnId);
  getParadigmOntologySchemaTables(ontology, schemaId).forEach((table) => {
    table.rowOrder.forEach((rowId) => {
      table.rowsById[rowId].cellsByColumnId[columnId] = createParadigmOntologyCell();
      table.rowsById[rowId].updatedAt = timestamp;
    });
    table.updatedAt = timestamp;
  });
  schema.updatedAt = timestamp;
  ontology.updatedAt = timestamp;
    const validation = validateParadigmOntology(ontology, limits);
    if (!validation.ok) throw new Error(validation.errors[0] || "新增列后 Ontology 结构无效。");
    return schema.columnsById[columnId];
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function deleteParadigmOntologyTableSubtree(ontology, tableId) {
  const table = ontology?.tablesById?.[tableId];
  if (!table) return 0;
  let removed = 1;
  getParadigmOntologyTableChildren(ontology, table).forEach((childTableId) => {
    removed += deleteParadigmOntologyTableSubtree(ontology, childTableId);
  });
  delete ontology.tablesById[tableId];
  return removed;
}

function getParadigmOntologyTableSubtreeDataImpact(ontology, tableId) {
  const impact = { tableCount: 0, rowCount: 0, cellCount: 0, dataCellCount: 0, referenceCellCount: 0, schemaLineageCount: 0, maxDepth: 0 };
  const visiting = new Set();
  const visited = new Set();
  const visit = (currentTableId, depth) => {
    const id = sanitizeText(currentTableId, "");
    if (!id || visiting.has(id) || visited.has(id)) {
      throw new Error("子表结构存在循环或重复引用，已阻止破坏性操作。");
    }
    const table = ontology?.tablesById?.[id];
    const schema = ontology?.schemasById?.[table?.schemaId];
    if (!table || !schema) throw new Error("子表结构不完整，已阻止破坏性操作。");
    visiting.add(id);
    visited.add(id);
    impact.tableCount += 1;
    if (paradigmOntologySchemaHasRetainedLineage(schema)) impact.schemaLineageCount += 1;
    impact.maxDepth = Math.max(impact.maxDepth, depth);
    for (const rowId of Array.isArray(table.rowOrder) ? table.rowOrder : []) {
      const row = table.rowsById?.[rowId];
      if (!row) throw new Error("子表行结构不完整，已阻止破坏性操作。");
      impact.rowCount += 1;
      for (const columnId of getParadigmOntologySchemaColumnIds(schema, true)) {
        const cell = row.cellsByColumnId?.[columnId];
        if (!cell) throw new Error("子表单元格结构不完整，已阻止破坏性操作。");
        impact.cellCount += 1;
        if (paradigmOntologyCellHasRetainedData(cell)) impact.dataCellCount += 1;
        if (isObjectLike(cell.reference)) impact.referenceCellCount += 1;
        const nestedTableId = sanitizeText(cell.nestedTableId, "");
        if (nestedTableId) visit(nestedTableId, depth + 1);
      }
    }
    visiting.delete(id);
  };
  visit(tableId, 1);
  return impact;
}

function getParadigmOntologyRowNestedDataImpact(ontology, tableId, rowId) {
  const table = ontology?.tablesById?.[tableId];
  const schema = ontology?.schemasById?.[table?.schemaId];
  const row = table?.rowsById?.[rowId];
  if (!table || !schema || !row) throw new Error("无法定位待删除行。");
  const validation = validateParadigmOntology(ontology);
  if (!validation.ok) throw new Error(validation.errors[0] || "Ontology 结构异常，已阻止删除行。");
  const impact = {
    branchCount: 0,
    dataBranchCount: 0,
    tableCount: 0,
    rowCount: 0,
    cellCount: 0,
    dataCellCount: 0,
    referenceCellCount: 0,
    schemaLineageCount: 0,
    maxDepth: 0,
  };
  getParadigmOntologySchemaColumnIds(schema, true).forEach((columnId) => {
    const nestedTableId = sanitizeText(row.cellsByColumnId?.[columnId]?.nestedTableId, "");
    if (!nestedTableId) return;
    impact.branchCount += 1;
    const branch = getParadigmOntologyTableSubtreeDataImpact(ontology, nestedTableId);
    if (branch.dataCellCount > 0 || branch.schemaLineageCount > 0) impact.dataBranchCount += 1;
    impact.tableCount += branch.tableCount;
    impact.rowCount += branch.rowCount;
    impact.cellCount += branch.cellCount;
    impact.dataCellCount += branch.dataCellCount;
    impact.referenceCellCount += branch.referenceCellCount;
    impact.schemaLineageCount += branch.schemaLineageCount;
    impact.maxDepth = Math.max(impact.maxDepth, branch.maxDepth);
  });
  return impact;
}

function getParadigmOntologyColumnNestedDataImpact(ontology, schemaId, columnId) {
  const schema = ontology?.schemasById?.[schemaId];
  if (!schema?.columnsById?.[columnId]) throw new Error("无法定位待删除列。");
  const validation = validateParadigmOntology(ontology);
  if (!validation.ok) throw new Error(validation.errors[0] || "Ontology 结构异常，已阻止删除列。");
  const impact = {
    branchCount: 0,
    dataBranchCount: 0,
    tableCount: 0,
    rowCount: 0,
    cellCount: 0,
    dataCellCount: 0,
    referenceCellCount: 0,
    schemaLineageCount: paradigmOntologySchemaHasRetainedLineage(schema) ? 1 : 0,
    maxDepth: 0,
  };
  getParadigmOntologySchemaTables(ontology, schemaId).forEach((table) => {
    table.rowOrder.forEach((rowId) => {
      const nestedTableId = sanitizeText(table.rowsById?.[rowId]?.cellsByColumnId?.[columnId]?.nestedTableId, "");
      if (!nestedTableId) return;
      impact.branchCount += 1;
      const branch = getParadigmOntologyTableSubtreeDataImpact(ontology, nestedTableId);
      if (branch.dataCellCount > 0 || branch.schemaLineageCount > 0) impact.dataBranchCount += 1;
      impact.tableCount += branch.tableCount;
      impact.rowCount += branch.rowCount;
      impact.cellCount += branch.cellCount;
      impact.dataCellCount += branch.dataCellCount;
      impact.referenceCellCount += branch.referenceCellCount;
      impact.schemaLineageCount += branch.schemaLineageCount;
      impact.maxDepth = Math.max(impact.maxDepth, branch.maxDepth);
    });
  });
  return impact;
}

function deleteParadigmOntologyRow(ontology, tableId, rowId) {
  const table = ontology?.tablesById?.[tableId];
  if (!table?.rowsById?.[rowId]) return false;
  const nestedDataImpact = getParadigmOntologyRowNestedDataImpact(ontology, tableId, rowId);
  const row = table.rowsById[rowId];
  const directDataCellCount = Object.values(row.cellsByColumnId || {})
    .filter((cell) => paradigmOntologyCellHasRetainedData(cell)).length;
  if (directDataCellCount > 0 || nestedDataImpact.dataBranchCount > 0) {
    const error = new Error(`该行仍有 ${directDataCellCount} 个直接内容单元格、${nestedDataImpact.dataBranchCount} 个含数据的子表分支；为保护历史记录，不能删除。`);
    error.code = nestedDataImpact.dataBranchCount > 0 ? "ONTOLOGY_ROW_HAS_NESTED_DATA" : "ONTOLOGY_ROW_HAS_DATA";
    error.impact = nestedDataImpact;
    error.impact.directDataCellCount = directDataCellCount;
    throw error;
  }
  const snapshot = deepClone(ontology, null);
  Object.values(row.cellsByColumnId || {}).forEach((cell) => {
    const nestedTableId = sanitizeText(cell?.nestedTableId, "");
    if (nestedTableId) deleteParadigmOntologyTableSubtree(ontology, nestedTableId);
  });
  delete table.rowsById[rowId];
  table.rowOrder = table.rowOrder.filter((id) => id !== rowId);
  table.updatedAt = nowString();
  ontology.updatedAt = table.updatedAt;
  const validation = validateParadigmOntology(ontology);
  if (!validation.ok) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw new Error(validation.errors[0] || "删除行后 Ontology 结构无效。");
  }
  return true;
}

function deleteParadigmOntologyColumn(ontology, schemaId, columnId) {
  const schema = ontology?.schemasById?.[schemaId];
  if (!schema?.columnsById?.[columnId]) return false;
  if (!schema.columnOrder.includes(columnId)) return false;
  if (schema.columnOrder.length <= 1) throw new Error("至少保留一个显示列。");
  const snapshot = deepClone(ontology, null);
  const timestamp = nowString();
  schema.columnOrder = schema.columnOrder.filter((id) => id !== columnId);
  schema.archivedColumnOrder = Array.isArray(schema.archivedColumnOrder) ? schema.archivedColumnOrder : [];
  if (!schema.archivedColumnOrder.includes(columnId)) schema.archivedColumnOrder.push(columnId);
  schema.columnsById[columnId].lifecycleState = "archived";
  schema.columnsById[columnId].archivedAt = timestamp;
  schema.columnsById[columnId].updatedAt = timestamp;
  schema.updatedAt = timestamp;
  ontology.updatedAt = schema.updatedAt;
  const validation = validateParadigmOntology(ontology);
  if (!validation.ok) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw new Error(validation.errors[0] || "归档列后 Ontology 结构无效。");
  }
  return true;
}

function restoreParadigmOntologyColumn(ontology, schemaId, columnId, limits = PARADIGM_ONTOLOGY_LIMITS) {
  const schema = ontology?.schemasById?.[schemaId];
  const column = schema?.columnsById?.[columnId];
  if (!schema || !column || !Array.isArray(schema.archivedColumnOrder) || !schema.archivedColumnOrder.includes(columnId)) return false;
  const maxActiveColumns = Number(limits.maxActiveColumnsPerSchema || limits.maxColumnsPerSchema || 32);
  if (schema.columnOrder.length >= maxActiveColumns) throw new Error("已达到单表最大显示列数，暂不能恢复更多列。");
  const snapshot = deepClone(ontology, null);
  const timestamp = nowString();
  schema.archivedColumnOrder = schema.archivedColumnOrder.filter((id) => id !== columnId);
  schema.columnOrder.push(columnId);
  column.lifecycleState = "active";
  column.archivedAt = null;
  column.restoredAt = timestamp;
  column.updatedAt = timestamp;
  schema.updatedAt = timestamp;
  ontology.updatedAt = timestamp;
  const validation = validateParadigmOntology(ontology, limits);
  if (!validation.ok) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw new Error(validation.errors[0] || "恢复列后 Ontology 结构无效。");
  }
  return true;
}

function moveParadigmOntologyOrder(orderLike, id, delta) {
  const order = Array.isArray(orderLike) ? orderLike : [];
  const index = order.indexOf(id);
  const nextIndex = index + Number(delta || 0);
  if (index < 0 || nextIndex < 0 || nextIndex >= order.length) return false;
  [order[index], order[nextIndex]] = [order[nextIndex], order[index]];
  return true;
}

function createNestedParadigmOntologyTable(ontology, parentTableId, parentRowId, parentColumnId) {
  const parentTable = ontology?.tablesById?.[parentTableId];
  const parentSchema = ontology?.schemasById?.[parentTable?.schemaId];
  const parentRow = parentTable?.rowsById?.[parentRowId];
  const parentColumn = parentSchema?.columnsById?.[parentColumnId];
  const cell = parentRow?.cellsByColumnId?.[parentColumnId];
  const childSchema = ontology?.schemasById?.[sanitizeText(parentColumn?.childSchemaId, "")];
  if (!parentTable || !parentRow || !parentColumn || !cell || !childSchema) throw new Error("父单元格尚未声明有效的子表 schema。");
  if (isObjectLike(cell.reference)) throw new Error("引用单元格不能同时拥有本地子表。");
  if (sanitizeText(cell.nestedTableId, "")) throw new Error("该单元格已经拥有子表。");
  reserveParadigmOntologyColumnIds(ontology, getParadigmOntologySchemaColumnIds(childSchema, true));
  const childTable = createParadigmOntologyTable(childSchema, { parentTableId, parentRowId, parentColumnId });
  ontology.tablesById[childTable.id] = childTable;
  cell.nestedTableId = childTable.id;
  parentRow.updatedAt = nowString();
  parentTable.updatedAt = parentRow.updatedAt;
  ontology.updatedAt = parentRow.updatedAt;
  const validation = validateParadigmOntology(ontology);
  if (!validation.ok) {
    cell.nestedTableId = null;
    delete ontology.tablesById[childTable.id];
    throw new Error(validation.errors[0] || "子表结构无效。");
  }
  return childTable;
}

function createParadigmOntologyNestedTableAtomic(ontology, parentTableId, parentRowId, parentColumnId, options = {}) {
  const parentTable = ontology?.tablesById?.[parentTableId];
  const parentSchema = ontology?.schemasById?.[parentTable?.schemaId];
  const parentRow = parentTable?.rowsById?.[parentRowId];
  const parentColumn = parentSchema?.columnsById?.[parentColumnId];
  const cell = parentRow?.cellsByColumnId?.[parentColumnId];
  if (!parentTable || !parentSchema || !parentRow || !parentColumn || !cell) {
    throw new Error("无法定位父单元格。");
  }
  if (isObjectLike(cell.reference)) throw new Error("引用单元格不能同时拥有本地子表。");
  const existingTableId = sanitizeText(cell.nestedTableId, "");
  if (existingTableId) {
    const existingTable = ontology?.tablesById?.[existingTableId];
    if (!existingTable) throw new Error("父单元格指向的子表不存在。");
    return { table: existingTable, schema: ontology.schemasById[existingTable.schemaId], createdTable: false, createdSchema: false };
  }
  if (!sanitizeText(parentColumn.childSchemaId, "") && paradigmOntologySchemaHasRetainedLineage(parentSchema)) {
    throw createParadigmOntologyContractError(
      "ONTOLOGY_SHARED_SCHEMA_SOURCE_OWNED",
      "当前列属于共享结构，只有来源 owner 可以建立新的子 Schema。",
    );
  }
  const snapshot = deepClone(ontology, null);
  try {
    let childSchema = ontology?.schemasById?.[sanitizeText(parentColumn.childSchemaId, "")];
    let createdSchema = false;
    if (!childSchema) {
      const rawColumns = Array.isArray(options.columns) && options.columns.length > 0
        ? options.columns
        : [{ label: "内容", cellType: "long-text" }];
      childSchema = createParadigmOntologySchema(
        sanitizeText(options.schemaName, `${sanitizeText(parentColumn.label, "当前列")}明细`),
        rawColumns,
        ontology,
      );
      ontology.schemasById[childSchema.id] = childSchema;
      reserveParadigmOntologyColumnIds(ontology, getParadigmOntologySchemaColumnIds(childSchema, true));
      parentColumn.childSchemaId = childSchema.id;
      parentColumn.updatedAt = nowString();
      parentSchema.updatedAt = parentColumn.updatedAt;
      createdSchema = true;
    }
    const childTable = createNestedParadigmOntologyTable(ontology, parentTableId, parentRowId, parentColumnId);
    const validation = validateParadigmOntology(ontology, options.limits || PARADIGM_ONTOLOGY_LIMITS);
    if (!validation.ok) throw new Error(validation.errors[0] || "子表结构无效。");
    return { table: childTable, schema: childSchema, createdTable: true, createdSchema };
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function deleteParadigmOntologyNestedTable(ontology, tableId) {
  const id = sanitizeText(tableId, "");
  if (!id || id === sanitizeText(ontology?.rootTableId, "")) throw new Error("根表不能作为子表删除。");
  const table = ontology?.tablesById?.[id];
  const ref = table?.parentCellRef;
  const parentTable = ontology?.tablesById?.[ref?.parentTableId];
  const parentRow = parentTable?.rowsById?.[ref?.parentRowId];
  const parentCell = parentRow?.cellsByColumnId?.[ref?.parentColumnId];
  if (!table || !parentTable || !parentRow || !parentCell || sanitizeText(parentCell.nestedTableId, "") !== id) {
    throw new Error("子表父引用不完整，已阻止删除。");
  }
  const snapshot = deepClone(ontology, null);
  const impact = getParadigmOntologySubtreeImpact(ontology, id);
  try {
    parentCell.nestedTableId = null;
    parentRow.updatedAt = nowString();
    parentTable.updatedAt = parentRow.updatedAt;
    ontology.updatedAt = parentRow.updatedAt;
    deleteParadigmOntologyTableSubtree(ontology, id);
    const validation = validateParadigmOntology(ontology);
    if (!validation.ok) throw new Error(validation.errors[0] || "删除子表后 Ontology 结构无效。");
    return { parentTableId: parentTable.id, impact };
  } catch (error) {
    restoreParadigmOntologySnapshot(ontology, snapshot);
    throw error;
  }
}

function compactParadigmOntology(ontology, preserveRowIds = new Set()) {
  const draft = deepClone(ontology, null);
  if (!draft) return null;
  Object.values(draft.tablesById || {}).forEach((table) => {
    const removable = (Array.isArray(table?.rowOrder) ? table.rowOrder : []).filter((rowId) => {
      const row = table?.rowsById?.[rowId];
      const cells = Object.values(row?.cellsByColumnId || {});
      return !preserveRowIds.has(rowId)
        && cells.length > 0
        && cells.every((cell) => !paradigmOntologyCellHasRetainedData(cell) && !sanitizeText(cell?.nestedTableId, ""));
    });
    removable.forEach((rowId) => {
      delete table.rowsById[rowId];
    });
    table.rowOrder = table.rowOrder.filter((rowId) => !removable.includes(rowId));
  });
  draft.updatedAt = nowString();
  return draft;
}

function normalizeBridgeScopeType(value, fallback = "note") {
  const scope = sanitizeText(value, fallback);
  if (scope === "workspace" || scope === "global") return scope;
  return "note";
}

function createBridgeScopeKey({ scopeType = "note", notePath = "", viewType = "" } = {}) {
  const normalizedScope = normalizeBridgeScopeType(scopeType);
  const normalizedNotePath = normalizedScope === "note" ? sanitizeText(notePath, "") : "*";
  const normalizedViewType = sanitizeText(viewType, "*");
  return [normalizedScope, normalizedNotePath, normalizedViewType].join("::");
}

function createBridgeRouteKey({ scopeType = "note", notePath = "", viewType = "", instanceId = "" } = {}) {
  return [
    createBridgeScopeKey({ scopeType, notePath, viewType }),
    sanitizeText(instanceId, "default"),
  ].join("::");
}

function ensureObsidianBridgeBus() {
  const existing = window[OBSIDIAN_BRIDGE_BUS_GLOBAL];
  if (
    existing
    && existing.protocol === OBSIDIAN_BRIDGE_PROTOCOL
    && existing.version === OBSIDIAN_BRIDGE_VERSION
    && typeof existing.registerHost === "function"
  ) {
    return existing;
  }

  const hostRecords = new Map();
  const activeRouteByScopeKey = new Map();
  const diagnostics = [];
  const pendingStateByScopeKey = new Map();

  const pushDiagnostic = (event, payload = {}) => {
    diagnostics.push({
      ts: nowString(),
      event: sanitizeText(event, "unknown"),
      payload: JSON.parse(JSON.stringify(payload || {})),
    });
    while (diagnostics.length > OBSIDIAN_BRIDGE_DIAGNOSTIC_LIMIT) diagnostics.shift();
  };

  const isExpired = (record) => {
    if (!record) return true;
    const expiresAt = Number(record.expiresAt);
    return Number.isFinite(expiresAt) && expiresAt > 0 && expiresAt <= Date.now();
  };

  const cleanupExpiredHosts = () => {
    activeRouteByScopeKey.forEach((routeKey, scopeKey) => {
      const record = hostRecords.get(routeKey);
      if (!record || isExpired(record)) {
        if (record) {
          pushDiagnostic("host_expired", {
            scopeKey,
            routeKey,
            leaseId: sanitizeText(record.leaseId, ""),
          });
          hostRecords.delete(routeKey);
        }
        activeRouteByScopeKey.delete(scopeKey);
      }
    });
  };

  const buildRecord = (input = {}) => {
    const scopeType = normalizeBridgeScopeType(input.scopeType);
    const notePath = scopeType === "note" ? sanitizeText(input.notePath, "") : "";
    const viewType = sanitizeText(input.viewType, sanitizeText(input.bridgeName, "*"));
    const instanceId = sanitizeText(input.instanceId, sanitizeText(input.hostId, "default"));
    const heartbeatTtlMs = Math.max(500, Number(input.heartbeatTtlMs) || 4000);
    const expiresAt = Number.isFinite(Number(input.expiresAt))
      ? Number(input.expiresAt)
      : Date.now() + heartbeatTtlMs;
    const registrationEpoch = Math.max(1, Number(input.registrationEpoch) || 1);
    const scopeKey = createBridgeScopeKey({ scopeType, notePath, viewType });
    const routeKey = createBridgeRouteKey({ scopeType, notePath, viewType, instanceId });
    return {
      protocol: OBSIDIAN_BRIDGE_PROTOCOL,
      version: OBSIDIAN_BRIDGE_VERSION,
      pluginId: sanitizeText(input.pluginId || input.sourcePlugin, ""),
      sourcePlugin: sanitizeText(input.sourcePlugin || input.pluginId, ""),
      scopeType,
      notePath,
      viewType,
      bridgeName: sanitizeText(input.bridgeName, ""),
      instanceId,
      hostId: sanitizeText(input.hostId, instanceId),
      leaseId: sanitizeText(input.leaseId, ""),
      handoffFromLeaseId: sanitizeText(input.handoffFromLeaseId, ""),
      registrationEpoch,
      heartbeatTtlMs,
      expiresAt,
      routeKey,
      scopeKey,
      capabilities: Array.isArray(input.capabilities) ? [...new Set(input.capabilities.map((entry) => sanitizeText(entry, "")).filter(Boolean))] : [],
      bridge: input.bridge || null,
      ready: input.payload?.ready === true || input.ready === true,
      isConnected: input.payload?.isConnected === true || input.isConnected === true,
      meta: JSON.parse(JSON.stringify(input.payload || input.meta || {})),
      updatedAt: Date.now(),
    };
  };

  const canActivateRecord = (current, next) => {
    if (!current) return true;
    if (isExpired(current)) return true;
    if (current.routeKey === next.routeKey && current.leaseId === next.leaseId) return true;
    if (next.handoffFromLeaseId && next.handoffFromLeaseId === current.leaseId) return true;
    return next.registrationEpoch > Number(current.registrationEpoch || 0);
  };

  const resolveActiveRecord = (selector = {}) => {
    cleanupExpiredHosts();
    const directRouteKey = sanitizeText(selector.routeKey, "");
    if (directRouteKey) {
      const record = hostRecords.get(directRouteKey) || null;
      if (!record || activeRouteByScopeKey.get(record.scopeKey) !== directRouteKey || isExpired(record)) return null;
      return record;
    }
    const scopeKey = createBridgeScopeKey(selector);
    const routeKey = activeRouteByScopeKey.get(scopeKey);
    if (!routeKey) return null;
    const record = hostRecords.get(routeKey) || null;
    if (!record || isExpired(record)) {
      activeRouteByScopeKey.delete(scopeKey);
      if (record) hostRecords.delete(routeKey);
      return null;
    }
    return record;
  };

  const cleanupExpiredPendingStates = () => {
    for (const [scopeKey, entry] of pendingStateByScopeKey.entries()) {
      const expiresAt = Number(entry?.expiresAt);
      if (Number.isFinite(expiresAt) && expiresAt > 0 && expiresAt <= Date.now()) {
        pendingStateByScopeKey.delete(scopeKey);
        pushDiagnostic("queue_expired", {
          scopeKey,
          routeKey: sanitizeText(entry?.routeKey, ""),
        });
      }
    }
  };

  const queueState = (message = {}) => {
    cleanupExpiredHosts();
    cleanupExpiredPendingStates();
    const scopeType = normalizeBridgeScopeType(message.scopeType);
    const notePath = scopeType === "note" ? sanitizeText(message.notePath, "") : "";
    const viewType = sanitizeText(message.viewType, sanitizeText(message.channel, "*"));
    const scopeKey = createBridgeScopeKey({ scopeType, notePath, viewType });
    const routeKey = sanitizeText(message.routeKey, createBridgeRouteKey({
      scopeType,
      notePath,
      viewType,
      instanceId: sanitizeText(message.instanceId, "default"),
    }));
    const ttlMs = Math.max(500, Number(message.payload?.ttlMs) || Number(message.ttlMs) || OBSIDIAN_BRIDGE_PENDING_TTL_MS);
    pendingStateByScopeKey.set(scopeKey, {
      scopeKey,
      routeKey,
      state: JSON.parse(JSON.stringify(message.payload?.state ?? {})),
      options: JSON.parse(JSON.stringify(message.payload?.options ?? {})),
      sourcePlugin: sanitizeText(message.sourcePlugin, ""),
      source: sanitizeText(message.source, "obsidian-bridge-bus"),
      registrationEpoch: Number(message.registrationEpoch) || 0,
      queuedAt: Date.now(),
      expiresAt: Date.now() + ttlMs,
    });
    pushDiagnostic("queue_state", {
      scopeKey,
      routeKey,
      ttlMs,
      sourcePlugin: sanitizeText(message.sourcePlugin, ""),
    });
    while (pendingStateByScopeKey.size > OBSIDIAN_BRIDGE_PENDING_LIMIT) {
      const oldestKey = pendingStateByScopeKey.keys().next().value;
      pendingStateByScopeKey.delete(oldestKey);
    }
    return { ok: true, status: "queued", queued: true, queueKey: scopeKey, routeKey };
  };

  const flushPendingStateForRecord = async (record) => {
    cleanupExpiredPendingStates();
    if (!record) return false;
    const pending = pendingStateByScopeKey.get(record.scopeKey);
    if (!pending) return false;
    if (Number(pending.registrationEpoch || 0) > 0 && Number(record.registrationEpoch || 0) < Number(pending.registrationEpoch || 0)) {
      return false;
    }
    if (typeof record.bridge?.applyState !== "function") return false;
    try {
      const result = await record.bridge.applyState(
        JSON.parse(JSON.stringify(pending.state)),
        Object.assign({}, JSON.parse(JSON.stringify(pending.options)), {
          source: sanitizeText(pending.source, "obsidian-bridge-queue"),
          rerender: pending.options?.rerender !== false,
        }),
      );
      pendingStateByScopeKey.delete(record.scopeKey);
      pushDiagnostic("queue_flushed", {
        scopeKey: record.scopeKey,
        routeKey: record.routeKey,
        leaseId: record.leaseId,
        queuedAt: pending.queuedAt,
      });
      return result?.ok !== false;
    } catch (error) {
      pushDiagnostic("queue_flush_error", {
        scopeKey: record.scopeKey,
        routeKey: record.routeKey,
        error: sanitizeText(error?.message, "unknown"),
      });
      return false;
    }
  };

  const hasCapability = (record, capability) => {
    if (!capability) return true;
    return Array.isArray(record?.capabilities) && record.capabilities.includes(capability);
  };

  const registerHost = (input = {}) => {
    cleanupExpiredHosts();
    const next = buildRecord(input);
    if (next.scopeType === "note" && !next.notePath) {
      pushDiagnostic("host_register_rejected", { reason: "missing-notePath", routeKey: next.routeKey, leaseId: next.leaseId });
      return { ok: false, reason: "missing-notePath", routeKey: next.routeKey, scopeKey: next.scopeKey };
    }
    if (!next.viewType || !next.instanceId || !next.hostId || !next.leaseId) {
      pushDiagnostic("host_register_rejected", { reason: "missing-identity", routeKey: next.routeKey });
      return { ok: false, reason: "missing-identity", routeKey: next.routeKey, scopeKey: next.scopeKey };
    }
    if (next.ready !== true || next.isConnected !== true || !next.bridge) {
      pushDiagnostic("host_register_rejected", { reason: "host-not-ready", routeKey: next.routeKey, leaseId: next.leaseId });
      return { ok: false, reason: "host-not-ready", routeKey: next.routeKey, scopeKey: next.scopeKey };
    }
    const current = resolveActiveRecord(next);
    if (!canActivateRecord(current, next)) {
      pushDiagnostic("host_register_rejected", {
        reason: "active-host-exists",
        routeKey: next.routeKey,
        leaseId: next.leaseId,
        activeRouteKey: current?.routeKey || "",
      });
      return { ok: false, reason: "active-host-exists", routeKey: next.routeKey, scopeKey: next.scopeKey };
    }
    activeRouteByScopeKey.set(next.scopeKey, next.routeKey);
    hostRecords.set(next.routeKey, next);
    if (current && current.routeKey !== next.routeKey) {
      hostRecords.delete(current.routeKey);
    }
    pushDiagnostic("host_register", {
      routeKey: next.routeKey,
      scopeKey: next.scopeKey,
      leaseId: next.leaseId,
      registrationEpoch: next.registrationEpoch,
      notePath: next.notePath,
    });
    void flushPendingStateForRecord(next);
    return {
      ok: true,
      routeKey: next.routeKey,
      scopeKey: next.scopeKey,
      leaseId: next.leaseId,
      registrationEpoch: next.registrationEpoch,
    };
  };

  const unregisterHost = (input = {}) => {
    cleanupExpiredHosts();
    const current = resolveActiveRecord(input);
    if (!current) return false;
    const leaseId = sanitizeText(input.leaseId, "");
    const hostId = sanitizeText(input.hostId, "");
    if (leaseId && current.leaseId !== leaseId) return false;
    if (hostId && current.hostId !== hostId) return false;
    hostRecords.delete(current.routeKey);
    if (activeRouteByScopeKey.get(current.scopeKey) === current.routeKey) {
      activeRouteByScopeKey.delete(current.scopeKey);
    }
    pushDiagnostic("host_unregister", {
      routeKey: current.routeKey,
      scopeKey: current.scopeKey,
      leaseId: current.leaseId,
    });
    return true;
  };

  const heartbeat = (input = {}) => {
    cleanupExpiredHosts();
    const current = resolveActiveRecord(input);
    if (!current) return false;
    const leaseId = sanitizeText(input.leaseId, "");
    if (leaseId && current.leaseId !== leaseId) return false;
    const heartbeatTtlMs = Math.max(500, Number(input.heartbeatTtlMs) || Number(current.heartbeatTtlMs) || 4000);
    current.heartbeatTtlMs = heartbeatTtlMs;
    current.expiresAt = Date.now() + heartbeatTtlMs;
    current.updatedAt = Date.now();
    hostRecords.set(current.routeKey, current);
    return true;
  };

  const sendCommandSync = (message = {}) => {
    cleanupExpiredHosts();
    cleanupExpiredPendingStates();
    const type = sanitizeText(message.type, "");
    const current = resolveActiveRecord(message);
    if (!current) return { ok: false, status: "skipped", warnings: ["bridge host unavailable"] };
    if (type === "bridge/get-state") {
      if (!hasCapability(current, "bridge.getState") || typeof current.bridge?.getState !== "function") {
        return { ok: false, status: "skipped", warnings: ["bridge.getState unsupported"] };
      }
      try {
        return {
          ok: true,
          status: "applied",
          state: current.bridge.getState(),
          routeKey: current.routeKey,
          leaseId: current.leaseId,
        };
      } catch (error) {
        return { ok: false, status: "error", warnings: [sanitizeText(error?.message, "unknown")] };
      }
    }
    return { ok: false, status: "error", warnings: ["unsupported sync command"] };
  };

  const sendCommand = async (message = {}) => {
    cleanupExpiredHosts();
    cleanupExpiredPendingStates();
    const type = sanitizeText(message.type, "");
    const current = resolveActiveRecord(message);
    if (!current) {
      if (type === "bridge/apply-state" || type === "bridge/queue-state") return queueState(message);
      return { ok: false, status: "skipped", warnings: ["bridge host unavailable"] };
    }
    if (type === "bridge/get-state") return sendCommandSync(message);
    if (type === "bridge/queue-state") return queueState(message);
    if (type === "bridge/apply-state") {
      if (!hasCapability(current, "bridge.applyState") || typeof current.bridge?.applyState !== "function") {
        return queueState(message);
      }
      try {
        const result = await current.bridge.applyState(
          message.payload?.state ?? {},
          Object.assign({}, message.payload?.options || {}, {
            source: sanitizeText(message.source, "obsidian-bridge-bus"),
          }),
        );
        return {
          ok: result?.ok !== false,
          status: result?.queued ? "queued" : (result?.ok === false ? "error" : "applied"),
          result,
          routeKey: current.routeKey,
          leaseId: current.leaseId,
        };
      } catch (error) {
        return { ok: false, status: "error", warnings: [sanitizeText(error?.message, "unknown")] };
      }
    }
    return { ok: false, status: "error", warnings: ["unsupported command"] };
  };

  const publishEvent = (message = {}) => {
    const channel = sanitizeText(message.channel, "default");
    pushDiagnostic("event_publish", {
      channel,
      type: sanitizeText(message.type, ""),
      sourcePlugin: sanitizeText(message.sourcePlugin, ""),
    });
    if (typeof window.dispatchEvent === "function") {
      window.dispatchEvent(new CustomEvent(`${OBSIDIAN_BRIDGE_EVENT_PREFIX}${channel}`, {
        detail: JSON.parse(JSON.stringify(message)),
      }));
    }
  };

  const subscribe = (channel, handler) => {
    const normalizedChannel = sanitizeText(channel, "default");
    const eventName = `${OBSIDIAN_BRIDGE_EVENT_PREFIX}${normalizedChannel}`;
    const listener = (event) => handler(event?.detail);
    if (typeof window.addEventListener === "function") {
      window.addEventListener(eventName, listener);
    }
    return () => {
      if (typeof window.removeEventListener === "function") {
        window.removeEventListener(eventName, listener);
      }
    };
  };

  const bus = {
    protocol: OBSIDIAN_BRIDGE_PROTOCOL,
    version: OBSIDIAN_BRIDGE_VERSION,
    createScopeKey: createBridgeScopeKey,
    createRouteKey: createBridgeRouteKey,
    registerHost,
    unregisterHost,
    heartbeat,
    queueState,
    sendCommandSync,
    sendCommand,
    publishEvent,
    subscribe,
    getActiveHosts: (selector = {}) => {
      cleanupExpiredHosts();
      const scopeType = sanitizeText(selector.scopeType, "");
      const notePath = sanitizeText(selector.notePath, "");
      const viewType = sanitizeText(selector.viewType, "");
      return JSON.parse(JSON.stringify(Array.from(hostRecords.values()).filter((record) => (
        activeRouteByScopeKey.get(record.scopeKey) === record.routeKey
        && (!scopeType || record.scopeType === scopeType)
        && (!notePath || record.notePath === notePath)
        && (!viewType || record.viewType === viewType)
      ))));
    },
    getActiveHost: (selector = {}) => resolveActiveRecord(selector),
    getActiveHostBridge: (selector = {}) => resolveActiveRecord(selector)?.bridge || null,
    getPendingState: (selector = {}) => {
      cleanupExpiredPendingStates();
      const scopeKey = createBridgeScopeKey(selector);
      return JSON.parse(JSON.stringify(pendingStateByScopeKey.get(scopeKey) || null));
    },
    getPendingStates: () => {
      cleanupExpiredPendingStates();
      return JSON.parse(JSON.stringify(Array.from(pendingStateByScopeKey.values())));
    },
    getDiagnostics: () => JSON.parse(JSON.stringify(diagnostics)),
    clearDiagnostics: () => { diagnostics.length = 0; },
  };

  window[OBSIDIAN_BRIDGE_BUS_GLOBAL] = bus;
  return bus;
}

function normalizeTabEmoji(value) {
  return sanitizeText(value, "").slice(0, 8);
}

function normalizeTabAccentColor(value) {
  const raw = sanitizeText(value, "");
  if (!raw) return "";
  const prefixed = raw.startsWith("#") ? raw : `#${raw}`;
  if (/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(prefixed)) return prefixed.toLowerCase();
  return "";
}

function expandHexColor(hexColor) {
  const normalized = normalizeTabAccentColor(hexColor);
  if (!normalized) return "";
  return normalized.length === 4
    ? `#${normalized[1]}${normalized[1]}${normalized[2]}${normalized[2]}${normalized[3]}${normalized[3]}`
    : normalized;
}

function getReadableTextColor(hexColor) {
  const full = expandHexColor(hexColor);
  if (!full) return "var(--text-on-accent)";
  const r = parseInt(full.slice(1, 3), 16);
  const g = parseInt(full.slice(3, 5), 16);
  const b = parseInt(full.slice(5, 7), 16);
  const luminance = (0.299 * r) + (0.587 * g) + (0.114 * b);
  return luminance >= 150 ? "#1f2328" : "#ffffff";
}

function buildTabDisplayState(tabLike = {}, fallbackName = "未命名 Tab") {
  const name = sanitizeText(tabLike?.name, fallbackName) || fallbackName;
  const emoji = normalizeTabEmoji(tabLike?.emoji || "");
  const accentColor = normalizeTabAccentColor(tabLike?.accentColor || "");
  return {
    name,
    emoji,
    accentColor,
    accentTextColor: accentColor ? getReadableTextColor(accentColor) : "var(--text-on-accent)",
  };
}

function formatTabDisplayLabel(tabLike = {}, options = {}) {
  const display = buildTabDisplayState(tabLike, options.fallbackName || "未命名 Tab");
  return `${options.activeDot ? "● " : ""}${display.emoji ? `${display.emoji} ` : ""}${display.name}`;
}

function applyTabFramePalette(element, accentColor = "") {
  if (!element?.style) return;
  const normalized = expandHexColor(accentColor);
  const properties = [
    "--workspace-tab-frame-border",
    "--workspace-tab-frame-border-hover",
    "--workspace-tab-frame-border-current",
    "--workspace-tab-frame-bg-strong",
    "--workspace-tab-frame-bg-soft",
  ];
  if (!normalized) {
    properties.forEach((property) => element.style.removeProperty(property));
    return;
  }
  element.style.setProperty("--workspace-tab-frame-border", `${normalized}52`);
  element.style.setProperty("--workspace-tab-frame-border-hover", `${normalized}88`);
  element.style.setProperty("--workspace-tab-frame-border-current", `${normalized}78`);
  element.style.setProperty("--workspace-tab-frame-bg-strong", `${normalized}18`);
  element.style.setProperty("--workspace-tab-frame-bg-soft", `${normalized}08`);
}

function applyTabPillPalette(element, accentColor = "", accentTextColor = "var(--text-on-accent)") {
  if (!element?.style) return;
  const normalized = expandHexColor(accentColor);
  const properties = [
    "--workspace-tab-active-bg",
    "--workspace-tab-active-border",
    "--workspace-tab-active-fg",
  ];
  if (!normalized) {
    properties.forEach((property) => element.style.removeProperty(property));
    return;
  }
  element.style.setProperty("--workspace-tab-active-bg", normalized);
  element.style.setProperty("--workspace-tab-active-border", normalized);
  element.style.setProperty("--workspace-tab-active-fg", accentTextColor || getReadableTextColor(normalized));
}

function getDefaultParadigmTagColor(seed = "") {
  const text = sanitizeText(seed, "") || "paradigm-tag";
  const hash = hashString(text);
  return PARADIGM_TAG_COLOR_PALETTE[Math.abs(hash) % PARADIGM_TAG_COLOR_PALETTE.length] || DEFAULT_PARADIGM_TAG_COLOR;
}

function hashString(value) {
  const text = sanitizeText(value, "");
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) {
    hash = ((hash << 5) - hash) + text.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

function buildParadigmPalette(seed) {
  const hue = hashString(seed) % 360;
  return {
    accent: `hsl(${hue} 58% 42%)`,
    border: `hsla(${hue}, 58%, 42%, 0.34)`,
    bg: `hsla(${hue}, 72%, 52%, 0.08)`,
    bgStrong: `hsla(${hue}, 72%, 52%, 0.14)`,
    chipBg: `hsla(${hue}, 78%, 50%, 0.12)`,
    chipBorder: `hsla(${hue}, 58%, 42%, 0.22)`,
  };
}

function getBindingLabel(noteBinding) {
  if (!noteBinding) return "";
  if (typeof noteBinding === "string") return sanitizeText(noteBinding, "");
  if (typeof noteBinding === "object") {
    const path = sanitizeText(noteBinding.path, "");
    if (path) return path.split("/").pop() || path;
  }
  return "";
}

function getCommentSummary(commentText) {
  const text = sanitizeText(commentText, "");
  if (!text) return "";
  return text.length > 48 ? `${text.slice(0, 48)}...` : text;
}

function parseParadigmItemCommentKeywords(commentText) {
  const text = String(commentText == null ? "" : commentText);
  if (!text.trim()) return [];
  const keywords = [];
  const seen = new Set();
  let inKeywordBlock = false;
  text.split(/\r?\n/).forEach((line) => {
    const raw = String(line || "");
    if (/^\s*---+\s*$/.test(raw)) {
      inKeywordBlock = !inKeywordBlock;
      return;
    }
    if (!inKeywordBlock) return;
    const keyword = sanitizeText(raw, "");
    const keywordKey = normalizeParadigmTagKeywordKey(keyword);
    if (!keyword || !keywordKey || seen.has(keywordKey)) return;
    seen.add(keywordKey);
    keywords.push({ keyword, keywordKey });
  });
  return keywords;
}

function getLevelBackground(level) {
  const palette = [
    "rgba(52, 152, 219, 0.06)",
    "rgba(46, 204, 113, 0.08)",
    "rgba(241, 196, 15, 0.09)",
    "rgba(230, 126, 34, 0.09)",
    "rgba(231, 76, 60, 0.08)",
    "rgba(155, 89, 182, 0.08)",
    "rgba(26, 188, 156, 0.08)",
    "rgba(52, 73, 94, 0.08)",
    "rgba(127, 140, 141, 0.08)",
    "rgba(243, 156, 18, 0.08)",
    "rgba(233, 30, 99, 0.07)",
    "rgba(63, 81, 181, 0.07)",
  ];
  if (!Number.isFinite(level) || level < 0) return palette[0];
  return palette[level % palette.length];
}

function normalizeImageRef(imageRef) {
  const raw = sanitizeText(imageRef, "");
  if (!raw) return "";
  const withoutBang = raw.replace(/^!\[\[/, "[[").trim();
  const wikiMatch = withoutBang.match(/^\[\[(.+?)\]\]$/);
  if (wikiMatch) return sanitizeText(wikiMatch[1], "");
  return raw;
}

function isExternalImageRef(value) {
  return /^(https?:\/\/|data:image\/|file:\/\/|app:\/\/)/i.test(String(value || "").trim());
}

function sanitizeShortcutTargetInput(raw) {
  let text = String(raw || "").trim();
  if (!text) return "";
  const markdownLinkMatch = text.match(/^!?\[[^\]]*]\((.*?)\)$/);
  if (markdownLinkMatch && markdownLinkMatch[1]) text = markdownLinkMatch[1].trim();
  if (/^!?\[\[.*\]\]$/.test(text)) text = text.replace(/^!?\[\[/, "").replace(/\]\]$/, "").trim();
  if (text.startsWith("<") && text.endsWith(">")) text = text.slice(1, -1).trim();
  const cleaned = text.split("|")[0].split("#")[0].trim();
  if (/^(?:[a-zA-Z]:[\\/]|\\\\|\/(?!\/)|https?:\/\/|file:\/\/|obsidian:\/\/)/i.test(cleaned)) return cleaned;
  return cleaned.replace(/^\/+/, "");
}

function normalizeShortcutLabel(value) {
  return String(value || "").trim();
}

function normalizeShortcutEntries(entriesLike) {
  const out = [];
  const seen = new Set();
  for (const raw of Array.isArray(entriesLike) ? entriesLike : []) {
    const entry = raw && typeof raw === "object" ? raw : {};
    const path = sanitizeShortcutTargetInput(entry.path || entry.targetPath || entry.filePath || entry.file_path || entry.href || "");
    if (!path) continue;
    const pathKey = path.toLowerCase();
    if (seen.has(pathKey)) continue;
    seen.add(pathKey);
    out.push({
      id: String(entry.id || `shortcut_${createId("sc")}`).trim() || `shortcut_${createId("sc")}`,
      path,
      label: normalizeShortcutLabel(entry.label || entry.name || ""),
      ctime: Number.isFinite(entry.ctime) ? Number(entry.ctime) : null,
      createdAt: entry.createdAt || nowString(),
      updatedAt: entry.updatedAt || nowString(),
    });
  }
  return out;
}

function normalizeExternalFileShortcutEntry(entryLike, fallback = {}) {
  const entry = entryLike && typeof entryLike === "object" ? entryLike : {};
  const normalized = normalizeShortcutEntries([entry])[0];
  if (!normalized) return null;
  const itemId = sanitizeText(entry.itemId || fallback.itemId || "", "");
  if (!itemId) return null;
  const tabId = sanitizeText(entry.tabId || fallback.tabId || "", "");
  const path = normalized.path;
  const lowerPath = path.toLowerCase();
  const kind = entry.kind === "folder"
    ? "folder"
    : (/^https?:\/\//i.test(path) ? "url" : (lowerPath.endsWith(".md") ? "note" : "file"));
  return {
    id: sanitizeText(entry.id || fallback.id || `external_file_shortcut_${createId("efs")}`, "") || `external_file_shortcut_${createId("efs")}`,
    itemId,
    tabId,
    path,
    name: normalizeShortcutLabel(entry.name || entry.label || normalized.label || ""),
    kind,
    ctime: Number.isFinite(entry.ctime) ? Number(entry.ctime) : normalized.ctime,
    createdAt: entry.createdAt || normalized.createdAt || nowString(),
    updatedAt: nowString(),
  };
}

function normalizeExternalFileShortcutEntries(entriesLike, fallback = {}) {
  const out = [];
  const seen = new Set();
  for (const raw of Array.isArray(entriesLike) ? entriesLike : []) {
    const entry = normalizeExternalFileShortcutEntry(raw, fallback);
    if (!entry) continue;
    const pathKey = `${entry.itemId}::${entry.path}`.toLowerCase();
    if (seen.has(pathKey)) continue;
    seen.add(pathKey);
    out.push(entry);
  }
  return out;
}

class WorkspaceTextInputModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      title = "输入内容",
      description = "",
      value = "",
      placeholder = "",
      confirmText = "保存",
      allowEmpty = false,
    } = this.options;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    contentEl.empty();
    contentEl.createEl("h3", { text: title });
    if (description) contentEl.createEl("div", { text: description, cls: "workspace-modal-desc" });
    const input = contentEl.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder },
    });
    input.value = value;
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const cancelBtn = actions.createEl("button", { text: "取消" });
    cancelBtn.onclick = () => {
      this.didExplicitCancel = true;
      this.close();
    };
    const confirmBtn = actions.createEl("button", { text: confirmText, cls: "mod-cta" });
    const submit = () => {
      const nextValue = String(input.value || "");
      if (!allowEmpty && !sanitizeText(nextValue, "")) return;
      this.result = nextValue;
      this.close();
    };
    confirmBtn.onclick = submit;
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        submit();
      }
    });
    window.setTimeout(() => {
      input.focus();
      input.select();
    }, 0);
  }

  onClose() {
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceTabCapsuleKeywordsModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.hasUnsavedChanges = false;
    this.collectDraft = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  close() {
    if (this.result === null && this.hasUnsavedChanges) {
      const draft = typeof this.collectDraft === "function" ? this.collectDraft({ silent: true }) : null;
      if (draft?.label) {
        this.result = draft;
      } else {
        new Notice("范式标签名称为空，未自动保存。");
      }
    }
    super.close();
  }

  onOpen() {
    const { contentEl } = this;
    const {
      tabName = "",
      keywords = [],
    } = this.options;
    contentEl.empty();
    contentEl.createEl("h3", { text: "Tab capsule keywords" });
    contentEl.createEl("div", {
      text: `One keyword can bind to one tab only. Current tab: ${sanitizeText(tabName, "-")}`,
      cls: "workspace-modal-desc",
    });
    const textarea = contentEl.createEl("textarea", {
      cls: "workspace-tab-capsule-keyword-textarea",
      attr: {
        placeholder: "One keyword per line",
      },
    });
    textarea.value = (Array.isArray(keywords) ? keywords : []).join("\n");
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const cancelBtn = actions.createEl("button", { text: "Cancel" });
    cancelBtn.onclick = () => {
      this.result = null;
      this.close();
    };
    const clearBtn = actions.createEl("button", { text: "Clear" });
    clearBtn.onclick = () => {
      textarea.value = "";
      textarea.focus();
    };
    const saveBtn = actions.createEl("button", { text: "Save", cls: "mod-cta" });
    saveBtn.onclick = () => {
      this.result = String(textarea.value || "")
        .split(/\r?\n/)
        .map((value) => sanitizeText(value, ""))
        .filter(Boolean);
      this.close();
    };
    window.setTimeout(() => {
      textarea.focus();
      textarea.selectionStart = textarea.value.length;
      textarea.selectionEnd = textarea.value.length;
    }, 0);
  }

  onClose() {
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceTabEditorModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      tab = {},
      title = "编辑 Tab",
      description = "",
      confirmText = "保存",
      focusField = "name",
    } = this.options;
    const initialName = sanitizeText(tab?.name, "") || sanitizeText(tab?.id, "未命名 Tab");
    const initialEmoji = normalizeTabEmoji(tab?.emoji || "");
    const initialAccentColor = normalizeTabAccentColor(tab?.accentColor || "");
    const fallbackPickerColor = initialAccentColor || TAB_ACCENT_COLOR_PRESETS[0];

    this.result = null;
    contentEl.empty();
    this.modalEl.style.maxWidth = "720px";
    this.modalEl.style.width = "92vw";

    contentEl.createEl("h3", { text: title });
    contentEl.createEl("div", {
      text: description || `编辑当前 Tab 的名称和特征。Tab ID：${sanitizeText(tab?.id, "未命名")}`,
      cls: "workspace-modal-desc",
    });

    const form = contentEl.createDiv({ cls: "workspace-tab-editor-form" });

    const nameRow = form.createEl("label", { cls: "workspace-tab-editor-field" });
    nameRow.createEl("span", { text: "Tab 名称", cls: "workspace-tab-editor-label" });
    const nameInput = nameRow.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder: "例如：写作工作台、研究母版、复盘区" },
    });
    nameInput.value = initialName;

    const emojiRow = form.createEl("label", { cls: "workspace-tab-editor-field" });
    emojiRow.createEl("span", { text: "Emoji", cls: "workspace-tab-editor-label" });
    const emojiInput = emojiRow.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder: "例如：🧠、📝、📚；留空表示清除", maxlength: "8" },
    });
    emojiInput.value = initialEmoji;

    const colorRow = form.createEl("label", { cls: "workspace-tab-editor-field" });
    colorRow.createEl("span", { text: "强调色", cls: "workspace-tab-editor-label" });
    const colorInputRow = colorRow.createDiv({ cls: "workspace-tab-editor-color-row" });
    const colorPicker = colorInputRow.createEl("input", {
      type: "color",
      cls: "workspace-tab-editor-color-picker",
      attr: { title: "选择强调色" },
    });
    colorPicker.value = fallbackPickerColor;
    const colorTextInput = colorInputRow.createEl("input", {
      type: "text",
      cls: "workspace-modal-input workspace-tab-editor-color-text",
      attr: { placeholder: "#3498db；留空表示清除" },
    });
    colorTextInput.value = initialAccentColor;
    const clearFeatureBtn = colorInputRow.createEl("button", {
      text: "清空特征",
      attr: { type: "button" },
    });

    const colorHint = colorRow.createEl("div", {
      text: "可直接输入十六进制颜色，或点下面的预设色。留空时恢复默认外观。",
      cls: "workspace-modal-desc workspace-tab-editor-help",
    });
    const colorWarning = colorRow.createEl("div", {
      text: "颜色格式无效，请输入 #3498db 这类 3 位或 6 位十六进制颜色。",
      cls: "workspace-tab-editor-warning",
    });
    colorWarning.hidden = true;

    const presetRow = colorRow.createDiv({ cls: "workspace-tab-editor-presets" });
    TAB_ACCENT_COLOR_PRESETS.forEach((color) => {
      const presetBtn = presetRow.createEl("button", {
        cls: "workspace-tab-editor-preset",
        attr: {
          type: "button",
          title: color,
          "aria-label": `使用颜色 ${color}`,
          style: `--workspace-tab-editor-preset:${color};`,
        },
      });
      presetBtn.onclick = () => {
        colorTextInput.value = color;
        colorPicker.value = color;
        updatePreview();
      };
    });

    const previewSection = contentEl.createDiv({ cls: "workspace-tab-editor-preview" });
    previewSection.createEl("div", {
      text: "实时预览",
      cls: "workspace-tab-editor-preview-title",
    });
    const previewRow = previewSection.createDiv({ cls: "workspace-tab-editor-preview-row" });

    const buildPreviewCard = (label, isActive = false) => {
      const card = previewRow.createDiv({ cls: "workspace-tab-editor-preview-card" });
      card.createEl("div", { text: label, cls: "workspace-tab-editor-preview-label" });
      const frame = card.createDiv({
        cls: `workspace-mount-tab-leaf workspace-tab-editor-preview-frame ${isActive ? "is-current" : ""}`.trim(),
      });
      const pill = frame.createDiv({
        cls: `workspace-mount-tab-pill workspace-tab-editor-preview-pill ${isActive ? "active" : ""}`.trim(),
      });
      const textEl = pill.createEl("span");
      return { frame, pill, textEl };
    };

    const inactivePreview = buildPreviewCard("普通状态", false);
    const activePreview = buildPreviewCard("当前激活状态", true);

    const readDraft = () => {
      const rawName = sanitizeText(nameInput.value, "");
      const rawColor = sanitizeText(colorTextInput.value, "");
      const normalizedColor = normalizeTabAccentColor(rawColor);
      return {
        name: rawName || "Tab 名称预览",
        emoji: normalizeTabEmoji(emojiInput.value || ""),
        accentColor: normalizedColor,
        rawColor,
      };
    };

    const updatePreview = () => {
      const draft = readDraft();
      const isInvalidColor = !!draft.rawColor && !draft.accentColor;
      if (draft.accentColor) colorPicker.value = draft.accentColor;
      colorWarning.hidden = !isInvalidColor;
      colorHint.hidden = isInvalidColor;
      const inactiveLabel = formatTabDisplayLabel(draft, { activeDot: false, fallbackName: "Tab 名称预览" });
      const activeLabel = formatTabDisplayLabel(draft, { activeDot: true, fallbackName: "Tab 名称预览" });
      inactivePreview.textEl.textContent = inactiveLabel;
      activePreview.textEl.textContent = activeLabel;
      applyTabFramePalette(inactivePreview.frame, draft.accentColor);
      applyTabFramePalette(activePreview.frame, draft.accentColor);
      applyTabPillPalette(inactivePreview.pill, draft.accentColor, draft.accentColor ? getReadableTextColor(draft.accentColor) : "var(--text-on-accent)");
      applyTabPillPalette(activePreview.pill, draft.accentColor, draft.accentColor ? getReadableTextColor(draft.accentColor) : "var(--text-on-accent)");
    };

    colorPicker.addEventListener("input", () => {
      const next = normalizeTabAccentColor(colorPicker.value) || TAB_ACCENT_COLOR_PRESETS[0];
      colorTextInput.value = next;
      updatePreview();
    });
    clearFeatureBtn.onclick = () => {
      emojiInput.value = "";
      colorTextInput.value = "";
      colorPicker.value = fallbackPickerColor;
      updatePreview();
    };
    nameInput.addEventListener("input", updatePreview);
    emojiInput.addEventListener("input", updatePreview);
    colorTextInput.addEventListener("input", updatePreview);
    updatePreview();

    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const cancelBtn = actions.createEl("button", {
      text: "取消",
      attr: { type: "button" },
    });
    cancelBtn.onclick = () => this.close();
    const saveBtn = actions.createEl("button", {
      text: confirmText,
      cls: "mod-cta",
      attr: { type: "button" },
    });

    const submit = () => {
      const name = sanitizeText(nameInput.value, "");
      const rawColor = sanitizeText(colorTextInput.value, "");
      const accentColor = normalizeTabAccentColor(rawColor);
      if (!name) {
        new Notice("⚠️ Tab 名称不能为空");
        return;
      }
      if (rawColor && !accentColor) {
        new Notice("⚠️ 强调色格式无效，请输入 #3498db 这类颜色值");
        return;
      }
      this.result = {
        name,
        emoji: normalizeTabEmoji(emojiInput.value || ""),
        accentColor,
      };
      this.close();
    };
    saveBtn.onclick = submit;

    [nameInput, emojiInput, colorTextInput].forEach((input) => {
      input.addEventListener("keydown", (event) => {
        if (event.key === "Enter" && !event.shiftKey) {
          event.preventDefault();
          submit();
        }
      });
    });

    window.setTimeout(() => {
      const focusTarget = focusField === "emoji"
        ? emojiInput
        : (focusField === "accentColor" ? colorTextInput : nameInput);
      focusTarget.focus();
      focusTarget.select?.();
    }, 0);
  }

  onClose() {
    this.modalEl.style.maxWidth = "";
    this.modalEl.style.width = "";
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceImageEditorModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      title = "图片设置",
      value = "",
      shortcutEntries = [],
      resolvePreview = () => ({ url: "", file: null }),
      openImagePreview = () => {},
      savePastedImage = async () => null,
      resolveShortcutEntryFromRawInput = () => null,
      resolveShortcutEntryFromDrop = () => null,
      getShortcutDisplayLabel = () => "未命名快捷方式",
      getShortcutPreviewMeta = async () => ({ title: "", subtitle: "", detail: "" }),
      openShortcutPreview = async () => {},
      openShortcutEntry = async () => false,
      openShortcutFolder = async () => false,
    } = this.options;
    this.shortcutEntries = normalizeShortcutEntries(shortcutEntries);
    contentEl.empty();
    this.modalEl.style.maxWidth = "760px";
    this.modalEl.style.width = "86vw";
    contentEl.createEl("h3", { text: title });
    contentEl.createEl("div", {
      text: "你可以手动填图片引用，或直接在下方区域 Ctrl/Cmd+V 粘贴剪贴板图片。",
      cls: "workspace-modal-desc",
    });
    const input = contentEl.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder: "支持 ![[附件]] / [[附件]] / 图片 URL" },
    });
    input.value = value || "";
    const previewBox = contentEl.createDiv({ cls: "workspace-image-preview" });
    const previewTitle = previewBox.createEl("div", {
      text: "当前图片预览",
      cls: "workspace-modal-desc",
    });
    const previewWrap = previewBox.createDiv({ cls: "workspace-image-preview-stage" });
    const previewActions = previewBox.createDiv({ cls: "workspace-modal-actions" });
    const previewBtn = previewActions.createEl("button", { text: "查看大图" });
    const renderPreview = () => {
      previewWrap.empty();
      const imageRef = sanitizeText(input.value, "");
      if (!imageRef) {
        previewTitle.textContent = "当前图片预览";
        previewWrap.createDiv({ text: "暂无图片引用", cls: "workspace-empty" });
        previewBtn.disabled = true;
        return;
      }
      const preview = resolvePreview(imageRef);
      if (!preview?.url) {
        previewTitle.textContent = "当前图片预览（未解析）";
        previewWrap.createDiv({ text: "当前引用未解析成可预览图片", cls: "workspace-empty" });
        previewBtn.disabled = true;
        return;
      }
      previewTitle.textContent = "当前图片预览";
      previewBtn.disabled = false;
      previewBtn.onclick = () => openImagePreview(imageRef);
      const img = previewWrap.createEl("img", { cls: "workspace-image-preview-img" });
      img.src = preview.url;
      img.alt = imageRef;
      img.style.cursor = "zoom-in";
      img.onclick = () => openImagePreview(imageRef);
    };
    renderPreview();
    input.addEventListener("input", renderPreview);

    contentEl.createEl("div", {
      text: "粘贴区（自动保存到 /attachments 并生成 ![[Pasted image ...]]）",
      cls: "workspace-modal-desc",
    });
    const pasteStatus = contentEl.createEl("div", {
      text: "等待粘贴，或直接修改上面的图片引用后点保存。",
      cls: "workspace-modal-desc",
    });
    const pasteZone = contentEl.createEl("div", {
      cls: "workspace-image-paste-zone",
      text: "在这里粘贴图片",
    });
    pasteZone.setAttr("contenteditable", "true");
    pasteZone.addEventListener("paste", async (event) => {
      event.preventDefault();
      const items = Array.from(event.clipboardData?.items || []);
      const imageItem = items.find((it) => typeof it?.type === "string" && it.type.startsWith("image/"));
      if (!imageItem) {
        pasteStatus.textContent = "未检测到图片，请复制图片后再粘贴。";
        return;
      }
      const file = imageItem.getAsFile();
      if (!file) {
        pasteStatus.textContent = "读取剪贴板图片失败，请重试。";
        return;
      }
      pasteStatus.textContent = "正在保存图片...";
      try {
        const saved = await savePastedImage(file);
        input.value = saved?.embedLink || "";
        pasteStatus.textContent = `已生成并填入: ${saved?.embedLink || ""}`;
        renderPreview();
      } catch (error) {
        console.error("[Workspace Mount] save pasted image failed:", error);
        pasteStatus.textContent = `保存失败: ${error.message}`;
      }
    });

    const shortcutWrap = contentEl.createDiv({ cls: "workspace-shortcut-panel" });
    shortcutWrap.createEl("div", { text: "外部文件快捷方式", cls: "workspace-shortcut-title" });
    shortcutWrap.createEl("div", {
      text: "把文件拖到下面区域，或手动输入文件路径。保存的是本机路径；跨设备同步后可能不可用。",
      cls: "workspace-modal-desc",
    });
    const shortcutStatus = shortcutWrap.createEl("div", {
      text: this.shortcutEntries.length > 0 ? `当前已挂 ${this.shortcutEntries.length} 个快捷方式` : "当前还没有快捷方式",
      cls: "workspace-modal-desc",
    });
    const shortcutDropZone = shortcutWrap.createEl("div", {
      cls: "workspace-shortcut-drop-zone",
      text: "拖拽文件到这里",
    });
    const shortcutPasteRow = shortcutWrap.createDiv({ cls: "workspace-shortcut-input-row" });
    const shortcutPasteInput = shortcutPasteRow.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder: "也可粘贴文件路径 / file:// / Obsidian 链接后点添加" },
    });
    const shortcutPasteBtn = shortcutPasteRow.createEl("button", { text: "添加" });
    const shortcutList = shortcutWrap.createDiv({ cls: "workspace-shortcut-list" });
    const appendShortcutEntry = (entry, successPrefix = "已添加快捷方式") => {
      if (!entry) return false;
      const next = normalizeShortcutEntries(this.shortcutEntries.concat([entry]));
      if (next.length === this.shortcutEntries.length) {
        shortcutStatus.textContent = `已存在同一路径快捷方式：${getShortcutDisplayLabel(entry)}`;
        return false;
      }
      this.shortcutEntries = next;
      shortcutStatus.textContent = `${successPrefix}：${getShortcutDisplayLabel(entry)}`;
      renderShortcutList();
      return true;
    };
    const addShortcutFromPaste = () => {
      const entry = resolveShortcutEntryFromRawInput(shortcutPasteInput.value);
      if (!entry) {
        shortcutStatus.textContent = "没有识别到可用的 URL 或快捷方式";
        return;
      }
      const added = appendShortcutEntry(entry, "已粘贴添加快捷方式");
      if (added) {
        shortcutPasteInput.value = "";
        shortcutPasteInput.focus();
      }
    };
    const renderShortcutList = () => {
      shortcutList.empty();
      shortcutStatus.textContent = this.shortcutEntries.length > 0
        ? `当前已挂 ${this.shortcutEntries.length} 个快捷方式`
        : "当前还没有快捷方式";
      if (this.shortcutEntries.length === 0) {
        shortcutList.createDiv({ text: "暂无快捷方式", cls: "workspace-empty" });
        return;
      }
      this.shortcutEntries.forEach((entry) => {
        const row = shortcutList.createDiv({ cls: "workspace-shortcut-row" });
        const meta = row.createDiv({ cls: "workspace-shortcut-meta" });
        const titleEl = meta.createEl("div", { text: `↗ ${getShortcutDisplayLabel(entry)}`, cls: "workspace-shortcut-label" });
        const subtitleEl = meta.createEl("div", { text: "正在识别预览信息…", cls: "workspace-shortcut-subtitle" });
        const pathEl = meta.createEl("div", { text: entry.path, cls: "workspace-shortcut-path" });
        void getShortcutPreviewMeta(entry).then((metaInfo) => {
          if (!row.isConnected) return;
          titleEl.textContent = `↗ ${metaInfo.title || getShortcutDisplayLabel(entry)}`;
          subtitleEl.textContent = metaInfo.subtitle || "";
          pathEl.textContent = metaInfo.detail || entry.path;
        }).catch(() => {
          if (!row.isConnected) return;
          subtitleEl.textContent = "";
        });
        const actionsWrap = row.createDiv({ cls: "workspace-shortcut-row-actions" });
        const previewShortcutBtn = actionsWrap.createEl("button", { text: "预览" });
        previewShortcutBtn.onclick = async () => { await openShortcutPreview(entry); };
        const openFileBtn = actionsWrap.createEl("button", { text: "打开文件", cls: "mod-cta" });
        openFileBtn.onclick = async () => { await openShortcutEntry(entry); };
        const openFolderBtn = actionsWrap.createEl("button", { text: "打开文件夹" });
        openFolderBtn.onclick = async () => { await openShortcutFolder(entry); };
        const removeBtn = actionsWrap.createEl("button", { text: "移除" });
        removeBtn.onclick = () => {
          this.shortcutEntries = this.shortcutEntries.filter((it) => it.id !== entry.id);
          renderShortcutList();
        };
      });
    };
    shortcutDropZone.addEventListener("dragover", (event) => {
      event.preventDefault();
      shortcutDropZone.classList.add("is-drag-over");
    });
    shortcutDropZone.addEventListener("dragleave", () => shortcutDropZone.classList.remove("is-drag-over"));
    shortcutDropZone.addEventListener("drop", (event) => {
      event.preventDefault();
      shortcutDropZone.classList.remove("is-drag-over");
      const entry = resolveShortcutEntryFromDrop(event.dataTransfer);
      if (!entry) {
        shortcutStatus.textContent = "没有识别到可用的快捷方式";
        return;
      }
      appendShortcutEntry(entry);
    });
    shortcutPasteBtn.onclick = addShortcutFromPaste;
    shortcutPasteInput.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      event.stopPropagation();
      addShortcutFromPaste();
    });
    renderShortcutList();

    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const clearBtn = actions.createEl("button", { text: "清除图片" });
    clearBtn.onclick = () => {
      this.result = { action: "clear", value: "", shortcuts: this.shortcutEntries.slice() };
      this.close();
    };
    const cancelBtn = actions.createEl("button", { text: "取消" });
    cancelBtn.onclick = () => {
      this.didExplicitCancel = true;
      this.close();
    };
    const saveBtn = actions.createEl("button", { text: "保存", cls: "mod-cta" });
    saveBtn.onclick = () => {
      this.result = { action: "save", value: sanitizeText(input.value, ""), shortcuts: this.shortcutEntries.slice() };
      this.close();
    };
    window.setTimeout(() => {
      input.focus();
      input.select();
    }, 0);
  }

  onClose() {
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceOntologyColumnDescriptionModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.textareaEl = null;
    this.statusEl = null;
    this.savingPromise = null;
    this.cancelPromise = null;
    this.finalClosing = false;
    this.didExplicitCancel = false;
    this.initialValue = typeof options.value === "string" ? options.value : "";
  }

  onOpen() {
    const { contentEl } = this;
    const label = sanitizeText(this.options.columnLabel, "未命名列");
    const editable = this.options.editable === true;
    contentEl.empty();
    this.modalEl.addClass("workspace-ontology-column-description-modal");
    contentEl.createEl("h3", { text: `列说明 · ${label}` });
    contentEl.createEl("div", {
      cls: "workspace-modal-desc",
      text: editable
        ? "说明这一列为什么存在、应记录什么，以及怎样判断填写到位。"
        : sanitizeText(this.options.readOnlyReason, "当前列说明只读。"),
    });
    const textarea = contentEl.createEl("textarea", {
      cls: "workspace-comment-textarea workspace-ontology-column-description-textarea",
    });
    this.textareaEl = textarea;
    textarea.value = this.initialValue;
    textarea.placeholder = "例如：本列用于……；记录范围是……；填写到位的判据是……";
    textarea.disabled = !editable;
    const footer = contentEl.createDiv({ cls: "workspace-ontology-column-description-footer" });
    const counter = footer.createSpan({ cls: "workspace-comment-counter" });
    this.statusEl = footer.createSpan({ cls: "workspace-ontology-column-description-status" });
    const updateCounter = () => { counter.textContent = `${textarea.value.length} 字`; };
    textarea.addEventListener("input", () => {
      updateCounter();
      if (this.statusEl) this.statusEl.textContent = "未保存";
    });
    updateCounter();
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const cancelButton = actions.createEl("button", { text: editable ? "放弃修改" : "关闭" });
    cancelButton.onclick = () => { void this.cancelAndClose(); };
    if (editable) {
      const saveButton = actions.createEl("button", { text: "保存说明", cls: "mod-cta" });
      saveButton.onclick = () => { void this.requestClose("save-button"); };
      window.setTimeout(() => {
        textarea.focus();
        textarea.selectionStart = textarea.value.length;
        textarea.selectionEnd = textarea.value.length;
      }, 0);
    }
  }

  close() {
    if (this.finalClosing) {
      super.close();
      return;
    }
    void this.requestClose("implicit-close");
  }

  async requestClose(reason = "close") {
    if (this.finalClosing) return true;
    if (this.savingPromise) return await this.savingPromise;
    if (this.didExplicitCancel || this.options.editable !== true) {
      this.finishClose();
      return true;
    }
    this.savingPromise = (async () => {
      if (this.statusEl) this.statusEl.textContent = "正在保存...";
      try {
        await this.options.onSubmit?.(String(this.textareaEl?.value || ""), { reason });
        this.finishClose();
        return true;
      } catch (error) {
        if (this.statusEl) this.statusEl.textContent = error?.message || "保存失败，输入仍保留";
        new Notice(error?.message || "列说明保存失败，输入仍保留");
        return false;
      }
    })();
    try {
      return await this.savingPromise;
    } finally {
      if (!this.finalClosing) this.savingPromise = null;
    }
  }

  async cancelAndClose() {
    if (this.savingPromise || this.finalClosing) return false;
    if (this.cancelPromise) return await this.cancelPromise;
    const currentValue = String(this.textareaEl?.value || "");
    if (this.options.editable === true && currentValue !== this.initialValue) {
      this.cancelPromise = Promise.resolve(this.options.onConfirmDiscard?.({
        title: "放弃列说明修改？",
        message: "当前列说明尚未保存。放弃后，本次输入不会写入 Ontology。",
        confirmText: "放弃修改",
        cancelText: "继续编辑",
      })).then((confirmed) => {
        if (!confirmed || this.finalClosing) return false;
        this.didExplicitCancel = true;
        this.finishClose();
        return true;
      }).finally(() => {
        if (!this.finalClosing) this.cancelPromise = null;
      });
      return await this.cancelPromise;
    }
    this.didExplicitCancel = true;
    this.finishClose();
    return true;
  }

  finishClose() {
    if (this.finalClosing) return;
    this.finalClosing = true;
    super.close();
  }

  onClose() {
    this.modalEl.removeClass?.("workspace-ontology-column-description-modal");
    this.textareaEl = null;
    this.statusEl = null;
    this.contentEl.empty();
    try { this.options.onFinalized?.(this); } catch (_) {}
  }
}

class WorkspaceCommentEditorModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      title = "评论",
      value = "",
    } = this.options;
    this.result = null;
    this.didExplicitCancel = false;
    this.textareaEl = null;
    contentEl.empty();
    this.modalEl.style.maxWidth = "1100px";
    this.modalEl.style.width = "92vw";
    this.modalEl.style.height = "78vh";
    contentEl.style.display = "flex";
    contentEl.style.flexDirection = "column";
    contentEl.style.height = "100%";
    contentEl.style.gap = "10px";
    contentEl.createEl("h3", { text: title });
    contentEl.createEl("div", {
      text: "可写长评论，列表中展示前 100 字摘要。",
      cls: "workspace-modal-desc",
    });
    const textarea = contentEl.createEl("textarea", {
      text: value,
      cls: "workspace-comment-textarea",
    });
    this.textareaEl = textarea;
    textarea.placeholder = "记录思路、补充信息、执行细节...";
    textarea.focus();
    textarea.selectionStart = textarea.value.length;
    textarea.selectionEnd = textarea.value.length;
    const counter = contentEl.createEl("div", { cls: "workspace-comment-counter" });
    const updateCounter = () => {
      counter.textContent = `${textarea.value.length} 字`;
    };
    textarea.addEventListener("input", updateCounter);
    updateCounter();
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const clearBtn = actions.createEl("button", { text: "清空评论" });
    clearBtn.onclick = () => {
      this.result = { action: "clear" };
      this.close();
    };
    const cancelBtn = actions.createEl("button", { text: "取消" });
    cancelBtn.onclick = () => {
      this.didExplicitCancel = true;
      this.close();
    };
    const saveBtn = actions.createEl("button", { text: "保存评论", cls: "mod-cta" });
    saveBtn.onclick = () => {
      this.result = { action: "save", value: textarea.value };
      this.close();
    };
  }

  onClose() {
    if (!this.result && !this.didExplicitCancel) {
      this.result = {
        action: "save",
        value: String(this.textareaEl?.value || ""),
      };
    }
    this.modalEl.style.maxWidth = "";
    this.modalEl.style.width = "";
    this.modalEl.style.height = "";
    this.contentEl.style.display = "";
    this.contentEl.style.flexDirection = "";
    this.contentEl.style.height = "";
    this.contentEl.style.gap = "";
    this.textareaEl = null;
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceConfirmModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = false;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      title = "确认",
      message = "",
      confirmText = "确认",
      cancelText = "取消",
      danger = false,
    } = this.options;
    this.result = false;
    contentEl.empty();
    contentEl.removeClass("workspace-confirm-modal");
    contentEl.removeClass("is-danger");
    contentEl.addClass("workspace-confirm-modal");
    if (danger) contentEl.addClass("is-danger");
    contentEl.createEl("h3", { text: title, cls: "workspace-confirm-title" });
    const messageWrap = contentEl.createDiv({ cls: "workspace-modal-desc" });
    String(message || "")
      .split("\n")
      .map((line) => String(line || "").trim())
      .filter(Boolean)
      .forEach((line) => {
        messageWrap.createDiv({ text: line });
      });
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const cancelBtn = actions.createEl("button", { text: cancelText });
    cancelBtn.onclick = () => {
      this.result = false;
      this.close();
    };
    const okBtn = actions.createEl("button", { text: confirmText, cls: danger ? "workspace-confirm-danger-btn" : "mod-cta" });
    okBtn.onclick = () => {
      this.result = true;
      this.close();
    };
    window.setTimeout(() => okBtn.focus(), 0);
  }

  onClose() {
    this.contentEl.empty();
    this._resolve(this.result === true);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

class WorkspaceParadigmOntologyAlbumModal extends Modal {
  constructor(app, parentModal, cellRef, lifecycleToken) {
    super(app);
    this.parentModal = parentModal;
    this.cellRef = parentModal.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId);
    this.cellKey = parentModal.getParadigmOntologyCellRefKey(this.cellRef);
    this.lifecycleToken = lifecycleToken;
    this.invalidated = false;
    this.boundPaste = (event) => {
      if (!this.isActive() || this.parentModal.isParadigmOntologyCellMutationBlocked(this.cellRef)) return;
      this.parentModal.handleParadigmOntologyClipboardPaste(event, this.cellRef, this.lifecycleToken);
    };
  }

  isActive() {
    return !this.invalidated
      && this.parentModal?.isParadigmOntologyAlbumTokenActive?.(this.cellRef, this.lifecycleToken, this);
  }

  invalidate() {
    if (this.invalidated) return;
    this.invalidated = true;
    if (this.lifecycleToken) this.lifecycleToken.active = false;
    super.close();
  }

  focusAlbum() {
    this.modalEl?.focus?.();
  }

  onOpen() {
    this.modalEl.addClass("workspace-ontology-album-modal");
    this.modalEl.setAttribute("tabindex", "-1");
    this.modalEl.addEventListener("paste", this.boundPaste);
    this.renderAlbum();
    window.setTimeout(() => this.focusAlbum(), 0);
  }

  renderAlbum() {
    if (!this.isActive()) {
      this.invalidate();
      return;
    }
    const resolved = this.parentModal.resolveParadigmOntologyCell(this.cellRef);
    if (!resolved) {
      this.invalidate();
      return;
    }
    const records = parseParadigmOntologyImageEmbeds(resolved.cell.value);
    const pending = this.parentModal.pendingImageCellKeys.has(this.cellKey);
    const readOnly = this.parentModal.isReadOnly()
      || this.parentModal.isParadigmOntologyCellMutationBlocked(this.cellRef)
      || pending
      || !this.parentModal.acceptingImageImports;
    const { contentEl } = this;
    contentEl.empty();

    const header = contentEl.createDiv({ cls: "workspace-ontology-album-head" });
    const titleWrap = header.createDiv({ cls: "workspace-ontology-album-title-wrap" });
    titleWrap.createEl("h3", { text: "Ontology 图片" });
    titleWrap.createDiv({ cls: "workspace-ontology-album-count", text: `${records.length} 张` });
    const actions = header.createDiv({ cls: "workspace-ontology-album-actions" });
    const imageInput = actions.createEl("input", {
      type: "file",
      cls: "workspace-ontology-image-input",
      attr: { accept: ".png,.jpg,.jpeg,.webp,.gif,.bmp,image/png,image/jpeg,image/webp,image/gif,image/bmp", multiple: "multiple", tabindex: "-1" },
    });
    imageInput.disabled = readOnly;
    const addButton = actions.createEl("button", {
      attr: { type: "button", title: "添加图片", "aria-label": "添加图片" },
    });
    setIcon(addButton, "image-plus");
    addButton.disabled = readOnly;
    addButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      imageInput.click();
    };
    imageInput.addEventListener("change", () => {
      const files = Array.from(imageInput.files || []);
      imageInput.value = "";
      if (files.length === 0 || !this.isActive()) return;
      void this.parentModal.enqueueParadigmOntologyImageImport(this.cellRef, files);
    });

    const body = contentEl.createDiv({ cls: "workspace-ontology-album-body" });
    const setDragState = (enabled) => body.classList.toggle("is-image-dragover", enabled);
    body.addEventListener("dragenter", (event) => {
      if (readOnly || !this.isActive()) return;
      event.preventDefault();
      setDragState(true);
    });
    body.addEventListener("dragover", (event) => {
      if (readOnly || !this.isActive()) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
      setDragState(true);
    });
    body.addEventListener("dragleave", (event) => {
      if (event.relatedTarget && body.contains?.(event.relatedTarget)) return;
      setDragState(false);
    });
    body.addEventListener("drop", (event) => {
      setDragState(false);
      if (readOnly || !this.isActive()) return;
      const files = Array.from(event.dataTransfer?.files || []);
      const vaultFiles = files.length === 0
        ? this.parentModal.resolveDroppedParadigmOntologyVaultImages(event.dataTransfer)
        : [];
      if (files.length === 0 && vaultFiles.length === 0) return;
      event.preventDefault();
      event.stopPropagation();
      if (files.length > 0) void this.parentModal.enqueueParadigmOntologyImageImport(this.cellRef, files);
      else void this.parentModal.enqueueParadigmOntologyVaultImageImport(this.cellRef, vaultFiles);
    });

    if (records.length === 0) {
      const empty = body.createDiv({ cls: "workspace-ontology-album-empty" });
      setIcon(empty, "images");
      return;
    }
    const gallery = body.createDiv({ cls: "workspace-ontology-album-gallery" });
    records.forEach((record) => {
      const tile = gallery.createDiv({ cls: "workspace-ontology-album-tile" });
      const preview = this.parentModal.resolveParadigmOntologyImagePreview(record.target);
      if (preview.url) {
        const previewButton = tile.createEl("button", {
          cls: "workspace-ontology-album-preview-button",
          attr: { type: "button", title: record.target, "aria-label": `查看图片 ${record.target}` },
        });
        const image = previewButton.createEl("img", { cls: "workspace-ontology-album-image" });
        image.src = preview.url;
        image.alt = record.target;
        previewButton.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          this.parentModal.view?.openImagePreview?.(record.target);
        };
      } else {
        const unresolved = tile.createDiv({ cls: "workspace-ontology-album-unresolved", attr: { title: record.target } });
        setIcon(unresolved, "image-off");
      }
      tile.createDiv({ cls: "workspace-ontology-album-caption", text: record.target || "未解析图片" });
      const removeButton = tile.createEl("button", {
        cls: "workspace-ontology-image-remove",
        attr: { type: "button", title: "移除图片引用（保留附件文件）", "aria-label": "移除图片引用" },
      });
      setIcon(removeButton, "x");
      removeButton.disabled = readOnly;
      removeButton.onclick = async (event) => {
        event.preventDefault();
        event.stopPropagation();
        await this.parentModal.removeParadigmOntologyImageFromUi(this.cellRef, record, {
          album: this,
          lifecycleToken: this.lifecycleToken,
        });
      };
    });
  }

  onClose() {
    this.invalidated = true;
    if (this.lifecycleToken) this.lifecycleToken.active = false;
    this.modalEl.removeEventListener("paste", this.boundPaste);
    this.modalEl.removeClass("workspace-ontology-album-modal");
    this.parentModal?.unregisterParadigmOntologyAlbum?.(this);
    this.contentEl.empty();
  }
}

class WorkspaceParadigmOntologyModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.view = options.view;
    this.plugin = options.plugin;
    this.viewStatePlugin = options.viewStatePlugin
      || (typeof options.plugin?.getParadigmOntologyViewState === "function" ? options.plugin : null);
    this.paradigmItemId = sanitizeText(options.paradigmItemId, "");
    this.paradigmItemTitle = sanitizeText(options.paradigmItemTitle, this.paradigmItemId);
    this.modalTitle = sanitizeText(options.modalTitle, "范式 Ontology");
    this.modalSubtitle = sanitizeText(options.modalSubtitle, `${this.paradigmItemTitle} · ${this.paradigmItemId}`);
    this.ownerPluginId = sanitizeText(options.ownerPluginId, "workspace-mount");
    this.externalOwnerNamespace = sanitizeText(options.externalOwnerNamespace, "");
    this.externalOwnerKey = sanitizeText(options.externalOwnerKey, "");
    this.providerGeneration = sanitizeText(options.providerGeneration, "");
    this.referenceAdapter = isObjectLike(options.referenceAdapter) ? options.referenceAdapter : null;
    this.resolveDetachedBindingPolicy = typeof options.resolveDetachedBindingPolicy === "function"
      ? options.resolveDetachedBindingPolicy
      : null;
    this.cellAddressBase = isObjectLike(options.cellAddressBase) ? deepClone(options.cellAddressBase, null) : null;
    this.onExternalClose = typeof options.onExternalClose === "function" ? options.onExternalClose : null;
    this.didNotifyExternalClose = false;
    this.dataPath = sanitizeText(options.dataPath, "");
    this.sourceNotePath = sanitizeText(options.sourceNotePath, "");
    this.baseOntologyHash = sanitizeText(options.baseOntologyHash, hashParadigmOntology(null));
    this.draft = upgradeParadigmOntologyToV3(options.draft) || createDefaultParadigmOntology();
    this.didRestoreRecovery = options.didRestoreRecovery === true;
    this.recoveryConflict = options.recoveryConflict === true;
    this.formalOntology = options.formalOntology == null ? null : deepClone(options.formalOntology, null);
    this.formalOntologyHash = sanitizeText(options.formalOntologyHash, hashParadigmOntology(this.formalOntology));
    this.referenceWriteState = this.readParadigmOntologyReferenceWriteState();
    this.referenceWriteStateUnsubscribe = null;
    this.referenceCaptureState = this.readParadigmOntologyCaptureState();
    this.referenceCaptureStateUnsubscribe = null;
    this.referenceCapabilityReadOnly = false;
    this.initialDraftHash = this.didRestoreRecovery ? this.baseOntologyHash : hashParadigmOntology(this.draft);
    this.initialRowIds = new Set(Object.values(this.draft?.tablesById || {}).flatMap((table) => table?.rowOrder || []));
    this.readOnlyErrors = Array.isArray(options.readOnlyErrors) ? options.readOnlyErrors.filter(Boolean) : [];
    this.sessionId = createId("pgOntSession");
    this.generation = Number(options.generation) || Date.now();
    this.recoveryTimer = 0;
    this.viewStateTimer = 0;
    this.closingPromise = null;
    this.finalClosing = false;
    this.forcedTeardown = false;
    this.forcedTeardownPromise = null;
    this.acceptingImageImports = true;
    this.imageImportQueue = Promise.resolve();
    this.pendingImageImportCount = 0;
    this.pendingImageCellKeys = new Set();
    this.pendingImageCellCounts = new Map();
    this.admittedImageOperationIds = new Set();
    this.albumModalsByCellKey = new Map();
    this.albumLifecycleSequence = 0;
    this.protectedImageRecoveryRecord = null;
    this.lastPersistedRecoveryDraftHash = this.didRestoreRecovery ? hashParadigmOntology(this.draft) : "";
    this.dirty = false;
    this.statusEl = null;
    this.editorEl = null;
    this.footerEl = null;
    this.surfaceMode = "table";
    this.treeRenderEpoch = 0;
    this.treeRenderComponent = null;
    this.treeCleanupFns = [];
    this.treeFitRaf = 0;
    this.treePendingFit = false;
    this.treeProjection = null;
    this.treeViewportEl = null;
    this.treeStageEl = null;
    this.treeZoomLabelEl = null;
    this.treePanState = null;
    this.treePanActive = false;
    this.conflictHostEl = null;
    this.saveCloseBtn = null;
    this.currentTableId = sanitizeText(this.draft?.rootTableId, "");
    this.schemaOnlySchemaId = sanitizeText(options.focusSchemaAddress?.schemaId, "");
    this.schemaOnlyHistory = this.schemaOnlySchemaId ? [this.schemaOnlySchemaId] : [];
    this.schemaLineageSyncFailures = new Set();
    this.schemaLineageSyncPromise = null;
    this.schemaLineageSyncEpoch = 0;
    this.closeOperationToken = 0;
    this.sharedSchemaRequiredFailure = null;
    if (this.schemaOnlySchemaId && !this.draft?.schemasById?.[this.schemaOnlySchemaId]) {
      this.readOnlyErrors.push(`请求的共享 Schema 不存在：${this.schemaOnlySchemaId}`);
      this.schemaOnlySchemaId = "";
      this.schemaOnlyHistory = [];
    }
    this.pendingCellFocus = options.focusCellAddress || options.focusCellRef
      ? deepClone(options.focusCellAddress || options.focusCellRef, null)
      : null;
    this.cellFocusTimers = new Set();
    const pendingFocusTableId = sanitizeText(this.pendingCellFocus?.tableId, "");
    if (pendingFocusTableId && this.draft?.tablesById?.[pendingFocusTableId]) {
      this.currentTableId = pendingFocusTableId;
    } else if (!this.schemaOnlySchemaId && !this.pendingCellFocus) {
      const savedViewState = this.viewStatePlugin?.getParadigmOntologyViewState?.(this.dataPath, this.paradigmItemId);
      this.currentTableId = resolveParadigmOntologyViewStateTableId(this.draft, savedViewState);
    }
    this.cellElementsByKey = new Map();
    this.referenceUiGeneration = 0;
    this.showArchivedColumns = false;
    this.structureMutationButtons = [];
    this.schemaMutationButtons = [];
    this.draftBytes = validateParadigmOntology(this.draft).stats?.bytes || workspacePerfByteLength(canonicalJsonString(this.draft));
    this.lastSizeLimitNoticeAt = 0;
    this.rangePhase = "idle";
    this.rangePhaseToken = 0;
    this.rangeAnchorRef = null;
    this.rangeExtentRef = null;
    this.rangeSelection = null;
    this.rangePointerActive = false;
    this.rangeConflictKeys = new Set();
    this.rangeSuccessKeys = new Set();
    this.rangeCueTimer = 0;
    this.rangeToolbarEl = null;
    this.rangeToolbarStatusEl = null;
    this.rangeCopyButton = null;
    this.rangePasteButton = null;
    this.rangeClearButton = null;
    this.rangeCancelButton = null;
    this.ontologyTreeButton = null;
    this.ontologyTreeControlsEl = null;
    this.minimized = false;
    this.scopeSuspendedForMinimize = false;
    this.restoreTrayEl = null;
    this.restoreChipEl = null;
    this.restoreChipTitleEl = null;
    this.restoreChipDirtyEl = null;
    this.columnDescriptionModal = null;
    this.columnDescriptionSettlementPromise = null;
    this.setParadigmOntologyDirtyState(this.didRestoreRecovery);
    this.boundParadigmOntologyBackdropClick = (event) => {
      if (this.finalClosing || this.minimized || this.modalEl?.contains?.(event?.target)) return;
      event?.preventDefault?.();
      event?.stopPropagation?.();
      event?.stopImmediatePropagation?.();
      this.minimizeParadigmOntologyModal();
    };
    this.boundRangeKeydown = (event) => this.handleParadigmOntologyRangeKeydown(event);
    this.boundRangePointerEnd = () => { this.rangePointerActive = false; };
    this.boundRangePointerCancel = () => {
      this.rangePointerActive = false;
      if (this.rangePhase !== "idle") this.cancelParadigmOntologyRangeMode("pointercancel");
    };
    this.confirmAction = typeof options.confirmAction === "function"
      ? options.confirmAction
      : async (modalOptions) => await new WorkspaceConfirmModal(this.app, modalOptions).waitForResult();
  }

  onOpen() {
    const { contentEl } = this;
    this.plugin?.registerParadigmOntologyModal?.(this);
    this.modalEl.addClass("workspace-ontology-modal");
    contentEl.empty();
    const head = contentEl.createDiv({ cls: "workspace-ontology-head" });
    const titleWrap = head.createDiv();
    titleWrap.createEl("h3", { text: this.modalTitle });
    titleWrap.createDiv({
      cls: "workspace-ontology-subtitle",
      text: this.modalSubtitle,
    });
    const headActions = head.createDiv({ cls: "workspace-ontology-head-actions" });
    this.statusEl = headActions.createDiv({ cls: "workspace-ontology-status" });
    const minimizeButton = headActions.createEl("button", {
      cls: "workspace-ontology-minimize",
      attr: { type: "button", title: "最小化 Ontology", "aria-label": "最小化 Ontology" },
    });
    setIcon(minimizeButton, "minus");
    minimizeButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.minimizeParadigmOntologyModal();
    };
    if (this.didRestoreRecovery) {
      this.setStatus(this.recoveryConflict ? "已恢复冲突草稿，等待选择" : "已恢复上次未完成草稿", "is-warning");
    }
    if (this.readOnlyErrors.length > 0) {
      this.setStatus("结构异常，只读保护", "is-error");
      const errorBox = contentEl.createDiv({ cls: "workspace-ontology-error" });
      errorBox.createDiv({ text: "当前 Ontology 未通过结构校验。为防止静默丢数据，本次只读。" });
      this.readOnlyErrors.slice(0, 8).forEach((message) => errorBox.createDiv({ text: message }));
    }
    this.conflictHostEl = contentEl.createDiv({ cls: "workspace-ontology-conflict-host" });
    this.renderRecoveryConflictControls();
    this.renderParadigmOntologyRangeToolbar(contentEl);
    this.editorEl = contentEl.createDiv({ cls: "workspace-ontology-editor" });
    this.renderEditor();
    this.modalEl.addEventListener("keydown", this.boundRangeKeydown, true);
    this.containerEl?.addEventListener?.("click", this.boundParadigmOntologyBackdropClick, true);
    window.addEventListener?.("pointerup", this.boundRangePointerEnd, true);
    window.addEventListener?.("pointercancel", this.boundRangePointerCancel, true);
    const footer = contentEl.createDiv({ cls: "workspace-ontology-footer" });
    this.footerEl = footer;
    const addRowBtn = footer.createEl("button", { attr: { type: "button", title: "在表格末尾新增一行" } });
    setIcon(addRowBtn, "list-plus");
    addRowBtn.createSpan({ text: "新增行" });
    addRowBtn.disabled = this.isReadOnly() || Boolean(this.schemaOnlySchemaId);
    this.addRowBtn = addRowBtn;
    this.structureMutationButtons.push(addRowBtn);
    addRowBtn.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (this.isParadigmOntologyTableInArchivedBranch(this.currentTableId)) {
        new Notice("当前位于归档历史分支，只能查看。");
        return;
      }
      if (this.schemaOnlySchemaId) {
        new Notice("Schema-only 模式只编辑结构，不创建虚假表格实例。");
        return;
      }
      if (this.guardPendingImageImports()) return;
      const { table } = this.getCurrentTableContext();
      if (!table) return;
      try {
        addParadigmOntologyRow(this.draft, table.id);
        this.markDirty("新增行");
        this.renderEditor();
      } catch (error) {
        new Notice(error.message);
      }
    };
    const addColumnBtn = footer.createEl("button", { attr: { type: "button", title: "新增一列并同步到同 schema 的表格实例" } });
    setIcon(addColumnBtn, "columns-3");
    addColumnBtn.createSpan({ text: "新增列" });
    addColumnBtn.disabled = this.isReadOnly();
    this.structureMutationButtons.push(addColumnBtn);
    this.schemaMutationButtons.push(addColumnBtn);
    addColumnBtn.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (this.isParadigmOntologyTableInArchivedBranch(this.currentTableId)) {
        new Notice("当前位于归档历史分支，只能查看。");
        return;
      }
      if (this.guardPendingImageImports()) return;
      const { schema } = this.getCurrentTableContext();
      if (paradigmOntologySchemaHasRetainedLineage(schema)) {
        new Notice("当前是共享结构，请使用“编辑共享结构”进入来源 owner 修改。");
        return;
      }
      if (!schema) return;
      const label = await new WorkspaceTextInputModal(this.app, {
        title: "新增 Ontology 列",
        placeholder: "输入列名",
        confirmText: "新增",
      }).waitForResult();
      if (!sanitizeText(label, "")) return;
      try {
        addParadigmOntologyColumn(this.draft, schema.id, label);
        this.markDirty("新增列");
        this.renderEditor();
      } catch (error) {
        new Notice(error.message);
      }
    };
    const restoreColumnBtn = footer.createEl("button", { attr: { type: "button", title: "恢复本层已归档的历史列" } });
    setIcon(restoreColumnBtn, "archive-restore");
    restoreColumnBtn.createSpan({ text: "恢复列" });
    restoreColumnBtn.disabled = this.isReadOnly();
    this.structureMutationButtons.push(restoreColumnBtn);
    this.schemaMutationButtons.push(restoreColumnBtn);
    restoreColumnBtn.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (this.isParadigmOntologyTableInArchivedBranch(this.currentTableId)) {
        new Notice("当前位于归档历史分支，只能查看。");
        return;
      }
      if (this.guardPendingImageImports()) return;
      const { schema } = this.getCurrentTableContext();
      if (paradigmOntologySchemaHasRetainedLineage(schema)) {
        new Notice("当前是共享结构，请使用“编辑共享结构”进入来源 owner 修改。");
        return;
      }
      const archivedIds = Array.isArray(schema?.archivedColumnOrder) ? schema.archivedColumnOrder : [];
      if (!schema || archivedIds.length === 0) {
        new Notice("当前表格没有已归档列。");
        return;
      }
      const choice = await new WorkspaceTextInputModal(this.app, {
        title: "恢复 Ontology 历史列",
        placeholder: archivedIds.map((id) => sanitizeText(schema.columnsById?.[id]?.label, id)).join(" / "),
        confirmText: "恢复",
      }).waitForResult();
      const normalized = sanitizeText(choice, "");
      const columnId = archivedIds.find((id) => id === normalized || sanitizeText(schema.columnsById?.[id]?.label, "") === normalized);
      if (!columnId) {
        if (normalized) new Notice("请输入完整列名或列 ID。");
        return;
      }
      try {
        restoreParadigmOntologyColumn(this.draft, schema.id, columnId);
        this.markDirty("恢复历史列");
        this.renderEditor();
      } catch (error) {
        new Notice(error.message);
      }
    };
    const archivedViewBtn = footer.createEl("button", { attr: { type: "button", title: "只读查看或隐藏本层已归档的历史列" } });
    setIcon(archivedViewBtn, "history");
    const archivedViewLabel = archivedViewBtn.createSpan({ text: "查看归档" });
    archivedViewBtn.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const { schema } = this.getCurrentTableContext();
      const archivedIds = Array.isArray(schema?.archivedColumnOrder) ? schema.archivedColumnOrder : [];
      if (archivedIds.length === 0) {
        new Notice("当前表格没有已归档列。");
        return;
      }
      this.showArchivedColumns = !this.showArchivedColumns;
      archivedViewLabel.setText(this.showArchivedColumns ? "隐藏归档" : "查看归档");
      this.renderEditor();
    };
    const spacer = footer.createDiv({ cls: "workspace-ontology-footer-spacer" });
    const closeBtn = footer.createEl("button", { text: "保存并关闭", cls: "mod-cta", attr: { type: "button" } });
    this.saveCloseBtn = closeBtn;
    closeBtn.disabled = this.isReadOnly() || this.recoveryConflict;
    closeBtn.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      await this.requestClose("save-button");
    };
    if (this.isReadOnly()) {
      spacer.remove();
      const readOnlyCloseBtn = footer.createEl("button", { text: "关闭", attr: { type: "button" } });
      readOnlyCloseBtn.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.finishClose();
      };
    }
    if (this.didRestoreRecovery && !this.isReadOnly()) this.scheduleRecovery();
    this.bindParadigmOntologyReferenceWriteState();
    this.bindParadigmOntologyCaptureState();
    this.refreshParadigmOntologyRangeToolbar();
    void this.reconcileSharedSchemas({ required: false, render: true });
  }

  isReadOnly() {
    return this.readOnlyErrors.length > 0
      || (this.hasParadigmOntologyReferenceProtectedState() && this.referenceWriteState?.writable !== true);
  }

  hasParadigmOntologyReferenceProtectedState() {
    return hasParadigmOntologyReferenceState(this.formalOntology)
      || hasParadigmOntologyReferenceState(this.draft);
  }

  readParadigmOntologyReferenceWriteState() {
    if (typeof this.referenceAdapter?.getWriteState !== "function") {
      return { writable: false, code: "REFERENCE_ADAPTER_UNAVAILABLE", reason: "Ontology 引用协调器当前不可用。" };
    }
    try {
      const state = this.referenceAdapter.getWriteState();
      return isObjectLike(state)
        ? Object.assign({ writable: false, code: "REFERENCE_WRITE_UNAVAILABLE", reason: "Ontology 引用能力不可用。" }, state)
        : { writable: false, code: "REFERENCE_WRITE_UNAVAILABLE", reason: "Ontology 引用能力状态无效。" };
    } catch (error) {
      return { writable: false, code: sanitizeText(error?.code, "REFERENCE_WRITE_UNAVAILABLE"), reason: error?.message || "Ontology 引用能力不可用。" };
    }
  }

  bindParadigmOntologyReferenceWriteState() {
    if (this.referenceWriteStateUnsubscribe || typeof this.referenceAdapter?.subscribeWriteState !== "function") return;
    try {
      const unsubscribe = this.referenceAdapter.subscribeWriteState((state) => this.applyParadigmOntologyReferenceWriteState(state));
      this.referenceWriteStateUnsubscribe = typeof unsubscribe === "function" ? unsubscribe : null;
    } catch (error) {
      this.applyParadigmOntologyReferenceWriteState({
        writable: false,
        code: sanitizeText(error?.code, "REFERENCE_WRITE_SUBSCRIPTION_FAILED"),
        reason: error?.message || "Ontology 引用能力订阅失败。",
      });
    }
  }

  renderParadigmOntologyRangeToolbar(host) {
    const toolbar = host.createDiv({ cls: "workspace-ontology-range-toolbar" });
    this.rangeToolbarEl = toolbar;
    const copyButton = toolbar.createEl("button", {
      cls: "workspace-ontology-range-copy",
      attr: { type: "button", title: "选择矩形区域，只复制文字和图片引用" },
    });
    setIcon(copyButton, "copy");
    const copyLabel = copyButton.createSpan({ text: "复制区域" });
    copyButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (this.rangePhase === "select-source" && this.rangeSelection?.ok) void this.copyParadigmOntologyRangeSelection();
      else this.activateParadigmOntologyRangeSourceMode();
    };
    const pasteButton = toolbar.createEl("button", {
      cls: "workspace-ontology-range-paste",
      attr: { type: "button", title: "将已复制区域粘贴到所点格子的右下方" },
    });
    setIcon(pasteButton, "clipboard-paste");
    const pasteLabel = pasteButton.createSpan({ text: "粘贴" });
    pasteButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.armParadigmOntologyRangeTargetMode();
    };
    const clearButton = toolbar.createEl("button", {
      cls: "workspace-ontology-range-clear",
      attr: { type: "button", title: "清空本次 Ontology 内容剪贴板", "aria-label": "清空 Ontology 内容剪贴板" },
    });
    setIcon(clearButton, "trash-2");
    clearButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.plugin?.clearParadigmOntologyRangeClipboard?.("explicit-toolbar");
      this.cancelParadigmOntologyRangeMode("clipboard-cleared");
      new Notice("Ontology 内容剪贴板已清空。");
    };
    const cancelButton = toolbar.createEl("button", {
      cls: "workspace-ontology-range-cancel",
      attr: { type: "button", title: "取消当前区域操作，保留已复制内容", "aria-label": "取消当前区域操作" },
    });
    setIcon(cancelButton, "circle-x");
    cancelButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.cancelParadigmOntologyRangeMode("explicit-cancel");
    };
    const treeButton = toolbar.createEl("button", {
      cls: "workspace-ontology-tree-entry",
      attr: { type: "button", title: "将当前 Ontology 递归展开为只读全景树" },
    });
    setIcon(treeButton, "workflow");
    treeButton.createSpan({ text: "全景树" });
    treeButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.enterParadigmOntologyTreeMode();
    };
    this.ontologyTreeButton = treeButton;
    const treeControls = toolbar.createDiv({ cls: "workspace-ontology-tree-controls" });
    treeControls.hidden = true;
    const returnButton = treeControls.createEl("button", {
      cls: "workspace-ontology-tree-return",
      attr: { type: "button", title: "返回 Ontology 表格" },
    });
    setIcon(returnButton, "table-properties");
    returnButton.createSpan({ text: "返回表格" });
    returnButton.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.exitParadigmOntologyTreeMode();
    };
    const zoomOutButton = treeControls.createEl("button", {
      cls: "workspace-ontology-tree-zoom-out",
      attr: { type: "button", title: "缩小全景树", "aria-label": "缩小全景树" },
    });
    setIcon(zoomOutButton, "zoom-out");
    zoomOutButton.onclick = (event) => { event.preventDefault(); event.stopPropagation(); this.zoomParadigmOntologyTree(-0.1); };
    const fitButton = treeControls.createEl("button", {
      cls: "workspace-ontology-tree-fit",
      attr: { type: "button", title: "适应窗口", "aria-label": "适应窗口" },
    });
    setIcon(fitButton, "scan");
    fitButton.onclick = (event) => { event.preventDefault(); event.stopPropagation(); this.fitParadigmOntologyTreeViewport(); };
    const zoomInButton = treeControls.createEl("button", {
      cls: "workspace-ontology-tree-zoom-in",
      attr: { type: "button", title: "放大全景树", "aria-label": "放大全景树" },
    });
    setIcon(zoomInButton, "zoom-in");
    zoomInButton.onclick = (event) => { event.preventDefault(); event.stopPropagation(); this.zoomParadigmOntologyTree(0.1); };
    const resetButton = treeControls.createEl("button", {
      cls: "workspace-ontology-tree-reset",
      attr: { type: "button", title: "重置全景树位置和缩放", "aria-label": "重置全景树位置和缩放" },
    });
    setIcon(resetButton, "rotate-ccw");
    resetButton.onclick = (event) => { event.preventDefault(); event.stopPropagation(); this.resetParadigmOntologyTreeViewport(); };
    const zoomLabel = treeControls.createSpan({ cls: "workspace-ontology-tree-zoom-label", text: "100%" });
    this.ontologyTreeControlsEl = treeControls;
    this.treeZoomLabelEl = zoomLabel;
    this.rangeToolbarStatusEl = toolbar.createDiv({ cls: "workspace-ontology-range-toolbar-status" });
    this.rangeCopyButton = copyButton;
    this.rangeCopyButtonLabel = copyLabel;
    this.rangePasteButton = pasteButton;
    this.rangePasteButtonLabel = pasteLabel;
    this.rangeClearButton = clearButton;
    this.rangeCancelButton = cancelButton;
    this.refreshParadigmOntologyRangeToolbar();
  }

  canEnterParadigmOntologyTreeMode() {
    if (this.finalClosing || this.forcedTeardown) return { ok: false, reason: "当前 Ontology 窗口正在关闭。" };
    if (this.schemaOnlySchemaId) return { ok: false, reason: "Schema-only 模式不能展开内容全景。" };
    if (this.referenceCaptureState?.active === true) return { ok: false, reason: "请先退出 Ontology Meta 模式。" };
    if (this.rangePhase !== "idle") return { ok: false, reason: "请先结束当前区域复制或粘贴操作。" };
    if (this.pendingImageImportCount > 0) {
      return { ok: false, reason: "图片仍在导入，请稍后再展开全景。" };
    }
    if (this.albumModalsByCellKey.size > 0) return { ok: false, reason: "请先关闭图片相册。" };
    if (this.getActiveColumnDescriptionModal()) return { ok: false, reason: "请先保存或放弃列说明。" };
    const projection = buildParadigmOntologyTreeProjection(this.draft);
    if (!projection.ok) return { ok: false, reason: projection.error || "无法建立 Ontology 全景树。" };
    return { ok: true, projection };
  }

  enterParadigmOntologyTreeMode() {
    if (this.surfaceMode === "tree") return true;
    const admission = this.canEnterParadigmOntologyTreeMode();
    if (!admission.ok) {
      new Notice(admission.reason);
      return false;
    }
    this.cancelParadigmOntologyRangeMode("tree-entered");
    this.surfaceMode = "tree";
    this.treeProjection = admission.projection;
    this.renderParadigmOntologyTreePanorama();
    this.refreshParadigmOntologyRangeToolbar();
    return true;
  }

  cleanupParadigmOntologyTreeSurface() {
    this.treeRenderEpoch += 1;
    if (this.treeFitRaf) {
      window.cancelAnimationFrame?.(this.treeFitRaf);
      window.clearTimeout?.(this.treeFitRaf);
      this.treeFitRaf = 0;
    }
    this.treeCleanupFns.splice(0).reverse().forEach((cleanup) => {
      try { cleanup(); } catch (_) {}
    });
    if (this.treeRenderComponent) {
      try { this.treeRenderComponent.unload?.(); } catch (_) {}
      this.treeRenderComponent = null;
    }
    this.treeViewportEl = null;
    this.treeStageEl = null;
    this.treePanState = null;
    this.treePanActive = false;
    this.treePendingFit = false;
  }

  exitParadigmOntologyTreeMode() {
    if (this.surfaceMode !== "tree") return false;
    this.cleanupParadigmOntologyTreeSurface();
    this.surfaceMode = "table";
    this.treeProjection = null;
    this.refreshParadigmOntologyRangeToolbar();
    if (this.footerEl) this.footerEl.hidden = false;
    this.renderEditor();
    return true;
  }

  refreshParadigmOntologyTreeTransform() {
    if (!this.treeStageEl) return;
    const state = this.treePanState || { scale: 1, x: 16, y: 16 };
    this.treeStageEl.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    if (this.treeZoomLabelEl) {
      const text = `${Math.round(state.scale * 100)}%`;
      this.treeZoomLabelEl.setText?.(text);
      if (!this.treeZoomLabelEl.setText) this.treeZoomLabelEl.textContent = text;
    }
  }

  zoomParadigmOntologyTree(delta, anchor = null) {
    if (this.surfaceMode !== "tree" || !this.treeViewportEl) return false;
    const state = this.treePanState || { scale: 1, x: 16, y: 16 };
    const nextScale = Math.min(3, Math.max(0.25, state.scale + Number(delta || 0)));
    if (nextScale === state.scale) return false;
    const rect = this.treeViewportEl.getBoundingClientRect?.() || { left: 0, top: 0, width: 0, height: 0 };
    const pointX = Number(anchor?.x ?? rect.width / 2);
    const pointY = Number(anchor?.y ?? rect.height / 2);
    const contentX = (pointX - state.x) / state.scale;
    const contentY = (pointY - state.y) / state.scale;
    state.x = pointX - contentX * nextScale;
    state.y = pointY - contentY * nextScale;
    state.scale = nextScale;
    this.treePanState = state;
    this.refreshParadigmOntologyTreeTransform();
    return true;
  }

  resetParadigmOntologyTreeViewport() {
    if (this.surfaceMode !== "tree" || !this.treeViewportEl) return false;
    this.treePanState = { scale: 1, x: 16, y: 16 };
    this.treePendingFit = false;
    this.refreshParadigmOntologyTreeTransform();
    return true;
  }

  fitParadigmOntologyTreeViewport() {
    if (this.surfaceMode !== "tree" || this.minimized || !this.treeViewportEl || !this.treeStageEl) {
      this.treePendingFit = true;
      return false;
    }
    const svg = this.treeStageEl.querySelector?.("svg");
    const viewportRect = this.treeViewportEl.getBoundingClientRect?.() || { width: 0, height: 0 };
    const svgRect = svg?.getBoundingClientRect?.() || { width: 0, height: 0 };
    const viewBox = svg?.viewBox?.baseVal;
    const width = Number(viewBox?.width) || Number(svgRect.width) || 0;
    const height = Number(viewBox?.height) || Number(svgRect.height) || 0;
    if (viewportRect.width <= 0 || viewportRect.height <= 0 || width <= 0 || height <= 0) {
      this.treePendingFit = true;
      return false;
    }
    const scale = Math.min(3, Math.max(0.25, Math.min((viewportRect.width - 32) / width, (viewportRect.height - 32) / height)));
    this.treePanState = {
      scale,
      x: (viewportRect.width - width * scale) / 2,
      y: (viewportRect.height - height * scale) / 2,
    };
    this.treePendingFit = false;
    this.refreshParadigmOntologyTreeTransform();
    return true;
  }

  scheduleParadigmOntologyTreeFit() {
    if (this.treeFitRaf) return;
    const callback = () => {
      this.treeFitRaf = 0;
      if (!this.finalClosing && this.surfaceMode === "tree") this.fitParadigmOntologyTreeViewport();
    };
    this.treeFitRaf = window.requestAnimationFrame?.(callback) || window.setTimeout(callback, 0);
  }

  setupParadigmOntologyTreeViewport(viewport, stage, epoch) {
    this.treeViewportEl = viewport;
    this.treeStageEl = stage;
    this.treePanState = { scale: 1, x: 16, y: 16 };
    this.refreshParadigmOntologyTreeTransform();
    let pointerStart = null;
    const onPointerDown = (event) => {
      if (event?.button != null && event.button !== 0) return;
      pointerStart = { x: Number(event.clientX) || 0, y: Number(event.clientY) || 0, originX: this.treePanState.x, originY: this.treePanState.y };
      this.treePanActive = true;
      viewport.classList?.add?.("is-panning");
      viewport.setPointerCapture?.(event.pointerId);
    };
    const onPointerMove = (event) => {
      if (!pointerStart || epoch !== this.treeRenderEpoch || this.surfaceMode !== "tree") return;
      this.treePanState.x = pointerStart.originX + (Number(event.clientX) || 0) - pointerStart.x;
      this.treePanState.y = pointerStart.originY + (Number(event.clientY) || 0) - pointerStart.y;
      this.refreshParadigmOntologyTreeTransform();
    };
    const onPointerEnd = (event) => {
      if (!pointerStart) return;
      pointerStart = null;
      this.treePanActive = false;
      viewport.classList?.remove?.("is-panning");
      viewport.releasePointerCapture?.(event?.pointerId);
    };
    const onWheel = (event) => {
      if (!event?.ctrlKey || epoch !== this.treeRenderEpoch || this.surfaceMode !== "tree") return;
      event.preventDefault?.();
      const rect = viewport.getBoundingClientRect?.() || { left: 0, top: 0, width: 0, height: 0 };
      this.zoomParadigmOntologyTree(event.deltaY < 0 ? 0.1 : -0.1, {
        x: (Number(event.clientX) || rect.left) - rect.left,
        y: (Number(event.clientY) || rect.top) - rect.top,
      });
    };
    viewport.addEventListener("pointerdown", onPointerDown);
    viewport.addEventListener("pointermove", onPointerMove);
    viewport.addEventListener("pointerup", onPointerEnd);
    viewport.addEventListener("pointercancel", onPointerEnd);
    viewport.addEventListener("wheel", onWheel, { passive: false });
    this.treeCleanupFns.push(() => viewport.removeEventListener("pointerdown", onPointerDown));
    this.treeCleanupFns.push(() => viewport.removeEventListener("pointermove", onPointerMove));
    this.treeCleanupFns.push(() => viewport.removeEventListener("pointerup", onPointerEnd));
    this.treeCleanupFns.push(() => viewport.removeEventListener("pointercancel", onPointerEnd));
    this.treeCleanupFns.push(() => viewport.removeEventListener("wheel", onWheel));
    this.scheduleParadigmOntologyTreeFit();
  }

  renderParadigmOntologyTreePanorama() {
    if (this.surfaceMode !== "tree" || !this.editorEl) return;
    this.cleanupParadigmOntologyTreeSurface();
    const epoch = this.treeRenderEpoch;
    this.editorEl.empty();
    const projection = this.treeProjection || buildParadigmOntologyTreeProjection(this.draft);
    this.treeProjection = projection;
    const summary = this.editorEl.createDiv({ cls: "workspace-ontology-tree-summary" });
    summary.createSpan({ text: `全景树 · ${projection.tableCount || 0} 个表格 · ${projection.nodeCount || 0} 个节点` });
    if (projection.truncated) summary.createSpan({ cls: "is-truncated", text: `已截断：${projection.truncationReasons.join("、")}` });
    const viewport = this.editorEl.createDiv({ cls: "workspace-ontology-tree-viewport" });
    const stage = viewport.createDiv({ cls: "workspace-ontology-tree-stage" });
    const renderHost = stage.createDiv({ cls: "workspace-ontology-tree-render" });
    const component = typeof Component === "function" ? new Component() : null;
    this.treeRenderComponent = component;
    if (component?.load) component.load();
    const markdown = projection.ok ? `\`\`\`mermaid\n${projection.mermaid}\n\`\`\`` : projection.error || "无法建立全景树。";
    const renderPromise = typeof MarkdownRenderer?.render === "function"
      ? MarkdownRenderer.render(this.app, markdown, renderHost, this.sourceNotePath || "", component)
      : Promise.resolve().then(() => { renderHost.createEl("pre", { text: markdown }); });
    this.setupParadigmOntologyTreeViewport(viewport, stage, epoch);
    void Promise.resolve(renderPromise).then(() => {
      if (this.finalClosing || this.surfaceMode !== "tree" || epoch !== this.treeRenderEpoch) return;
      if (this.treePendingFit || this.minimized) this.scheduleParadigmOntologyTreeFit();
      else this.fitParadigmOntologyTreeViewport();
    }).catch((error) => {
      if (this.finalClosing || this.surfaceMode !== "tree" || epoch !== this.treeRenderEpoch) return;
      renderHost.empty();
      renderHost.createDiv({ cls: "workspace-ontology-error", text: `全景树渲染失败：${error?.message || "未知错误"}` });
    });
  }

  getParadigmOntologyRangeClipboard() {
    if (typeof this.plugin?.getParadigmOntologyRangeClipboard !== "function") {
      return { ok: false, errors: ["CLIPBOARD_PROVIDER_UNAVAILABLE"], payload: null };
    }
    try { return this.plugin.getParadigmOntologyRangeClipboard(); }
    catch (error) { return { ok: false, errors: [sanitizeText(error?.code, "CLIPBOARD_READ_FAILED")], payload: null }; }
  }

  refreshParadigmOntologyRangeToolbar() {
    if (!this.rangeToolbarEl) return;
    const treeMode = this.surfaceMode === "tree";
    [this.rangeCopyButton, this.rangePasteButton, this.rangeClearButton, this.rangeCancelButton]
      .filter(Boolean)
      .forEach((button) => { button.hidden = treeMode; });
    if (this.rangeToolbarStatusEl) this.rangeToolbarStatusEl.hidden = treeMode;
    if (this.ontologyTreeButton) this.ontologyTreeButton.hidden = treeMode;
    if (this.ontologyTreeControlsEl) this.ontologyTreeControlsEl.hidden = !treeMode;
    if (this.footerEl) this.footerEl.hidden = treeMode;
    if (this.conflictHostEl) this.conflictHostEl.hidden = treeMode;
    if (this.ontologyTreeButton && !treeMode) {
      const admission = this.canEnterParadigmOntologyTreeMode();
      this.ontologyTreeButton.disabled = !admission.ok;
      this.ontologyTreeButton.title = admission.ok ? "将当前 Ontology 递归展开为只读全景树" : admission.reason;
    }
    if (treeMode) return;
    const clipboard = this.getParadigmOntologyRangeClipboard();
    const payload = clipboard.ok ? clipboard.payload : null;
    const metaActive = this.referenceCaptureState?.active === true;
    const sourceSelection = this.rangeSelection?.ok ? this.rangeSelection : null;
    if (this.rangeCopyButton) {
      this.rangeCopyButton.disabled = metaActive || Boolean(this.schemaOnlySchemaId);
      const label = this.rangeCopyButtonLabel;
      if (label?.setText) label.setText(this.rangePhase === "select-source" && sourceSelection
        ? `复制 ${sourceSelection.rowCount}×${sourceSelection.columnCount}`
        : "复制区域");
      else if (label) label.textContent = this.rangePhase === "select-source" && sourceSelection
        ? `复制 ${sourceSelection.rowCount}×${sourceSelection.columnCount}`
        : "复制区域";
    }
    if (this.rangePasteButton) {
      this.rangePasteButton.disabled = metaActive || !payload || this.isReadOnly() || Boolean(this.schemaOnlySchemaId);
      const label = this.rangePasteButtonLabel;
      const text = payload ? `粘贴 ${payload.rowCount}×${payload.columnCount}` : "粘贴";
      if (label?.setText) label.setText(text); else if (label) label.textContent = text;
    }
    if (this.rangeClearButton) this.rangeClearButton.disabled = !payload;
    if (this.rangeCancelButton) this.rangeCancelButton.hidden = this.rangePhase === "idle";
    if (this.rangeToolbarStatusEl) {
      let text = payload ? `已复制 ${payload.rowCount}×${payload.columnCount} · ${payload.imageCount || 0} 张图片` : "";
      if (this.rangePhase === "select-source") text = sourceSelection
        ? `已选 ${sourceSelection.rowCount}×${sourceSelection.columnCount}，可继续拖选或复制`
        : "拖动选择区域，或依次点击首格与末格";
      if (this.rangePhase === "target-armed" && payload) text = `请选择目标左上角 · 需要连续空白 ${payload.rowCount}×${payload.columnCount}`;
      this.rangeToolbarStatusEl.setText?.(text);
      if (!this.rangeToolbarStatusEl.setText) this.rangeToolbarStatusEl.textContent = text;
    }
    this.rangeToolbarEl.classList.toggle("is-range-active", this.rangePhase !== "idle");
    this.rangeToolbarEl.classList.toggle("is-target-armed", this.rangePhase === "target-armed");
  }

  cancelParadigmOntologyRangeMode(_reason = "cancel") {
    this.rangePhaseToken += 1;
    this.rangePhase = "idle";
    this.rangeAnchorRef = null;
    this.rangeExtentRef = null;
    this.rangeSelection = null;
    this.rangePointerActive = false;
    this.rangeConflictKeys.clear();
    this.rangeSuccessKeys.clear();
    this.applyParadigmOntologyRangeCues();
    this.refreshParadigmOntologyRangeToolbar();
  }

  activateParadigmOntologyRangeSourceMode() {
    if (this.referenceCaptureState?.active === true) {
      new Notice("请先退出 Ontology Meta 模式，再复制区域。");
      return false;
    }
    if (this.schemaOnlySchemaId) {
      new Notice("Schema-only 页面没有内容格可复制。");
      return false;
    }
    this.rangePhaseToken += 1;
    this.rangePhase = "select-source";
    this.rangeAnchorRef = null;
    this.rangeExtentRef = null;
    this.rangeSelection = null;
    this.rangePointerActive = false;
    this.rangeConflictKeys.clear();
    this.rangeSuccessKeys.clear();
    this.applyParadigmOntologyRangeCues();
    this.refreshParadigmOntologyRangeToolbar();
    return true;
  }

  armParadigmOntologyRangeTargetMode() {
    const clipboard = this.getParadigmOntologyRangeClipboard();
    if (!clipboard.ok || !clipboard.payload) {
      new Notice("Ontology 内容剪贴板为空或已过期，请重新复制。");
      this.refreshParadigmOntologyRangeToolbar();
      return false;
    }
    if (this.referenceCaptureState?.active === true) {
      new Notice("请先退出 Ontology Meta 模式，再粘贴区域。");
      return false;
    }
    if (!this.canMutateParadigmOntologyAfterConfirmation() || this.schemaOnlySchemaId) {
      new Notice("当前 Ontology 不能粘贴内容。");
      return false;
    }
    this.rangePhaseToken += 1;
    this.rangePhase = "target-armed";
    this.rangeAnchorRef = null;
    this.rangeExtentRef = null;
    this.rangeSelection = null;
    this.rangeConflictKeys.clear();
    this.rangeSuccessKeys.clear();
    this.applyParadigmOntologyRangeCues();
    this.refreshParadigmOntologyRangeToolbar();
    return true;
  }

  getParadigmOntologyVisibleRangeAxes() {
    const { table, schema } = this.getCurrentTableContext();
    if (!table || !schema) return { table: null, schema: null, rowIds: [], columnIds: [] };
    const columnIds = this.showArchivedColumns
      ? getParadigmOntologySchemaColumnIds(schema, true)
      : [...(schema.columnOrder || [])];
    return { table, schema, rowIds: [...(table.rowOrder || [])], columnIds };
  }

  updateParadigmOntologyRangeSelection(anchorRef, extentRef) {
    const axes = this.getParadigmOntologyVisibleRangeAxes();
    if (!axes.table || sanitizeText(anchorRef?.tableId, "") !== axes.table.id
      || sanitizeText(extentRef?.tableId, "") !== axes.table.id) return false;
    const selection = buildParadigmOntologyRangeRefs(axes.table.id, axes.rowIds, axes.columnIds, anchorRef, extentRef);
    if (!selection.ok) return false;
    this.rangeAnchorRef = this.getParadigmOntologyCellRef(anchorRef.tableId, anchorRef.rowId, anchorRef.columnId);
    this.rangeExtentRef = this.getParadigmOntologyCellRef(extentRef.tableId, extentRef.rowId, extentRef.columnId);
    this.rangeSelection = selection;
    this.applyParadigmOntologyRangeCues();
    this.refreshParadigmOntologyRangeToolbar();
    return true;
  }

  applyParadigmOntologyRangeCues() {
    const selectedKeys = new Set((this.rangeSelection?.refs || []).map((ref) => this.getParadigmOntologyCellRefKey(ref)));
    this.cellElementsByKey.forEach((entry, key) => {
      const wrap = entry?.wrap;
      if (!wrap) return;
      const conflict = this.rangeConflictKeys.has(key);
      const success = !conflict && this.rangeSuccessKeys.has(key);
      const selected = !conflict && !success && this.rangePhase === "select-source" && selectedKeys.has(key);
      wrap.classList.toggle("workspace-ontology-range-state", conflict || success || selected || this.rangePhase !== "idle");
      wrap.classList.toggle("is-range-conflict", conflict);
      wrap.classList.toggle("is-range-success", success);
      wrap.classList.toggle("is-range-selected", selected);
      wrap.classList.toggle("is-range-targetable", this.rangePhase === "target-armed");
      if (this.rangePhase !== "idle") {
        wrap.setAttribute("tabindex", "0");
        wrap.setAttribute("role", "gridcell");
        wrap.setAttribute("aria-selected", selected ? "true" : "false");
      } else {
        wrap.removeAttribute?.("tabindex");
        wrap.removeAttribute?.("role");
        wrap.removeAttribute?.("aria-selected");
      }
    });
    this.modalEl?.classList?.toggle?.("is-ontology-range-active", this.rangePhase !== "idle");
    this.modalEl?.classList?.toggle?.("is-ontology-range-source", this.rangePhase === "select-source");
    this.modalEl?.classList?.toggle?.("is-ontology-range-target", this.rangePhase === "target-armed");
  }

  handleParadigmOntologyRangeCellPointerDown(event, cellRef, wrap) {
    if (this.rangePhase === "idle" || event?.button > 0) return;
    event.preventDefault();
    event.stopPropagation();
    wrap?.focus?.();
    if (this.rangePhase === "select-source") {
      if (!this.rangeAnchorRef) this.rangeAnchorRef = deepClone(cellRef, null);
      this.rangePointerActive = true;
      this.updateParadigmOntologyRangeSelection(this.rangeAnchorRef, cellRef);
      return;
    }
    if (this.rangePhase === "target-armed") void this.pasteParadigmOntologyRangeAt(cellRef);
  }

  handleParadigmOntologyRangeCellPointerEnter(event, cellRef) {
    if (this.rangePhase !== "select-source" || !this.rangePointerActive || !this.rangeAnchorRef) return;
    event.preventDefault();
    this.updateParadigmOntologyRangeSelection(this.rangeAnchorRef, cellRef);
  }

  handleParadigmOntologyRangeKeydown(event) {
    if (!event || event.isComposing) return;
    const target = event.target;
    if (!this.editorEl?.contains?.(target)) return;
    const contentEditableOwner = target?.closest?.("[contenteditable]");
    const isContentEditable = target?.isContentEditable === true
      || (contentEditableOwner && sanitizeText(contentEditableOwner.getAttribute?.("contenteditable"), "").toLowerCase() !== "false");
    if (isContentEditable
      || target?.closest?.("textarea, input, .workspace-ontology-album-modal, .workspace-confirm-modal")) return;
    if (String(event.key || "").toLowerCase() === "escape" && this.rangePhase !== "idle") {
      event.preventDefault();
      event.stopPropagation();
      this.cancelParadigmOntologyRangeMode("escape");
      return;
    }
    if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
    const cell = target?.closest?.(".workspace-ontology-value-cell");
    if (!cell || !this.editorEl.contains(cell)) return;
    const key = String(event.key || "").toLowerCase();
    if (key === "c" && this.rangePhase === "select-source" && this.rangeSelection?.ok) {
      event.preventDefault();
      event.stopPropagation();
      void this.copyParadigmOntologyRangeSelection();
    } else if (key === "v" && this.rangePhase === "target-armed") {
      const ref = this.getParadigmOntologyCellRefFromElement(cell);
      if (!ref) return;
      event.preventDefault();
      event.stopPropagation();
      void this.pasteParadigmOntologyRangeAt(ref);
    }
  }

  getParadigmOntologyCellRefFromElement(element) {
    const key = sanitizeText(element?.getAttribute?.("data-ontology-cell-key"), "");
    if (!key) return null;
    const [tableId, rowId, columnId] = key.split("\u0000");
    return tableId && rowId && columnId ? this.getParadigmOntologyCellRef(tableId, rowId, columnId) : null;
  }

  resolveParadigmOntologyRangeImageFile(target) {
    const normalized = sanitizeText(target, "");
    if (!normalized) return null;
    const linked = this.app?.metadataCache?.getFirstLinkpathDest?.(normalized, this.sourceNotePath);
    const exact = this.app?.vault?.getAbstractFileByPath?.(normalized);
    const fallback = this.view?.resolveImageFile?.(normalized)?.file;
    const file = linked instanceof TFile ? linked : (exact instanceof TFile ? exact : (fallback instanceof TFile ? fallback : null));
    if (!(file instanceof TFile) || !getParadigmOntologyImageKindByExtension(getParadigmOntologyImageExtension(file.path))) return null;
    return file;
  }

  async copyParadigmOntologyRangeSelection() {
    const selection = this.rangeSelection;
    if (this.rangePhase !== "select-source" || !selection?.ok) return false;
    const phaseToken = this.rangePhaseToken;
    const cells = [];
    let imageCount = 0;
    let ignoredNestedTableCount = 0;
    let ignoredReferenceCount = 0;
    try {
      selection.refs.forEach((ref) => {
        const resolved = this.resolveParadigmOntologyCell(ref);
        if (!resolved) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_SOURCE_CHANGED", "复制区域中的格子已经变化，请重新选择。");
        const syntax = inspectParadigmOntologyRangeImageSyntax(resolved.cell.value);
        if (!syntax.ok) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_SYNTAX_UNSUPPORTED", "区域内存在不支持或不完整的图片语法，请先修正。", { errors: syntax.errors });
        const images = syntax.records.map((record) => {
          const file = this.resolveParadigmOntologyRangeImageFile(record.target);
          if (!(file instanceof TFile)) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_UNRESOLVED", "区域内有图片无法解析到本地附件，未复制。");
          const size = Number(file.stat?.size);
          const mtime = Number(file.stat?.mtime);
          if (!Number.isFinite(size) || !Number.isFinite(mtime)) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_FINGERPRINT_MISSING", "图片附件缺少文件指纹，未复制。");
          return { path: file.path, size, mtime };
        });
        imageCount += images.length;
        if (sanitizeText(resolved.cell.nestedTableId, "")) ignoredNestedTableCount += 1;
        if (Object.prototype.hasOwnProperty.call(resolved.cell, "reference")) ignoredReferenceCount += 1;
        cells.push({
          rowOffset: ref.rowOffset,
          columnOffset: ref.columnOffset,
          body: stripParadigmOntologyImageEmbeds(resolved.cell.value),
          lineBreak: getParadigmOntologyLineBreak(resolved.cell.value),
          images,
        });
      });
      if (cells.every((cell) => cell.body.length === 0 && cell.images.length === 0)) {
        throw createParadigmOntologyContractError("ONTOLOGY_RANGE_SOURCE_EMPTY", "所选区域没有文字或图片，无需复制。");
      }
      if (phaseToken !== this.rangePhaseToken || this.rangePhase !== "select-source") return false;
      const payload = this.plugin?.setParadigmOntologyRangeClipboard?.({
        rowCount: selection.rowCount,
        columnCount: selection.columnCount,
        cells,
        imageCount,
        ignoredNestedTableCount,
        ignoredReferenceCount,
        createdAt: Date.now(),
      });
      if (!payload) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_CLIPBOARD_WRITE_FAILED", "Ontology 内容剪贴板写入失败。");
      this.cancelParadigmOntologyRangeMode("copy-complete");
      new Notice(`已复制 ${payload.rowCount}×${payload.columnCount} 个 Ontology 格子；子表和引用未包含。`);
      return true;
    } catch (error) {
      console.warn("[Workspace Mount][ontology.range-paste-rejected]", {
        stage: "copy",
        code: sanitizeText(error?.code, "ONTOLOGY_RANGE_COPY_FAILED"),
        rowCount: Number(selection?.rowCount) || 0,
        columnCount: Number(selection?.columnCount) || 0,
      });
      new Notice(error?.message || "Ontology 区域复制失败。");
      return false;
    }
  }

  materializeParadigmOntologyRangeClipboard(payload) {
    return payload.cells.map((cell) => {
      const embeds = cell.images.map((identity) => {
        const file = this.app?.vault?.getAbstractFileByPath?.(identity.path);
        if (!(file instanceof TFile)) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_MISSING", "复制区域中的图片附件已不存在，未粘贴。");
        if (Number(file.stat?.size) !== Number(identity.size) || Number(file.stat?.mtime) !== Number(identity.mtime)) {
          throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_CHANGED", "复制区域中的图片附件已被替换或修改，请重新复制。");
        }
        const embed = this.buildParadigmOntologyImageEmbed(file, this.sourceNotePath);
        const parsed = parseParadigmOntologyImageEmbeds(embed);
        if (parsed.length !== 1 || parsed[0].token !== embed) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_LINK_INVALID", "无法为目标 Ontology 生成可靠的图片引用。");
        const roundTrip = this.resolveParadigmOntologyRangeImageFile(parsed[0].target);
        if (!(roundTrip instanceof TFile) || roundTrip.path !== file.path) throw createParadigmOntologyContractError("ONTOLOGY_RANGE_IMAGE_LINK_MISMATCH", "目标图片引用校验失败，未粘贴。");
        return embed;
      });
      return { value: composeParadigmOntologyCellValue(cell.body, embeds, cell.lineBreak) };
    });
  }

  inspectParadigmOntologyRangeTarget(cellRef, payload) {
    const axes = this.getParadigmOntologyVisibleRangeAxes();
    if (!axes.table || this.schemaOnlySchemaId) return { ok: false, code: "ONTOLOGY_RANGE_TARGET_UNAVAILABLE", conflicts: [], targetRefs: [] };
    const inspection = inspectParadigmOntologyRangePasteTarget(this.draft, {
      tableId: axes.table.id,
      rowIds: axes.rowIds,
      columnIds: axes.columnIds,
      targetRowId: cellRef?.rowId,
      targetColumnId: cellRef?.columnId,
      payload,
    });
    if (!inspection.ok) return inspection;
    const archivedColumns = new Set(axes.schema?.archivedColumnOrder || []);
    if (inspection.targetRefs.some((ref) => archivedColumns.has(ref.columnId))
      || this.isParadigmOntologyTableInArchivedBranch(axes.table.id)) {
      return Object.assign({}, inspection, { ok: false, code: "ONTOLOGY_RANGE_TARGET_ARCHIVED" });
    }
    return inspection;
  }

  captureParadigmOntologyRangeScroll() {
    const scroll = this.editorEl?.querySelector?.(".workspace-ontology-scroll");
    return scroll ? {
      tableId: this.currentTableId,
      top: Number(scroll.scrollTop) || 0,
      left: Number(scroll.scrollLeft) || 0,
      pendingFocusOwned: Boolean(this.pendingCellFocus),
    } : null;
  }

  restoreParadigmOntologyRangeScroll(snapshot) {
    if (!snapshot || snapshot.tableId !== this.currentTableId || snapshot.pendingFocusOwned || this.pendingCellFocus) return;
    const scroll = this.editorEl?.querySelector?.(".workspace-ontology-scroll");
    if (!scroll) return;
    scroll.scrollTop = Math.max(0, Math.min(Number(snapshot.top) || 0, Math.max(0, (scroll.scrollHeight || 0) - (scroll.clientHeight || 0))));
    scroll.scrollLeft = Math.max(0, Math.min(Number(snapshot.left) || 0, Math.max(0, (scroll.scrollWidth || 0) - (scroll.clientWidth || 0))));
  }

  revealParadigmOntologyRangeTargetInTable(cellRef) {
    const scroll = this.editorEl?.querySelector?.(".workspace-ontology-scroll");
    const target = this.cellElementsByKey.get(this.getParadigmOntologyCellRefKey(cellRef))?.wrap;
    if (!scroll?.getBoundingClientRect || !target?.getBoundingClientRect) return;
    const viewport = scroll.getBoundingClientRect();
    const rect = target.getBoundingClientRect();
    if (rect.top < viewport.top) scroll.scrollTop += rect.top - viewport.top;
    else if (rect.bottom > viewport.bottom) scroll.scrollTop += rect.bottom - viewport.bottom;
    if (rect.left < viewport.left) scroll.scrollLeft += rect.left - viewport.left;
    else if (rect.right > viewport.right) scroll.scrollLeft += rect.right - viewport.right;
  }

  setParadigmOntologyRangeConflicts(conflicts) {
    this.rangeConflictKeys = new Set((conflicts || []).map((entry) => this.getParadigmOntologyCellRefKey(entry.ref)));
    this.rangeSuccessKeys.clear();
    this.applyParadigmOntologyRangeCues();
  }

  logParadigmOntologyRangeRejected(stage, code, cellRef = null, payload = null, extra = {}) {
    console.warn("[Workspace Mount][ontology.range-paste-rejected]", Object.assign({
      stage: sanitizeText(stage, "unknown"),
      code: sanitizeText(code, "ONTOLOGY_RANGE_REJECTED"),
      rowCount: Math.max(0, Number(payload?.rowCount) || 0),
      columnCount: Math.max(0, Number(payload?.columnCount) || 0),
      tableId: sanitizeText(cellRef?.tableId, sanitizeText(this.currentTableId, "")),
      targetRowId: sanitizeText(cellRef?.rowId, ""),
      targetColumnId: sanitizeText(cellRef?.columnId, ""),
    }, extra));
  }

  installParadigmOntologyRecoveryTimerTransactional(previousTimer = this.recoveryTimer) {
    if (this.isReadOnly()) return 0;
    let replacement = 0;
    replacement = window.setTimeout(() => {
      if (this.recoveryTimer !== replacement) return;
      this.recoveryTimer = 0;
      void this.flushRecovery("debounce");
    }, PARADIGM_ONTOLOGY_RECOVERY_DEBOUNCE_MS);
    this.recoveryTimer = replacement;
    if (previousTimer && previousTimer !== replacement) window.clearTimeout(previousTimer);
    return replacement;
  }

  async pasteParadigmOntologyRangeAt(cellRef) {
    if (this.rangePhase !== "target-armed") return false;
    if (!this.canMutateParadigmOntologyAfterConfirmation()) {
      const clipboard = this.getParadigmOntologyRangeClipboard();
      this.logParadigmOntologyRangeRejected("admission", "ONTOLOGY_RANGE_TARGET_READ_ONLY", cellRef, clipboard.ok ? clipboard.payload : null);
      new Notice("当前 Ontology 已变为只读或存在恢复冲突，未粘贴。");
      return false;
    }
    if (this.guardPendingImageImports() || this.schemaLineageSyncPromise || this.sharedSchemaRequiredFailure) {
      this.logParadigmOntologyRangeRejected("admission", "ONTOLOGY_RANGE_ASYNC_WORK_PENDING", cellRef);
      new Notice("图片或共享结构仍在处理，请完成后再粘贴。");
      return false;
    }
    const clipboard = this.getParadigmOntologyRangeClipboard();
    if (!clipboard.ok || !clipboard.payload) {
      this.logParadigmOntologyRangeRejected("clipboard", clipboard.errors?.[0] || "ONTOLOGY_RANGE_CLIPBOARD_INVALID", cellRef);
      new Notice("Ontology 内容剪贴板为空、已过期或来自旧插件实例，请重新复制。");
      this.cancelParadigmOntologyRangeMode("clipboard-invalid");
      return false;
    }
    const payload = clipboard.payload;
    const firstInspection = this.inspectParadigmOntologyRangeTarget(cellRef, payload);
    if (!firstInspection.ok) {
      this.setParadigmOntologyRangeConflicts(firstInspection.conflicts);
      this.logParadigmOntologyRangeRejected("preflight", firstInspection.code, cellRef, payload, {
        conflictCount: firstInspection.conflicts?.length || 0,
      });
      new Notice(firstInspection.code === "ONTOLOGY_RANGE_TARGET_OCCUPIED"
        ? `目标区域有 ${firstInspection.conflicts.length} 个非空格，整批未粘贴。`
        : "目标区域超出表格、属于历史只读区域或已经变化，未粘贴。");
      return false;
    }
    this.setParadigmOntologyRangeConflicts([]);
    let materialized;
    try { materialized = this.materializeParadigmOntologyRangeClipboard(payload); }
    catch (error) {
      this.logParadigmOntologyRangeRejected("materialize-before-confirm", error?.code, cellRef, payload);
      new Notice(error?.message || "图片引用校验失败，未粘贴。");
      return false;
    }
    const frozen = {
      draftHash: hashParadigmOntology(this.draft),
      generation: this.generation,
      closeToken: this.closeOperationToken,
      phaseToken: this.rangePhaseToken,
      tableId: this.currentTableId,
      clipboardHash: payload.payloadHash,
      signature: firstInspection.signature,
    };
    const confirmed = await this.confirmAction({
      title: "粘贴 Ontology 区域",
      message: `区域：${payload.rowCount}×${payload.columnCount}\n文字格：${payload.cellCount}\n图片引用：${payload.imageCount || 0}\n忽略子表：${payload.ignoredNestedTableCount || 0}\n忽略 Meta 引用：${payload.ignoredReferenceCount || 0}\n\n图片仍引用同一批 Obsidian 本地附件；不会复制子表、共享结构或引用关系。目标区域只要有一个格非空，整批都会取消。`,
      confirmText: "粘贴到空白区域",
      cancelText: "取消",
    });
    if (!confirmed) return false;
    const currentClipboard = this.getParadigmOntologyRangeClipboard();
    const stale = !this.canMutateParadigmOntologyAfterConfirmation()
      || this.guardPendingImageImports()
      || Boolean(this.schemaLineageSyncPromise)
      || Boolean(this.sharedSchemaRequiredFailure)
      || frozen.generation !== this.generation
      || frozen.closeToken !== this.closeOperationToken
      || frozen.phaseToken !== this.rangePhaseToken
      || frozen.tableId !== this.currentTableId
      || frozen.draftHash !== hashParadigmOntology(this.draft)
      || !currentClipboard.ok
      || currentClipboard.payload?.payloadHash !== frozen.clipboardHash;
    if (stale) {
      this.logParadigmOntologyRangeRejected("confirmation-recheck", "ONTOLOGY_RANGE_CONFIRMATION_STALE", cellRef, payload);
      new Notice("Ontology 或剪贴板已变化，请重新选择目标。");
      return false;
    }
    const secondInspection = this.inspectParadigmOntologyRangeTarget(cellRef, currentClipboard.payload);
    if (!secondInspection.ok || secondInspection.signature !== frozen.signature) {
      this.setParadigmOntologyRangeConflicts(secondInspection.conflicts);
      this.logParadigmOntologyRangeRejected("commit-preflight", secondInspection.code || "ONTOLOGY_RANGE_SIGNATURE_CHANGED", cellRef, payload, {
        conflictCount: secondInspection.conflicts?.length || 0,
      });
      new Notice("目标区域已变化，整批未粘贴。");
      return false;
    }
    try { materialized = this.materializeParadigmOntologyRangeClipboard(currentClipboard.payload); }
    catch (error) {
      this.logParadigmOntologyRangeRejected("materialize-at-commit", error?.code, cellRef, payload);
      new Notice(error?.message || "图片附件已变化，整批未粘贴。");
      return false;
    }
    let built;
    try { built = createParadigmOntologyRangePasteCandidate(this.draft, secondInspection.targetRefs, materialized); }
    catch (error) {
      this.logParadigmOntologyRangeRejected("candidate", error?.code, cellRef, payload);
      new Notice(error?.message || "区域粘贴校验失败。");
      return false;
    }
    const previous = {
      draft: this.draft,
      dirty: this.dirty,
      draftBytes: this.draftBytes,
      statusText: String(this.statusEl?.textContent || ""),
      statusClass: String(this.statusEl?.className || ""),
      recoveryTimer: this.recoveryTimer,
      rangePhase: this.rangePhase,
      rangePhaseToken: this.rangePhaseToken,
      rangeAnchorRef: this.rangeAnchorRef,
      rangeExtentRef: this.rangeExtentRef,
      rangeSelection: this.rangeSelection,
      rangeConflictKeys: new Set(this.rangeConflictKeys),
      rangeSuccessKeys: new Set(this.rangeSuccessKeys),
      rangeCueTimer: this.rangeCueTimer,
      scroll: this.captureParadigmOntologyRangeScroll(),
    };
    let replacementCueTimer = 0;
    try {
      this.draft = built.candidate;
      this.draftBytes = built.byteCount;
      this.setParadigmOntologyDirtyState(hashParadigmOntology(this.draft) !== this.initialDraftHash);
      this.rangePhase = "idle";
      this.rangePhaseToken += 1;
      this.rangeAnchorRef = null;
      this.rangeExtentRef = null;
      this.rangeSelection = null;
      this.rangeConflictKeys.clear();
      this.rangeSuccessKeys = new Set(secondInspection.targetRefs.map((ref) => this.getParadigmOntologyCellRefKey(ref)));
      this.renderEditor();
      this.restoreParadigmOntologyRangeScroll(previous.scroll);
      this.applyParadigmOntologyRangeCues();
      this.revealParadigmOntologyRangeTargetInTable(secondInspection.targetRefs[0]);
      this.setStatus(`已粘贴 ${payload.rowCount}×${payload.columnCount} · 尚未保存`, "is-dirty");
      this.refreshParadigmOntologyRangeToolbar();
      replacementCueTimer = window.setTimeout(() => {
        if (this.rangeCueTimer !== replacementCueTimer) return;
        this.rangeCueTimer = 0;
        this.rangeSuccessKeys.clear();
        this.applyParadigmOntologyRangeCues();
      }, 2200);
      this.rangeCueTimer = replacementCueTimer;
      if (previous.rangeCueTimer && previous.rangeCueTimer !== replacementCueTimer) window.clearTimeout(previous.rangeCueTimer);
      this.installParadigmOntologyRecoveryTimerTransactional(previous.recoveryTimer);
    } catch (error) {
      if (replacementCueTimer) window.clearTimeout(replacementCueTimer);
      this.draft = previous.draft;
      this.setParadigmOntologyDirtyState(previous.dirty);
      this.draftBytes = previous.draftBytes;
      this.rangePhase = previous.rangePhase;
      this.rangePhaseToken = previous.rangePhaseToken;
      this.rangeAnchorRef = previous.rangeAnchorRef;
      this.rangeExtentRef = previous.rangeExtentRef;
      this.rangeSelection = previous.rangeSelection;
      this.rangeConflictKeys = previous.rangeConflictKeys;
      this.rangeSuccessKeys = previous.rangeSuccessKeys;
      this.rangeCueTimer = previous.rangeCueTimer;
      this.recoveryTimer = previous.recoveryTimer;
      try {
        this.renderEditor();
        this.restoreParadigmOntologyRangeScroll(previous.scroll);
        if (this.statusEl) {
          this.statusEl.className = previous.statusClass;
          this.statusEl.textContent = previous.statusText;
        }
      } catch (restoreError) {
        console.error("[Workspace Mount][ontology.range-paste-rejected]", { stage: "rollback-render", code: "ONTOLOGY_RANGE_ROLLBACK_RENDER_FAILED" });
      }
      this.logParadigmOntologyRangeRejected("commit", error?.code || "ONTOLOGY_RANGE_COMMIT_FAILED", cellRef, payload);
      new Notice("区域粘贴未完成，原草稿已恢复。");
      return false;
    }
    try {
      console.info("[Workspace Mount][ontology.range-paste-applied]", {
        rowCount: payload.rowCount,
        columnCount: payload.columnCount,
        cellCount: payload.cellCount,
        tableId: this.currentTableId,
        targetRowId: sanitizeText(cellRef?.rowId, ""),
        targetColumnId: sanitizeText(cellRef?.columnId, ""),
      });
      new Notice(`已粘贴 ${payload.rowCount}×${payload.columnCount} 个格子，请保存 Ontology。`);
    } catch (_) {}
    return true;
  }

  readParadigmOntologyCaptureState() {
    if (typeof this.referenceAdapter?.getCaptureState !== "function") return { active: false, phase: "source", sourceKey: "" };
    try {
      const state = this.referenceAdapter.getCaptureState();
      return isObjectLike(state) ? state : { active: false, phase: "source", sourceKey: "" };
    } catch (_) {
      return { active: false, phase: "source", sourceKey: "" };
    }
  }

  bindParadigmOntologyCaptureState() {
    if (this.referenceCaptureStateUnsubscribe || typeof this.referenceAdapter?.subscribeCaptureState !== "function") {
      this.applyParadigmOntologyCaptureState(this.referenceCaptureState);
      return;
    }
    try {
      const unsubscribe = this.referenceAdapter.subscribeCaptureState((state) => this.applyParadigmOntologyCaptureState(state));
      this.referenceCaptureStateUnsubscribe = typeof unsubscribe === "function" ? unsubscribe : null;
    } catch (_) {
      this.applyParadigmOntologyCaptureState({ active: false, phase: "source", sourceKey: "" });
    }
  }

  refreshParadigmOntologyRelationsVisibility(relations) {
    if (!relations) return;
    const hasVisibleChild = Array.from(relations.children || []).some((child) => child.hidden !== true);
    relations.hidden = !hasVisibleChild;
  }

  applyParadigmOntologyCaptureState(stateValue) {
    if (this.finalClosing) return;
    const state = isObjectLike(stateValue) ? stateValue : { active: false, phase: "source", sourceKey: "" };
    this.referenceCaptureState = state;
    const active = state.active === true;
    if (active && this.surfaceMode === "tree") this.exitParadigmOntologyTreeMode();
    if (active && this.rangePhase !== "idle") this.cancelParadigmOntologyRangeMode("meta-activated");
    this.modalEl?.classList?.toggle?.("is-ontology-meta-active", active);
    let sourceKey = sanitizeText(state.sourceKey, "");
    if (!sourceKey && state?.source?.address) {
      try { sourceKey = serializeParadigmOntologyAddress(state.source.address); } catch (_) {}
    }
    this.editorEl?.querySelectorAll?.(".workspace-ontology-capture-cell")?.forEach?.((button) => {
      const addressKey = sanitizeText(button.getAttribute?.("data-ontology-address-key"), "");
      button.hidden = !active;
      button.classList.toggle("is-active", active);
      button.classList.toggle("is-source", active && Boolean(addressKey) && addressKey === sourceKey);
      button.disabled = this.isReadOnly() && sanitizeText(state.phase, "source") === "target";
      this.refreshParadigmOntologyRelationsVisibility(button.parentElement);
    });
    this.refreshParadigmOntologyRangeToolbar();
  }

  applyParadigmOntologyReferenceWriteState(stateValue) {
    if (this.finalClosing) return;
    const nextState = isObjectLike(stateValue)
      ? Object.assign({ writable: false, code: "REFERENCE_WRITE_UNAVAILABLE", reason: "Ontology 引用能力不可用。" }, stateValue)
      : { writable: false, code: "REFERENCE_WRITE_UNAVAILABLE", reason: "Ontology 引用能力状态无效。" };
    const previousKey = `${this.referenceWriteState?.writable === true}|${sanitizeText(this.referenceWriteState?.code, "")}`;
    const nextKey = `${nextState.writable === true}|${sanitizeText(nextState.code, "")}`;
    this.referenceWriteState = nextState;
    const wasReadOnly = this.referenceCapabilityReadOnly;
    this.referenceCapabilityReadOnly = this.hasParadigmOntologyReferenceProtectedState() && nextState.writable !== true;
    if (this.referenceCapabilityReadOnly) {
      if (this.recoveryTimer) window.clearTimeout(this.recoveryTimer);
      this.recoveryTimer = 0;
      this.acceptingImageImports = false;
      this.admittedImageOperationIds.clear();
      this.invalidateParadigmOntologyAlbums();
      this.structureMutationButtons.forEach((button) => { button.disabled = true; });
      if (this.saveCloseBtn) this.saveCloseBtn.disabled = true;
      this.setStatus("引用能力已降级，只读保护", "is-error");
    } else if (wasReadOnly && !this.closingPromise && !this.forcedTeardown) {
      this.acceptingImageImports = true;
      this.structureMutationButtons.forEach((button) => { button.disabled = this.isReadOnly(); });
      if (this.saveCloseBtn) this.saveCloseBtn.disabled = this.isReadOnly() || this.recoveryConflict;
      this.setStatus(this.dirty ? "未保存" : "", this.dirty ? "is-dirty" : "");
    }
    if ((previousKey !== nextKey || wasReadOnly !== this.referenceCapabilityReadOnly) && this.editorEl) {
      this.renderRecoveryConflictControls();
      this.renderEditor();
    }
  }

  getParadigmOntologyCellRef(tableId, rowId, columnId) {
    return {
      tableId: sanitizeText(tableId, ""),
      rowId: sanitizeText(rowId, ""),
      columnId: sanitizeText(columnId, ""),
    };
  }

  getParadigmOntologyCellRefKey(cellRef) {
    return `${sanitizeText(cellRef?.tableId, "")}\u0000${sanitizeText(cellRef?.rowId, "")}\u0000${sanitizeText(cellRef?.columnId, "")}`;
  }

  buildParadigmOntologyCellAddress(cellRef) {
    const localRef = this.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId);
    if (typeof this.referenceAdapter?.buildCellAddress === "function") {
      try {
        return normalizeParadigmOntologyCellAddress(this.referenceAdapter.buildCellAddress({
          cellRef: deepClone(localRef, {}),
          documentId: sanitizeText(this.draft?.documentId, ""),
          ownerPluginId: this.ownerPluginId,
          ownerNamespace: this.externalOwnerNamespace,
          ownerKey: this.externalOwnerKey || this.paradigmItemId,
          sourceNotePath: this.sourceNotePath,
        }));
      } catch (_) { return null; }
    }
    if (!this.cellAddressBase) return null;
    try {
      return normalizeParadigmOntologyCellAddress(Object.assign({}, this.cellAddressBase, localRef, {
        addressVersion: PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION,
        documentId: sanitizeText(this.draft?.documentId, ""),
      }));
    } catch (_) { return null; }
  }

  buildParadigmOntologySchemaAddress(schemaId) {
    if (typeof this.referenceAdapter?.buildSchemaAddress === "function") {
      try {
        return normalizeParadigmOntologySchemaAddress(this.referenceAdapter.buildSchemaAddress({
          schemaId: sanitizeText(schemaId, ""),
          documentId: sanitizeText(this.draft?.documentId, ""),
          ownerPluginId: this.ownerPluginId,
          ownerNamespace: this.externalOwnerNamespace,
          ownerKey: this.externalOwnerKey || this.paradigmItemId,
          sourceNotePath: this.sourceNotePath,
        }));
      } catch (_) { return null; }
    }
    if (!this.cellAddressBase) return null;
    try {
      const base = Object.assign({}, this.cellAddressBase);
      delete base.tableId;
      delete base.rowId;
      delete base.columnId;
      return normalizeParadigmOntologySchemaAddress(Object.assign(base, {
        addressVersion: PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_VERSION,
        documentId: sanitizeText(this.draft?.documentId, ""),
        schemaId: sanitizeText(schemaId, ""),
      }));
    } catch (_) { return null; }
  }

  getParadigmOntologyReferenceCallbackPayload(cellRef, extra = {}) {
    const resolved = this.resolveParadigmOntologyCell(cellRef);
    return Object.assign({
      address: this.buildParadigmOntologyCellAddress(cellRef),
      cellRef: this.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId),
      documentId: sanitizeText(this.draft?.documentId, ""),
      ontologyHash: hashParadigmOntology(this.draft),
      ontologySchemaVersion: Number(this.draft?.schemaVersion) || 0,
      formalOntologyHash: this.formalOntologyHash,
      dirty: this.dirty === true,
      readOnly: this.isReadOnly() || this.recoveryConflict,
      writable: !this.isReadOnly() && !this.recoveryConflict,
      cell: resolved ? deepClone(resolved.cell, null) : null,
      modalGeneration: this.generation,
      providerGeneration: this.providerGeneration,
    }, extra);
  }

  applyParadigmOntologyCaptureResult(cellRef, result) {
    if (this.isReadOnly()) return false;
    if (!isObjectLike(result) || result.ok !== true || !isObjectLike(result.reference)) return false;
    const targetAddress = this.buildParadigmOntologyCellAddress(cellRef);
    if (!targetAddress) throw new Error("当前 owner 未提供稳定 celladdr:v1，不能建立引用。");
    const snapshot = deepClone(this.draft, null);
    try {
      const mirror = result.schemaMirror;
      if (isObjectLike(mirror)) {
        const resolved = this.resolveParadigmOntologyCell(cellRef);
        const targetSchemaId = sanitizeText(resolved?.table?.schemaId, "");
        attachParadigmOntologySchemaLineageMirror(
          this.draft,
          targetSchemaId,
          sanitizeText(cellRef?.columnId, ""),
          mirror.sourceOntology,
          sanitizeText(mirror.sourceSchemaId, ""),
          mirror.sourceSchemaAddress,
          mirror.evidence || {},
        );
      }
      setParadigmOntologyCellReference(this.draft, targetAddress, result.reference);
      const validation = validateParadigmOntology(this.draft);
      if (!validation.ok) throw new Error(validation.errors[0] || "引用写入后 Ontology 无效。");
      this.markDirty("建立单元格引用");
      this.renderEditor();
      return true;
    } catch (error) {
      restoreParadigmOntologySnapshot(this.draft, snapshot);
      throw error;
    }
  }

  async captureParadigmOntologyCellFromUi(cellRef) {
    if (typeof this.referenceAdapter?.captureCell !== "function") return false;
    if (this.isReadOnly() || this.isParadigmOntologyCellMutationBlocked(cellRef)) return false;
    try {
      const result = await this.referenceAdapter.captureCell(this.getParadigmOntologyReferenceCallbackPayload(cellRef));
      if (!isObjectLike(result) || result.ok !== true) {
        if (sanitizeText(result?.message, "")) new Notice(result.message);
        return false;
      }
      if (isObjectLike(result.reference)) return this.applyParadigmOntologyCaptureResult(cellRef, result);
      this.renderEditor();
      return true;
    } catch (error) {
      new Notice(error?.message || "Ontology 单元格捕获失败。");
      return false;
    }
  }

  async unlinkParadigmOntologyCellReferenceFromUi(cellRef) {
    const resolved = this.resolveParadigmOntologyCell(cellRef);
    if (!resolved || !isObjectLike(resolved.cell.reference) || !this.canMutateParadigmOntologyAfterConfirmation()) return false;
    const frozenReferenceKey = serializeParadigmOntologyAddress(resolved.cell.reference.sourceAddress);
    const confirmed = await this.confirmFrozenDestructive({
      title: "解除 Ontology 单元格引用",
      message: "确定解除当前单元格引用吗？\n保存时将重新核查共享结构：B 已使用的结构会无损分叉为本地结构；未使用且无人依赖的结构会清空。A 不会被修改。",
      confirmText: "解除引用",
      cancelText: "取消",
      danger: true,
    }, () => {
      const current = this.resolveParadigmOntologyCell(cellRef);
      if (!isObjectLike(current?.cell?.reference)) return false;
      try { return serializeParadigmOntologyAddress(current.cell.reference.sourceAddress) === frozenReferenceKey; }
      catch (_) { return false; }
    });
    if (!confirmed) return false;
    const targetAddress = this.buildParadigmOntologyCellAddress(cellRef);
    if (!targetAddress || !unlinkParadigmOntologyCellReference(this.draft, targetAddress)) return false;
    this.markDirty("解除单元格引用");
    this.setStatus("解除引用待保存；共享结构将在正式保存时核查并分叉或清空", "is-warning");
    this.renderEditor();
    return true;
  }

  resolveParadigmOntologyCell(cellRef) {
    const table = this.draft?.tablesById?.[sanitizeText(cellRef?.tableId, "")];
    const row = table?.rowsById?.[sanitizeText(cellRef?.rowId, "")];
    const cell = row?.cellsByColumnId?.[sanitizeText(cellRef?.columnId, "")];
    return table && row && cell ? { table, row, cell } : null;
  }

  hasPendingImageImports() {
    return this.pendingImageImportCount > 0;
  }

  guardPendingImageImports(message = "图片仍在导入，请等待完成后再执行此操作。") {
    if (!this.hasPendingImageImports()) return false;
    new Notice(message);
    return true;
  }

  setStatus(text, className = "") {
    if (!this.statusEl) return;
    this.statusEl.textContent = sanitizeText(text, "");
    this.statusEl.className = `workspace-ontology-status ${className}`.trim();
  }

  setParadigmOntologyDirtyState(nextDirty) {
    this.dirty = nextDirty === true;
    this.syncParadigmOntologyRestoreChipState();
    return this.dirty;
  }

  syncParadigmOntologyRestoreChipState() {
    if (!this.restoreChipEl) return;
    const title = sanitizeText(this.paradigmItemTitle, "Ontology");
    const dirty = this.dirty === true;
    this.restoreChipEl.classList?.toggle?.("is-dirty", dirty);
    this.restoreChipEl.setAttribute?.("title", dirty ? `恢复 ${title} Ontology · 未保存` : `恢复 ${title} Ontology`);
    this.restoreChipEl.setAttribute?.("aria-label", dirty ? `恢复 ${title} Ontology，存在未保存修改` : `恢复 ${title} Ontology`);
    if (this.restoreChipDirtyEl) this.restoreChipDirtyEl.hidden = !dirty;
  }

  invalidateSharedSchemaAsyncWork() {
    this.schemaLineageSyncEpoch += 1;
  }

  createSharedSchemaAsyncToken() {
    return {
      epoch: this.schemaLineageSyncEpoch,
      modalGeneration: this.generation,
      closeOperationToken: this.closeOperationToken,
      draft: this.draft,
    };
  }

  isSharedSchemaAsyncTokenCurrent(token) {
    return token
      && token.epoch === this.schemaLineageSyncEpoch
      && token.modalGeneration === this.generation
      && token.closeOperationToken === this.closeOperationToken
      && token.draft === this.draft
      && !this.finalClosing;
  }

  getSharedSchemaPartition() {
    return partitionParadigmOntologySharedSchemaGraphs(this.draft);
  }

  getSharedSchemaGraphEntry(schemaId, partition = this.getSharedSchemaPartition()) {
    const id = sanitizeText(schemaId, "");
    return partition.allRoots.find((entry) => entry.graphSchemaIds.includes(id)) || null;
  }

  buildSharedSchemaDiagnostic(entry, options = {}) {
    const error = options.error;
    let targetAddress = null;
    try { targetAddress = this.buildParadigmOntologySchemaAddress(entry?.rootSchemaId); } catch (_) {}
    return {
      schemaId: sanitizeText(entry?.rootSchemaId, "") || null,
      graphSchemaIds: Array.isArray(entry?.graphSchemaIds) ? entry.graphSchemaIds.slice() : [],
      sourceAddress: deepClone(entry?.schema?.sourceLineage?.sourceSchemaAddress, null),
      targetAddress: deepClone(targetAddress, null),
      stage: sanitizeText(options.stage, "unknown"),
      code: sanitizeText(options.code || error?.code, "ONTOLOGY_SHARED_SCHEMA_REJECTED"),
      message: sanitizeText(options.message || error?.message, "共享结构操作被拒绝。"),
      pendingDetach: entry?.pendingDetach === true,
      blockSave: options.blockSave !== false,
      aggregateReasons: Array.isArray(options.aggregateReasons) ? deepClone(options.aggregateReasons, []) : [],
      parentEvidence: deepClone(entry?.parentColumns, []),
      ownerPluginId: this.ownerPluginId,
      ownerKey: this.externalOwnerKey || this.paradigmItemId,
      modalGeneration: this.generation,
    };
  }

  logSharedSchemaRejection(entry, options = {}) {
    const detail = this.buildSharedSchemaDiagnostic(entry, options);
    console.error("[Workspace Mount][ontology.shared-schema-rejected]", detail);
    return detail;
  }

  refreshDraftBytes() {
    this.draftBytes = workspacePerfByteLength(canonicalJsonString(this.draft));
    return this.draftBytes;
  }

  replaceDraftTextValue(target, key, nextValue) {
    const previous = String(target?.[key] || "");
    const next = String(nextValue || "");
    const previousBytes = workspacePerfByteLength(JSON.stringify(previous));
    const nextBytes = workspacePerfByteLength(JSON.stringify(next));
    const candidateBytes = this.draftBytes - previousBytes + nextBytes;
    if (candidateBytes > PARADIGM_ONTOLOGY_LIMITS.maxBytes) {
      const now = Date.now();
      if (now - this.lastSizeLimitNoticeAt > 1200) {
        new Notice("Ontology 已达到大小上限，当前输入未写入草稿。");
        this.lastSizeLimitNoticeAt = now;
      }
      return false;
    }
    target[key] = next;
    this.draftBytes = candidateBytes;
    return true;
  }

  renderRecoveryConflictControls() {
    if (!this.conflictHostEl) return;
    this.conflictHostEl.empty();
    if (!this.recoveryConflict && !this.sharedSchemaRequiredFailure) return;
    const box = this.conflictHostEl.createDiv({ cls: "workspace-ontology-conflict" });
    if (this.sharedSchemaRequiredFailure && !this.recoveryConflict) {
      box.createDiv({ text: "共享结构未通过同步。正式数据未改写，当前草稿已进入恢复保护。" });
      const actions = box.createDiv({ cls: "workspace-ontology-conflict-actions" });
      const preserveBtn = actions.createEl("button", { text: "保留草稿并关闭", attr: { type: "button" } });
      preserveBtn.onclick = async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const asyncToken = this.createSharedSchemaAsyncToken();
        try {
          await this.flushRecovery("shared-schema-preserve-close");
          if (!this.isSharedSchemaAsyncTokenCurrent(asyncToken)) return;
          this.invalidateSharedSchemaAsyncWork();
          this.closeOperationToken += 1;
          this.finishClose();
        } catch (error) {
          this.setStatus("恢复草稿写入失败，窗口保持打开", "is-error");
          new Notice(error?.message || "恢复草稿写入失败");
        }
      };
      const localForkCandidates = this.getCorruptedSharedSchemaRecoveryCandidates();
      if (localForkCandidates.length > 0) {
        const localForkBtn = actions.createEl("button", {
          text: "保留当前结构并转为本地",
          cls: "mod-warning",
          attr: { type: "button" },
        });
        localForkBtn.onclick = async (event) => {
          event.preventDefault();
          event.stopPropagation();
          try {
            await this.recoverCorruptedSharedSchemasAsLocal();
          } catch (error) {
            this.setStatus("转为本地结构失败，恢复草稿保持原状", "is-error");
            new Notice(error?.message || "转为本地结构失败");
          }
        };
      }
      const discardBtn = actions.createEl("button", { text: "放弃草稿并关闭", cls: "mod-warning", attr: { type: "button" } });
      discardBtn.onclick = async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const confirmed = await this.confirmAction({
          title: "放弃 Ontology 恢复草稿",
          message: "确定放弃本次未保存修改并关闭吗？正式数据不会变化。",
          confirmText: "放弃草稿",
          cancelText: "取消",
          danger: true,
        });
        if (!confirmed || this.finalClosing) return;
        const asyncToken = this.createSharedSchemaAsyncToken();
        try {
          await this.plugin.clearParadigmOntologyRecovery(this.dataPath, this.paradigmItemId, this.formalOntologyHash, {
            sessionId: this.sessionId,
            generation: this.generation,
          });
          if (!this.isSharedSchemaAsyncTokenCurrent(asyncToken)) return;
          this.invalidateSharedSchemaAsyncWork();
          this.closeOperationToken += 1;
          this.finishClose();
        } catch (error) {
          this.setStatus("恢复草稿清理失败，窗口保持打开", "is-error");
          new Notice(error?.message || "恢复草稿清理失败");
        }
      };
      return;
    }
    box.createDiv({ text: "正式数据已变化。当前显示的是保留下来的冲突草稿。" });
    const actions = box.createDiv({ cls: "workspace-ontology-conflict-actions" });
    const formalBtn = actions.createEl("button", { text: "使用当前正式数据", attr: { type: "button" } });
    formalBtn.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      await this.resolveRecoveryConflict(false);
    };
    const draftBtn = actions.createEl("button", { text: "以草稿替换当前版本", cls: "mod-warning", attr: { type: "button" } });
    draftBtn.onclick = async (event) => {
      event.preventDefault();
      event.stopPropagation();
      await this.resolveRecoveryConflict(true);
    };
  }

  async resolveRecoveryConflict(useDraft) {
    if (!this.recoveryConflict) return;
    if (this.guardPendingImageImports()) return;
    if (this.protectedImageRecoveryRecord) {
      new Notice("存在尚未并入正式数据的图片恢复引用，请关闭并重新打开 Ontology 处理恢复草稿。");
      return;
    }
    if (useDraft) {
      const previousBaseHash = this.baseOntologyHash;
      this.baseOntologyHash = this.formalOntologyHash;
      this.recoveryConflict = false;
      this.setParadigmOntologyDirtyState(true);
      try {
        await this.plugin.persistParadigmOntologyRecovery(this.buildRecoveryRecord("editing", "explicit-draft-rebase"));
        this.setStatus("草稿已显式设为待保存版本", "is-warning");
      } catch (error) {
        this.baseOntologyHash = previousBaseHash;
        this.recoveryConflict = true;
        this.setStatus("冲突草稿保护失败", "is-error");
        new Notice(error.message || "冲突草稿保护失败");
        this.renderRecoveryConflictControls();
        return;
      }
    } else {
      try {
        await this.plugin.clearParadigmOntologyRecovery(this.dataPath, this.paradigmItemId, this.formalOntologyHash, {
          sessionId: this.sessionId,
          generation: this.generation,
        });
      } catch (error) {
        this.setStatus("冲突草稿清理失败", "is-error");
        new Notice(error.message || "冲突草稿清理失败");
        return;
      }
      this.draft = deepClone(this.formalOntology, null) || createDefaultParadigmOntology();
      this.baseOntologyHash = this.formalOntologyHash;
      this.initialDraftHash = hashParadigmOntology(this.draft);
      this.initialRowIds = new Set(Object.values(this.draft?.tablesById || {}).flatMap((table) => table?.rowOrder || []));
      this.currentTableId = sanitizeText(this.draft?.rootTableId, "");
      this.recoveryConflict = false;
      this.setParadigmOntologyDirtyState(false);
      this.setStatus("已使用当前正式数据", "is-saved");
    }
    if (this.saveCloseBtn) this.saveCloseBtn.disabled = this.isReadOnly();
    this.refreshDraftBytes();
    this.renderRecoveryConflictControls();
    this.renderEditor();
  }

  scheduleParadigmOntologyViewState(reason = "navigation") {
    if (this.schemaOnlySchemaId || typeof this.viewStatePlugin?.persistParadigmOntologyViewState !== "function") return;
    if (this.viewStateTimer) window.clearTimeout(this.viewStateTimer);
    this.viewStateTimer = window.setTimeout(() => {
      this.viewStateTimer = 0;
      void this.flushParadigmOntologyViewState(reason);
    }, PARADIGM_ONTOLOGY_VIEW_STATE_DEBOUNCE_MS);
  }

  async flushParadigmOntologyViewState(reason = "flush") {
    if (this.viewStateTimer) window.clearTimeout(this.viewStateTimer);
    this.viewStateTimer = 0;
    if (this.schemaOnlySchemaId || typeof this.viewStatePlugin?.persistParadigmOntologyViewState !== "function") return true;
    const record = buildParadigmOntologyViewStateRecord(this.draft, this.currentTableId, {
      dataPath: this.dataPath,
      paradigmItemId: this.paradigmItemId,
      generation: this.generation,
      sessionId: this.sessionId,
    });
    if (!record) return false;
    try {
      await this.viewStatePlugin.persistParadigmOntologyViewState(record);
      return true;
    } catch (error) {
      console.warn("[WorkspaceMount][ontology.view-state-save-failed]", {
        reason,
        dataPath: this.dataPath,
        paradigmItemId: this.paradigmItemId,
        tableId: this.currentTableId,
        message: error?.message || String(error),
      });
      return false;
    }
  }

  getParadigmOntologyRestoreTray() {
    const body = globalThis.document?.body;
    if (!body) return null;
    const existing = body.querySelector?.(".workspace-ontology-restore-tray");
    if (existing) return existing;
    return body.createDiv
      ? body.createDiv({ cls: "workspace-ontology-restore-tray" })
      : null;
  }

  getActiveColumnDescriptionModal() {
    const modal = this.columnDescriptionModal;
    return modal && !modal.finalClosing ? modal : null;
  }

  async settleActiveColumnDescriptionModal(reason = "parent-close") {
    if (this.columnDescriptionSettlementPromise) return await this.columnDescriptionSettlementPromise;
    const modal = this.getActiveColumnDescriptionModal();
    if (!modal) return true;
    const promise = modal.requestClose(reason);
    this.columnDescriptionSettlementPromise = promise;
    try {
      return await promise;
    } finally {
      if (this.columnDescriptionSettlementPromise === promise) this.columnDescriptionSettlementPromise = null;
    }
  }

  commitParadigmOntologyColumnDescription(schemaId, columnId, nextValue) {
    if (this.finalClosing || this.forcedTeardown) throw new Error("Ontology 正在关闭，列说明输入仍保留。");
    if (this.isReadOnly()) throw new Error("当前 Ontology 已转为只读，列说明输入仍保留。");
    const schema = this.draft?.schemasById?.[sanitizeText(schemaId, "")];
    const column = schema?.columnsById?.[sanitizeText(columnId, "")];
    if (!schema || !column) throw new Error("目标列已不存在，列说明输入仍保留。");
    if (!(schema.columnOrder || []).includes(column.id) || (schema.archivedColumnOrder || []).includes(column.id)) {
      throw new Error("目标列已归档，列说明输入仍保留。");
    }
    if (paradigmOntologySchemaHasRetainedLineage(schema)) {
      throw new Error("说明由来源 Schema 管理，当前镜像只能查看。");
    }
    const nextDescription = String(nextValue || "");
    const previousDescription = typeof column.description === "string" ? column.description : "";
    if (nextDescription === previousDescription) return true;
    const snapshot = {
      hadDescription: Object.prototype.hasOwnProperty.call(column, "description"),
      description: column.description,
      columnUpdatedAt: column.updatedAt,
      schemaUpdatedAt: schema.updatedAt,
      ontologyUpdatedAt: this.draft.updatedAt,
      draftBytes: this.draftBytes,
    };
    try {
      if (!this.replaceDraftTextValue(column, "description", nextDescription)) {
        throw new Error("Ontology 已达到大小上限，列说明输入仍保留。");
      }
      if (!nextDescription) delete column.description;
      const timestamp = nowString();
      column.updatedAt = timestamp;
      schema.updatedAt = timestamp;
      this.draft.updatedAt = timestamp;
      const validation = validateParadigmOntology(this.draft);
      if (!validation.ok) throw new Error(validation.errors[0] || "列说明写入后 Ontology 校验失败。");
      this.markDirty(nextDescription ? "修改列说明" : "清空列说明");
      this.renderEditor();
      return true;
    } catch (error) {
      if (snapshot.hadDescription) column.description = snapshot.description;
      else delete column.description;
      column.updatedAt = snapshot.columnUpdatedAt;
      schema.updatedAt = snapshot.schemaUpdatedAt;
      this.draft.updatedAt = snapshot.ontologyUpdatedAt;
      this.draftBytes = snapshot.draftBytes;
      throw error;
    }
  }

  openParadigmOntologyColumnDescription(schemaId, columnId, options = {}) {
    const active = this.getActiveColumnDescriptionModal();
    if (active) {
      active.modalEl?.focus?.();
      return active;
    }
    const schema = this.draft?.schemasById?.[sanitizeText(schemaId, "")];
    const column = schema?.columnsById?.[sanitizeText(columnId, "")];
    if (!schema || !column) {
      new Notice("目标列已不存在。");
      return null;
    }
    const archived = (schema.archivedColumnOrder || []).includes(column.id);
    const sharedProjection = paradigmOntologySchemaHasRetainedLineage(schema);
    const editable = options.editable !== false
      && !this.isReadOnly()
      && !archived
      && !sharedProjection
      && !this.finalClosing
      && !this.forcedTeardown;
    const readOnlyReason = sharedProjection
      ? "说明由来源 Schema 管理；当前共享镜像只读。"
      : archived
        ? "历史归档列的说明只读。"
        : "当前 Ontology 处于只读状态。";
    const modal = new WorkspaceOntologyColumnDescriptionModal(this.app, {
      columnLabel: sanitizeText(column.label, column.id),
      value: typeof column.description === "string" ? column.description : "",
      editable,
      readOnlyReason,
      onSubmit: async (value) => this.commitParadigmOntologyColumnDescription(schema.id, column.id, value),
      onConfirmDiscard: async (modalOptions) => await this.confirmAction(modalOptions),
      onFinalized: (closedModal) => {
        if (this.columnDescriptionModal === closedModal) this.columnDescriptionModal = null;
      },
    });
    this.columnDescriptionModal = modal;
    modal.open();
    return modal;
  }

  renderParadigmOntologyColumnDescriptionButton(host, schema, column, options = {}) {
    if (!host || !schema || !column) return null;
    const hasDescription = typeof column.description === "string" && column.description.length > 0;
    const title = hasDescription ? "查看或编辑列说明（已有说明）" : "添加列说明";
    const button = host.createEl("button", {
      cls: `workspace-ontology-column-description${hasDescription ? " is-present" : ""}`,
      attr: { type: "button", title, "aria-label": title },
    });
    setIcon(button, hasDescription ? "file-text" : "info");
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.openParadigmOntologyColumnDescription(schema.id, column.id, options);
    };
    return button;
  }

  minimizeParadigmOntologyModal() {
    const columnDescriptionModal = this.getActiveColumnDescriptionModal();
    if (columnDescriptionModal) {
      columnDescriptionModal.modalEl?.focus?.();
      new Notice("请先保存或放弃列说明修改，再最小化 Ontology。");
      return false;
    }
    if (this.finalClosing || this.minimized || this.forcedTeardown) return false;
    if (this.dirty || this.hasPendingImageImports() || this.closingPromise
      || this.protectedImageRecoveryRecord || this.recoveryConflict) {
      return this.requestClose("minimize");
    }
    return this.performParadigmOntologyMinimize();
  }

  performParadigmOntologyMinimize() {
    if (this.finalClosing || this.minimized || this.forcedTeardown) return false;
    const tray = this.getParadigmOntologyRestoreTray();
    if (!tray) {
      new Notice("当前环境无法创建 Ontology 恢复入口。");
      return false;
    }
    const activeElement = globalThis.document?.activeElement;
    if (activeElement && this.containerEl?.contains?.(activeElement)) activeElement.blur?.();
    if (!this.scopeSuspendedForMinimize && this.scope && typeof this.app?.keymap?.popScope === "function") {
      this.app.keymap.popScope(this.scope);
      this.scopeSuspendedForMinimize = true;
    }
    this.containerEl?.addClass?.("is-workspace-ontology-minimized");
    this.minimized = true;
    if (this.surfaceMode === "tree") this.treePendingFit = true;
    this.restoreTrayEl = tray;
    this.restoreChipEl = tray.createEl("button", {
      cls: "workspace-ontology-restore-chip",
      attr: { type: "button", title: "恢复 Ontology 窗口", "aria-label": `恢复 ${this.paradigmItemTitle} Ontology` },
    });
    const iconEl = this.restoreChipEl.createSpan({ cls: "workspace-ontology-restore-chip-icon" });
    setIcon(iconEl, "table-properties");
    this.restoreChipTitleEl = this.restoreChipEl.createSpan({
      cls: "workspace-ontology-restore-chip-title",
      text: sanitizeText(this.paradigmItemTitle, "Ontology"),
    });
    this.restoreChipDirtyEl = this.restoreChipEl.createSpan({ cls: "workspace-ontology-restore-chip-dirty" });
    setIcon(this.restoreChipDirtyEl, "triangle-alert");
    this.restoreChipDirtyEl.createSpan({ text: "未保存" });
    this.syncParadigmOntologyRestoreChipState();
    this.restoreChipEl.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.restoreParadigmOntologyModal();
    };
    return true;
  }

  restoreParadigmOntologyModal() {
    if (!this.minimized || this.finalClosing) return false;
    this.containerEl?.removeClass?.("is-workspace-ontology-minimized");
    this.minimized = false;
    this.removeParadigmOntologyRestoreChip();
    if (this.scopeSuspendedForMinimize && this.scope && typeof this.app?.keymap?.pushScope === "function") {
      this.app.keymap.pushScope(this.scope);
      this.scopeSuspendedForMinimize = false;
    }
    this.modalEl?.focus?.();
    if (this.surfaceMode === "tree" && this.treePendingFit) this.scheduleParadigmOntologyTreeFit();
    return true;
  }

  removeParadigmOntologyRestoreChip() {
    if (this.restoreChipEl?.isConnected !== false) this.restoreChipEl?.remove?.();
    this.restoreChipEl = null;
    this.restoreChipTitleEl = null;
    this.restoreChipDirtyEl = null;
    const tray = this.restoreTrayEl;
    this.restoreTrayEl = null;
    if (tray && (tray.childElementCount === 0 || tray.children?.length === 0)) tray.remove?.();
  }

  prepareParadigmOntologyModalForClose() {
    if (this.surfaceMode === "tree") {
      this.cleanupParadigmOntologyTreeSurface();
      this.surfaceMode = "table";
    }
    this.removeParadigmOntologyRestoreChip();
    if (this.scopeSuspendedForMinimize && this.scope && typeof this.app?.keymap?.pushScope === "function") {
      this.app.keymap.pushScope(this.scope);
    }
    this.scopeSuspendedForMinimize = false;
    this.minimized = false;
    this.containerEl?.removeClass?.("is-workspace-ontology-minimized");
  }

  applyExternalOntologyFocusRequest(options = {}) {
    if (this.finalClosing || this.forcedTeardown) return false;
    if (this.surfaceMode === "tree") this.exitParadigmOntologyTreeMode();
    const focusSchemaAddress = isObjectLike(options.focusSchemaAddress) ? options.focusSchemaAddress : null;
    const focusCellAddress = isObjectLike(options.focusCellAddress || options.focusCellRef)
      ? options.focusCellAddress || options.focusCellRef
      : null;
    let rerender = false;
    if (focusSchemaAddress) {
      const schemaId = sanitizeText(focusSchemaAddress.schemaId, "");
      if (!schemaId || !this.draft?.schemasById?.[schemaId]) {
        new Notice("请求的共享 Schema 已不存在。");
      } else {
        this.pendingCellFocus = null;
        this.schemaOnlySchemaId = schemaId;
        this.schemaOnlyHistory = [schemaId];
        rerender = true;
      }
    } else if (focusCellAddress) {
      const documentId = sanitizeText(focusCellAddress.documentId, "");
      const tableId = sanitizeText(focusCellAddress.tableId, "");
      if (documentId && documentId !== sanitizeText(this.draft?.documentId, "")) {
        new Notice("请求的 Ontology 单元格属于另一个文档。");
      } else if (!tableId || !this.draft?.tablesById?.[tableId]) {
        new Notice("请求的 Ontology 单元格已不存在。");
      } else {
        this.schemaOnlySchemaId = "";
        this.schemaOnlyHistory = [];
        this.pendingCellFocus = deepClone(focusCellAddress, null);
        this.currentTableId = tableId;
        rerender = true;
      }
    }
    if (this.minimized) this.restoreParadigmOntologyModal();
    if (rerender) {
      this.renderEditor();
      if (!this.schemaOnlySchemaId) this.scheduleParadigmOntologyViewState("external-focus");
    }
    this.modalEl?.focus?.();
    return true;
  }

  getCurrentTableContext() {
    if (this.schemaOnlySchemaId) {
      return {
        table: null,
        schema: this.draft?.schemasById?.[this.schemaOnlySchemaId] || null,
        path: this.schemaOnlyHistory.map((schemaId) => ({ schemaId, label: sanitizeText(this.draft?.schemasById?.[schemaId]?.name, schemaId) })),
        navigationError: this.draft?.schemasById?.[this.schemaOnlySchemaId] ? "" : "请求的 Schema 已不存在。",
        archivedBranchReadOnly: false,
      };
    }
    let navigation = getParadigmOntologyNavigationPath(this.draft, this.currentTableId);
    if (!navigation.ok) {
      this.currentTableId = sanitizeText(this.draft?.rootTableId, "");
      navigation = getParadigmOntologyNavigationPath(this.draft, this.currentTableId);
    }
    const table = this.draft?.tablesById?.[this.currentTableId] || null;
    const schema = this.draft?.schemasById?.[table?.schemaId] || null;
    return {
      table,
      schema,
      path: navigation.ok ? navigation.path : [],
      navigationError: navigation.error,
      archivedBranchReadOnly: this.isParadigmOntologyTableInArchivedBranch(this.currentTableId),
    };
  }

  isParadigmOntologyTableInArchivedBranch(tableId) {
    let currentTableId = sanitizeText(tableId, "");
    const visited = new Set();
    while (currentTableId && currentTableId !== sanitizeText(this.draft?.rootTableId, "")) {
      if (visited.has(currentTableId)) return true;
      visited.add(currentTableId);
      const table = this.draft?.tablesById?.[currentTableId];
      const ref = table?.parentCellRef;
      const parentTable = this.draft?.tablesById?.[sanitizeText(ref?.parentTableId, "")];
      const parentSchema = this.draft?.schemasById?.[sanitizeText(parentTable?.schemaId, "")];
      if (!table || !parentTable || !parentSchema || !ref) return true;
      if (Array.isArray(parentSchema.archivedColumnOrder)
        && parentSchema.archivedColumnOrder.includes(sanitizeText(ref.parentColumnId, ""))) return true;
      currentTableId = parentTable.id;
    }
    return false;
  }

  navigateToTable(tableId) {
    if (this.guardPendingImageImports("图片仍在导入，请等待完成后再切换表格。")) return;
    if (this.rangePhase === "select-source") this.cancelParadigmOntologyRangeMode("table-navigation");
    const navigation = getParadigmOntologyNavigationPath(this.draft, tableId);
    if (!navigation.ok) {
      new Notice(navigation.error || "无法进入该子表。");
      this.currentTableId = sanitizeText(this.draft?.rootTableId, "");
    } else {
      this.currentTableId = sanitizeText(tableId, this.draft.rootTableId);
    }
    this.renderEditor();
    this.scheduleParadigmOntologyViewState("navigation");
  }

  navigateToSchemaOnly(schemaId) {
    const id = sanitizeText(schemaId, "");
    if (!id || !this.draft?.schemasById?.[id]) {
      new Notice("无法进入该 Schema。");
      return;
    }
    const existingIndex = this.schemaOnlyHistory.indexOf(id);
    this.schemaOnlyHistory = existingIndex >= 0
      ? this.schemaOnlyHistory.slice(0, existingIndex + 1)
      : [...this.schemaOnlyHistory, id];
    this.schemaOnlySchemaId = id;
    this.renderEditor();
  }

  renderSchemaOnlyEditor(schema, path = []) {
    this.refreshDraftBytes();
    const sharedSchemaProjection = paradigmOntologySchemaHasRetainedLineage(schema);
    this.structureMutationButtons.forEach((button) => { button.disabled = this.isReadOnly(); });
    this.schemaMutationButtons.forEach((button) => { button.disabled = this.isReadOnly() || sharedSchemaProjection; });
    if (this.addRowBtn) this.addRowBtn.disabled = true;
    const nav = this.editorEl.createDiv({ cls: "workspace-ontology-navigation is-schema-only" });
    const backBtn = nav.createEl("button", { attr: { type: "button", title: "返回上一级 Schema", "aria-label": "返回上一级 Schema" } });
    setIcon(backBtn, "arrow-left");
    backBtn.disabled = path.length <= 1;
    backBtn.onclick = () => {
      if (this.schemaOnlyHistory.length <= 1) return;
      this.schemaOnlyHistory.pop();
      this.schemaOnlySchemaId = this.schemaOnlyHistory[this.schemaOnlyHistory.length - 1];
      this.renderEditor();
    };
    const breadcrumbs = nav.createDiv({ cls: "workspace-ontology-breadcrumbs" });
    path.forEach((entry, index) => {
      if (index > 0) setIcon(breadcrumbs.createSpan({ cls: "workspace-ontology-breadcrumb-separator" }), "chevron-right");
      const button = breadcrumbs.createEl("button", { text: entry.label, attr: { type: "button" } });
      button.disabled = index === path.length - 1;
      button.onclick = () => this.navigateToSchemaOnly(entry.schemaId);
    });
    nav.createDiv({ cls: "workspace-ontology-schema-scope", text: `Schema-only · ${schema.id} · 不创建表实例` });
    if (sharedSchemaProjection) this.renderParadigmOntologySchemaLineage(nav, schema);
    const grid = this.editorEl.createDiv({ cls: "workspace-ontology-grid workspace-ontology-schema-only-grid" });
    const columnIds = this.showArchivedColumns
      ? [...(schema.columnOrder || []), ...(schema.archivedColumnOrder || [])]
      : [...(schema.columnOrder || [])];
    columnIds.forEach((columnId, index) => {
      const column = schema.columnsById?.[columnId];
      if (!column) return;
      const archived = (schema.archivedColumnOrder || []).includes(columnId);
      const cell = grid.createDiv({ cls: `workspace-ontology-header-cell ${archived ? "is-archived" : ""}` });
      const input = cell.createEl("input", { type: "text", attr: { "aria-label": `Schema-only 列名 ${index + 1}` } });
      input.value = sanitizeText(column.label, "未命名列");
      input.disabled = this.isReadOnly() || archived || sharedSchemaProjection;
      input.addEventListener("input", () => {
        if (!this.replaceDraftTextValue(column, "label", input.value)) return;
        column.updatedAt = nowString();
        schema.updatedAt = column.updatedAt;
        this.markDirty("修改共享 Schema 列名");
      });
      const tools = cell.createDiv({ cls: "workspace-ontology-cell-tools" });
      this.renderParadigmOntologyColumnDescriptionButton(tools, schema, column, {
        editable: !archived && !sharedSchemaProjection,
      });
      if (archived) {
        tools.createSpan({ cls: "workspace-ontology-archived-badge", text: "历史只读" });
      } else {
        const childSchemaId = sanitizeText(column.childSchemaId, "");
        if (childSchemaId) {
          const childBtn = tools.createEl("button", { attr: { type: "button", title: "进入下一级 Schema", "aria-label": "进入下一级 Schema" } });
          setIcon(childBtn, "panel-right-open");
          childBtn.onclick = () => this.navigateToSchemaOnly(childSchemaId);
        }
        const up = tools.createEl("button", { attr: { type: "button", title: "左移列", "aria-label": "左移列" } });
        setIcon(up, "arrow-left");
        up.disabled = this.isReadOnly() || sharedSchemaProjection || index === 0;
        up.onclick = () => { if (moveParadigmOntologyOrder(schema.columnOrder, columnId, -1)) { schema.updatedAt = nowString(); this.markDirty("移动共享 Schema 列"); this.renderEditor(); } };
        const down = tools.createEl("button", { attr: { type: "button", title: "右移列", "aria-label": "右移列" } });
        setIcon(down, "arrow-right");
        down.disabled = this.isReadOnly() || sharedSchemaProjection || index === schema.columnOrder.length - 1;
        down.onclick = () => { if (moveParadigmOntologyOrder(schema.columnOrder, columnId, 1)) { schema.updatedAt = nowString(); this.markDirty("移动共享 Schema 列"); this.renderEditor(); } };
        const archive = tools.createEl("button", { attr: { type: "button", title: "归档列", "aria-label": "归档列" } });
        setIcon(archive, "archive");
        archive.disabled = this.isReadOnly() || sharedSchemaProjection || schema.columnOrder.length <= 1;
        archive.onclick = () => { deleteParadigmOntologyColumn(this.draft, schema.id, columnId); this.markDirty("归档共享 Schema 列"); this.renderEditor(); };
      }
    });
  }

  getCorruptedSharedSchemaRecoveryCandidates() {
    return getParadigmOntologyCorruptedSharedSchemaRecoveryCandidates(this.draft, {
      didRestoreRecovery: this.didRestoreRecovery,
      failure: this.sharedSchemaRequiredFailure,
    });
  }

  async recoverCorruptedSharedSchemasAsLocal() {
    const candidates = this.getCorruptedSharedSchemaRecoveryCandidates();
    if (candidates.length === 0) return false;
    const rootSchemaIds = candidates.map((entry) => entry.rootSchemaId).sort();
    const frozenDraft = this.draft;
    const frozenGeneration = this.generation;
    const confirmed = await this.confirmFrozenDestructive({
      title: "将损坏的共享结构恢复为本地结构",
      message: "该恢复草稿中的共享结构地址已损坏，无法再确认正式来源。此操作会保留当前全部表格、内容、图片和稳定 ID，仅解除这组 Schema 的共享结构身份。正式数据此时不会改写；之后仍需另行点击“保存并关闭”。",
      confirmText: "保留并转为本地",
      cancelText: "取消",
      danger: true,
    }, () => {
      if (this.draft !== frozenDraft || this.generation !== frozenGeneration) return false;
      const currentIds = this.getCorruptedSharedSchemaRecoveryCandidates()
        .map((entry) => entry.rootSchemaId)
        .sort();
      return canonicalJsonString(currentIds) === canonicalJsonString(rootSchemaIds);
    });
    if (!confirmed) return false;

    const snapshot = deepClone(this.draft, null);
    const previousDirty = this.dirty;
    const previousRequiredFailure = this.sharedSchemaRequiredFailure;
    const previousSyncFailures = new Set(this.schemaLineageSyncFailures);
    try {
      rootSchemaIds.forEach((schemaId) => {
        stripParadigmOntologyActiveLineageGraph(this.draft, schemaId, {
          operationId: `${this.sessionId}:${this.generation}:corrupted-address-local-fork`,
          outcome: "forked-local",
          reason: "corrupted-recovery-schema-address",
        });
      });
      const validation = validateParadigmOntology(this.draft);
      if (!validation.ok) throw new Error(validation.errors[0] || "转为本地后的 Ontology 结构无效。");
      candidates.flatMap((entry) => entry.graphSchemaIds)
        .forEach((schemaId) => this.schemaLineageSyncFailures.delete(schemaId));
      this.sharedSchemaRequiredFailure = null;
      this.refreshDraftBytes();
      this.markDirty("损坏的共享结构已转为本地");
      await this.flushRecovery("corrupted-shared-schema-local-fork", { forceCurrentDraft: true });
      this.setStatus("当前结构已转为本地；正式数据尚未保存", "is-warning");
      this.renderRecoveryConflictControls();
      this.renderEditor();
      return true;
    } catch (error) {
      restoreParadigmOntologySnapshot(this.draft, snapshot);
      this.setParadigmOntologyDirtyState(previousDirty);
      this.sharedSchemaRequiredFailure = previousRequiredFailure;
      this.schemaLineageSyncFailures = previousSyncFailures;
      this.refreshDraftBytes();
      this.renderRecoveryConflictControls();
      this.renderEditor();
      throw error;
    }
  }

  async confirmFrozenDestructive(options, targetStillExists = () => true) {
    if (!this.canMutateParadigmOntologyAfterConfirmation() || this.guardPendingImageImports()) return false;
    const frozenHash = hashParadigmOntology(this.draft);
    const confirmed = await this.confirmAction(options);
    if (!confirmed) return false;
    if (!this.canMutateParadigmOntologyAfterConfirmation()) {
      new Notice("Ontology 已进入只读或关闭状态，当前操作已取消。");
      return false;
    }
    if (this.guardPendingImageImports()) return false;
    if (frozenHash !== hashParadigmOntology(this.draft)) {
      new Notice("Ontology 已变化，请重新执行当前操作。");
      return false;
    }
    if (!targetStillExists()) {
      new Notice("目标已经变化，请重新执行操作。");
      return false;
    }
    return true;
  }

  getRowRemovalImpact(table, row) {
    const nested = getParadigmOntologyRowNestedDataImpact(this.draft, table?.id, row?.id);
    return {
      tableCount: nested.tableCount,
      rowCount: 1 + nested.rowCount,
      cellCount: Object.keys(row?.cellsByColumnId || {}).length + nested.cellCount,
      branchCount: nested.branchCount,
      dataBranchCount: nested.dataBranchCount,
      dataCellCount: nested.dataCellCount,
      referenceCellCount: nested.referenceCellCount,
      directDataCellCount: Object.values(row?.cellsByColumnId || {})
        .filter((cell) => paradigmOntologyCellHasRetainedData(cell)).length,
      directReferenceCellCount: Object.values(row?.cellsByColumnId || {})
        .filter((cell) => isObjectLike(cell?.reference)).length,
      schemaLineageCount: nested.schemaLineageCount,
      maxDepth: nested.maxDepth,
      imageReferenceCount: Object.values(row?.cellsByColumnId || {})
        .reduce((count, cell) => count + parseParadigmOntologyImageEmbeds(cell?.value).length, 0),
    };
  }

  getColumnRemovalImpact(schema, columnId) {
    const impact = { tableCount: 0, rowCount: 0, cellCount: 0, descendantTableCount: 0, descendantRowCount: 0, descendantCellCount: 0, imageReferenceCount: 0, cellReferenceCount: 0, schemaLineageCount: 0 };
    const schemaTables = getParadigmOntologySchemaTables(this.draft, schema.id);
    impact.tableCount = schemaTables.length;
    schemaTables.forEach((table) => {
      impact.rowCount += table.rowOrder.length;
      impact.cellCount += table.rowOrder.length;
      table.rowOrder.forEach((rowId) => {
        const targetCell = table.rowsById?.[rowId]?.cellsByColumnId?.[columnId];
        impact.imageReferenceCount += parseParadigmOntologyImageEmbeds(targetCell?.value).length;
        if (isObjectLike(targetCell?.reference)) impact.cellReferenceCount += 1;
        const childTableId = sanitizeText(targetCell?.nestedTableId, "");
        if (!childTableId) return;
        const childImpact = getParadigmOntologySubtreeImpact(this.draft, childTableId);
        impact.descendantTableCount += childImpact.tableCount;
        impact.descendantRowCount += childImpact.rowCount;
        impact.descendantCellCount += childImpact.cellCount;
        impact.cellReferenceCount += childImpact.referenceCellCount;
        impact.schemaLineageCount += childImpact.schemaLineageCount;
      });
    });
    const nestedDataImpact = getParadigmOntologyColumnNestedDataImpact(this.draft, schema.id, columnId);
    impact.descendantBranchCount = nestedDataImpact.branchCount;
    impact.dataBranchCount = nestedDataImpact.dataBranchCount;
    impact.descendantDataCellCount = nestedDataImpact.dataCellCount;
    impact.cellReferenceCount = Math.max(impact.cellReferenceCount, nestedDataImpact.referenceCellCount);
    impact.schemaLineageCount = Math.max(impact.schemaLineageCount, nestedDataImpact.schemaLineageCount);
    return impact;
  }

  getSubtreeImageReferenceCount(tableId, visited = new Set()) {
    const id = sanitizeText(tableId, "");
    if (!id || visited.has(id)) return 0;
    visited.add(id);
    const table = this.draft?.tablesById?.[id];
    if (!table) return 0;
    let count = 0;
    table.rowOrder.forEach((rowId) => {
      Object.values(table.rowsById?.[rowId]?.cellsByColumnId || {}).forEach((cell) => {
        count += parseParadigmOntologyImageEmbeds(cell?.value).length;
        const childTableId = sanitizeText(cell?.nestedTableId, "");
        if (childTableId) count += this.getSubtreeImageReferenceCount(childTableId, visited);
      });
    });
    return count;
  }

  async deleteNestedTableFromUi(tableId) {
    if (this.guardPendingImageImports()) return;
    const id = sanitizeText(tableId, "");
    if (this.isParadigmOntologyTableInArchivedBranch(id)) {
      new Notice("归档历史分支中的子表只能查看，不能删除。");
      return;
    }
    const impact = getParadigmOntologySubtreeImpact(this.draft, id);
    const imageReferenceCount = this.getSubtreeImageReferenceCount(id);
    const table = this.draft?.tablesById?.[id];
    if (!table || id === this.draft.rootTableId) return;
    const confirmed = await this.confirmFrozenDestructive({
      title: "删除 Ontology 子表",
      message: `将删除当前子表及全部下层内容。\n表格：${impact.tableCount}\n行：${impact.rowCount}\n单元格：${impact.cellCount}\n内容引用：${impact.referenceCellCount}\nschema lineage：${impact.schemaLineageCount}\n图片引用：${imageReferenceCount}（仅移除引用，不删除附件文件）\n父格文字和父列保留的 schema lineage 不会删除。`,
      confirmText: "删除子表",
      danger: true,
    }, () => Boolean(this.draft?.tablesById?.[id]));
    if (!confirmed || !this.draft?.tablesById?.[id]) return;
    try {
      const result = deleteParadigmOntologyNestedTable(this.draft, id);
      if (this.currentTableId === id || !getParadigmOntologyNavigationPath(this.draft, this.currentTableId).ok) {
        this.currentTableId = result.parentTableId;
      }
      this.markDirty("删除子表");
      this.renderEditor();
    } catch (error) {
      new Notice(error.message);
    }
  }

  async reconcileSharedSchemas(options = {}) {
    const required = options.required === true;
    if (this.schemaLineageSyncPromise) {
      const pendingResult = await this.schemaLineageSyncPromise;
      if (pendingResult?.cancelled === true && !this.finalClosing) {
        return await this.reconcileSharedSchemas(options);
      }
      if (required && pendingResult?.ok !== true) {
        throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_FAILED", "共享结构自动同步未完成，已阻止保存旧投影。");
      }
      return pendingResult;
    }
    const shouldRender = options.render === true;
    const partition = this.getSharedSchemaPartition();
    partition.pendingDetachRoots.forEach((entry) => {
      entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.delete(schemaId));
    });
    if (partition.invalidOrphanRoots.length > 0) {
      const aggregateReasons = partition.invalidOrphanRoots.flatMap((entry) => entry.reasons.map((reason) => ({
        schemaId: entry.rootSchemaId,
        stage: "partition",
        code: reason.code,
        message: reason.message,
        pendingDetach: false,
        blockSave: true,
      })));
      partition.invalidOrphanRoots.forEach((entry) => {
        entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.add(schemaId));
        this.logSharedSchemaRejection(entry, {
          stage: "partition",
          code: entry.reasons[0]?.code,
          message: entry.reasons[0]?.message,
          aggregateReasons,
        });
      });
      const error = createParadigmOntologyContractError(
        "ONTOLOGY_SHARED_SCHEMA_GRAPH_INVALID",
        "共享结构关系不完整，已阻止保存。请根据 Console 诊断核查来源和父列。",
        { aggregateReasons },
      );
      if (required) throw error;
    }
    const targets = partition.activeRoots;
    if (targets.length === 0) {
      if (partition.invalidOrphanRoots.length === 0) {
        this.sharedSchemaRequiredFailure = null;
        this.renderRecoveryConflictControls();
      }
      return {
        ok: partition.invalidOrphanRoots.length === 0,
        changed: false,
        reconciled: 0,
        pendingDetach: partition.pendingDetachRoots.length,
      };
    }
    if (typeof this.referenceAdapter?.syncSchemaLineage !== "function") {
      const error = createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_UNAVAILABLE", "共享结构来源当前不可解析，已阻止把旧投影保存为正式结构。");
      const aggregateReasons = targets.map((entry) => ({
        schemaId: entry.rootSchemaId,
        stage: "reconcile",
        code: error.code,
        message: error.message,
        pendingDetach: false,
        blockSave: true,
      }));
      targets.forEach((entry) => {
        entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.add(schemaId));
        this.logSharedSchemaRejection(entry, { stage: "reconcile", error, aggregateReasons });
      });
      if (required) throw error;
      return { ok: false, changed: false, reconciled: 0, error };
    }
    const asyncToken = this.createSharedSchemaAsyncToken();
    const promise = (async () => {
      const beforeHash = hashParadigmOntology(this.draft);
      let reconciled = 0;
      const rejectionReasons = [];
      let requiredError = null;
      for (const entry of targets) {
        const schema = this.draft?.schemasById?.[entry.rootSchemaId];
        try {
          const lineage = this.draft?.schemasById?.[schema.id]?.sourceLineage;
          if (!isObjectLike(lineage?.sourceSchemaAddress)) continue;
          const result = await this.referenceAdapter.syncSchemaLineage({
            sourceSchemaAddress: deepClone(lineage.sourceSchemaAddress, null),
            localSchemaAddress: this.buildParadigmOntologySchemaAddress(schema.id),
            ontologyHash: hashParadigmOntology(this.draft),
            modalGeneration: this.generation,
          });
          if (!this.isSharedSchemaAsyncTokenCurrent(asyncToken)) {
            return { ok: false, changed: false, reconciled, cancelled: true };
          }
          if (!isObjectLike(result?.sourceProjection)) {
            throw createParadigmOntologyContractError("ONTOLOGY_SCHEMA_RECONCILE_INVALID", "共享结构来源未返回完整递归投影。");
          }
          const sourceRevision = sanitizeText(result.authorityRevision, "");
          const sourceHash = hashCanonicalJson(result.sourceProjection);
          const localDiverged = paradigmOntologyLineageGraphHasLegacyDivergence(this.draft, schema.id);
          if (!localDiverged
            && sanitizeText(lineage.sourceRevision, "") === sourceRevision
            && sanitizeText(lineage.sourceHash, "") === sourceHash) {
            entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.delete(schemaId));
            continue;
          }
          reconcileParadigmOntologySchemaLineageMirror(
            this.draft,
            schema.id,
            result.sourceProjection,
            result.canonicalAddress || lineage.sourceSchemaAddress,
            {
              sourceRevision,
              sourceHash,
            },
          );
          entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.delete(schemaId));
          reconciled += 1;
        } catch (error) {
          entry.graphSchemaIds.forEach((schemaId) => this.schemaLineageSyncFailures.add(schemaId));
          const reason = {
            schemaId: entry.rootSchemaId,
            stage: "reconcile",
            code: sanitizeText(error?.code, "ONTOLOGY_SCHEMA_RECONCILE_FAILED"),
            message: error?.message || String(error),
            pendingDetach: false,
            blockSave: true,
          };
          rejectionReasons.push(reason);
          this.logSharedSchemaRejection(entry, { stage: "reconcile", error, aggregateReasons: rejectionReasons });
          if (required) {
            requiredError = error;
            break;
          }
        }
      }
      if (!this.isSharedSchemaAsyncTokenCurrent(asyncToken)) {
        return { ok: false, changed: false, reconciled, cancelled: true };
      }
      if (rejectionReasons.length > 0) {
        console.error("[Workspace Mount][ontology.shared-schema-rejected]", {
          schemaId: null,
          graphSchemaIds: [],
          sourceAddress: targets.map((entry) => deepClone(entry.schema?.sourceLineage?.sourceSchemaAddress, null)),
          targetAddress: targets.map((entry) => {
            try { return this.buildParadigmOntologySchemaAddress(entry.rootSchemaId); } catch (_) { return null; }
          }),
          stage: "reconcile-summary",
          code: "ONTOLOGY_SCHEMA_RECONCILE_AGGREGATE",
          message: `${rejectionReasons.length} 个共享结构未通过同步。`,
          pendingDetach: false,
          blockSave: required,
          aggregateReasons: rejectionReasons,
          ownerPluginId: this.ownerPluginId,
          ownerKey: this.externalOwnerKey || this.paradigmItemId,
          modalGeneration: this.generation,
        });
      }
      if (requiredError) throw requiredError;
      const changed = hashParadigmOntology(this.draft) !== beforeHash;
      if (changed) {
        this.markDirty("自动同步共享结构");
        if (shouldRender && !this.finalClosing) this.renderEditor();
      }
      if (this.schemaLineageSyncFailures.size > 0) {
        this.setStatus("共享结构存在同步冲突，保存前必须解决", "is-warning");
      } else {
        this.sharedSchemaRequiredFailure = null;
        this.renderRecoveryConflictControls();
      }
      return { ok: this.schemaLineageSyncFailures.size === 0, changed, reconciled };
    })();
    this.schemaLineageSyncPromise = promise;
    try {
      return await promise;
    } finally {
      if (this.schemaLineageSyncPromise === promise) this.schemaLineageSyncPromise = null;
    }
  }

  renderParadigmOntologySchemaLineage(host, schema) {
    const lineage = schema?.sourceLineage;
    if (!isObjectLike(lineage)) return;
    const graphEntry = this.getSharedSchemaGraphEntry(schema.id);
    const pendingDetach = graphEntry?.pendingDetach === true;
    const strip = host.createDiv({ cls: "workspace-ontology-lineage-strip" });
    const state = sanitizeText(lineage.state, "active");
    strip.createSpan({
      cls: `workspace-ontology-lineage-badge is-${pendingDetach ? "pending-detach" : state}`,
      text: pendingDetach ? "待解除" : "共享结构",
    });
    strip.createSpan({
      cls: "workspace-ontology-lineage-label",
      text: pendingDetach
        ? "保存后转为本地结构或清空"
        : sanitizeText(lineage.sourceLabel, lineage.sourceSchemaAddress?.schemaId || "来源 schema"),
    });
    const mappingCount = Array.isArray(lineage.mappingOrder) ? lineage.mappingOrder.length : 0;
    strip.createSpan({
      cls: "workspace-ontology-lineage-meta",
      text: pendingDetach ? `${mappingCount} 列映射 · B 将恢复本地自治` : `${mappingCount} 列映射 · A 为结构 owner`,
    });
    if (!pendingDetach && typeof this.referenceAdapter?.openSchema === "function") {
      const openBtn = strip.createEl("button", { attr: { type: "button", title: "编辑共享结构", "aria-label": "编辑共享结构" } });
      setIcon(openBtn, "external-link");
      openBtn.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        void Promise.resolve(this.referenceAdapter.openSchema({
          sourceSchemaAddress: deepClone(lineage.sourceSchemaAddress, null),
          localSchemaAddress: this.buildParadigmOntologySchemaAddress(schema.id),
          modalGeneration: this.generation,
        })).catch((error) => new Notice(error?.message || "无法打开来源 schema。"));
      };
    }
    const needsManualRecovery = this.schemaLineageSyncFailures.has(schema.id) || ["stale", "conflict"].includes(state);
    if (!pendingDetach && typeof this.referenceAdapter?.syncSchemaLineage === "function" && state !== "archived" && needsManualRecovery) {
      const syncBtn = strip.createEl("button", { attr: { type: "button", title: "解决共享结构版本冲突", "aria-label": "同步共享结构" } });
      setIcon(syncBtn, "refresh-cw");
      syncBtn.disabled = this.isReadOnly() || this.recoveryConflict;
      syncBtn.onclick = async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const asyncToken = this.createSharedSchemaAsyncToken();
        try {
          const result = await this.referenceAdapter.syncSchemaLineage({
            sourceSchemaAddress: deepClone(lineage.sourceSchemaAddress, null),
            localSchemaAddress: this.buildParadigmOntologySchemaAddress(schema.id),
            ontology: deepClone(this.draft, null),
            ontologyHash: hashParadigmOntology(this.draft),
            modalGeneration: this.generation,
          });
          if (!this.isSharedSchemaAsyncTokenCurrent(asyncToken)) return;
          if (isObjectLike(result?.sourceProjection)) {
            const reconciled = deepClone(this.draft, null);
            reconcileParadigmOntologySchemaLineageMirror(
              reconciled,
              schema.id,
              result.sourceProjection,
              result.canonicalAddress || lineage.sourceSchemaAddress,
              {
                sourceRevision: sanitizeText(result.authorityRevision, ""),
                sourceHash: hashCanonicalJson(result.sourceProjection),
              },
            );
            const validation = validateParadigmOntology(reconciled);
            if (!validation.ok) throw new Error(validation.errors[0] || "同步结果无效。");
            this.draft = reconciled;
            (graphEntry?.graphSchemaIds || [schema.id]).forEach((schemaId) => this.schemaLineageSyncFailures.delete(schemaId));
            this.sharedSchemaRequiredFailure = null;
            this.markDirty("同步共享结构");
            this.renderRecoveryConflictControls();
            this.renderEditor();
          } else if (sanitizeText(result?.message, "")) {
            new Notice(result.message);
          }
        } catch (error) {
          this.logSharedSchemaRejection(graphEntry || {
            rootSchemaId: schema.id,
            schema,
            graphSchemaIds: [schema.id],
            parentColumns: [],
            pendingDetach: false,
          }, { stage: "manual-refresh", error, blockSave: true });
          new Notice(error?.message || "来源结构同步失败。");
        }
      };
    }
  }

  renderParadigmOntologyTargetReference(host, cellRef, reference) {
    const strip = host.createDiv({ cls: "workspace-ontology-reference-strip is-target" });
    const label = strip.createDiv({ cls: "workspace-ontology-reference-main" });
    setIcon(label.createSpan({ cls: "workspace-ontology-reference-icon" }), "quote");
    label.createSpan({ text: "引用自", cls: "workspace-ontology-reference-kicker" });
    const sourceLabel = label.createSpan({
      text: sanitizeText(reference.sourceBreadcrumb, sanitizeText(reference.sourceLabel, "来源单元格")),
      cls: "workspace-ontology-reference-label",
    });
    const stateBadge = label.createSpan({ text: "读取中", cls: "workspace-ontology-reference-state is-loading" });
    const projection = strip.createDiv({ cls: "workspace-ontology-reference-projection", text: "正在读取来源的已提交内容..." });
    const actions = strip.createDiv({ cls: "workspace-ontology-reference-actions" });
    if (typeof this.referenceAdapter?.openCell === "function") {
      const openBtn = actions.createEl("button", { attr: { type: "button", title: "打开来源单元格", "aria-label": "打开来源单元格" } });
      setIcon(openBtn, "external-link");
      openBtn.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        void Promise.resolve(this.referenceAdapter.openCell({
          address: deepClone(reference.sourceAddress, null),
          relationRole: "source",
          modalGeneration: this.generation,
        })).catch((error) => new Notice(error?.message || "无法打开引用来源。"));
      };
    }
    const unlinkBtn = actions.createEl("button", { attr: { type: "button", title: "解除内容引用", "aria-label": "解除内容引用" } });
    setIcon(unlinkBtn, "unlink");
    unlinkBtn.disabled = this.isReadOnly() || this.recoveryConflict || this.isParadigmOntologyCellMutationBlocked(cellRef);
    unlinkBtn.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      void this.unlinkParadigmOntologyCellReferenceFromUi(cellRef);
    };
    if (typeof this.referenceAdapter?.resolveReference !== "function") {
      stateBadge.textContent = "待连接 Hub";
      stateBadge.className = "workspace-ontology-reference-state is-broken";
      projection.textContent = "引用地址已保留；当前 Hub 不可用，来源内容不会被自动删除。";
      return;
    }
    const uiGeneration = this.referenceUiGeneration;
    const frozenKey = this.getParadigmOntologyCellRefKey(cellRef);
    Promise.resolve(this.referenceAdapter.resolveReference(this.getParadigmOntologyReferenceCallbackPayload(cellRef, {
      reference: deepClone(reference, null),
    }))).then((result) => {
      if (uiGeneration !== this.referenceUiGeneration || !strip.isConnected) return;
      const current = this.resolveParadigmOntologyCell(cellRef);
      if (!current || !isObjectLike(current.cell.reference)) return;
      const state = sanitizeText(result?.state, result?.ok === false ? "broken" : "live");
      stateBadge.textContent = sanitizeText(result?.stateLabel, state === "live" ? "实时" : (state === "historical" ? "历史" : "失联"));
      stateBadge.className = `workspace-ontology-reference-state is-${state}`;
      sourceLabel.textContent = sanitizeText(result?.sourceBreadcrumb, sanitizeText(result?.sourceLabel, sourceLabel.textContent));
      const previewText = sanitizeText(result?.previewText || result?.textPreview, "");
      const imageCount = Math.max(0, Number(result?.imageCount) || 0);
      const nestedTableCount = Math.max(0, Number(result?.nestedTableCount) || 0);
      const meta = [imageCount > 0 ? `${imageCount} 张图片` : "", nestedTableCount > 0 ? `${nestedTableCount} 个递归表` : ""].filter(Boolean).join(" · ");
      const brokenReason = state === "broken"
        ? sanitizeText(result?.message, sanitizeText(result?.reason, "来源当前不可用；引用地址已保留。"))
        : "";
      projection.textContent = [brokenReason || previewText || "来源当前没有文字内容", meta].filter(Boolean).join("\n");
      projection.setAttribute("data-cell-key", frozenKey);
    }).catch((error) => {
      if (uiGeneration !== this.referenceUiGeneration || !strip.isConnected) return;
      stateBadge.textContent = "失联";
      stateBadge.className = "workspace-ontology-reference-state is-broken";
      projection.textContent = error?.message || "来源当前不可用；引用地址已保留。";
    });
  }

  renderParadigmOntologyInboundReferences(host, cellRef) {
    if (typeof this.referenceAdapter?.getInboundReferences !== "function") return;
    const address = this.buildParadigmOntologyCellAddress(cellRef);
    if (!address) return;
    const uiGeneration = this.referenceUiGeneration;
    const shell = host.createDiv({ cls: "workspace-ontology-inbound-shell is-loading" });
    Promise.resolve(this.referenceAdapter.getInboundReferences(this.getParadigmOntologyReferenceCallbackPayload(cellRef)))
      .then((result) => {
        if (uiGeneration !== this.referenceUiGeneration || !shell.isConnected) return;
        shell.empty();
        shell.className = "workspace-ontology-inbound-shell";
        const items = Array.isArray(result?.items) ? result.items : [];
        const count = Math.max(items.length, Number(result?.count) || 0);
        if (count <= 0 && result?.complete !== false) {
          shell.remove();
          this.refreshParadigmOntologyRelationsVisibility(host);
          return;
        }
        const complete = result?.complete === true && result?.truncated !== true;
        const details = shell.createEl("details", { cls: `workspace-ontology-inbound-details ${complete ? "is-complete" : "is-incomplete"}` });
        details.createEl("summary", {
          text: complete
            ? `被引用 ${count} 处`
            : (count > 0 ? `至少 ${count} 处引用 / 索引尚未完整验证` : "未发现引用 / 索引尚未完整验证"),
        });
        const list = details.createDiv({ cls: "workspace-ontology-inbound-list" });
        items.slice(0, 50).forEach((item) => {
          const row = list.createDiv({ cls: "workspace-ontology-inbound-item" });
          const textWrap = row.createDiv();
          textWrap.createDiv({ cls: "workspace-ontology-inbound-label", text: sanitizeText(item?.label, "引用位置") });
          const inboundMeta = sanitizeText(item?.breadcrumb, "");
          if (inboundMeta) textWrap.createDiv({ cls: "workspace-ontology-inbound-meta", text: inboundMeta });
          if (item?.address && typeof this.referenceAdapter?.openCell === "function") {
            const openBtn = row.createEl("button", { attr: { type: "button", title: "打开引用位置", "aria-label": "打开引用位置" } });
            setIcon(openBtn, "external-link");
            openBtn.onclick = (event) => {
              event.preventDefault();
              event.stopPropagation();
              void Promise.resolve(this.referenceAdapter.openCell({
                address: deepClone(item.address, null),
                relationRole: "target",
                modalGeneration: this.generation,
              })).catch((error) => new Notice(error?.message || "无法打开引用位置。"));
            };
          }
        });
        if (!complete) {
          const reasons = Array.isArray(result?.reasons) ? result.reasons.slice(0, 8) : [];
          const diagnostics = list.createDiv({ cls: "workspace-ontology-inbound-diagnostics" });
          if (reasons.length === 0) diagnostics.textContent = "至少一个引用提供方尚未完成验证。";
          reasons.forEach((reason) => {
            const providerId = sanitizeText(reason?.providerId, "引用提供方");
            const message = sanitizeText(reason?.message, sanitizeText(reason?.code, "验证未完成"));
            diagnostics.createDiv({ text: `${providerId}: ${message}` });
          });
        }
      }).catch(() => {
        if (uiGeneration !== this.referenceUiGeneration || !shell.isConnected) return;
        shell.className = "workspace-ontology-inbound-shell is-incomplete";
        shell.textContent = "反向引用索引不可用";
      });
  }

  renderParadigmOntologyCellRelations(host, cellRef, cell) {
    const relations = host.createDiv({ cls: "workspace-ontology-cell-relations" });
    if (isObjectLike(cell?.reference)) this.renderParadigmOntologyTargetReference(relations, cellRef, cell.reference);
    this.renderParadigmOntologyInboundReferences(relations, cellRef);
    if (typeof this.referenceAdapter?.captureCell === "function") {
      const captureBtn = relations.createEl("button", {
        cls: "workspace-ontology-capture-cell",
        attr: { type: "button", title: "在 Meta 模式中选择此单元格", "aria-label": "选择 Ontology 单元格" },
      });
      setIcon(captureBtn, "mouse-pointer-2");
      const captureState = this.referenceCaptureState || this.readParadigmOntologyCaptureState();
      const captureAddress = this.buildParadigmOntologyCellAddress(cellRef);
      const captureAddressKey = captureAddress ? serializeParadigmOntologyAddress(captureAddress) : "";
      captureBtn.setAttribute("data-ontology-address-key", captureAddressKey);
      let captureSourceKey = "";
      try {
        captureSourceKey = captureState?.source?.address
          ? serializeParadigmOntologyAddress(captureState.source.address)
          : sanitizeText(captureState?.sourceKey, "");
      } catch (_) {
        captureSourceKey = "";
      }
      captureBtn.classList.toggle("is-active", captureState?.active === true);
      captureBtn.classList.toggle("is-source", captureState?.active === true && Boolean(captureAddressKey) && captureSourceKey === captureAddressKey);
      captureBtn.hidden = captureState?.active !== true;
      captureBtn.disabled = this.isReadOnly() && sanitizeText(captureState?.phase, "source") === "target";
      captureBtn.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        void this.captureParadigmOntologyCellFromUi(cellRef);
      };
    }
    if (relations.children.length === 0) relations.remove();
    else this.refreshParadigmOntologyRelationsVisibility(relations);
  }

  consumePendingParadigmOntologyCellFocus() {
    const focus = this.pendingCellFocus;
    if (!focus) return;
    if (sanitizeText(focus.documentId, "") && sanitizeText(focus.documentId, "") !== sanitizeText(this.draft?.documentId, "")) {
      this.pendingCellFocus = null;
      return;
    }
    const ref = this.getParadigmOntologyCellRef(focus.tableId, focus.rowId, focus.columnId);
    const key = this.getParadigmOntologyCellRefKey(ref);
    const target = this.cellElementsByKey.get(key);
    if (!target) return;
    this.pendingCellFocus = null;
    this.clearParadigmOntologyCellFocusTimers();
    target.wrap.addClass("is-focus-pending");
    target.wrap.addClass("is-jump-highlight");
    target.wrap.scrollIntoView?.({ behavior: "smooth", block: "center", inline: "center" });
    this.scheduleParadigmOntologyCellFocusTimer(() => {
      target.textarea?.focus?.();
      target.wrap.removeClass?.("is-focus-pending");
    }, 120);
    this.scheduleParadigmOntologyCellFocusTimer(() => {
      target.wrap.removeClass?.("is-jump-highlight");
    }, 2400);
  }

  scheduleParadigmOntologyCellFocusTimer(callback, delayMs) {
    const timer = window.setTimeout(() => {
      this.cellFocusTimers.delete(timer);
      callback();
    }, delayMs);
    this.cellFocusTimers.add(timer);
    return timer;
  }

  clearParadigmOntologyCellFocusTimers() {
    this.cellFocusTimers.forEach((timer) => window.clearTimeout(timer));
    this.cellFocusTimers.clear();
    this.cellElementsByKey.forEach((cell) => {
      cell?.wrap?.removeClass?.("is-focus-pending");
      cell?.wrap?.removeClass?.("is-jump-highlight");
    });
  }

  renderEditor() {
    if (this.surfaceMode === "tree") return;
    if (!this.editorEl) return;
    this.referenceUiGeneration += 1;
    this.cellElementsByKey.clear();
    this.editorEl.empty();
    const { schema, table, path, navigationError, archivedBranchReadOnly } = this.getCurrentTableContext();
    if (this.schemaOnlySchemaId && schema) {
      this.renderSchemaOnlyEditor(schema, path);
      this.refreshParadigmOntologyAlbums();
      return;
    }
    if (!schema || !table) {
      this.editorEl.createDiv({ text: navigationError || "表格结构不可用。", cls: "workspace-ontology-error" });
      this.refreshParadigmOntologyAlbums();
      return;
    }
    this.refreshDraftBytes();
    this.structureMutationButtons.forEach((button) => {
      button.disabled = this.isReadOnly() || archivedBranchReadOnly;
    });
    const sharedSchemaProjection = paradigmOntologySchemaHasRetainedLineage(schema);
    this.schemaMutationButtons.forEach((button) => {
      button.disabled = this.isReadOnly() || archivedBranchReadOnly || sharedSchemaProjection;
    });
    const nav = this.editorEl.createDiv({ cls: "workspace-ontology-navigation" });
    const backBtn = nav.createEl("button", {
      cls: "workspace-ontology-back",
      attr: { type: "button", title: "返回上一级", "aria-label": "返回上一级" },
    });
    setIcon(backBtn, "arrow-left");
    backBtn.disabled = path.length <= 1;
    backBtn.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const parentEntry = path[path.length - 2];
      if (parentEntry) this.navigateToTable(parentEntry.tableId);
    };
    const breadcrumbs = nav.createDiv({ cls: "workspace-ontology-breadcrumbs" });
    path.forEach((entry, index) => {
      if (index > 0) {
        const separator = breadcrumbs.createSpan({ cls: "workspace-ontology-breadcrumb-separator" });
        setIcon(separator, "chevron-right");
      }
      const crumb = breadcrumbs.createEl("button", {
        text: entry.label,
        cls: index === path.length - 1 ? "is-current" : "",
        attr: { type: "button", title: entry.label },
      });
      crumb.disabled = index === path.length - 1;
      crumb.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.navigateToTable(entry.tableId);
      };
    });
    const schemaTableCount = getParadigmOntologySchemaTables(this.draft, schema.id).length;
    nav.createDiv({
      cls: "workspace-ontology-schema-scope",
      text: `结构共享 ${schemaTableCount} 个实例 · 内容独立`,
    });
    this.renderParadigmOntologySchemaLineage(nav, schema);
    if (table.id !== this.draft.rootTableId) {
      const deleteCurrentBtn = nav.createEl("button", {
        cls: "workspace-ontology-delete-current",
        attr: { type: "button", title: "删除当前子表", "aria-label": "删除当前子表" },
      });
      setIcon(deleteCurrentBtn, "trash-2");
      deleteCurrentBtn.disabled = this.isReadOnly() || archivedBranchReadOnly;
      deleteCurrentBtn.onclick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        void this.deleteNestedTableFromUi(table.id);
      };
    }
    const activeColumnIds = Array.isArray(schema.columnOrder) ? schema.columnOrder : [];
    const archivedColumnIds = Array.isArray(schema.archivedColumnOrder) ? schema.archivedColumnOrder : [];
    const columnIds = this.showArchivedColumns
      ? getParadigmOntologySchemaColumnIds(schema, true)
      : [...activeColumnIds];
    const gridTemplate = `${columnIds.map(() => "minmax(220px, 1fr)").join(" ")} 112px`;
    const scroll = this.editorEl.createDiv({ cls: "workspace-ontology-scroll" });
    const tableEl = scroll.createDiv({ cls: "workspace-ontology-table" });
    tableEl.style.minWidth = `${Math.max(820, columnIds.length * 220 + 112)}px`;
    const header = tableEl.createDiv({ cls: "workspace-ontology-grid workspace-ontology-grid-header" });
    header.style.gridTemplateColumns = gridTemplate;
    columnIds.forEach((columnId, columnIndex) => {
      const column = schema.columnsById[columnId];
      const cell = header.createDiv({ cls: "workspace-ontology-header-cell" });
      const isArchivedColumn = archivedColumnIds.includes(columnId);
      cell.classList.toggle("is-archived-history", isArchivedColumn);
      const input = cell.createEl("input", {
        type: "text",
        cls: "workspace-ontology-column-name",
        attr: { "aria-label": `列名 ${columnIndex + 1}` },
      });
      input.value = sanitizeText(column?.label, "未命名列");
      input.disabled = this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || sharedSchemaProjection;
      input.addEventListener("input", () => {
        const previous = String(column.label || "");
        if (!this.replaceDraftTextValue(column, "label", input.value)) {
          input.value = previous;
          return;
        }
        column.updatedAt = nowString();
        schema.updatedAt = column.updatedAt;
        this.markDirty("修改列名");
      });
      const childSchemaId = sanitizeText(column?.childSchemaId, "");
      const childSchema = this.draft?.schemasById?.[childSchemaId];
      if (paradigmOntologySchemaHasRetainedLineage(childSchema)) {
        this.renderParadigmOntologySchemaLineage(cell, childSchema);
      }
      const tools = cell.createDiv({ cls: "workspace-ontology-cell-tools" });
      this.renderParadigmOntologyColumnDescriptionButton(tools, schema, column, {
        editable: !isArchivedColumn && !archivedBranchReadOnly && !sharedSchemaProjection,
      });
      if (isArchivedColumn) {
        tools.createSpan({ cls: "workspace-ontology-archived-badge", text: "历史只读" });
        return;
      }
      const makeTool = (icon, title, handler, disabled = false) => {
        const button = tools.createEl("button", { attr: { type: "button", title, "aria-label": title } });
        setIcon(button, icon);
        button.disabled = disabled || this.isReadOnly() || archivedBranchReadOnly || sharedSchemaProjection;
        button.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          handler();
        };
        return button;
      };
      makeTool("arrow-left", "左移此列", () => {
        if (moveParadigmOntologyOrder(schema.columnOrder, columnId, -1)) {
          schema.updatedAt = nowString();
          this.markDirty("移动列");
          this.renderEditor();
        }
      }, columnIndex === 0);
      makeTool("arrow-right", "右移此列", () => {
        if (moveParadigmOntologyOrder(schema.columnOrder, columnId, 1)) {
          schema.updatedAt = nowString();
          this.markDirty("移动列");
          this.renderEditor();
        }
      }, columnIndex === columnIds.length - 1);
      makeTool("archive", "归档并隐藏此列", async () => {
        let impact;
        try {
          impact = this.getColumnRemovalImpact(schema, columnId);
        } catch (error) {
          new Notice(error.message);
          return;
        }
        const confirmed = await this.confirmFrozenDestructive({
          title: "归档 Ontology 列",
          message: `列：${sanitizeText(column?.label, columnId)}\n共享结构实例：${impact.tableCount}\n直接单元格：${impact.cellCount}\n内容引用：${impact.cellReferenceCount}\nschema lineage：${impact.schemaLineageCount}\n图片引用：${impact.imageReferenceCount}\n下层表格：${impact.descendantTableCount}\n\n归档只会隐藏该列，稳定 ID、文字、内容引用、图片引用、schema lineage 和全部递归子表都会保留，可从“恢复列”重新显示。`,
          confirmText: "归档并隐藏",
        }, () => Boolean(this.draft?.schemasById?.[schema.id]?.columnsById?.[columnId]));
        if (!confirmed || !this.draft?.schemasById?.[schema.id]?.columnsById?.[columnId]) return;
        try {
          deleteParadigmOntologyColumn(this.draft, schema.id, columnId);
          this.markDirty("归档列");
          this.renderEditor();
        } catch (error) {
          new Notice(error.message);
        }
      }, columnIds.length <= 1);
    });
    header.createDiv({ cls: "workspace-ontology-row-actions-label", text: "行操作" });

    if (table.rowOrder.length === 0) {
      const empty = tableEl.createDiv({ cls: "workspace-ontology-empty", text: "当前没有步骤。使用下方“新增行”继续。" });
      empty.style.gridColumn = `1 / span ${columnIds.length + 1}`;
    }
    table.rowOrder.forEach((rowId, rowIndex) => {
      const row = table.rowsById[rowId];
      const rowEl = tableEl.createDiv({ cls: "workspace-ontology-grid workspace-ontology-grid-row" });
      rowEl.style.gridTemplateColumns = gridTemplate;
      columnIds.forEach((columnId) => {
        const isArchivedColumn = archivedColumnIds.includes(columnId);
        const cell = row?.cellsByColumnId?.[columnId];
        const cellRef = this.getParadigmOntologyCellRef(table.id, rowId, columnId);
        const cellRefKey = this.getParadigmOntologyCellRefKey(cellRef);
        const nestedTableId = sanitizeText(cell?.nestedTableId, "");
        const wrap = rowEl.createDiv({ cls: "workspace-ontology-value-cell" });
        wrap.classList.toggle("is-archived-history", isArchivedColumn);
        wrap.classList.toggle("is-image-importing", this.pendingImageCellKeys.has(cellRefKey));
        wrap.classList.toggle("has-nested-table", Boolean(nestedTableId));
        wrap.classList.toggle("has-cell-reference", isObjectLike(cell?.reference));
        wrap.setAttribute("data-ontology-cell-key", cellRefKey);
        wrap.addEventListener("pointerdown", (event) => this.handleParadigmOntologyRangeCellPointerDown(event, cellRef, wrap));
        wrap.addEventListener("pointerenter", (event) => this.handleParadigmOntologyRangeCellPointerEnter(event, cellRef));
        const textarea = wrap.createEl("textarea", {
          cls: "workspace-ontology-value-input",
          attr: { "aria-label": `${sanitizeText(schema.columnsById?.[columnId]?.label, columnId)} 第 ${rowIndex + 1} 行` },
        });
        textarea.value = stripParadigmOntologyImageEmbeds(cell?.value);
        textarea.disabled = this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || this.pendingImageCellKeys.has(cellRefKey);
        const resizeTextarea = () => {
          textarea.style.height = "auto";
          textarea.style.height = `${Math.max(78, textarea.scrollHeight + 2)}px`;
        };
        textarea.addEventListener("input", () => {
          const current = this.resolveParadigmOntologyCell(cellRef);
          if (!current) {
            textarea.disabled = true;
            return;
          }
          const canonicalValue = String(current.cell.value || "");
          const currentTokens = parseParadigmOntologyImageEmbeds(canonicalValue).map((record) => record.token);
          const typedValue = String(textarea.value || "");
          const typedTokens = parseParadigmOntologyImageEmbeds(typedValue).map((record) => record.token);
          const visibleValue = stripParadigmOntologyImageEmbeds(typedValue);
          const lineBreak = getParadigmOntologyLineBreak(canonicalValue, getParadigmOntologyLineBreak(typedValue));
          const nextValue = composeParadigmOntologyCellValue(visibleValue, [...currentTokens, ...typedTokens], lineBreak);
          if (!this.replaceDraftTextValue(current.cell, "value", nextValue)) {
            textarea.value = stripParadigmOntologyImageEmbeds(current.cell.value);
            resizeTextarea();
            return;
          }
          textarea.value = visibleValue;
          current.row.updatedAt = nowString();
          current.table.updatedAt = current.row.updatedAt;
          this.markDirty("编辑单元格");
          renderCellImages();
          resizeTextarea();
        });
        textarea.addEventListener("paste", (event) => {
          this.handleParadigmOntologyClipboardPaste(event, cellRef);
        });
        window.setTimeout(resizeTextarea, 0);
        this.cellElementsByKey.set(cellRefKey, { wrap, textarea });
        this.renderParadigmOntologyCellRelations(wrap, cellRef, cell);
        const cellFooter = wrap.createDiv({ cls: "workspace-ontology-cell-footer" });
        const nestedActions = cellFooter.createDiv({ cls: "workspace-ontology-nested-actions" });
        const imageProjection = cellFooter.createDiv({ cls: "workspace-ontology-image-projection" });
        const renderCellImages = () => {
          imageProjection.empty();
          this.renderParadigmOntologyCellImages(imageProjection, cellRef, wrap);
        };
        renderCellImages();
        const imageActions = cellFooter.createDiv({ cls: "workspace-ontology-image-actions" });
        const imageInput = imageActions.createEl("input", {
          type: "file",
          cls: "workspace-ontology-image-input",
          attr: { accept: ".png,.jpg,.jpeg,.webp,.gif,.bmp,image/png,image/jpeg,image/webp,image/gif,image/bmp", multiple: "multiple", tabindex: "-1" },
        });
        imageInput.disabled = this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || this.pendingImageCellKeys.has(cellRefKey);
        const imageButton = imageActions.createEl("button", {
          cls: "workspace-ontology-image-add",
          attr: { type: "button", title: "添加图片", "aria-label": "添加图片" },
        });
        setIcon(imageButton, "image-plus");
        imageButton.disabled = imageInput.disabled;
        imageButton.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          imageInput.click();
        };
        imageInput.addEventListener("change", () => {
          const files = Array.from(imageInput.files || []);
          imageInput.value = "";
          if (files.length > 0) void this.enqueueParadigmOntologyImageImport(cellRef, files);
        });
        const setDragState = (enabled) => wrap.classList.toggle("is-image-dragover", enabled);
        wrap.addEventListener("dragenter", (event) => {
          if (this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || !this.acceptingImageImports) return;
          event.preventDefault();
          setDragState(true);
        });
        wrap.addEventListener("dragover", (event) => {
          if (this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || !this.acceptingImageImports) return;
          event.preventDefault();
          if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
          setDragState(true);
        });
        wrap.addEventListener("dragleave", (event) => {
          if (event.relatedTarget && wrap.contains?.(event.relatedTarget)) return;
          setDragState(false);
        });
        wrap.addEventListener("drop", (event) => {
          setDragState(false);
          if (this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn || !this.acceptingImageImports) return;
          const files = Array.from(event.dataTransfer?.files || []);
          const vaultFiles = files.length === 0 ? this.resolveDroppedParadigmOntologyVaultImages(event.dataTransfer) : [];
          if (files.length === 0 && vaultFiles.length === 0) return;
          event.preventDefault();
          event.stopPropagation();
          if (files.length > 0) void this.enqueueParadigmOntologyImageImport(cellRef, files);
          else void this.enqueueParadigmOntologyVaultImageImport(cellRef, vaultFiles);
        });
        const nestedButton = nestedActions.createEl("button", {
          cls: "workspace-ontology-nested-button",
          attr: { type: "button", title: nestedTableId ? "进入子表" : "创建子表" },
        });
        setIcon(nestedButton, nestedTableId ? "panel-right-open" : "table-2");
        nestedButton.createSpan({ text: nestedTableId ? "进入子表" : "创建子表" });
        if (nestedTableId) {
          nestedButton.addClass("is-established");
          const establishedMarker = nestedButton.createSpan({
            cls: "workspace-ontology-nested-established-marker",
            attr: { title: "已建立子表", "aria-label": "已建立子表" },
          });
          setIcon(establishedMarker, "check-circle-2");
        }
        const hasDeclaredChildSchema = Boolean(sanitizeText(schema.columnsById?.[columnId]?.childSchemaId, ""));
        nestedButton.disabled = this.isReadOnly()
          || isObjectLike(cell?.reference)
          || (sharedSchemaProjection && !hasDeclaredChildSchema && !nestedTableId)
          || ((archivedBranchReadOnly || isArchivedColumn) && !nestedTableId);
        nestedButton.onclick = async (event) => {
          event.preventDefault();
          event.stopPropagation();
          if (nestedTableId) {
            this.navigateToTable(nestedTableId);
            return;
          }
          const hasChildSchema = Boolean(sanitizeText(schema.columnsById?.[columnId]?.childSchemaId, ""));
          if (sharedSchemaProjection && !hasChildSchema) {
            new Notice("当前列属于共享结构，请使用“编辑共享结构”在来源 owner 建立子 Schema。");
            return;
          }
          if (!hasChildSchema) {
            const confirmed = await this.confirmFrozenDestructive({
              title: "建立子表结构",
              message: `列：${sanitizeText(schema.columnsById?.[columnId]?.label, columnId)}\n此列将共享同一种子表结构，每一行的内容保持独立。`,
              confirmText: "建立并进入",
            }, () => Boolean(
              this.draft?.tablesById?.[table.id]?.rowsById?.[rowId]?.cellsByColumnId?.[columnId]
              && !sanitizeText(this.draft.tablesById[table.id].rowsById[rowId].cellsByColumnId[columnId].nestedTableId, ""),
            ));
            if (!confirmed) return;
          }
          try {
            const result = createParadigmOntologyNestedTableAtomic(this.draft, table.id, rowId, columnId, {
              schemaName: `${sanitizeText(schema.columnsById?.[columnId]?.label, "当前列")}明细`,
              columns: [{ label: "内容", cellType: "long-text" }],
            });
            if (result.createdTable || result.createdSchema) this.markDirty("创建子表");
            this.navigateToTable(result.table.id);
          } catch (error) {
            new Notice(error.message);
          }
        };
        if (nestedTableId) {
          const deleteNestedBtn = nestedActions.createEl("button", {
            cls: "workspace-ontology-delete-nested",
            attr: { type: "button", title: "删除子表", "aria-label": "删除子表" },
          });
          setIcon(deleteNestedBtn, "trash-2");
          deleteNestedBtn.disabled = this.isReadOnly() || archivedBranchReadOnly || isArchivedColumn;
          deleteNestedBtn.onclick = (event) => {
            event.preventDefault();
            event.stopPropagation();
            void this.deleteNestedTableFromUi(nestedTableId);
          };
        }
      });
      const rowTools = rowEl.createDiv({ cls: "workspace-ontology-row-tools" });
      const makeRowTool = (icon, title, handler, disabled = false) => {
        const button = rowTools.createEl("button", { attr: { type: "button", title, "aria-label": title } });
        setIcon(button, icon);
        button.disabled = disabled || this.isReadOnly() || archivedBranchReadOnly;
        button.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          handler();
        };
      };
      makeRowTool("arrow-up", "上移此行", () => {
        if (moveParadigmOntologyOrder(table.rowOrder, rowId, -1)) {
          table.updatedAt = nowString();
          this.markDirty("移动行");
          this.renderEditor();
        }
      }, rowIndex === 0);
      makeRowTool("arrow-down", "下移此行", () => {
        if (moveParadigmOntologyOrder(table.rowOrder, rowId, 1)) {
          table.updatedAt = nowString();
          this.markDirty("移动行");
          this.renderEditor();
        }
      }, rowIndex === table.rowOrder.length - 1);
      makeRowTool("trash-2", "删除此行", async () => {
        let impact;
        try {
          impact = this.getRowRemovalImpact(table, row);
        } catch (error) {
          new Notice(error.message);
          return;
        }
        if (impact.directDataCellCount > 0 || impact.dataBranchCount > 0) {
          new Notice(`该行仍有 ${impact.directDataCellCount} 个直接内容单元格（含 ${impact.directReferenceCellCount} 个引用）、${impact.dataBranchCount} 个含保留数据的子表分支；为保护历史记录，不能删除。`);
          return;
        }
        const confirmed = await this.confirmFrozenDestructive({
          title: "删除 Ontology 行",
          message: `步骤：第 ${rowIndex + 1} 行\n内容引用：${impact.directReferenceCellCount + impact.referenceCellCount}\nschema lineage：${impact.schemaLineageCount}\n图片引用：${impact.imageReferenceCount}（仅移除引用，不删除附件文件）\n下层表格：${impact.tableCount}\n总行数：${impact.rowCount}\n总单元格：${impact.cellCount}\n删除后无法在当前弹窗中撤销。`,
          confirmText: "删除行",
          danger: true,
        }, () => Boolean(this.draft?.tablesById?.[table.id]?.rowsById?.[rowId]));
        if (!confirmed || !this.draft?.tablesById?.[table.id]?.rowsById?.[rowId]) return;
        try {
          deleteParadigmOntologyRow(this.draft, table.id, rowId);
          this.markDirty("删除行");
          this.renderEditor();
        } catch (error) {
          new Notice(error.message);
        }
      });
    });
    this.consumePendingParadigmOntologyCellFocus();
    this.refreshParadigmOntologyAlbums();
    this.applyParadigmOntologyRangeCues();
    this.refreshParadigmOntologyRangeToolbar();
  }

  resolveParadigmOntologyImagePreview(target) {
    const normalized = sanitizeText(target, "");
    if (!normalized) return { url: "", file: null };
    const linked = this.app?.metadataCache?.getFirstLinkpathDest?.(normalized, this.sourceNotePath);
    const exact = this.app?.vault?.getAbstractFileByPath?.(normalized);
    const file = linked instanceof TFile ? linked : (exact instanceof TFile ? exact : null);
    if (file) return { url: this.app?.vault?.getResourcePath?.(file) || "", file };
    const fallback = this.view?.resolveImageFile?.(normalized);
    return fallback?.url ? fallback : { url: "", file: null };
  }

  canMutateParadigmOntologyAfterConfirmation() {
    return !this.isReadOnly()
      && !this.closingPromise
      && !this.finalClosing
      && !this.forcedTeardown
      && !this.recoveryConflict;
  }

  findExactParadigmOntologyImageRecord(cellRef, frozenRecord) {
    const current = this.resolveParadigmOntologyCell(cellRef);
    if (!current) return null;
    const match = parseParadigmOntologyImageEmbeds(current.cell.value)
      .find((candidate) => candidate.start === frozenRecord.start
        && candidate.end === frozenRecord.end
        && candidate.token === frozenRecord.token);
    return match ? { ...current, record: match } : null;
  }

  async removeParadigmOntologyImageFromUi(cellRef, record, albumContext = null) {
    if (!this.canMutateParadigmOntologyAfterConfirmation()
      || this.isParadigmOntologyCellMutationBlocked(cellRef)
      || this.guardPendingImageImports()) return false;
    const stableRef = this.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId);
    const frozenRecord = {
      start: Number(record?.start),
      end: Number(record?.end),
      token: String(record?.token || ""),
      target: sanitizeText(record?.target, ""),
    };
    const albumGuard = () => !albumContext || this.isParadigmOntologyAlbumTokenActive(
      stableRef,
      albumContext.lifecycleToken,
      albumContext.album,
    );
    if (!albumGuard() || !this.findExactParadigmOntologyImageRecord(stableRef, frozenRecord)) {
      new Notice("单元格内容已变化，请使用刷新后的图片缩略图重试。");
      this.renderEditor();
      return false;
    }
    let confirmed = false;
    try {
      confirmed = await this.confirmFrozenDestructive({
        title: "移除 Ontology 图片引用",
        message: `确定从当前单元格移除这张图片吗？\n附件：${frozenRecord.target || "未解析图片"}\n只会移除 Ontology 中的引用，不会删除 Obsidian 附件文件。`,
        confirmText: "移除引用",
        cancelText: "取消",
        danger: true,
      }, () => albumGuard()
        && this.canMutateParadigmOntologyAfterConfirmation()
        && !this.isParadigmOntologyCellMutationBlocked(stableRef)
        && Boolean(this.findExactParadigmOntologyImageRecord(stableRef, frozenRecord)));
    } catch (error) {
      new Notice(`图片移除确认失败：${error?.message || "请重试"}`);
      return false;
    }
    if (!confirmed) return false;
    if (!albumGuard()
      || !this.canMutateParadigmOntologyAfterConfirmation()
      || this.isParadigmOntologyCellMutationBlocked(stableRef)
      || this.guardPendingImageImports()) {
      new Notice("Ontology 正在关闭或状态已变化，图片引用未移除。");
      return false;
    }
    const current = this.findExactParadigmOntologyImageRecord(stableRef, frozenRecord);
    if (!current) {
      new Notice("单元格内容已变化，请使用刷新后的图片缩略图重试。");
      this.renderEditor();
      return false;
    }
    const next = removeParadigmOntologyImageEmbed(current.cell.value, current.record);
    if (!this.replaceDraftTextValue(current.cell, "value", next)) return false;
    const timestamp = nowString();
    current.row.updatedAt = timestamp;
    current.table.updatedAt = timestamp;
    this.markDirty("移除图片引用");
    this.renderEditor();
    return true;
  }

  renderParadigmOntologyCellImages(host, cellRef, cellWrap = host) {
    const resolved = this.resolveParadigmOntologyCell(cellRef);
    const records = parseParadigmOntologyImageEmbeds(resolved?.cell?.value);
    cellWrap.classList.toggle("has-images", records.length > 0);
    if (records.length === 0) return;
    const previews = records.map((record) => ({ record, preview: this.resolveParadigmOntologyImagePreview(record.target) }));
    const cover = previews.find((entry) => entry.preview.url);
    const unresolvedCount = previews.filter((entry) => !entry.preview.url).length;
    const launcher = host.createEl("button", {
      cls: "workspace-ontology-album-launcher",
      attr: { type: "button", title: `打开图片相册（${records.length} 张）`, "aria-label": `打开图片相册，共 ${records.length} 张` },
    });
    const coverEl = launcher.createDiv({ cls: "workspace-ontology-album-launcher-cover" });
    if (cover?.preview?.url) {
      const image = coverEl.createEl("img", { cls: "workspace-ontology-album-launcher-image" });
      image.src = cover.preview.url;
      image.alt = cover.record.target;
    } else {
      setIcon(coverEl, "images");
    }
    const meta = launcher.createDiv({ cls: "workspace-ontology-album-launcher-meta" });
    meta.createSpan({ cls: "workspace-ontology-album-launcher-count", text: `${records.length} 张图片` });
    if (unresolvedCount > 0) {
      const bounded = unresolvedCount > 99 ? "99+" : String(unresolvedCount);
      meta.createSpan({ cls: "workspace-ontology-album-launcher-unresolved", text: `${bounded} 未解析` });
    }
    setIcon(launcher.createSpan({ cls: "workspace-ontology-album-launcher-open" }), "expand");
    launcher.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.openParadigmOntologyImageAlbum(cellRef);
    };
  }

  getParadigmOntologyClipboardExtension(mimeType) {
    const kind = getParadigmOntologyImageKindByMime(mimeType);
    return kind ? PARADIGM_ONTOLOGY_IMAGE_TYPES[kind].extensions[0] : "png";
  }

  normalizeParadigmOntologyClipboardFile(file, batchId, index) {
    const currentName = sanitizeText(file?.name, "");
    if (currentName) return file;
    const extension = this.getParadigmOntologyClipboardExtension(file?.type);
    const name = `ontology-paste-${batchId}-${String(index + 1).padStart(2, "0")}.${extension}`;
    return {
      name,
      type: sanitizeText(file?.type, `image/${extension}`),
      size: Math.max(0, Number(file?.size) || 0),
      lastModified: Number(file?.lastModified) || Date.now(),
      arrayBuffer: () => file.arrayBuffer(),
    };
  }

  extractParadigmOntologyClipboardImages(clipboardData) {
    const itemFiles = [];
    Array.from(clipboardData?.items || []).forEach((item) => {
      if (item?.kind !== "file" || !String(item?.type || "").toLowerCase().startsWith("image/")) return;
      const file = item.getAsFile?.();
      if (file) itemFiles.push(file);
    });
    const rawFiles = itemFiles.length > 0
      ? itemFiles
      : Array.from(clipboardData?.files || []).filter((file) => {
        const mime = String(file?.type || "").toLowerCase();
        return mime.startsWith("image/") || Boolean(getParadigmOntologyImageKindByExtension(getParadigmOntologyImageExtension(file?.name)));
      });
    if (rawFiles.length === 0) return [];
    const batchId = `${Date.now().toString(36)}-${(++this.albumLifecycleSequence).toString(36)}`;
    return rawFiles.map((file, index) => this.normalizeParadigmOntologyClipboardFile(file, batchId, index));
  }

  handleParadigmOntologyClipboardPaste(event, cellRef, lifecycleToken = null) {
    if (this.isParadigmOntologyCellMutationBlocked(cellRef)) return false;
    const files = this.extractParadigmOntologyClipboardImages(event?.clipboardData);
    if (files.length === 0) return false;
    event.preventDefault();
    event.stopPropagation();
    if (lifecycleToken && !this.isParadigmOntologyAlbumTokenActive(cellRef, lifecycleToken)) {
      new Notice("图片相册已失效，请重新打开后粘贴。");
      return true;
    }
    void this.enqueueParadigmOntologyImageImport(cellRef, files);
    return true;
  }

  isParadigmOntologyAlbumTokenActive(cellRef, lifecycleToken, album = null) {
    if (!lifecycleToken?.active || lifecycleToken.sessionId !== this.sessionId || lifecycleToken.generation !== this.generation) return false;
    const key = this.getParadigmOntologyCellRefKey(cellRef);
    const currentAlbum = this.albumModalsByCellKey.get(key);
    if (!currentAlbum || currentAlbum.lifecycleToken !== lifecycleToken) return false;
    if (album && currentAlbum !== album) return false;
    return Boolean(this.resolveParadigmOntologyCell(cellRef));
  }

  isParadigmOntologyCellArchived(cellRef) {
    const table = this.draft?.tablesById?.[sanitizeText(cellRef?.tableId, "")];
    const schema = this.draft?.schemasById?.[sanitizeText(table?.schemaId, "")];
    return Array.isArray(schema?.archivedColumnOrder)
      && schema.archivedColumnOrder.includes(sanitizeText(cellRef?.columnId, ""));
  }

  isParadigmOntologyCellMutationBlocked(cellRef) {
    return this.isParadigmOntologyCellArchived(cellRef)
      || this.isParadigmOntologyTableInArchivedBranch(cellRef?.tableId);
  }

  openParadigmOntologyImageAlbum(cellRef) {
    const stableRef = this.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId);
    if (!this.resolveParadigmOntologyCell(stableRef) || this.finalClosing || this.forcedTeardown || this.closingPromise) return null;
    const key = this.getParadigmOntologyCellRefKey(stableRef);
    const existing = this.albumModalsByCellKey.get(key);
    if (existing?.isActive?.()) {
      existing.renderAlbum();
      existing.focusAlbum();
      return existing;
    }
    const lifecycleToken = {
      active: true,
      id: `ontologyAlbum-${++this.albumLifecycleSequence}`,
      sessionId: this.sessionId,
      generation: this.generation,
      cellKey: key,
    };
    const album = new WorkspaceParadigmOntologyAlbumModal(this.app, this, stableRef, lifecycleToken);
    this.albumModalsByCellKey.set(key, album);
    album.open();
    return album;
  }

  unregisterParadigmOntologyAlbum(album) {
    if (!album) return;
    const current = this.albumModalsByCellKey.get(album.cellKey);
    if (current === album) this.albumModalsByCellKey.delete(album.cellKey);
  }

  refreshParadigmOntologyAlbums() {
    Array.from(this.albumModalsByCellKey.values()).forEach((album) => {
      if (!album?.isActive?.() || !this.resolveParadigmOntologyCell(album.cellRef)) album?.invalidate?.();
      else album.renderAlbum();
    });
  }

  invalidateParadigmOntologyAlbums() {
    const albums = Array.from(this.albumModalsByCellKey.values());
    this.albumModalsByCellKey.clear();
    albums.forEach((album) => album?.invalidate?.());
  }

  buildParadigmOntologyImageEmbed(file, sourcePath) {
    const generated = sanitizeText(this.app.fileManager?.generateMarkdownLink?.(file, sourcePath), "");
    if (!generated) return `![[${file.path}]]`;
    return generated.startsWith("!") ? generated : `!${generated}`;
  }

  canPrepareParadigmOntologyImageImport(cellRef, operation) {
    const admissionId = sanitizeText(operation?.admissionId, "");
    return Boolean(admissionId && this.admittedImageOperationIds.has(admissionId))
      && !this.finalClosing
      && !this.isReadOnly()
      && !this.recoveryConflict
      && operation?.sessionId === this.sessionId
      && operation?.generation === this.generation
      && !this.isParadigmOntologyCellMutationBlocked(cellRef)
      && Boolean(this.resolveParadigmOntologyCell(cellRef));
  }

  resolveDroppedParadigmOntologyVaultImages(dataTransfer) {
    const rawValues = ["text/plain", "text/uri-list"]
      .map((type) => {
        try {
          return String(dataTransfer?.getData?.(type) || "");
        } catch (_) {
          return "";
        }
      })
      .filter(Boolean);
    const targets = [];
    rawValues.forEach((raw) => {
      parseParadigmOntologyImageEmbeds(raw).forEach((record) => targets.push(record.target));
      raw.split(/\r?\n/).map((line) => sanitizeShortcutTargetInput(line)).filter(Boolean).forEach((target) => targets.push(target));
    });
    const filesByPath = new Map();
    targets.forEach((target) => {
      const exact = this.app.vault?.getAbstractFileByPath?.(target);
      const linked = this.app.metadataCache?.getFirstLinkpathDest?.(target, this.sourceNotePath);
      const file = exact instanceof TFile ? exact : (linked instanceof TFile ? linked : null);
      if (!file || !getParadigmOntologyImageKindByExtension(getParadigmOntologyImageExtension(file.path))) return;
      filesByPath.set(file.path, file);
    });
    return Array.from(filesByPath.values());
  }

  rollbackPreparedParadigmOntologyImage(cellRef, preparedToken, mutationSnapshot = null) {
    const current = this.resolveParadigmOntologyCell(cellRef);
    if (!current) return false;
    const canRestoreExactSnapshot = mutationSnapshot
      && String(current.cell.value || "") === String(mutationSnapshot.preparedValue || "");
    if (canRestoreExactSnapshot) {
      if (!this.replaceDraftTextValue(current.cell, "value", String(mutationSnapshot.cellValue || ""))) return false;
      current.row.updatedAt = mutationSnapshot.rowUpdatedAt;
      current.table.updatedAt = mutationSnapshot.tableUpdatedAt;
      this.markDirty("回滚未完成图片导入");
      return true;
    }
    const record = parseParadigmOntologyImageEmbeds(current.cell.value)
      .find((candidate) => candidate.token === preparedToken);
    if (!record) return false;
    const next = removeParadigmOntologyImageEmbed(current.cell.value, record);
    if (!this.replaceDraftTextValue(current.cell, "value", next)) return false;
    const timestamp = nowString();
    current.row.updatedAt = timestamp;
    current.table.updatedAt = timestamp;
    this.markDirty("回滚未完成图片导入");
    return true;
  }

  async importOneParadigmOntologyImage(cellRef, file, operation, preparedBuffer = null) {
    if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
      throw new Error("Ontology 正在关闭或目标状态已变化，图片未写入附件目录。");
    }
    const buffer = preparedBuffer || await file.arrayBuffer();
    if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
      throw new Error("Ontology 正在关闭或目标单元格已不存在，图片未写入附件目录。");
    }
    const validation = validateParadigmOntologyImageFile(file, buffer);
    if (!validation.ok) throw new Error(validation.error);
    const sourcePath = sanitizeText(this.sourceNotePath, sanitizeText(this.view?.sourceFile?.path, ""));
    const attachmentPath = sanitizeText(
      await this.app.fileManager.getAvailablePathForAttachment(file.name, sourcePath),
      "",
    );
    if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
      throw new Error("Ontology 正在关闭或目标单元格已不存在，图片未写入附件目录。");
    }
    if (!attachmentPath) throw new Error(`无法为图片 ${file.name} 分配附件路径。`);
    const encodedAttachmentPath = attachmentPath.split("/").map((segment) => encodeURIComponent(segment)).join("/");
    const preparedToken = `![](<${encodedAttachmentPath}>)`;
    const current = this.resolveParadigmOntologyCell(cellRef);
    if (!current) throw new Error("目标单元格已不存在，图片未写入附件目录。");
    const mutationSnapshot = {
      cellValue: String(current.cell.value || ""),
      rowUpdatedAt: current.row.updatedAt,
      tableUpdatedAt: current.table.updatedAt,
      preparedValue: "",
    };
    const preparedValue = appendParadigmOntologyImageEmbeds(current.cell.value, [preparedToken]);
    mutationSnapshot.preparedValue = preparedValue;
    if (!this.replaceDraftTextValue(current.cell, "value", preparedValue)) {
      throw new Error("Ontology 已达到大小上限，图片未写入附件目录。");
    }
    let timestamp = nowString();
    current.row.updatedAt = timestamp;
    current.table.updatedAt = timestamp;
    this.markDirty("准备导入图片");
    const prepareRecoveryRecord = this.buildRecoveryRecord("editing", "image-drop-prepare");
    try {
      await this.flushRecovery("image-drop-prepare", { forceCurrentDraft: true, recordOverride: prepareRecoveryRecord });
    } catch (error) {
      this.rollbackPreparedParadigmOntologyImage(cellRef, preparedToken, mutationSnapshot);
      throw error;
    }
    this.protectedImageRecoveryRecord = deepClone(prepareRecoveryRecord, null);
    if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
      const rolledBack = this.rollbackPreparedParadigmOntologyImage(cellRef, preparedToken, mutationSnapshot);
      if (rolledBack) {
        try {
          await this.flushRecovery("image-drop-prepare-close-rollback", { forceCurrentDraft: true });
          this.protectedImageRecoveryRecord = null;
        } catch (_) {}
      }
      if (!this.resolveParadigmOntologyCell(cellRef)) {
        throw new Error(`目标单元格已不存在；图片 ${file.name} 未写入，恢复草稿中保留了完整路径引用。`);
      }
      throw new Error(`Ontology 正在关闭；图片 ${file.name} 的预备引用已回滚，附件未创建。`);
    }

    let createdFile = null;
    try {
      createdFile = await this.app.vault.createBinary(attachmentPath, buffer);
    } catch (error) {
      const existing = this.app.vault.getAbstractFileByPath?.(attachmentPath);
      if (existing instanceof TFile) createdFile = existing;
      else {
        let pathExists = false;
        try {
          pathExists = await this.app.vault.adapter?.exists?.(attachmentPath) === true;
        } catch (_) {}
        if (!pathExists) {
          this.rollbackPreparedParadigmOntologyImage(cellRef, preparedToken, mutationSnapshot);
          try {
            await this.flushRecovery("image-drop-create-rollback", { forceCurrentDraft: true });
            this.protectedImageRecoveryRecord = null;
          } catch (_) {}
          throw new Error(`图片 ${file.name} 写入附件目录失败：${error.message}`);
        }
        try {
          await this.flushRecovery("image-drop-create-ambiguous");
        } catch (_) {}
        throw new Error(`图片 ${file.name} 的附件路径已存在但对象解析失败；完整路径引用已保留，请重载后核查。`);
      }
    }
    if (!(createdFile instanceof TFile)) {
      createdFile = this.app.vault.getAbstractFileByPath?.(attachmentPath);
    }
    if (!(createdFile instanceof TFile)) {
      throw new Error(`图片 ${file.name} 已写入，但无法解析附件对象；完整路径引用已保留。`);
    }
    if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
      throw new Error(`引用能力已降级；图片 ${file.name} 已写入附件目录，恢复草稿保留了完整路径引用。`);
    }

    const finalEmbed = this.buildParadigmOntologyImageEmbed(createdFile, sourcePath);
    const latest = this.resolveParadigmOntologyCell(cellRef);
    if (!latest) throw new Error(`图片 ${file.name} 已写入，恢复草稿中保留了完整路径引用。`);
    const finalizedValue = replaceParadigmOntologyImageEmbed(latest.cell.value, preparedToken, finalEmbed);
    if (finalizedValue !== latest.cell.value) {
      this.replaceDraftTextValue(latest.cell, "value", finalizedValue);
      timestamp = nowString();
      latest.row.updatedAt = timestamp;
      latest.table.updatedAt = timestamp;
      this.markDirty("导入图片");
    }
    try {
      await this.flushRecovery("image-drop-finalize", { forceCurrentDraft: true });
      this.protectedImageRecoveryRecord = null;
    } catch (error) {
      throw new Error(`图片 ${file.name} 已写入且完整路径引用已保护，但最终链接草稿刷新失败：${error.message}`);
    }
    return { file: createdFile, embed: finalEmbed };
  }

  async importParadigmOntologyImageBatch(cellRef, files, operation) {
    const batch = Array.from(files || []);
    if (batch.length === 0) return [];
    if (batch.length > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxFilesPerBatch) {
      throw new Error(`每次最多导入 ${PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxFilesPerBatch} 张图片。`);
    }
    const totalBytes = batch.reduce((sum, file) => sum + Math.max(0, Number(file?.size) || 0), 0);
    if (totalBytes > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxBatchBytes) {
      throw new Error("本批图片总大小超过 100 MiB。");
    }
    const preparedFiles = [];
    let actualTotalBytes = 0;
    for (const file of batch) {
      if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
        throw new Error("Ontology 正在关闭或目标状态已变化，图片未写入附件目录。");
      }
      const buffer = await file.arrayBuffer();
      if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
        throw new Error("Ontology 正在关闭或目标单元格已不存在，图片未写入附件目录。");
      }
      actualTotalBytes += Math.max(0, Number(buffer?.byteLength) || 0);
      if (actualTotalBytes > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxBatchBytes) {
        throw new Error("本批图片读取后的实际总大小超过 100 MiB。");
      }
      preparedFiles.push({ file, buffer });
    }
    const results = [];
    const errors = [];
    for (const entry of preparedFiles) {
      try {
        results.push(await this.importOneParadigmOntologyImage(cellRef, entry.file, operation, entry.buffer));
      } catch (error) {
        errors.push(error.message || String(error));
      }
    }
    if (errors.length > 0) throw new Error(errors.join("\n"));
    return results;
  }

  async importParadigmOntologyVaultImageBatch(cellRef, files, operation) {
    const batch = Array.from(files || []);
    if (batch.length === 0) return [];
    if (batch.length > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxFilesPerBatch) {
      throw new Error(`每次最多引用 ${PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxFilesPerBatch} 张图片。`);
    }
    const totalBytes = batch.reduce((sum, file) => sum + Math.max(0, Number(file?.stat?.size) || 0), 0);
    if (totalBytes > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxBatchBytes) throw new Error("本批图片总大小超过 100 MiB。");
    const preparedFiles = [];
    let actualTotalBytes = 0;
    for (const file of batch) {
      if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
        throw new Error("Ontology 正在关闭或目标状态已变化，未添加已有附件引用。");
      }
      const buffer = await this.app.vault.readBinary(file);
      if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
        throw new Error("Ontology 正在关闭或目标单元格已不存在，未添加已有附件引用。");
      }
      actualTotalBytes += Math.max(0, Number(buffer?.byteLength) || 0);
      if (actualTotalBytes > PARADIGM_ONTOLOGY_IMAGE_LIMITS.maxBatchBytes) {
        throw new Error("本批图片读取后的实际总大小超过 100 MiB。");
      }
      const fileName = sanitizeText(file.name, file.path.split("/").pop());
      const validation = validateParadigmOntologyImageFile({ name: fileName, type: "", size: file.stat?.size }, buffer);
      if (!validation.ok) throw new Error(validation.error);
      preparedFiles.push({ file, buffer });
    }
    const results = [];
    const errors = [];
    for (const entry of preparedFiles) {
      try {
        if (!this.canPrepareParadigmOntologyImageImport(cellRef, operation)) {
          throw new Error("Ontology 正在关闭或目标状态已变化，未添加已有附件引用。");
        }
        const file = entry.file;
        const current = this.resolveParadigmOntologyCell(cellRef);
        if (!current) throw new Error("目标单元格已不存在，未添加已有附件引用。");
        const alreadyReferenced = parseParadigmOntologyImageEmbeds(current.cell.value).some((record) => (
          this.resolveParadigmOntologyImagePreview(record.target)?.file?.path === file.path
        ));
        if (alreadyReferenced) continue;
        const sourcePath = sanitizeText(this.sourceNotePath, sanitizeText(this.view?.sourceFile?.path, ""));
        const embed = this.buildParadigmOntologyImageEmbed(file, sourcePath);
        const next = appendParadigmOntologyImageEmbeds(current.cell.value, [embed]);
        if (!this.replaceDraftTextValue(current.cell, "value", next)) throw new Error("Ontology 已达到大小上限，未添加已有附件引用。");
        const timestamp = nowString();
        current.row.updatedAt = timestamp;
        current.table.updatedAt = timestamp;
        this.markDirty("引用已有图片");
        await this.flushRecovery("image-vault-reference-finalize");
        results.push({ file, embed });
      } catch (error) {
        errors.push(error.message || String(error));
      }
    }
    if (errors.length > 0) throw new Error(errors.join("\n"));
    return results;
  }

  enqueueParadigmOntologyImageWork(cellRef, work) {
    if (this.isReadOnly()
      || this.isParadigmOntologyCellMutationBlocked(cellRef)
      || !this.acceptingImageImports
      || this.finalClosing
      || this.forcedTeardown
      || this.recoveryConflict) {
      new Notice("Ontology 正在关闭或处于冲突状态，未接收新的图片导入。");
      return Promise.resolve([]);
    }
    const stableRef = this.getParadigmOntologyCellRef(cellRef?.tableId, cellRef?.rowId, cellRef?.columnId);
    if (!this.resolveParadigmOntologyCell(stableRef)) {
      new Notice("目标单元格已不存在。");
      return Promise.resolve([]);
    }
    const operation = {
      sessionId: this.sessionId,
      generation: this.generation,
      admissionId: createId("pgOntImageAdmission"),
    };
    this.admittedImageOperationIds.add(operation.admissionId);
    const cellKey = this.getParadigmOntologyCellRefKey(stableRef);
    this.pendingImageImportCount += 1;
    this.pendingImageCellCounts.set(cellKey, (this.pendingImageCellCounts.get(cellKey) || 0) + 1);
    this.pendingImageCellKeys.add(cellKey);
    const task = this.imageImportQueue.then(() => work(stableRef, operation));
    let taskError = null;
    this.imageImportQueue = task.catch((error) => {
      taskError = error;
      console.error("[Workspace Mount][ontology.image-import]", {
        tableId: stableRef.tableId,
        rowId: stableRef.rowId,
        columnId: stableRef.columnId,
        error: error.message,
      });
      new Notice(error.message || "Ontology 图片导入失败");
      return [];
    }).finally(() => {
      this.admittedImageOperationIds.delete(operation.admissionId);
      this.pendingImageImportCount = Math.max(0, this.pendingImageImportCount - 1);
      const cellPending = Math.max(0, (this.pendingImageCellCounts.get(cellKey) || 1) - 1);
      if (cellPending > 0) this.pendingImageCellCounts.set(cellKey, cellPending);
      else {
        this.pendingImageCellCounts.delete(cellKey);
        this.pendingImageCellKeys.delete(cellKey);
      }
      if (!this.finalClosing) {
        try {
          if (taskError) this.setStatus("图片导入未全部完成，已保留可恢复引用", "is-error");
          else this.markDirty(this.pendingImageImportCount > 0 ? `仍有 ${this.pendingImageImportCount} 批图片待导入` : "图片导入完成");
          this.renderEditor();
        } catch (error) {
          console.error("[Workspace Mount][ontology.image-ui-render]", { phase: "settled", error: error.message });
        }
      }
    });
    try {
      this.setStatus(`正在导入图片 · 队列 ${this.pendingImageImportCount}`, "is-saving");
      this.renderEditor();
    } catch (error) {
      console.error("[Workspace Mount][ontology.image-ui-render]", { phase: "admitted", error: error.message });
    }
    return this.imageImportQueue;
  }

  enqueueParadigmOntologyImageImport(cellRef, files) {
    return this.enqueueParadigmOntologyImageWork(
      cellRef,
      (stableRef, operation) => this.importParadigmOntologyImageBatch(stableRef, files, operation),
    );
  }

  enqueueParadigmOntologyVaultImageImport(cellRef, files) {
    return this.enqueueParadigmOntologyImageWork(
      cellRef,
      (stableRef, operation) => this.importParadigmOntologyVaultImageBatch(stableRef, files, operation),
    );
  }

  markDirty(reason = "编辑") {
    if (this.isReadOnly()) return;
    this.setParadigmOntologyDirtyState(hashParadigmOntology(this.draft) !== this.initialDraftHash);
    this.setStatus(this.dirty ? `未保存 · ${reason}` : "", this.dirty ? "is-dirty" : "");
    if (this.dirty) this.scheduleRecovery();
  }

  scheduleRecovery() {
    if (this.isReadOnly()) return;
    this.installParadigmOntologyRecoveryTimerTransactional(this.recoveryTimer);
  }

  buildRecoveryRecord(status = "editing", failureReason = "") {
    return {
      ownerPluginId: this.ownerPluginId,
      externalOwnerNamespace: this.externalOwnerNamespace,
      externalOwnerKey: this.externalOwnerKey,
      providerGeneration: this.providerGeneration,
      sourceNotePath: this.sourceNotePath,
      canonicalDataPath: this.dataPath,
      paradigmItemId: this.paradigmItemId,
      documentId: sanitizeText(this.draft?.documentId, ""),
      sessionId: this.sessionId,
      generation: this.generation,
      baseOntologyHash: this.baseOntologyHash,
      draft: deepClone(this.draft, null),
      timestamp: Date.now(),
      status,
      failureReason: sanitizeText(failureReason, ""),
      committedHash: "",
    };
  }

  async flushRecovery(reason = "manual", options = {}) {
    if ((!this.dirty && !this.protectedImageRecoveryRecord) || this.isReadOnly()) return true;
    if (this.recoveryTimer) {
      window.clearTimeout(this.recoveryTimer);
      this.recoveryTimer = 0;
    }
    try {
      const forceCurrentDraft = options?.forceCurrentDraft === true;
      const recordOverride = options?.recordOverride
        ? deepClone(options.recordOverride, null)
        : null;
      const protectedRecord = !forceCurrentDraft && this.protectedImageRecoveryRecord
        ? deepClone(this.protectedImageRecoveryRecord, null)
        : null;
      const record = recordOverride || protectedRecord || this.buildRecoveryRecord(this.recoveryConflict ? "conflict" : "editing", reason);
      if (protectedRecord) {
        record.timestamp = Date.now();
        record.failureReason = sanitizeText(reason, "protected-image-recovery");
      }
      await this.plugin.persistParadigmOntologyRecovery(record);
      this.lastPersistedRecoveryDraftHash = hashParadigmOntology(record.draft);
      return true;
    } catch (error) {
      this.setStatus("草稿保护写入失败", "is-error");
      throw new Error(`草稿保护写入失败：${error.message}`);
    }
  }

  buildParadigmOntologyFormalCommitDiff(nextOntology) {
    const baseOntology = isObjectLike(this.formalOntology) ? this.formalOntology : null;
    const referenceDiff = diffParadigmOntologyOutboundReferences(baseOntology, nextOntology);
    const buildCellAddressFor = (ontology, tableId, rowId, columnId) => {
      if (typeof this.referenceAdapter?.buildCellAddress === "function") {
        return normalizeParadigmOntologyCellAddress(this.referenceAdapter.buildCellAddress({
          cellRef: { tableId, rowId, columnId },
          documentId: sanitizeText(ontology?.documentId, ""),
          ownerPluginId: this.ownerPluginId,
          ownerNamespace: this.externalOwnerNamespace,
          ownerKey: this.externalOwnerKey || this.paradigmItemId,
          sourceNotePath: this.sourceNotePath,
        }));
      }
      return normalizeParadigmOntologyCellAddress(Object.assign({}, this.cellAddressBase || {}, {
        addressVersion: PARADIGM_ONTOLOGY_CELL_ADDRESS_VERSION,
        documentId: sanitizeText(ontology?.documentId, ""),
        tableId,
        rowId,
        columnId,
      }));
    };
    const buildSchemaAddressFor = (ontology, schemaId) => {
      if (typeof this.referenceAdapter?.buildSchemaAddress === "function") {
        return normalizeParadigmOntologySchemaAddress(this.referenceAdapter.buildSchemaAddress({
          schemaId,
          documentId: sanitizeText(ontology?.documentId, ""),
          ownerPluginId: this.ownerPluginId,
          ownerNamespace: this.externalOwnerNamespace,
          ownerKey: this.externalOwnerKey || this.paradigmItemId,
          sourceNotePath: this.sourceNotePath,
        }));
      }
      return normalizeParadigmOntologySchemaAddress(Object.assign({}, this.cellAddressBase || {}, {
        addressVersion: PARADIGM_ONTOLOGY_SCHEMA_ADDRESS_VERSION,
        documentId: sanitizeText(ontology?.documentId, ""),
        schemaId,
      }));
    };
    const collectCells = (ontology) => {
      const rows = new Map();
      Object.values(ontology?.tablesById || {}).forEach((table) => {
        Object.values(table?.rowsById || {}).forEach((row) => {
          Object.keys(row?.cellsByColumnId || {}).forEach((columnId) => {
            const address = buildCellAddressFor(ontology, table.id, row.id, columnId);
            rows.set(serializeParadigmOntologyAddress(address), address);
          });
        });
      });
      return rows;
    };
    const collectSchemas = (ontology) => {
      const rows = new Map();
      Object.keys(ontology?.schemasById || {}).forEach((schemaId) => {
        const address = buildSchemaAddressFor(ontology, schemaId);
        rows.set(serializeParadigmOntologyAddress(address), address);
      });
      return rows;
    };
    const beforeCells = baseOntology ? collectCells(baseOntology) : new Map();
    const afterCells = collectCells(nextOntology);
    const beforeSchemas = baseOntology ? collectSchemas(baseOntology) : new Map();
    const afterSchemas = collectSchemas(nextOntology);
    const addedReferences = referenceDiff.added.concat(referenceDiff.redirected.map((entry) => entry.after)).map((edge) => ({
      targetAddress: buildCellAddressFor(nextOntology, edge.tableId, edge.rowId, edge.columnId),
      sourceAddress: deepClone(edge.sourceAddress, null),
    }));
    const removedReferences = referenceDiff.removed.concat(referenceDiff.redirected.map((entry) => entry.before)).map((edge) => ({
      targetAddress: buildCellAddressFor(baseOntology, edge.tableId, edge.rowId, edge.columnId),
      sourceAddress: deepClone(edge.sourceAddress, null),
    }));
    const collectLineages = (ontology) => {
      const rows = new Map();
      Object.values(ontology?.schemasById || {}).forEach((schema) => {
        if (!isObjectLike(schema?.sourceLineage?.sourceSchemaAddress)) return;
        const localSchemaAddress = buildSchemaAddressFor(ontology, schema.id);
        rows.set(serializeParadigmOntologyAddress(localSchemaAddress), {
          localSchemaAddress,
          sourceSchemaAddress: deepClone(schema.sourceLineage.sourceSchemaAddress, null),
        });
      });
      return rows;
    };
    const beforeLineages = baseOntology ? collectLineages(baseOntology) : new Map();
    const afterLineages = collectLineages(nextOntology);
    const addedSchemaLineages = [];
    afterLineages.forEach((edge, key) => {
      const previous = beforeLineages.get(key);
      if (!previous || serializeParadigmOntologyAddress(previous.sourceSchemaAddress) !== serializeParadigmOntologyAddress(edge.sourceSchemaAddress)) {
        addedSchemaLineages.push(edge);
      }
    });
    return {
      addedReferences,
      removedReferences,
      addedSchemaLineages,
      removedSourceAddresses: Array.from(beforeCells.entries()).filter(([key]) => !afterCells.has(key)).map(([, address]) => address),
      removedSchemaAddresses: Array.from(beforeSchemas.entries()).filter(([key]) => !afterSchemas.has(key)).map(([, address]) => address),
    };
  }

  async commitParadigmOntologyWithReferenceIntegrity(ontology, session = {}) {
    if (this.referenceCapabilityReadOnly) {
      const error = new Error("Ontology 引用能力已降级，正式数据保持只读。当前内存草稿未提交。");
      error.code = "ONTOLOGY_REFERENCE_WRITE_UNAVAILABLE";
      throw error;
    }
    const commitPrepared = async (preparedOntology) => {
      const submitted = deepClone(preparedOntology, null);
      const committed = await this.view.commitParadigmOntology(
        this.paradigmItemId, preparedOntology, this.baseOntologyHash, session,
      );
      return Object.assign({}, committed, { ontology: deepClone(committed?.ontology || submitted, null) });
    };
    const canAddressOwner = isObjectLike(this.cellAddressBase)
      || (typeof this.referenceAdapter?.buildCellAddress === "function"
        && typeof this.referenceAdapter?.buildSchemaAddress === "function");
    if (!canAddressOwner) {
      if (hasParadigmOntologyReferenceState(this.formalOntology) || hasParadigmOntologyReferenceState(ontology)) {
        const error = new Error("当前 Ontology owner 缺少稳定地址，已阻止覆盖引用数据。");
        error.code = "ONTOLOGY_CELL_ADDRESS_UNAVAILABLE";
        throw error;
      }
      return await commitPrepared(ontology);
    }
    const diff = this.buildParadigmOntologyFormalCommitDiff(ontology);
    const needsReferenceCoordinator = hasParadigmOntologyReferenceState(this.formalOntology)
      || hasParadigmOntologyReferenceState(ontology)
      || diff.removedSourceAddresses.length > 0
      || diff.removedSchemaAddresses.length > 0;
    if (!needsReferenceCoordinator) {
      return await commitPrepared(ontology);
    }
    if (typeof this.referenceAdapter?.coordinateFormalCommit !== "function") {
      const error = new Error("Ontology 引用协调器当前不可用，已阻止覆盖包含引用或 schema lineage 的正式数据。");
      error.code = "ONTOLOGY_REFERENCE_COORDINATOR_UNAVAILABLE";
      throw error;
    }
    const coordinated = await this.referenceAdapter.coordinateFormalCommit(Object.assign({}, diff, {
      operationId: `${this.sessionId}:${this.generation}`,
      allowIncompletePreservationOnly: diff.removedReferences.length === 1
        && diff.addedReferences.length === 0
        && diff.addedSchemaLineages.length === 0
        && diff.removedSourceAddresses.length === 0
        && diff.removedSchemaAddresses.length === 0,
      finalize: async (context = {}) => {
        const preparedOntology = deepClone(ontology, null);
        const downstreamSchemaAddressKeys = (Array.isArray(context?.proof?.schemaEdges) ? context.proof.schemaEdges : [])
          .map((edge) => {
            try { return serializeParadigmOntologyAddress(edge.toAddress || edge.sourceSchemaAddress); }
            catch (_) { return ""; }
          })
          .filter(Boolean);
        let outcomes;
        try {
          const pendingPartition = partitionParadigmOntologySharedSchemaGraphs(preparedOntology);
          let retainedPendingRootSchemaIds = [];
          if (pendingPartition.pendingDetachRoots.length > 0 && this.resolveDetachedBindingPolicy) {
            const policy = await this.resolveDetachedBindingPolicy({
              operationId: sanitizeText(context.operationId, `${this.sessionId}:${this.generation}`),
              formalOntology: deepClone(this.formalOntology, null),
              preparedOntology: deepClone(preparedOntology, null),
              removedReferences: deepClone(diff.removedReferences, []),
              pendingBindings: pendingPartition.pendingDetachRoots.map((entry) => ({
                rootSchemaId: entry.rootSchemaId,
                graphSchemaIds: entry.graphSchemaIds.slice(),
                parentColumns: deepClone(entry.parentColumns, []),
              })),
            });
            retainedPendingRootSchemaIds = Array.isArray(policy?.retainedRootSchemaIds)
              ? policy.retainedRootSchemaIds
              : pendingPartition.pendingDetachRoots.map((entry) => entry.rootSchemaId);
          }
          outcomes = finalizeParadigmOntologyDetachedBindings(preparedOntology, {
            operationId: sanitizeText(context.operationId, `${this.sessionId}:${this.generation}`),
            proofComplete: context?.proof?.complete === true,
            downstreamSchemaAddressKeys,
            buildSchemaAddress: (schemaId) => this.buildParadigmOntologySchemaAddress(schemaId),
            retainedPendingRootSchemaIds,
          });
        } catch (error) {
          const partition = partitionParadigmOntologySharedSchemaGraphs(ontology);
          const entry = partition.pendingDetachRoots[0] || partition.activeRoots[0] || partition.invalidOrphanRoots[0] || null;
          this.logSharedSchemaRejection(entry, { stage: "finalize", error, blockSave: true });
          throw error;
        }
        const finalDiff = this.buildParadigmOntologyFormalCommitDiff(preparedOntology);
        return { ok: true, preparedOntology, finalDiff, outcomes };
      },
      commit: async (context = {}) => {
        const preparedOntology = isObjectLike(context.preparedOntology) ? context.preparedOntology : ontology;
        const committed = await commitPrepared(preparedOntology);
        return { ok: true, committed };
      },
    }));
    return coordinated?.committed || coordinated;
  }

  close() {
    if (this.finalClosing) {
      super.close();
      return;
    }
    void this.requestClose("implicit-close");
  }

  async requestClose(reason = "close") {
    const minimize = reason === "minimize";
    if (this.closingPromise) {
      const savingToMinimize = this.closeReason === "minimize";
      const result = await this.closingPromise;
      if (savingToMinimize && !minimize && result && !this.finalClosing) return await this.requestClose(reason);
      return result;
    }
    if (minimize && (this.forcedTeardown || this.finalClosing || this.minimized)) return false;
    if (this.getActiveColumnDescriptionModal()) {
      const protectedDescription = await this.settleActiveColumnDescriptionModal(`ontology-${reason}`);
      if (protectedDescription !== true) {
        this.setStatus("列说明尚未安全写入，窗口保持打开", "is-error");
        return false;
      }
      if (this.closingPromise) return await this.closingPromise;
    }
    if (this.forcedTeardown) {
      try {
        if (this.forcedTeardownPromise) await this.forcedTeardownPromise;
      } catch (error) {
        this.setStatus("卸载前草稿保护失败，窗口保持打开", "is-error");
        new Notice(error.message || "卸载前草稿保护失败");
        return false;
      }
      this.finishClose();
      return true;
    }
    this.acceptingImageImports = false;
    this.invalidateParadigmOntologyAlbums();
    this.closeOperationToken += 1;
    this.invalidateSharedSchemaAsyncWork();
    this.closeReason = reason;
    const previousInert = this.contentEl?.inert;
    if (minimize && this.contentEl) this.contentEl.inert = true;
    this.closingPromise = (async () => {
      await this.flushParadigmOntologyViewState(`close:${reason}`);
      if (this.hasPendingImageImports()) {
        this.setStatus("正在等待图片导入完成...", "is-saving");
        await this.imageImportQueue;
      }
      if (minimize && (this.protectedImageRecoveryRecord || this.recoveryConflict || (this.isReadOnly() && this.dirty))) {
        await this.flushRecovery("minimize-blocked");
        this.setStatus("修改尚未正式保存，请先处理冲突或恢复提示", "is-error");
        new Notice("修改尚未正式保存，Ontology 窗口保持打开。");
        return false;
      }
      if (this.protectedImageRecoveryRecord) {
        try {
          await this.flushRecovery("protected-image-close");
          this.setStatus("图片恢复引用已保留", "is-warning");
          this.finishClose();
          return true;
        } catch (error) {
          new Notice(error.message || "图片恢复引用保护失败");
          return false;
        }
      }
      if (this.isReadOnly() || !this.dirty) {
        if (minimize) return this.performParadigmOntologyMinimize();
        this.finishClose();
        return true;
      }
      if (this.recoveryConflict) {
        try {
          await this.flushRecovery("conflict-close");
          this.finishClose();
          return true;
        } catch (error) {
          new Notice(error.message || "冲突草稿保护失败");
          return false;
        }
      }
      if (!this.isReadOnly()) {
        try {
          await this.reconcileSharedSchemas({ required: true, render: false });
        } catch (error) {
          this.sharedSchemaRequiredFailure = error;
          try {
            await this.flushRecovery("shared-schema-reconcile-failed");
          } catch (recoveryError) {
            this.setStatus("共享结构同步失败，且恢复草稿写入失败，窗口保持打开", "is-error");
            new Notice(recoveryError.message || "共享结构恢复草稿写入失败");
            return false;
          }
          const partition = this.getSharedSchemaPartition();
          const entry = partition.activeRoots[0] || partition.invalidOrphanRoots[0] || null;
          this.logSharedSchemaRejection(entry, {
            stage: "save-admission",
            error,
            blockSave: true,
            aggregateReasons: error?.detail?.aggregateReasons || [],
          });
          if (reason === "implicit-close") {
            this.finishClose();
            return true;
          }
          this.setStatus("共享结构同步失败；正式数据未改写，恢复草稿已保留", "is-error");
          this.renderRecoveryConflictControls();
          new Notice(error.message || "共享结构同步失败");
          return false;
        }
      }
      this.setStatus("正在保存...", "is-saving");
      try {
        await this.flushRecovery(reason);
        const compacted = compactParadigmOntology(this.draft, this.initialRowIds);
        const validation = validateParadigmOntology(compacted);
        if (!validation.ok) throw new Error(validation.errors[0] || "Ontology 结构校验失败。");
        const submittedDraftHash = hashParadigmOntology(this.draft);
        const committed = await this.commitParadigmOntologyWithReferenceIntegrity(compacted, {
          sessionId: this.sessionId,
          generation: this.generation,
        });
        this.baseOntologyHash = committed.hash;
        if (minimize) {
          const changedDuringSave = hashParadigmOntology(this.draft) !== submittedDraftHash;
          this.formalOntology = deepClone(committed.ontology, null);
          this.formalOntologyHash = committed.hash;
          this.initialDraftHash = hashParadigmOntology(this.formalOntology);
          this.initialRowIds = new Set(Object.values(this.formalOntology?.tablesById || {}).flatMap((table) => table?.rowOrder || []));
          if (!changedDuringSave) this.draft = deepClone(this.formalOntology, null);
          if (!this.draft?.tablesById?.[this.currentTableId]) this.currentTableId = this.draft.rootTableId;
          this.cancelParadigmOntologyRangeMode("minimize-saved");
          this.refreshDraftBytes();
          this.setParadigmOntologyDirtyState(hashParadigmOntology(this.draft) !== this.initialDraftHash);
          this.renderEditor();
          if (this.dirty) {
            await this.flushRecovery("edited-during-minimize");
            this.setStatus("已保存提交内容；新增修改待保存", "is-warning");
            return false;
          }
        }
        await this.plugin.clearParadigmOntologyRecovery(this.dataPath, this.paradigmItemId, committed.hash, {
          sessionId: this.sessionId,
          generation: this.generation,
        });
        if (minimize && hashParadigmOntology(this.draft) !== this.initialDraftHash) {
          this.setParadigmOntologyDirtyState(true);
          await this.flushRecovery("edited-during-minimize-cleanup");
          this.setStatus("新增修改待保存，窗口保持打开", "is-warning");
          return false;
        }
        this.setParadigmOntologyDirtyState(false);
        this.setStatus("已保存", "is-saved");
        if (minimize) return this.performParadigmOntologyMinimize();
        this.finishClose();
        return true;
      } catch (error) {
        const isConflict = error?.code === "ONTOLOGY_CONFLICT";
        if (isConflict) {
          this.recoveryConflict = true;
          const hasExternalFormal = Object.prototype.hasOwnProperty.call(error || {}, "currentFormalOntology");
          const currentFormal = hasExternalFormal
            ? error.currentFormalOntology
            : this.view?.getParadigmItemById?.(this.paradigmItemId)?.ontology;
          this.formalOntology = currentFormal == null ? null : deepClone(currentFormal, null);
          this.formalOntologyHash = sanitizeText(error?.currentFormalHash, hashParadigmOntology(this.formalOntology));
          try {
            await this.plugin.persistParadigmOntologyRecovery(this.buildRecoveryRecord("conflict", error.message));
          } catch (_) {}
          if (this.saveCloseBtn) this.saveCloseBtn.disabled = true;
          this.renderRecoveryConflictControls();
        }
        const partition = this.getSharedSchemaPartition();
        const entry = partition.activeRoots[0] || partition.invalidOrphanRoots[0] || partition.pendingDetachRoots[0] || null;
        if (entry) this.logSharedSchemaRejection(entry, { stage: "formal-save", error, blockSave: true });
        this.setStatus(isConflict ? "正式数据已变化，草稿未覆盖" : "保存失败，草稿已保留", "is-error");
        new Notice(error.message || "范式 Ontology 保存失败");
        return false;
      }
    })().catch((error) => {
      if (!minimize) throw error;
      this.setStatus("保存失败，窗口保持打开", "is-error");
      new Notice(error.message || "Ontology 缩小前保存失败");
      return false;
    });
    try {
      return await this.closingPromise;
    } finally {
      if (minimize && this.contentEl) this.contentEl.inert = previousInert || false;
      if (!this.finalClosing) {
        this.closingPromise = null;
        if (!this.forcedTeardown) this.acceptingImageImports = true;
      }
    }
  }

  async prepareForcedTeardown() {
    if (this.forcedTeardownPromise) return await this.forcedTeardownPromise;
    if (this.getActiveColumnDescriptionModal()) {
      const protectedDescription = await this.settleActiveColumnDescriptionModal("ontology-forced-teardown");
      if (protectedDescription !== true) throw new Error("列说明未能安全写入父 Ontology 草稿。");
    }
    this.forcedTeardown = true;
    this.acceptingImageImports = false;
    this.invalidateParadigmOntologyAlbums();
    this.closeOperationToken += 1;
    this.invalidateSharedSchemaAsyncWork();
    this.forcedTeardownPromise = (async () => {
      await this.flushParadigmOntologyViewState("forced-teardown");
      const activeClose = this.closingPromise;
      if (activeClose) await activeClose;
      this.acceptingImageImports = false;
      if (this.finalClosing) return true;
      await this.imageImportQueue;
      const sharedPartition = this.getSharedSchemaPartition();
      const blocksFormalFallback = sharedPartition.activeRoots.length > 0
        || sharedPartition.invalidOrphanRoots.length > 0
        || Boolean(this.sharedSchemaRequiredFailure);
      try {
        if (!this.isReadOnly()) await this.reconcileSharedSchemas({ required: true, render: false });
        await this.flushRecovery("forced-teardown");
        return true;
      } catch (recoveryError) {
        const protectedDraft = this.protectedImageRecoveryRecord?.draft;
        const durableDraft = isObjectLike(protectedDraft) ? protectedDraft : this.draft;
        const durableHash = hashParadigmOntology(durableDraft);
        if (this.lastPersistedRecoveryDraftHash && this.lastPersistedRecoveryDraftHash === durableHash) {
          this.setStatus("已使用先前写入的恢复草稿完成卸载保护", "is-warning");
          return true;
        }
        if (blocksFormalFallback) {
          const entry = sharedPartition.activeRoots[0] || sharedPartition.invalidOrphanRoots[0] || null;
          this.logSharedSchemaRejection(entry, {
            stage: "forced-teardown",
            error: recoveryError,
            blockSave: true,
          });
          throw new Error(`卸载前共享结构草稿保护失败：${recoveryError.message}`, { cause: recoveryError });
        }
        if (!this.isReadOnly() && !this.recoveryConflict && !this.protectedImageRecoveryRecord && this.dirty) {
          try {
            const compacted = compactParadigmOntology(this.draft, this.initialRowIds);
            const validation = validateParadigmOntology(compacted);
            if (!validation.ok) throw new Error(validation.errors[0] || "Ontology 结构校验失败。");
            const committed = await this.commitParadigmOntologyWithReferenceIntegrity(compacted, {
              sessionId: this.sessionId,
              generation: this.generation,
            });
            this.baseOntologyHash = committed.hash;
            this.setParadigmOntologyDirtyState(false);
            try {
              await this.plugin.clearParadigmOntologyRecovery(this.dataPath, this.paradigmItemId, committed.hash, {
                sessionId: this.sessionId,
                generation: this.generation,
              });
            } catch (_) {}
            this.setStatus("恢复草稿写入失败，已直接保存正式数据", "is-warning");
            return true;
          } catch (commitError) {
            throw new Error(`卸载前草稿保护失败；恢复写入失败，正式保存也失败：${commitError.message}`, { cause: recoveryError });
          }
        }
        throw new Error(`卸载前草稿保护失败：${recoveryError.message}`, { cause: recoveryError });
      }
    })();
    return await this.forcedTeardownPromise;
  }

  finishClose() {
    if (this.finalClosing) return;
    if (this.getActiveColumnDescriptionModal()) {
      void this.settleActiveColumnDescriptionModal("ontology-finish-close").then((protectedDescription) => {
        if (protectedDescription === true) this.finishClose();
      });
      return;
    }
    this.prepareParadigmOntologyModalForClose();
    this.acceptingImageImports = false;
    this.closeOperationToken += 1;
    this.invalidateSharedSchemaAsyncWork();
    this.finalClosing = true;
    super.close();
  }

  onClose() {
    this.cleanupParadigmOntologyTreeSurface();
    if (this.recoveryTimer) window.clearTimeout(this.recoveryTimer);
    this.recoveryTimer = 0;
    if (this.viewStateTimer) window.clearTimeout(this.viewStateTimer);
    this.viewStateTimer = 0;
    this.removeParadigmOntologyRestoreChip();
    if (this.rangeCueTimer) window.clearTimeout(this.rangeCueTimer);
    this.rangeCueTimer = 0;
    this.rangePhaseToken += 1;
    this.rangePointerActive = false;
    this.modalEl.removeEventListener("keydown", this.boundRangeKeydown, true);
    this.containerEl?.removeEventListener?.("click", this.boundParadigmOntologyBackdropClick, true);
    window.removeEventListener?.("pointerup", this.boundRangePointerEnd, true);
    window.removeEventListener?.("pointercancel", this.boundRangePointerCancel, true);
    this.clearParadigmOntologyCellFocusTimers();
    if (this.referenceWriteStateUnsubscribe) {
      try { this.referenceWriteStateUnsubscribe(); } catch (_) {}
      this.referenceWriteStateUnsubscribe = null;
    }
    if (this.referenceCaptureStateUnsubscribe) {
      try { this.referenceCaptureStateUnsubscribe(); } catch (_) {}
      this.referenceCaptureStateUnsubscribe = null;
    }
    this.modalEl.removeClass?.("is-ontology-meta-active");
    this.invalidateParadigmOntologyAlbums();
    this.plugin?.unregisterParadigmOntologyModal?.(this);
    if (!this.didNotifyExternalClose && this.onExternalClose) {
      this.didNotifyExternalClose = true;
      try { this.onExternalClose(); } catch (error) { console.warn("[WorkspaceMount][ontology.external-close-callback]", error); }
    }
    this.modalEl.removeClass("workspace-ontology-modal");
    this.contentEl.empty();
  }
}

if (typeof globalThis !== "undefined" && globalThis.__WM_ONTOLOGY_TEST_HOOKS === true
  && globalThis.__workspaceMountOntologyTestApi) {
  globalThis.__workspaceMountOntologyTestApi.WorkspaceConfirmModal = WorkspaceConfirmModal;
  globalThis.__workspaceMountOntologyTestApi.WorkspaceParadigmOntologyAlbumModal = WorkspaceParadigmOntologyAlbumModal;
  globalThis.__workspaceMountOntologyTestApi.WorkspaceOntologyColumnDescriptionModal = WorkspaceOntologyColumnDescriptionModal;
  globalThis.__workspaceMountOntologyTestApi.WorkspaceParadigmOntologyModal = WorkspaceParadigmOntologyModal;
}

class WorkspaceNoteBindingModal extends Modal {
  constructor(app, options = {}) {
    super(app);
    this.options = options;
    this.result = null;
    this.waiter = new Promise((resolve) => {
      this._resolve = resolve;
    });
  }

  onOpen() {
    const { contentEl } = this;
    const {
      title = "绑定笔记",
      value = "",
      noteIndex = [],
      onOpenCurrent = null,
    } = this.options;
    this.filtered = [];
    this.activeIndex = 0;
    contentEl.empty();
    this.modalEl.style.maxWidth = "1100px";
    this.modalEl.style.width = "92vw";
    this.modalEl.style.height = "80vh";
    contentEl.style.display = "flex";
    contentEl.style.flexDirection = "column";
    contentEl.style.height = "100%";
    contentEl.style.gap = "8px";
    contentEl.createEl("h3", { text: title });
    contentEl.createEl("div", {
      text: "已有笔记会直接列出来；也可以手动输入文件名或路径绑定。",
      cls: "workspace-modal-desc",
    });
    if (value) {
      const currentWrap = contentEl.createDiv({ cls: "workspace-note-picker-current" });
      currentWrap.createEl("div", { text: "当前绑定", cls: "workspace-shortcut-title" });
      currentWrap.createEl("div", { text: value, cls: "workspace-shortcut-path" });
      const currentActions = currentWrap.createDiv({ cls: "workspace-modal-actions" });
      if (typeof onOpenCurrent === "function") {
        const openBtn = currentActions.createEl("button", { text: "打开当前绑定" });
        openBtn.onclick = () => { onOpenCurrent(); };
      }
      const clearCurrentBtn = currentActions.createEl("button", { text: "清除绑定" });
      clearCurrentBtn.onclick = () => {
        this.result = { action: "clear", value: "" };
        this.close();
      };
    }
    const input = contentEl.createEl("input", {
      type: "text",
      cls: "workspace-modal-input",
      attr: { placeholder: "输入关键词筛选，或直接输入文件名/路径后绑定" },
    });
    input.value = value || "";
    const stat = contentEl.createEl("div", { text: "", cls: "workspace-modal-desc" });
    const listEl = contentEl.createDiv({ cls: "workspace-note-picker-list" });
    const actions = contentEl.createDiv({ cls: "workspace-modal-actions" });
    const syncActiveRows = () => {
      Array.from(listEl.children).forEach((child, idx) => {
        if (!(child instanceof HTMLElement)) return;
        child.classList.toggle("is-active", idx === this.activeIndex);
      });
    };
    const renderList = () => {
      const q = String(input.value || "").trim().toLowerCase();
      const terms = q ? q.split(/\s+/).filter(Boolean) : [];
      const matched = !terms.length
        ? noteIndex.slice(0, 240)
        : noteIndex.filter((item) => {
          const hay = `${item.search || ""} ${item.basenameLower || ""} ${item.pathLower || ""}`.toLowerCase();
          return terms.every((term) => hay.includes(term));
        }).slice(0, 240);
      this.filtered = matched;
      if (this.activeIndex >= matched.length) this.activeIndex = Math.max(0, matched.length - 1);
      stat.textContent = `共 ${matched.length} 条结果`;
      listEl.empty();
      if (matched.length === 0) {
        listEl.createDiv({ text: "无匹配笔记", cls: "workspace-empty" });
        return;
      }
      matched.forEach((item, idx) => {
        const row = listEl.createDiv({ cls: `workspace-note-picker-row ${idx === this.activeIndex ? "is-active" : ""}`.trim() });
        row.createEl("div", { text: `📝 ${item.basename}`, cls: "workspace-shortcut-label" });
        row.createEl("div", { text: item.path, cls: "workspace-shortcut-path" });
        row.onclick = () => {
          this.result = { action: "save", value: item.path };
          this.close();
        };
        row.onmouseenter = () => {
          this.activeIndex = idx;
          syncActiveRows();
        };
      });
    };
    input.addEventListener("input", () => {
      this.activeIndex = 0;
      renderList();
    });
    const clearBtn = actions.createEl("button", { text: "清除绑定" });
    clearBtn.onclick = () => {
      this.result = { action: "clear", value: "" };
      this.close();
    };
    const cancelBtn = actions.createEl("button", { text: "取消" });
    cancelBtn.onclick = () => this.close();
    const saveBtn = actions.createEl("button", { text: "绑定输入内容", cls: "mod-cta" });
    const submit = () => {
      this.result = { action: "save", value: sanitizeText(input.value, "") };
      this.close();
    };
    saveBtn.onclick = submit;
    input.addEventListener("keydown", (event) => {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        if (this.activeIndex < this.filtered.length - 1) this.activeIndex += 1;
        syncActiveRows();
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        if (this.activeIndex > 0) this.activeIndex -= 1;
        syncActiveRows();
      } else if (event.key === "Enter") {
        event.preventDefault();
        const selected = this.filtered[this.activeIndex];
        if (selected) {
          this.result = { action: "save", value: selected.path };
          this.close();
        } else {
          submit();
        }
      }
    });
    renderList();
    window.setTimeout(() => {
      input.focus();
      input.select();
    }, 0);
  }

  onClose() {
    this.modalEl.style.maxWidth = "";
    this.modalEl.style.width = "";
    this.modalEl.style.height = "";
    this.contentEl.style.display = "";
    this.contentEl.style.flexDirection = "";
    this.contentEl.style.height = "";
    this.contentEl.style.gap = "";
    this.contentEl.empty();
    this._resolve(this.result);
  }

  waitForResult() {
    this.open();
    return this.waiter;
  }
}

