    trackWorkspacePerfDetached("workspace.render.tail.relation-adapter", { domain: "render-tail" }, () => this.syncRelationAdapter());
    if (!this.historySession) trackWorkspacePerfDetached("workspace.render.tail.relation-focus", { domain: "render-tail" }, () => this.consumePendingRelationFocus());
