async function persistWorkspaceDataForPlugin(plugin, dataPath, safe, sourceData, saveSpan = null, creationProgress = null) {
  safe.lastModified = nowString();
  const serializeSpan = startWorkspacePerfSpan("workspace.save.serialize", { parentId: saveSpan?.id || null });
  let payload;
  try { payload = JSON.stringify(safe, null, 2); } finally { serializeSpan?.end({ bytes: workspacePerfByteLength(payload) }); }
  if (!sanitizeText(dataPath, "")) {
    throw new Error("Workspace data path is not resolved.");
  }
  const file = plugin.app.vault.getAbstractFileByPath(dataPath);
  const writeSpan = startWorkspacePerfSpan("workspace.save.write", {
    parentId: saveSpan?.id || null,
    bytes: saveSpan ? workspacePerfByteLength(payload) : undefined,
  });
  try {
    if (creationProgress) {
      creationProgress.assertCurrent();
      await creationProgress.beforeWrite?.();
      creationProgress.assertCurrent();
      creationProgress.completion.stages.primary = "unknown";
    }
    await plugin.getCenterNamingConsumerV1().publish(dataPath, payload, sourceData?.sourceNotePath || "", raw => {
      if (creationProgress) { creationProgress.assertCurrent(); if (creationProgress.preserveRaw === true) creationProgress.assertRaw(raw); }
      return true;
    });
    if (creationProgress) creationProgress.completion.stages.primary = "committed";
  } finally {
    writeSpan?.end();
  }
  if (creationProgress) {
    creationProgress.assertCurrent();
    creationProgress.completion.stages.carrierEvent = "pending";
  }
  plugin.dispatchContextCarrierChanged("workspace-data-saved", {
    revision: safe.lastModified,
    sourceNotePath: sanitizeText(sourceData?.sourceNotePath || "", ""),
  });
  if (creationProgress) creationProgress.completion.stages.carrierEvent = "dispatch-requested";
  return safe;
}

